fn broker_lease_wal_authenticate(
    authenticator: &GuardianBrokerLeaseWalAuthenticatorV1,
    bytes: &[u8],
) -> Result<[u8; BROKER_LEASE_WAL_MAC_BYTES], BrokerPaneLeaseWalErrorV1> {
    authenticator
        .authenticate(bytes)
        .map_err(|_| BrokerPaneLeaseWalErrorV1::AuthenticationFailed)
}

fn broker_lease_wal_verify(
    authenticator: &GuardianBrokerLeaseWalAuthenticatorV1,
    bytes: &[u8],
    tag: &[u8],
) -> Result<(), BrokerPaneLeaseWalErrorV1> {
    authenticator
        .verify(bytes, tag)
        .map_err(|_| BrokerPaneLeaseWalErrorV1::AuthenticationFailed)
}

fn validate_broker_lease_attachment_for_spawn(
    attachment: BrokerAttachmentIdentityV1,
    spawn: BrokerSpawnWalIdentityV1,
) -> Result<(), BrokerPaneLeaseWalErrorV1> {
    if attachment.broker_incarnation.is_nil()
        || attachment.durable_pane_id != spawn.durable_pane_id()
        || attachment.spawn_effect_id != spawn.spawn_effect_id()
        || attachment.attachment_id.is_nil()
        || !attachment.owner.is_valid()
        || attachment.lease_generation == 0
    {
        return Err(BrokerPaneLeaseWalErrorV1::InvalidIdentity);
    }
    Ok(())
}

fn broker_lease_attachment_digest(
    attachment: BrokerAttachmentIdentityV1,
) -> Result<[u8; 32], BrokerPaneLeaseWalErrorV1> {
    if attachment.broker_incarnation.is_nil()
        || attachment.durable_pane_id.is_nil()
        || attachment.spawn_effect_id.is_nil()
        || attachment.attachment_id.is_nil()
        || !attachment.owner.is_valid()
        || attachment.lease_generation == 0
    {
        return Err(BrokerPaneLeaseWalErrorV1::InvalidIdentity);
    }
    let mut hasher = Sha256::new();
    hasher.update(b"frankenterm.guardian-broker-lease-attachment.v1\0");
    hasher.update(attachment.broker_incarnation.as_bytes());
    hasher.update(attachment.durable_pane_id.as_bytes());
    hasher.update(attachment.spawn_effect_id.as_bytes());
    hasher.update(attachment.attachment_id.as_bytes());
    hasher.update(attachment.owner.guardian_incarnation.as_bytes());
    hasher.update(attachment.owner.connection_id.as_bytes());
    hasher.update(attachment.owner.mux_incarnation.as_bytes());
    hasher.update(attachment.owner.mux_build_identity_digest);
    hasher.update(attachment.owner.guardian_build_identity_digest);
    hasher.update(attachment.lease_generation.to_le_bytes());
    Ok(hasher.finalize().into())
}

fn broker_lease_catalog_wal_name(journal_id: Uuid) -> OsString {
    format!("{BROKER_LEASE_CATALOG_PREFIX}{journal_id}{BROKER_LEASE_CATALOG_WAL_SUFFIX}").into()
}

fn broker_lease_catalog_head_name(journal_id: Uuid) -> OsString {
    format!("{BROKER_LEASE_CATALOG_PREFIX}{journal_id}{BROKER_LEASE_CATALOG_HEAD_SUFFIX}").into()
}

fn broker_lease_catalog_creating_name(journal_id: Uuid) -> OsString {
    format!("{BROKER_LEASE_CATALOG_PREFIX}{journal_id}{BROKER_LEASE_CATALOG_CREATING_SUFFIX}")
        .into()
}

fn broker_lease_catalog_completed_name(journal_id: Uuid) -> OsString {
    format!("{BROKER_LEASE_CATALOG_PREFIX}{journal_id}{BROKER_LEASE_CATALOG_COMPLETED_SUFFIX}")
        .into()
}

fn parse_broker_lease_catalog_name(
    name: &OsStr,
) -> Result<BrokerPaneLeaseCatalogMemberV1, BrokerPaneLeaseWalErrorV1> {
    let text = name
        .to_str()
        .ok_or(BrokerPaneLeaseWalErrorV1::UnexpectedCatalogEntry)?;
    let variants = [
        (
            BROKER_LEASE_CATALOG_WAL_SUFFIX,
            BrokerPaneLeaseCatalogMemberV1::Wal as fn(Uuid) -> _,
        ),
        (
            BROKER_LEASE_CATALOG_HEAD_SUFFIX,
            BrokerPaneLeaseCatalogMemberV1::Head as fn(Uuid) -> _,
        ),
        (
            BROKER_LEASE_CATALOG_CREATING_SUFFIX,
            BrokerPaneLeaseCatalogMemberV1::Creating as fn(Uuid) -> _,
        ),
        (
            BROKER_LEASE_CATALOG_COMPLETED_SUFFIX,
            BrokerPaneLeaseCatalogMemberV1::Completed as fn(Uuid) -> _,
        ),
    ];
    let (identifier, constructor) = variants
        .into_iter()
        .find_map(|(suffix, constructor)| {
            text.strip_prefix(BROKER_LEASE_CATALOG_PREFIX)
                .and_then(|rest| rest.strip_suffix(suffix))
                .map(|identifier| (identifier, constructor))
        })
        .ok_or(BrokerPaneLeaseWalErrorV1::UnexpectedCatalogEntry)?;
    let journal_id = Uuid::parse_str(identifier)
        .map_err(|_| BrokerPaneLeaseWalErrorV1::UnexpectedCatalogEntry)?;
    if journal_id.is_nil() {
        return Err(BrokerPaneLeaseWalErrorV1::UnexpectedCatalogEntry);
    }
    let member = constructor(journal_id);
    let canonical = match member {
        BrokerPaneLeaseCatalogMemberV1::Wal(id) => broker_lease_catalog_wal_name(id),
        BrokerPaneLeaseCatalogMemberV1::Head(id) => broker_lease_catalog_head_name(id),
        BrokerPaneLeaseCatalogMemberV1::Creating(id) => broker_lease_catalog_creating_name(id),
        BrokerPaneLeaseCatalogMemberV1::Completed(id) => broker_lease_catalog_completed_name(id),
    };
    if canonical != name {
        return Err(BrokerPaneLeaseWalErrorV1::UnexpectedCatalogEntry);
    }
    Ok(member)
}

fn validate_broker_lease_catalog_name_capacity(
    directory: &File,
) -> Result<(), BrokerPaneLeaseWalErrorV1> {
    let observed = fpathconf(directory, PathconfVar::NAME_MAX)
        .map_err(std::io::Error::from)?
        .ok_or(BrokerPaneLeaseWalErrorV1::CatalogNameTooLong)?;
    let observed =
        usize::try_from(observed).map_err(|_| BrokerPaneLeaseWalErrorV1::CatalogNameTooLong)?;
    let maximum_id = Uuid::from_u128(u128::MAX);
    let maximum_required = [
        broker_lease_catalog_wal_name(maximum_id),
        broker_lease_catalog_head_name(maximum_id),
        broker_lease_catalog_creating_name(maximum_id),
        broker_lease_catalog_completed_name(maximum_id),
        OsString::from(BROKER_LEASE_CATALOG_LOCK_NAME),
    ]
    .into_iter()
    .map(|name| name.as_bytes().len())
    .max()
    .ok_or(BrokerPaneLeaseWalErrorV1::CatalogNameTooLong)?;
    if maximum_required > observed {
        return Err(BrokerPaneLeaseWalErrorV1::CatalogNameTooLong);
    }
    Ok(())
}

fn encode_broker_lease_file_header(
    magic: [u8; 8],
    identity: &BrokerPaneLeaseWalIdentityV1,
    authenticator: &GuardianBrokerLeaseWalAuthenticatorV1,
) -> Result<[u8; BROKER_LEASE_WAL_FILE_HEADER_BYTES], BrokerPaneLeaseWalErrorV1> {
    identity.validate()?;
    if identity.spawn.broker_lineage_id() != authenticator.lineage_id() {
        return Err(BrokerPaneLeaseWalErrorV1::LineageMismatch);
    }
    let spawn_identity = encode_broker_spawn_creation_identity(identity.spawn)
        .map_err(|_| BrokerPaneLeaseWalErrorV1::InvalidIdentity)?;
    let mut header = [0_u8; BROKER_LEASE_WAL_FILE_HEADER_BYTES];
    header[0..8].copy_from_slice(&magic);
    header[8..12].copy_from_slice(&BROKER_LEASE_WAL_FORMAT_VERSION.to_le_bytes());
    header[12..16].copy_from_slice(&BROKER_LEASE_WAL_FILE_HEADER_BYTES_U32.to_le_bytes());
    header[16..24].copy_from_slice(&authenticator.key_id());
    header[24..192].copy_from_slice(&spawn_identity);
    header[192..196].copy_from_slice(&identity.child_identity.process_id.to_le_bytes());
    header[200..216].copy_from_slice(identity.child_identity.broker_child_nonce.as_bytes());
    header[216..248].copy_from_slice(&identity.child_identity.kernel_start_identity_digest);
    header[248..280].copy_from_slice(&identity.initial_recovery_verifier.into_bytes());
    header[280..312].copy_from_slice(&identity.initial_attachment_digest);
    let tag = broker_lease_wal_authenticate(
        authenticator,
        &header[..BROKER_LEASE_WAL_AUTHENTICATED_HEADER_BYTES],
    )?;
    header[320..352].copy_from_slice(&tag);
    Ok(header)
}

fn decode_broker_lease_file_header(
    header: &[u8; BROKER_LEASE_WAL_FILE_HEADER_BYTES],
    magic: [u8; 8],
    authenticator: &GuardianBrokerLeaseWalAuthenticatorV1,
) -> Result<
    (
        BrokerPaneLeaseWalIdentityV1,
        [u8; BROKER_LEASE_WAL_MAC_BYTES],
    ),
    BrokerPaneLeaseWalErrorV1,
> {
    if header[0..8] != magic {
        return Err(BrokerPaneLeaseWalErrorV1::InvalidFileMagic);
    }
    let version = read_broker_u32(&header[8..12]);
    if version != BROKER_LEASE_WAL_FORMAT_VERSION {
        return Err(BrokerPaneLeaseWalErrorV1::UnsupportedVersion { observed: version });
    }
    if read_broker_u32(&header[12..16]) != BROKER_LEASE_WAL_FILE_HEADER_BYTES_U32 {
        return Err(BrokerPaneLeaseWalErrorV1::InvalidFileHeaderLength);
    }
    if header[16..24] != authenticator.key_id() {
        return Err(BrokerPaneLeaseWalErrorV1::KeyIdentityMismatch);
    }
    if header[196..200].iter().any(|byte| *byte != 0)
        || header[312..320].iter().any(|byte| *byte != 0)
    {
        return Err(BrokerPaneLeaseWalErrorV1::NonCanonicalFileHeader);
    }
    let mut encoded_spawn = [0_u8; BROKER_SPAWN_CREATION_IDENTITY_BYTES];
    encoded_spawn.copy_from_slice(&header[24..192]);
    let spawn = decode_broker_spawn_creation_identity(&encoded_spawn)
        .map_err(|_| BrokerPaneLeaseWalErrorV1::InvalidIdentity)?;
    if spawn.broker_lineage_id() != authenticator.lineage_id() {
        return Err(BrokerPaneLeaseWalErrorV1::LineageMismatch);
    }
    let child_identity = BrokerKernelChildIdentityV1 {
        process_id: read_broker_u32(&header[192..196]),
        broker_child_nonce: read_broker_uuid(&header[200..216]),
        kernel_start_identity_digest: read_broker_array_32(&header[216..248]),
    };
    let initial_recovery_verifier =
        BrokerPaneRecoveryVerifierV1::from_record(read_broker_array_32(&header[248..280]))
            .ok_or(BrokerPaneLeaseWalErrorV1::InvalidIdentity)?;
    let identity = BrokerPaneLeaseWalIdentityV1 {
        spawn,
        child_identity,
        initial_recovery_verifier,
        initial_attachment_digest: read_broker_array_32(&header[280..312]),
    };
    identity.validate()?;
    broker_lease_wal_verify(
        authenticator,
        &header[..BROKER_LEASE_WAL_AUTHENTICATED_HEADER_BYTES],
        &header[320..352],
    )?;
    Ok((identity, read_broker_array_32(&header[320..352])))
}

fn validate_broker_lease_record_fields(
    fields: &BrokerPaneLeaseWalRecordFieldsV1,
) -> Result<(), BrokerPaneLeaseWalErrorV1> {
    if fields.lease_generation <= 1
        || !fields.owner.is_valid()
        || fields.recovery_verifier.into_bytes() == [0; 32]
        || fields.attachment_digest == [0; 32]
        || fields.predecessor_attachment_id.is_nil()
    {
        return Err(BrokerPaneLeaseWalErrorV1::NonCanonicalRecord);
    }
    match fields.phase {
        BrokerPaneLeaseWalPhaseV1::PredecessorFenced
            if fields.handoff_id.is_nil()
                && fields.ack_id.is_nil()
                && fields.successor_attachment_id.is_nil()
                && fields.predecessor_attachment_digest == [0; 32] =>
        {
            Ok(())
        }
        BrokerPaneLeaseWalPhaseV1::SuccessorClaimed
            if !fields.handoff_id.is_nil()
                && fields.ack_id.is_nil()
                && !fields.successor_attachment_id.is_nil()
                && fields.successor_attachment_id != fields.predecessor_attachment_id
                && fields.predecessor_attachment_digest != [0; 32] =>
        {
            Ok(())
        }
        BrokerPaneLeaseWalPhaseV1::SuccessorAcknowledged
            if !fields.handoff_id.is_nil()
                && !fields.ack_id.is_nil()
                && !fields.successor_attachment_id.is_nil()
                && fields.successor_attachment_id != fields.predecessor_attachment_id
                && fields.predecessor_attachment_digest != [0; 32] =>
        {
            Ok(())
        }
        _ => Err(BrokerPaneLeaseWalErrorV1::NonCanonicalRecord),
    }
}

fn validate_broker_lease_record_transition(
    identity: &BrokerPaneLeaseWalIdentityV1,
    previous: Option<&BrokerPaneLeaseWalRecordFieldsV1>,
    current: &BrokerPaneLeaseWalRecordFieldsV1,
) -> Result<(), BrokerPaneLeaseWalErrorV1> {
    validate_broker_lease_record_fields(current)?;
    match (previous, current.phase) {
        (None, BrokerPaneLeaseWalPhaseV1::PredecessorFenced)
            if current.lease_generation == 2
                && current.owner.mux_incarnation == identity.spawn.mux_incarnation()
                && current.recovery_verifier == identity.initial_recovery_verifier
                && current.attachment_digest == identity.initial_attachment_digest =>
        {
            Ok(())
        }
        (Some(previous), BrokerPaneLeaseWalPhaseV1::PredecessorFenced)
            if previous.phase == BrokerPaneLeaseWalPhaseV1::SuccessorAcknowledged
                && current.lease_generation
                    == previous
                        .lease_generation
                        .checked_add(1)
                        .ok_or(BrokerPaneLeaseWalErrorV1::CapacityExhausted)?
                && current.predecessor_attachment_id == previous.successor_attachment_id
                && current.owner == previous.owner
                && current.recovery_verifier == previous.recovery_verifier
                && current.attachment_digest == previous.attachment_digest =>
        {
            Ok(())
        }
        (Some(previous), BrokerPaneLeaseWalPhaseV1::SuccessorClaimed)
            if previous.phase == BrokerPaneLeaseWalPhaseV1::PredecessorFenced
                && current.lease_generation == previous.lease_generation
                && current.predecessor_attachment_id == previous.predecessor_attachment_id
                && current.owner.guardian_incarnation != previous.owner.guardian_incarnation
                && current.owner.connection_id != previous.owner.connection_id
                && current.predecessor_attachment_digest == previous.attachment_digest =>
        {
            Ok(())
        }
        (Some(previous), BrokerPaneLeaseWalPhaseV1::SuccessorAcknowledged)
            if previous.phase == BrokerPaneLeaseWalPhaseV1::SuccessorClaimed
                && current.handoff_id == previous.handoff_id
                && current.predecessor_attachment_id == previous.predecessor_attachment_id
                && current.successor_attachment_id == previous.successor_attachment_id
                && current.lease_generation == previous.lease_generation
                && current.owner == previous.owner
                && current.recovery_verifier == previous.recovery_verifier
                && current.attachment_digest == previous.attachment_digest
                && current.predecessor_attachment_digest
                    == previous.predecessor_attachment_digest =>
        {
            Ok(())
        }
        _ => Err(BrokerPaneLeaseWalErrorV1::InvalidTransition),
    }
}

fn encode_broker_lease_wal_record(
    header_mac: [u8; BROKER_LEASE_WAL_MAC_BYTES],
    authenticator: &GuardianBrokerLeaseWalAuthenticatorV1,
    sequence: u64,
    fields: &BrokerPaneLeaseWalRecordFieldsV1,
    previous_record_mac: [u8; BROKER_LEASE_WAL_MAC_BYTES],
) -> Result<[u8; BROKER_LEASE_WAL_RECORD_BYTES], BrokerPaneLeaseWalErrorV1> {
    validate_broker_lease_record_fields(fields)?;
    let mut record = [0_u8; BROKER_LEASE_WAL_RECORD_BYTES];
    record[0..8].copy_from_slice(&BROKER_LEASE_WAL_RECORD_MAGIC);
    record[8..12].copy_from_slice(&BROKER_LEASE_WAL_RECORD_BYTES_U32.to_le_bytes());
    record[12] = fields.phase as u8;
    record[16..24].copy_from_slice(&sequence.to_le_bytes());
    record[24..40].copy_from_slice(fields.handoff_id.as_bytes());
    record[40..56].copy_from_slice(fields.ack_id.as_bytes());
    record[56..72].copy_from_slice(fields.predecessor_attachment_id.as_bytes());
    record[72..88].copy_from_slice(fields.successor_attachment_id.as_bytes());
    record[88..96].copy_from_slice(&fields.lease_generation.to_le_bytes());
    record[96..112].copy_from_slice(fields.owner.guardian_incarnation.as_bytes());
    record[112..128].copy_from_slice(fields.owner.connection_id.as_bytes());
    record[128..144].copy_from_slice(fields.owner.mux_incarnation.as_bytes());
    record[144..176].copy_from_slice(&fields.owner.mux_build_identity_digest);
    record[176..208].copy_from_slice(&fields.owner.guardian_build_identity_digest);
    record[208..240].copy_from_slice(&fields.recovery_verifier.into_bytes());
    record[240..272].copy_from_slice(&fields.attachment_digest);
    record[272..304].copy_from_slice(&fields.predecessor_attachment_digest);
    record[304..336].copy_from_slice(&previous_record_mac);
    let mut authenticated =
        [0_u8; BROKER_LEASE_WAL_MAC_BYTES + BROKER_LEASE_WAL_AUTHENTICATED_RECORD_BYTES];
    authenticated[..BROKER_LEASE_WAL_MAC_BYTES].copy_from_slice(&header_mac);
    authenticated[BROKER_LEASE_WAL_MAC_BYTES..]
        .copy_from_slice(&record[..BROKER_LEASE_WAL_AUTHENTICATED_RECORD_BYTES]);
    let tag = broker_lease_wal_authenticate(authenticator, &authenticated)?;
    record[336..368].copy_from_slice(&tag);
    Ok(record)
}

fn decode_broker_lease_wal_record(
    record: &[u8; BROKER_LEASE_WAL_RECORD_BYTES],
    identity: &BrokerPaneLeaseWalIdentityV1,
    header_mac: [u8; BROKER_LEASE_WAL_MAC_BYTES],
    authenticator: &GuardianBrokerLeaseWalAuthenticatorV1,
    expected_sequence: u64,
    expected_previous_mac: [u8; BROKER_LEASE_WAL_MAC_BYTES],
    previous: Option<&BrokerPaneLeaseWalRecordFieldsV1>,
) -> Result<BrokerPaneLeaseWalRecordStateV1, BrokerPaneLeaseWalErrorV1> {
    if record[0..8] != BROKER_LEASE_WAL_RECORD_MAGIC
        || read_broker_u32(&record[8..12]) != BROKER_LEASE_WAL_RECORD_BYTES_U32
    {
        return Err(BrokerPaneLeaseWalErrorV1::InvalidRecordFraming);
    }
    if record[13..16].iter().any(|byte| *byte != 0) {
        return Err(BrokerPaneLeaseWalErrorV1::NonCanonicalRecord);
    }
    let sequence = read_broker_u64(&record[16..24]);
    if sequence != expected_sequence {
        return Err(BrokerPaneLeaseWalErrorV1::SequenceMismatch);
    }
    if record[304..336] != expected_previous_mac {
        return Err(BrokerPaneLeaseWalErrorV1::RecordChainMismatch);
    }
    let mut authenticated =
        [0_u8; BROKER_LEASE_WAL_MAC_BYTES + BROKER_LEASE_WAL_AUTHENTICATED_RECORD_BYTES];
    authenticated[..BROKER_LEASE_WAL_MAC_BYTES].copy_from_slice(&header_mac);
    authenticated[BROKER_LEASE_WAL_MAC_BYTES..]
        .copy_from_slice(&record[..BROKER_LEASE_WAL_AUTHENTICATED_RECORD_BYTES]);
    broker_lease_wal_verify(authenticator, &authenticated, &record[336..368])?;
    let fields = BrokerPaneLeaseWalRecordFieldsV1 {
        phase: BrokerPaneLeaseWalPhaseV1::from_wire(record[12])?,
        handoff_id: read_broker_uuid(&record[24..40]),
        ack_id: read_broker_uuid(&record[40..56]),
        predecessor_attachment_id: read_broker_uuid(&record[56..72]),
        successor_attachment_id: read_broker_uuid(&record[72..88]),
        lease_generation: read_broker_u64(&record[88..96]),
        owner: BrokerGuardianOwnerIdentity {
            guardian_incarnation: read_broker_uuid(&record[96..112]),
            connection_id: read_broker_uuid(&record[112..128]),
            mux_incarnation: read_broker_uuid(&record[128..144]),
            mux_build_identity_digest: read_broker_array_32(&record[144..176]),
            guardian_build_identity_digest: read_broker_array_32(&record[176..208]),
        },
        recovery_verifier: BrokerPaneRecoveryVerifierV1::from_record(read_broker_array_32(
            &record[208..240],
        ))
        .ok_or(BrokerPaneLeaseWalErrorV1::NonCanonicalRecord)?,
        attachment_digest: read_broker_array_32(&record[240..272]),
        predecessor_attachment_digest: read_broker_array_32(&record[272..304]),
    };
    validate_broker_lease_record_transition(identity, previous, &fields)?;
    let record_mac = read_broker_array_32(&record[336..368]);
    Ok(BrokerPaneLeaseWalRecordStateV1 {
        fields,
        receipt: BrokerPaneLeaseWalReceiptV1 {
            sequence,
            phase: fields.phase,
            committed_wal_bytes: BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64
                + (sequence + 1) * BROKER_LEASE_WAL_RECORD_BYTES_U64,
            committed_head_bytes: BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
            record_mac,
            head_mac: [0; BROKER_LEASE_WAL_MAC_BYTES],
        },
    })
}

fn encode_broker_lease_head_record(
    head_header_mac: [u8; BROKER_LEASE_WAL_MAC_BYTES],
    authenticator: &GuardianBrokerLeaseWalAuthenticatorV1,
    sequence: u64,
    wal_record_mac: [u8; BROKER_LEASE_WAL_MAC_BYTES],
    previous_head_mac: [u8; BROKER_LEASE_WAL_MAC_BYTES],
) -> Result<[u8; BROKER_LEASE_HEAD_RECORD_BYTES], BrokerPaneLeaseWalErrorV1> {
    let mut record = [0_u8; BROKER_LEASE_HEAD_RECORD_BYTES];
    record[0..8].copy_from_slice(&BROKER_LEASE_HEAD_RECORD_MAGIC);
    record[8..12].copy_from_slice(&BROKER_LEASE_HEAD_RECORD_BYTES_U32.to_le_bytes());
    record[16..24].copy_from_slice(&sequence.to_le_bytes());
    record[24..56].copy_from_slice(&wal_record_mac);
    record[56..88].copy_from_slice(&previous_head_mac);
    let mut authenticated =
        [0_u8; BROKER_LEASE_WAL_MAC_BYTES + BROKER_LEASE_HEAD_AUTHENTICATED_RECORD_BYTES];
    authenticated[..BROKER_LEASE_WAL_MAC_BYTES].copy_from_slice(&head_header_mac);
    authenticated[BROKER_LEASE_WAL_MAC_BYTES..]
        .copy_from_slice(&record[..BROKER_LEASE_HEAD_AUTHENTICATED_RECORD_BYTES]);
    let tag = broker_lease_wal_authenticate(authenticator, &authenticated)?;
    record[88..120].copy_from_slice(&tag);
    Ok(record)
}

fn decode_broker_lease_head_record(
    record: &[u8; BROKER_LEASE_HEAD_RECORD_BYTES],
    head_header_mac: [u8; BROKER_LEASE_WAL_MAC_BYTES],
    authenticator: &GuardianBrokerLeaseWalAuthenticatorV1,
    expected_sequence: u64,
    expected_wal_record_mac: [u8; BROKER_LEASE_WAL_MAC_BYTES],
    expected_previous_head_mac: [u8; BROKER_LEASE_WAL_MAC_BYTES],
) -> Result<[u8; BROKER_LEASE_WAL_MAC_BYTES], BrokerPaneLeaseWalErrorV1> {
    if record[0..8] != BROKER_LEASE_HEAD_RECORD_MAGIC
        || read_broker_u32(&record[8..12]) != BROKER_LEASE_HEAD_RECORD_BYTES_U32
    {
        return Err(BrokerPaneLeaseWalErrorV1::InvalidRecordFraming);
    }
    if record[12..16].iter().any(|byte| *byte != 0)
        || read_broker_u64(&record[16..24]) != expected_sequence
        || record[24..56] != expected_wal_record_mac
        || record[56..88] != expected_previous_head_mac
    {
        return Err(BrokerPaneLeaseWalErrorV1::HeadAnchorMismatch);
    }
    let mut authenticated =
        [0_u8; BROKER_LEASE_WAL_MAC_BYTES + BROKER_LEASE_HEAD_AUTHENTICATED_RECORD_BYTES];
    authenticated[..BROKER_LEASE_WAL_MAC_BYTES].copy_from_slice(&head_header_mac);
    authenticated[BROKER_LEASE_WAL_MAC_BYTES..]
        .copy_from_slice(&record[..BROKER_LEASE_HEAD_AUTHENTICATED_RECORD_BYTES]);
    broker_lease_wal_verify(authenticator, &authenticated, &record[88..120])?;
    Ok(read_broker_array_32(&record[88..120]))
}

fn scan_broker_lease_wal(
    wal: &mut File,
    expected: &BrokerPaneLeaseWalIdentityV1,
    authenticator: &GuardianBrokerLeaseWalAuthenticatorV1,
) -> Result<([u8; BROKER_LEASE_WAL_MAC_BYTES], BrokerPaneLeaseWalScanV1), BrokerPaneLeaseWalErrorV1>
{
    let metadata = wal.metadata()?;
    if !metadata.file_type().is_file() {
        return Err(BrokerPaneLeaseWalErrorV1::NotRegularFile);
    }
    let physical_bytes = metadata.len();
    if physical_bytes < BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64 {
        return Err(BrokerPaneLeaseWalErrorV1::TornFileHeader);
    }
    let maximum_with_tail = BROKER_LEASE_WAL_MAX_PHYSICAL_BYTES
        .checked_add(BROKER_LEASE_WAL_RECORD_BYTES_U64 - 1)
        .ok_or(BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
    if physical_bytes > maximum_with_tail {
        return Err(BrokerPaneLeaseWalErrorV1::CapacityExhausted);
    }
    wal.seek(SeekFrom::Start(0))?;
    let mut header = [0_u8; BROKER_LEASE_WAL_FILE_HEADER_BYTES];
    wal.read_exact(&mut header)?;
    let (observed, header_mac) =
        decode_broker_lease_file_header(&header, BROKER_LEASE_WAL_FILE_MAGIC, authenticator)?;
    if observed != *expected {
        return Err(BrokerPaneLeaseWalErrorV1::IdentityMismatch);
    }
    let record_region = physical_bytes - BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64;
    let complete_records = record_region / BROKER_LEASE_WAL_RECORD_BYTES_U64;
    if complete_records > BROKER_LEASE_WAL_MAX_RECORDS {
        return Err(BrokerPaneLeaseWalErrorV1::CapacityExhausted);
    }
    let trailing_bytes = record_region % BROKER_LEASE_WAL_RECORD_BYTES_U64;
    let capacity = usize::try_from(complete_records)
        .map_err(|_| BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
    let mut records = Vec::new();
    records
        .try_reserve_exact(capacity)
        .map_err(|_| BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
    let mut previous_mac = header_mac;
    let mut previous = None;
    for sequence in 0..complete_records {
        let mut record = [0_u8; BROKER_LEASE_WAL_RECORD_BYTES];
        wal.read_exact(&mut record)?;
        let decoded = decode_broker_lease_wal_record(
            &record,
            expected,
            header_mac,
            authenticator,
            sequence,
            previous_mac,
            previous.as_ref(),
        )?;
        previous_mac = decoded.receipt.record_mac;
        previous = Some(decoded.fields);
        records.push(decoded);
    }
    Ok((
        header_mac,
        BrokerPaneLeaseWalScanV1 {
            committed_bytes: BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64
                + complete_records * BROKER_LEASE_WAL_RECORD_BYTES_U64,
            trailing_bytes,
            records,
        },
    ))
}

fn scan_broker_lease_head(
    head: &mut File,
    expected: &BrokerPaneLeaseWalIdentityV1,
    authenticator: &GuardianBrokerLeaseWalAuthenticatorV1,
    wal_records: &[BrokerPaneLeaseWalRecordStateV1],
) -> Result<([u8; BROKER_LEASE_WAL_MAC_BYTES], BrokerPaneLeaseHeadScanV1), BrokerPaneLeaseWalErrorV1>
{
    let metadata = head.metadata()?;
    if !metadata.file_type().is_file() {
        return Err(BrokerPaneLeaseWalErrorV1::NotRegularFile);
    }
    let physical_bytes = metadata.len();
    if physical_bytes < BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64 {
        return Err(BrokerPaneLeaseWalErrorV1::TornFileHeader);
    }
    let maximum_with_tail = BROKER_LEASE_HEAD_MAX_PHYSICAL_BYTES
        .checked_add(BROKER_LEASE_HEAD_RECORD_BYTES_U64 - 1)
        .ok_or(BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
    if physical_bytes > maximum_with_tail {
        return Err(BrokerPaneLeaseWalErrorV1::CapacityExhausted);
    }
    head.seek(SeekFrom::Start(0))?;
    let mut header = [0_u8; BROKER_LEASE_WAL_FILE_HEADER_BYTES];
    head.read_exact(&mut header)?;
    let (observed, head_header_mac) =
        decode_broker_lease_file_header(&header, BROKER_LEASE_HEAD_FILE_MAGIC, authenticator)?;
    if observed != *expected {
        return Err(BrokerPaneLeaseWalErrorV1::IdentityMismatch);
    }
    let record_region = physical_bytes - BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64;
    let complete_records = record_region / BROKER_LEASE_HEAD_RECORD_BYTES_U64;
    if complete_records > BROKER_LEASE_WAL_MAX_RECORDS
        || complete_records
            > u64::try_from(wal_records.len())
                .map_err(|_| BrokerPaneLeaseWalErrorV1::CapacityExhausted)?
    {
        return Err(BrokerPaneLeaseWalErrorV1::HeadAnchorMismatch);
    }
    let trailing_bytes = record_region % BROKER_LEASE_HEAD_RECORD_BYTES_U64;
    let capacity = usize::try_from(complete_records)
        .map_err(|_| BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
    let mut record_macs = Vec::new();
    record_macs
        .try_reserve_exact(capacity)
        .map_err(|_| BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
    let mut previous_head_mac = head_header_mac;
    for sequence in 0..complete_records {
        let index =
            usize::try_from(sequence).map_err(|_| BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
        let wal_record = wal_records
            .get(index)
            .ok_or(BrokerPaneLeaseWalErrorV1::HeadAnchorMismatch)?;
        let mut record = [0_u8; BROKER_LEASE_HEAD_RECORD_BYTES];
        head.read_exact(&mut record)?;
        let head_mac = decode_broker_lease_head_record(
            &record,
            head_header_mac,
            authenticator,
            sequence,
            wal_record.receipt.record_mac,
            previous_head_mac,
        )?;
        previous_head_mac = head_mac;
        record_macs.push(head_mac);
    }
    if trailing_bytes != 0 {
        let next_index = usize::try_from(complete_records)
            .map_err(|_| BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
        let wal_record = wal_records
            .get(next_index)
            .ok_or(BrokerPaneLeaseWalErrorV1::IncompleteTail)?;
        let expected_record = encode_broker_lease_head_record(
            head_header_mac,
            authenticator,
            complete_records,
            wal_record.receipt.record_mac,
            previous_head_mac,
        )?;
        let prefix_bytes = usize::try_from(trailing_bytes)
            .map_err(|_| BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
        let mut observed_prefix = [0_u8; BROKER_LEASE_HEAD_RECORD_BYTES];
        head.read_exact(&mut observed_prefix[..prefix_bytes])?;
        if observed_prefix[..prefix_bytes] != expected_record[..prefix_bytes] {
            return Err(BrokerPaneLeaseWalErrorV1::IncompleteTail);
        }
    }
    Ok((
        head_header_mac,
        BrokerPaneLeaseHeadScanV1 {
            committed_bytes: BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64
                + complete_records * BROKER_LEASE_HEAD_RECORD_BYTES_U64,
            trailing_bytes,
            record_macs,
            terminal_head_mac: previous_head_mac,
        },
    ))
}

impl BrokerPaneLeaseJournalV1 {
    fn create(
        mut wal: File,
        mut head: File,
        identity: &BrokerPaneLeaseWalIdentityV1,
        authenticator: GuardianBrokerLeaseWalAuthenticatorV1,
    ) -> Result<Self, BrokerPaneLeaseWalErrorV1> {
        identity.validate()?;
        if identity.spawn.broker_lineage_id() != authenticator.lineage_id() {
            return Err(BrokerPaneLeaseWalErrorV1::LineageMismatch);
        }
        if !wal.metadata()?.file_type().is_file() || !head.metadata()?.file_type().is_file() {
            return Err(BrokerPaneLeaseWalErrorV1::NotRegularFile);
        }
        if wal.metadata()?.len() != 0 || head.metadata()?.len() != 0 {
            return Err(BrokerPaneLeaseWalErrorV1::NewJournalNotEmpty);
        }
        let wal_header =
            encode_broker_lease_file_header(BROKER_LEASE_WAL_FILE_MAGIC, identity, &authenticator)?;
        let head_header = encode_broker_lease_file_header(
            BROKER_LEASE_HEAD_FILE_MAGIC,
            identity,
            &authenticator,
        )?;
        wal.seek(SeekFrom::Start(0))?;
        wal.write_all(&wal_header)?;
        wal.sync_all()?;
        head.seek(SeekFrom::Start(0))?;
        head.write_all(&head_header)?;
        head.sync_all()?;
        Ok(Self {
            wal,
            head,
            identity: *identity,
            authenticator,
            header_mac: read_broker_array_32(&wal_header[320..352]),
            head_header_mac: read_broker_array_32(&head_header[320..352]),
            committed_wal_bytes: BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
            committed_head_bytes: BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
            wal_trailing_bytes: 0,
            head_trailing_bytes: 0,
            records: Vec::new(),
            terminal_head_mac: read_broker_array_32(&head_header[320..352]),
            publication_binding: None,
            directory_entry_sync_required: true,
            recovery_append_authority_withheld: false,
            head_reconciliation_required: false,
            poisoned: false,
            #[cfg(test)]
            injected_fault: None,
        })
    }

    fn open(
        mut wal: File,
        mut head: File,
        identity: &BrokerPaneLeaseWalIdentityV1,
        authenticator: GuardianBrokerLeaseWalAuthenticatorV1,
    ) -> Result<Self, BrokerPaneLeaseWalErrorV1> {
        identity.validate()?;
        let (header_mac, mut wal_scan) = scan_broker_lease_wal(&mut wal, identity, &authenticator)?;
        let (head_header_mac, head_scan) =
            scan_broker_lease_head(&mut head, identity, &authenticator, &wal_scan.records)?;
        let wal_record_count = wal_scan.records.len();
        let head_record_count = head_scan.record_macs.len();
        let head_gap = wal_record_count
            .checked_sub(head_record_count)
            .ok_or(BrokerPaneLeaseWalErrorV1::HeadAnchorMismatch)?;
        if head_gap > 1 {
            return Err(BrokerPaneLeaseWalErrorV1::HeadReconciliationGap);
        }
        for (index, head_mac) in head_scan.record_macs.iter().copied().enumerate() {
            let record = wal_scan
                .records
                .get_mut(index)
                .ok_or(BrokerPaneLeaseWalErrorV1::HeadAnchorMismatch)?;
            record.receipt.head_mac = head_mac;
            record.receipt.committed_head_bytes = BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64
                + u64::try_from(index + 1)
                    .map_err(|_| BrokerPaneLeaseWalErrorV1::CapacityExhausted)?
                    * BROKER_LEASE_HEAD_RECORD_BYTES_U64;
        }
        Ok(Self {
            wal,
            head,
            identity: *identity,
            authenticator,
            header_mac,
            head_header_mac,
            committed_wal_bytes: wal_scan.committed_bytes,
            committed_head_bytes: head_scan.committed_bytes,
            wal_trailing_bytes: wal_scan.trailing_bytes,
            head_trailing_bytes: head_scan.trailing_bytes,
            records: wal_scan.records,
            terminal_head_mac: head_scan.terminal_head_mac,
            publication_binding: None,
            directory_entry_sync_required: false,
            recovery_append_authority_withheld: true,
            head_reconciliation_required: head_gap == 1,
            poisoned: false,
            #[cfg(test)]
            injected_fault: None,
        })
    }

    fn status(&self) -> BrokerPaneLeaseWalStatusV1 {
        let terminal = self.records.last().copied();
        let fields = terminal.map(|record| record.fields);
        BrokerPaneLeaseWalStatusV1 {
            identity: self.identity,
            phase: fields.map(|fields| fields.phase),
            handoff_id: fields
                .filter(|fields| !fields.handoff_id.is_nil())
                .map(|fields| fields.handoff_id),
            ack_id: fields
                .filter(|fields| !fields.ack_id.is_nil())
                .map(|fields| fields.ack_id),
            predecessor_attachment_id: fields.map(|fields| fields.predecessor_attachment_id),
            successor_attachment_id: fields
                .filter(|fields| !fields.successor_attachment_id.is_nil())
                .map(|fields| fields.successor_attachment_id),
            lease_generation: fields.map_or(1, |fields| fields.lease_generation),
            owner: fields.map(|fields| fields.owner),
            recovery_verifier: fields.map_or(self.identity.initial_recovery_verifier, |fields| {
                fields.recovery_verifier
            }),
            attachment_digest: fields.map_or(self.identity.initial_attachment_digest, |fields| {
                fields.attachment_digest
            }),
            predecessor_attachment_digest: fields
                .filter(|fields| fields.predecessor_attachment_digest != [0; 32])
                .map(|fields| fields.predecessor_attachment_digest),
            committed_records: u64::try_from(self.records.len()).unwrap_or(u64::MAX),
            committed_wal_bytes: self.committed_wal_bytes,
            committed_head_bytes: self.committed_head_bytes,
            tail: if self.wal_trailing_bytes == 0 && self.head_trailing_bytes == 0 {
                BrokerPaneLeaseWalTailV1::Clean
            } else {
                BrokerPaneLeaseWalTailV1::Incomplete {
                    wal_trailing_bytes: self.wal_trailing_bytes,
                    head_trailing_bytes: self.head_trailing_bytes,
                }
            },
            append_authority_withheld: self.directory_entry_sync_required
                || self.recovery_append_authority_withheld
                || self.head_reconciliation_required
                || self.poisoned
                || self.wal_trailing_bytes != 0
                || self.head_trailing_bytes != 0,
            head_reconciliation_required: self.head_reconciliation_required,
        }
    }

    fn bind_parent_publication(
        &mut self,
        parent_directory: &File,
        wal_name: &OsStr,
        head_name: &OsStr,
    ) -> Result<(), BrokerPaneLeaseWalErrorV1> {
        if !self.directory_entry_sync_required || self.publication_binding.is_some() {
            return Err(BrokerPaneLeaseWalErrorV1::DirectoryEntryNotDurable);
        }
        let parent = parent_directory.metadata()?;
        validate_broker_spawn_catalog_directory_metadata(&parent)
            .map_err(|_| BrokerPaneLeaseWalErrorV1::FilesystemRevalidationMismatch)?;
        revalidate_open_broker_spawn_catalog_file(
            parent_directory,
            wal_name,
            &self.wal,
            BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
            BROKER_LEASE_WAL_MAX_PHYSICAL_BYTES,
        )
        .map_err(|_| BrokerPaneLeaseWalErrorV1::FilesystemRevalidationMismatch)?;
        revalidate_open_broker_spawn_catalog_file(
            parent_directory,
            head_name,
            &self.head,
            BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
            BROKER_LEASE_HEAD_MAX_PHYSICAL_BYTES,
        )
        .map_err(|_| BrokerPaneLeaseWalErrorV1::FilesystemRevalidationMismatch)?;
        self.publication_binding = Some(BrokerSpawnWalPublicationBindingV1 {
            parent_device: parent.dev(),
            parent_inode: parent.ino(),
            wal_name: wal_name.to_os_string(),
            head_name: head_name.to_os_string(),
        });
        Ok(())
    }

    fn sync_parent_directory_and_activate(
        &mut self,
        parent_directory: &File,
    ) -> Result<(), BrokerPaneLeaseWalErrorV1> {
        if !self.directory_entry_sync_required {
            return Ok(());
        }
        let binding = self
            .publication_binding
            .as_ref()
            .ok_or(BrokerPaneLeaseWalErrorV1::DirectoryEntryNotDurable)?;
        let parent = parent_directory.metadata()?;
        validate_broker_spawn_catalog_directory_metadata(&parent)
            .map_err(|_| BrokerPaneLeaseWalErrorV1::FilesystemRevalidationMismatch)?;
        if parent.dev() != binding.parent_device || parent.ino() != binding.parent_inode {
            return Err(BrokerPaneLeaseWalErrorV1::FilesystemRevalidationMismatch);
        }
        revalidate_open_broker_spawn_catalog_file(
            parent_directory,
            &binding.wal_name,
            &self.wal,
            BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
            BROKER_LEASE_WAL_MAX_PHYSICAL_BYTES,
        )
        .map_err(|_| BrokerPaneLeaseWalErrorV1::FilesystemRevalidationMismatch)?;
        revalidate_open_broker_spawn_catalog_file(
            parent_directory,
            &binding.head_name,
            &self.head,
            BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
            BROKER_LEASE_HEAD_MAX_PHYSICAL_BYTES,
        )
        .map_err(|_| BrokerPaneLeaseWalErrorV1::FilesystemRevalidationMismatch)?;
        parent_directory.sync_all()?;
        self.directory_entry_sync_required = false;
        self.publication_binding = None;
        Ok(())
    }

    fn fence_predecessor_and_sync(
        &mut self,
        predecessor: BrokerAttachmentIdentityV1,
        next_generation: u64,
        recovery_verifier: BrokerPaneRecoveryVerifierV1,
    ) -> Result<BrokerPaneLeaseWalReceiptV1, BrokerPaneLeaseWalErrorV1> {
        validate_broker_lease_attachment_for_spawn(predecessor, self.identity.spawn)?;
        if predecessor
            .lease_generation
            .checked_add(1)
            .ok_or(BrokerPaneLeaseWalErrorV1::CapacityExhausted)?
            != next_generation
        {
            return Err(BrokerPaneLeaseWalErrorV1::InvalidIdentity);
        }
        let fields = BrokerPaneLeaseWalRecordFieldsV1 {
            phase: BrokerPaneLeaseWalPhaseV1::PredecessorFenced,
            handoff_id: Uuid::nil(),
            ack_id: Uuid::nil(),
            predecessor_attachment_id: predecessor.attachment_id,
            successor_attachment_id: Uuid::nil(),
            lease_generation: next_generation,
            owner: predecessor.owner,
            recovery_verifier,
            attachment_digest: broker_lease_attachment_digest(predecessor)?,
            predecessor_attachment_digest: [0; 32],
        };
        self.append_or_recover_exact(&fields)
    }

    fn claim_successor_and_sync(
        &mut self,
        handoff_id: Uuid,
        predecessor: BrokerAttachmentIdentityV1,
        successor: BrokerAttachmentIdentityV1,
        successor_recovery_verifier: BrokerPaneRecoveryVerifierV1,
    ) -> Result<BrokerPaneLeaseWalReceiptV1, BrokerPaneLeaseWalErrorV1> {
        if handoff_id.is_nil() {
            return Err(BrokerPaneLeaseWalErrorV1::InvalidIdentity);
        }
        validate_broker_lease_attachment_for_spawn(predecessor, self.identity.spawn)?;
        validate_broker_lease_attachment_for_spawn(successor, self.identity.spawn)?;
        if predecessor
            .lease_generation
            .checked_add(1)
            .ok_or(BrokerPaneLeaseWalErrorV1::CapacityExhausted)?
            != successor.lease_generation
        {
            return Err(BrokerPaneLeaseWalErrorV1::InvalidIdentity);
        }
        let fields = BrokerPaneLeaseWalRecordFieldsV1 {
            phase: BrokerPaneLeaseWalPhaseV1::SuccessorClaimed,
            handoff_id,
            ack_id: Uuid::nil(),
            predecessor_attachment_id: predecessor.attachment_id,
            successor_attachment_id: successor.attachment_id,
            lease_generation: successor.lease_generation,
            owner: successor.owner,
            recovery_verifier: successor_recovery_verifier,
            attachment_digest: broker_lease_attachment_digest(successor)?,
            predecessor_attachment_digest: broker_lease_attachment_digest(predecessor)?,
        };
        self.append_or_recover_exact(&fields)
    }

    fn acknowledge_successor_and_sync(
        &mut self,
        handoff_id: Uuid,
        ack_id: Uuid,
        predecessor: BrokerAttachmentIdentityV1,
        successor: BrokerAttachmentIdentityV1,
        successor_recovery_verifier: BrokerPaneRecoveryVerifierV1,
    ) -> Result<BrokerPaneLeaseWalReceiptV1, BrokerPaneLeaseWalErrorV1> {
        if handoff_id.is_nil() || ack_id.is_nil() {
            return Err(BrokerPaneLeaseWalErrorV1::InvalidIdentity);
        }
        validate_broker_lease_attachment_for_spawn(predecessor, self.identity.spawn)?;
        validate_broker_lease_attachment_for_spawn(successor, self.identity.spawn)?;
        if predecessor
            .lease_generation
            .checked_add(1)
            .ok_or(BrokerPaneLeaseWalErrorV1::CapacityExhausted)?
            != successor.lease_generation
        {
            return Err(BrokerPaneLeaseWalErrorV1::InvalidIdentity);
        }
        let fields = BrokerPaneLeaseWalRecordFieldsV1 {
            phase: BrokerPaneLeaseWalPhaseV1::SuccessorAcknowledged,
            handoff_id,
            ack_id,
            predecessor_attachment_id: predecessor.attachment_id,
            successor_attachment_id: successor.attachment_id,
            lease_generation: successor.lease_generation,
            owner: successor.owner,
            recovery_verifier: successor_recovery_verifier,
            attachment_digest: broker_lease_attachment_digest(successor)?,
            predecessor_attachment_digest: broker_lease_attachment_digest(predecessor)?,
        };
        self.append_or_recover_exact(&fields)
    }

    fn append_or_recover_exact(
        &mut self,
        fields: &BrokerPaneLeaseWalRecordFieldsV1,
    ) -> Result<BrokerPaneLeaseWalReceiptV1, BrokerPaneLeaseWalErrorV1> {
        validate_broker_lease_record_fields(fields)?;
        if let Some(existing) = self.records.iter().find(|record| record.fields == *fields) {
            return Ok(existing.receipt);
        }
        let conflicts_with_generation = self.records.iter().any(|record| {
            record.fields.phase == fields.phase
                && record.fields.lease_generation == fields.lease_generation
        });
        if conflicts_with_generation {
            return Err(BrokerPaneLeaseWalErrorV1::EffectIdentityConflict);
        }
        self.append_fields_and_head(fields)
    }

    fn append_fields_and_head(
        &mut self,
        fields: &BrokerPaneLeaseWalRecordFieldsV1,
    ) -> Result<BrokerPaneLeaseWalReceiptV1, BrokerPaneLeaseWalErrorV1> {
        self.require_append_authority()?;
        let previous = self.records.last();
        validate_broker_lease_record_transition(
            &self.identity,
            previous.map(|record| &record.fields),
            fields,
        )?;
        let sequence = u64::try_from(self.records.len())
            .map_err(|_| BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
        let previous_record_mac =
            previous.map_or(self.header_mac, |record| record.receipt.record_mac);
        let wal_record = encode_broker_lease_wal_record(
            self.header_mac,
            &self.authenticator,
            sequence,
            fields,
            previous_record_mac,
        )?;
        let record_mac = read_broker_array_32(&wal_record[336..368]);
        let head_record = encode_broker_lease_head_record(
            self.head_header_mac,
            &self.authenticator,
            sequence,
            record_mac,
            self.terminal_head_mac,
        )?;
        let projected_wal_bytes = self
            .committed_wal_bytes
            .checked_add(BROKER_LEASE_WAL_RECORD_BYTES_U64)
            .ok_or(BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
        let projected_head_bytes = self
            .committed_head_bytes
            .checked_add(BROKER_LEASE_HEAD_RECORD_BYTES_U64)
            .ok_or(BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
        if self.wal.metadata()?.len() != self.committed_wal_bytes
            || self.head.metadata()?.len() != self.committed_head_bytes
        {
            self.poisoned = true;
            return Err(BrokerPaneLeaseWalErrorV1::ExternalLengthChange);
        }
        #[cfg(test)]
        if self.take_fault(BrokerPaneLeaseWalInjectedFaultV1::BeforeWalWrite) {
            return Err(BrokerPaneLeaseWalErrorV1::Io(std::io::Error::other(
                "injected broker pane-lease WAL fault before write",
            )));
        }
        let result = (|| -> Result<(), BrokerPaneLeaseWalErrorV1> {
            self.wal.seek(SeekFrom::Start(self.committed_wal_bytes))?;
            self.wal.write_all(&wal_record)?;
            self.wal.sync_all()?;
            #[cfg(test)]
            if self.take_fault(BrokerPaneLeaseWalInjectedFaultV1::AfterWalSyncBeforeHead) {
                return Err(BrokerPaneLeaseWalErrorV1::Io(std::io::Error::other(
                    "injected broker pane-lease WAL fault after WAL sync",
                )));
            }
            self.head.seek(SeekFrom::Start(self.committed_head_bytes))?;
            self.head.write_all(&head_record)?;
            #[cfg(test)]
            if self.take_fault(BrokerPaneLeaseWalInjectedFaultV1::BeforeHeadSync) {
                return Err(BrokerPaneLeaseWalErrorV1::Io(std::io::Error::other(
                    "injected broker pane-lease WAL fault before head sync",
                )));
            }
            self.head.sync_all()?;
            Ok(())
        })();
        if let Err(error) = result {
            self.poisoned = true;
            return Err(error);
        }
        let head_mac = read_broker_array_32(&head_record[88..120]);
        let receipt = BrokerPaneLeaseWalReceiptV1 {
            sequence,
            phase: fields.phase,
            committed_wal_bytes: projected_wal_bytes,
            committed_head_bytes: projected_head_bytes,
            record_mac,
            head_mac,
        };
        self.records.push(BrokerPaneLeaseWalRecordStateV1 {
            fields: *fields,
            receipt,
        });
        self.committed_wal_bytes = projected_wal_bytes;
        self.committed_head_bytes = projected_head_bytes;
        self.terminal_head_mac = head_mac;
        Ok(receipt)
    }

    fn require_healthy_for_recovery(&self) -> Result<(), BrokerPaneLeaseWalErrorV1> {
        if self.poisoned {
            return Err(BrokerPaneLeaseWalErrorV1::Poisoned);
        }
        if self.directory_entry_sync_required {
            return Err(BrokerPaneLeaseWalErrorV1::DirectoryEntryNotDurable);
        }
        if self.wal_trailing_bytes != 0
            || (self.head_trailing_bytes != 0 && !self.head_reconciliation_required)
        {
            return Err(BrokerPaneLeaseWalErrorV1::IncompleteTail);
        }
        Ok(())
    }

    fn require_append_authority(&self) -> Result<(), BrokerPaneLeaseWalErrorV1> {
        self.require_healthy_for_recovery()?;
        if self.recovery_append_authority_withheld || self.head_reconciliation_required {
            return Err(BrokerPaneLeaseWalErrorV1::RecoveryAuthorityUnavailable);
        }
        if self.records.len()
            >= usize::try_from(BROKER_LEASE_WAL_MAX_RECORDS)
                .map_err(|_| BrokerPaneLeaseWalErrorV1::CapacityExhausted)?
        {
            return Err(BrokerPaneLeaseWalErrorV1::CapacityExhausted);
        }
        Ok(())
    }

    fn reconcile_recovered_head_and_activate(
        &mut self,
        authority: BrokerPaneLeaseWalFilesystemRevalidationV1,
    ) -> Result<(), BrokerPaneLeaseWalErrorV1> {
        let activation = self.preflight_recovered_head_activation(
            authority,
            BrokerPaneLeaseWalRecoveredAuthorityV1::ActivateAppend,
        )?;
        self.apply_recovered_head_activation(activation)
    }

    fn preflight_recovered_head_activation(
        &self,
        authority: BrokerPaneLeaseWalFilesystemRevalidationV1,
        recovered_authority: BrokerPaneLeaseWalRecoveredAuthorityV1,
    ) -> Result<BrokerPaneLeaseWalRecoveryActivationV1, BrokerPaneLeaseWalErrorV1> {
        self.require_healthy_for_recovery()?;
        if authority.identity != self.identity {
            return Err(BrokerPaneLeaseWalErrorV1::FilesystemRevalidationMismatch);
        }
        let authoritative_lengths = (authority.observed_wal_bytes, authority.observed_head_bytes);
        let recovered_lengths = (
            self.committed_wal_bytes,
            self.committed_head_bytes
                .checked_add(self.head_trailing_bytes)
                .ok_or(BrokerPaneLeaseWalErrorV1::CapacityExhausted)?,
        );
        if authoritative_lengths != recovered_lengths
            || (self.wal.metadata()?.len(), self.head.metadata()?.len()) != authoritative_lengths
        {
            return Err(BrokerPaneLeaseWalErrorV1::FilesystemRevalidationMismatch);
        }
        let head = if self.head_reconciliation_required {
            let record = self
                .records
                .last()
                .copied()
                .ok_or(BrokerPaneLeaseWalErrorV1::HeadAnchorMismatch)?;
            let sequence = u64::try_from(
                self.records
                    .len()
                    .checked_sub(1)
                    .ok_or(BrokerPaneLeaseWalErrorV1::HeadAnchorMismatch)?,
            )
            .map_err(|_| BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
            if record.receipt.sequence != sequence {
                return Err(BrokerPaneLeaseWalErrorV1::SequenceMismatch);
            }
            let encoded = encode_broker_lease_head_record(
                self.head_header_mac,
                &self.authenticator,
                sequence,
                record.receipt.record_mac,
                self.terminal_head_mac,
            )?;
            let durable_prefix_bytes = usize::try_from(self.head_trailing_bytes)
                .map_err(|_| BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
            if durable_prefix_bytes >= BROKER_LEASE_HEAD_RECORD_BYTES {
                return Err(BrokerPaneLeaseWalErrorV1::IncompleteTail);
            }
            Some(BrokerPaneLeaseWalHeadReconciliationV1 {
                encoded,
                durable_prefix_bytes,
                projected_head_bytes: self
                    .committed_head_bytes
                    .checked_add(BROKER_LEASE_HEAD_RECORD_BYTES_U64)
                    .ok_or(BrokerPaneLeaseWalErrorV1::CapacityExhausted)?,
                head_mac: read_broker_array_32(&encoded[88..120]),
            })
        } else {
            None
        };
        Ok(BrokerPaneLeaseWalRecoveryActivationV1 {
            authority,
            head,
            recovered_authority,
        })
    }

    fn apply_recovered_head_activation(
        &mut self,
        activation: BrokerPaneLeaseWalRecoveryActivationV1,
    ) -> Result<(), BrokerPaneLeaseWalErrorV1> {
        self.require_healthy_for_recovery()?;
        if activation.authority.identity != self.identity {
            return Err(BrokerPaneLeaseWalErrorV1::FilesystemRevalidationMismatch);
        }
        let authoritative_lengths = (
            activation.authority.observed_wal_bytes,
            activation.authority.observed_head_bytes,
        );
        let recovered_lengths = (
            self.committed_wal_bytes,
            self.committed_head_bytes
                .checked_add(self.head_trailing_bytes)
                .ok_or(BrokerPaneLeaseWalErrorV1::CapacityExhausted)?,
        );
        if authoritative_lengths != recovered_lengths
            || (self.wal.metadata()?.len(), self.head.metadata()?.len()) != authoritative_lengths
        {
            return Err(BrokerPaneLeaseWalErrorV1::FilesystemRevalidationMismatch);
        }
        match (self.head_reconciliation_required, activation.head) {
            (true, Some(head)) => {
                let result = (|| -> Result<(), BrokerPaneLeaseWalErrorV1> {
                    let write_offset = self
                        .committed_head_bytes
                        .checked_add(self.head_trailing_bytes)
                        .ok_or(BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
                    self.head.seek(SeekFrom::Start(write_offset))?;
                    #[cfg(test)]
                    if self.take_fault(BrokerPaneLeaseWalInjectedFaultV1::DuringRecoveredHeadWrite)
                    {
                        let remaining = &head.encoded[head.durable_prefix_bytes..];
                        let prefix_bytes = remaining.len().min(37);
                        self.head.write_all(&remaining[..prefix_bytes])?;
                        self.head.sync_all()?;
                        return Err(BrokerPaneLeaseWalErrorV1::Io(std::io::Error::other(
                            "injected partial broker pane-lease recovered-head write",
                        )));
                    }
                    self.head
                        .write_all(&head.encoded[head.durable_prefix_bytes..])?;
                    self.head.sync_all()?;
                    Ok(())
                })();
                if let Err(error) = result {
                    self.poisoned = true;
                    return Err(error);
                }
                let terminal = self
                    .records
                    .last_mut()
                    .ok_or(BrokerPaneLeaseWalErrorV1::HeadAnchorMismatch)?;
                self.committed_head_bytes = head.projected_head_bytes;
                self.head_trailing_bytes = 0;
                self.terminal_head_mac = head.head_mac;
                terminal.receipt.head_mac = head.head_mac;
                terminal.receipt.committed_head_bytes = self.committed_head_bytes;
                self.head_reconciliation_required = false;
            }
            (false, None) => {}
            _ => return Err(BrokerPaneLeaseWalErrorV1::FilesystemRevalidationMismatch),
        }
        self.recovery_append_authority_withheld = matches!(
            activation.recovered_authority,
            BrokerPaneLeaseWalRecoveredAuthorityV1::RetainWithheld
        );
        Ok(())
    }

    #[cfg(test)]
    fn inject_fault(&mut self, fault: BrokerPaneLeaseWalInjectedFaultV1) {
        self.injected_fault = Some(fault);
    }

    #[cfg(test)]
    fn take_fault(&mut self, fault: BrokerPaneLeaseWalInjectedFaultV1) -> bool {
        if self.injected_fault == Some(fault) {
            self.injected_fault = None;
            true
        } else {
            false
        }
    }
}

impl BrokerPaneLeaseWalFilesystemRevalidationV1 {
    fn from_revalidated_filesystem(
        identity: &BrokerPaneLeaseWalIdentityV1,
        observed_wal_bytes: u64,
        observed_head_bytes: u64,
    ) -> Result<Self, BrokerPaneLeaseWalErrorV1> {
        identity.validate()?;
        if !(BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64..=BROKER_LEASE_WAL_MAX_PHYSICAL_BYTES)
            .contains(&observed_wal_bytes)
            || !(BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64..=BROKER_LEASE_HEAD_MAX_PHYSICAL_BYTES)
                .contains(&observed_head_bytes)
        {
            return Err(BrokerPaneLeaseWalErrorV1::FilesystemRevalidationMismatch);
        }
        Ok(Self {
            identity: *identity,
            observed_wal_bytes,
            observed_head_bytes,
        })
    }
}

fn validate_broker_lease_creation_prefix(
    file: &mut File,
    expected: &[u8; BROKER_LEASE_WAL_FILE_HEADER_BYTES],
) -> Result<usize, BrokerPaneLeaseWalErrorV1> {
    let observed_bytes = usize::try_from(file.metadata()?.len())
        .map_err(|_| BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
    if observed_bytes > expected.len() {
        return Err(BrokerPaneLeaseWalErrorV1::InvalidCreationState);
    }
    let mut observed = [0_u8; BROKER_LEASE_WAL_FILE_HEADER_BYTES];
    file.seek(SeekFrom::Start(0))?;
    file.read_exact(&mut observed[..observed_bytes])?;
    if observed[..observed_bytes] != expected[..observed_bytes] {
        return Err(BrokerPaneLeaseWalErrorV1::CreationMarkerMismatch);
    }
    Ok(observed_bytes)
}

fn read_broker_lease_creation_marker(
    marker: &mut File,
    authenticator: &GuardianBrokerLeaseWalAuthenticatorV1,
) -> Result<BrokerPaneLeaseWalIdentityV1, BrokerPaneLeaseWalErrorV1> {
    if marker.metadata()?.len() != BROKER_LEASE_CREATION_MARKER_BYTES {
        return Err(BrokerPaneLeaseWalErrorV1::IncompleteTail);
    }
    marker.seek(SeekFrom::Start(0))?;
    let mut encoded = [0_u8; BROKER_LEASE_WAL_FILE_HEADER_BYTES];
    marker.read_exact(&mut encoded)?;
    marker.rewind()?;
    decode_broker_lease_file_header(&encoded, BROKER_LEASE_CREATION_MARKER_MAGIC, authenticator)
        .map(|(identity, _)| identity)
}

fn validate_broker_lease_catalog_identities(
    identities: &[BrokerPaneLeaseWalIdentityV1],
    authenticator: &GuardianBrokerLeaseWalAuthenticatorV1,
) -> Result<(), BrokerPaneLeaseWalErrorV1> {
    if identities.len() > GUARDIAN_MAX_PANES {
        return Err(BrokerPaneLeaseWalErrorV1::CapacityExhausted);
    }
    let mut journal_ids = HashSet::new();
    let mut pane_ids = HashSet::new();
    let mut effect_ids = HashSet::new();
    let mut child_nonces = HashSet::new();
    let mut kernel_births = HashSet::new();
    for index in [
        &mut journal_ids,
        &mut pane_ids,
        &mut effect_ids,
        &mut child_nonces,
    ] {
        index
            .try_reserve(identities.len())
            .map_err(|_| BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
    }
    kernel_births
        .try_reserve(identities.len())
        .map_err(|_| BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
    for identity in identities {
        identity.validate()?;
        if identity.spawn.broker_lineage_id() != authenticator.lineage_id() {
            return Err(BrokerPaneLeaseWalErrorV1::LineageMismatch);
        }
        if !journal_ids.insert(identity.spawn.journal_id())
            || !pane_ids.insert(identity.spawn.durable_pane_id())
            || !effect_ids.insert(identity.spawn.spawn_effect_id())
            || !child_nonces.insert(identity.child_identity.broker_child_nonce())
            || !kernel_births.insert((
                identity.child_identity.process_id(),
                identity.child_identity.kernel_start_identity_digest(),
            ))
        {
            return Err(BrokerPaneLeaseWalErrorV1::EffectIdentityConflict);
        }
    }
    Ok(())
}

impl BrokerPaneLeaseWalCatalogV1 {
    fn open(directory_path: PathBuf) -> Result<Self, BrokerPaneLeaseWalErrorV1> {
        validate_broker_spawn_catalog_path(&directory_path)?;
        let before = std::fs::symlink_metadata(&directory_path)?;
        validate_broker_spawn_catalog_directory_metadata(&before)?;
        let directory = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_CLOEXEC | libc::O_DIRECTORY | libc::O_NOFOLLOW)
            .open(&directory_path)?;
        let opened = directory.metadata()?;
        validate_broker_spawn_catalog_directory_metadata(&opened)?;
        require_same_broker_spawn_catalog_object(&before, &opened)?;
        let after = std::fs::symlink_metadata(&directory_path)?;
        require_same_broker_spawn_catalog_object(&opened, &after)?;
        validate_broker_lease_catalog_name_capacity(&directory)?;

        let lock_name = OsStr::new(BROKER_LEASE_CATALOG_LOCK_NAME);
        let (lock, created) = match open_broker_spawn_catalog_file_at(&directory, lock_name, true) {
            Ok(lock) => (lock, true),
            Err(error) if error.kind() == ErrorKind::AlreadyExists => (
                open_and_seal_broker_spawn_creation_file_mode_at(&directory, lock_name, 0, 0)?,
                false,
            ),
            Err(error) => return Err(error.into()),
        };
        if created {
            revalidate_open_broker_spawn_catalog_file(&directory, lock_name, &lock, 0, 0)?;
            lock.sync_all()?;
            directory.sync_all()?;
        }
        lock_broker_spawn_catalog(&lock)?;
        let catalog = Self {
            directory_path,
            directory,
            lock,
        };
        catalog.validate_pinned_directory()?;
        catalog.scan_states()?;
        Ok(catalog)
    }

    fn validate_pinned_directory(&self) -> Result<(), BrokerPaneLeaseWalErrorV1> {
        validate_broker_spawn_catalog_path(&self.directory_path)?;
        let opened = self.directory.metadata()?;
        validate_broker_spawn_catalog_directory_metadata(&opened)?;
        let named = std::fs::symlink_metadata(&self.directory_path)?;
        validate_broker_spawn_catalog_directory_metadata(&named)?;
        require_same_broker_spawn_catalog_object(&opened, &named)?;
        revalidate_open_broker_spawn_catalog_file(
            &self.directory,
            OsStr::new(BROKER_LEASE_CATALOG_LOCK_NAME),
            &self.lock,
            0,
            0,
        )?;
        Ok(())
    }

    fn scan_states(
        &self,
    ) -> Result<BTreeMap<Uuid, BrokerPaneLeaseWalCatalogPairV1>, BrokerPaneLeaseWalErrorV1> {
        self.validate_pinned_directory()?;
        let mut directory =
            rustix::fs::Dir::read_from(&self.directory).map_err(std::io::Error::from)?;
        let mut pairs = BTreeMap::<Uuid, BrokerPaneLeaseWalCatalogPairV1>::new();
        let mut observed_entries = 0_usize;
        let mut observed_bytes = 0_u64;
        while let Some(entry) = directory.read() {
            let entry = entry.map_err(std::io::Error::from)?;
            let raw_name = entry.file_name().to_bytes();
            if raw_name == b"." || raw_name == b".." {
                continue;
            }
            observed_entries = observed_entries
                .checked_add(1)
                .ok_or(BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
            if observed_entries > BROKER_LEASE_CATALOG_MAX_ENTRIES {
                return Err(BrokerPaneLeaseWalErrorV1::CapacityExhausted);
            }
            let name = OsStr::from_bytes(raw_name);
            if name == OsStr::new(BROKER_LEASE_CATALOG_LOCK_NAME) {
                let lock = broker_spawn_catalog_stat_identity_at(&self.directory, name, 0, 0)?;
                observed_bytes = observed_bytes
                    .checked_add(lock.bytes)
                    .ok_or(BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
                continue;
            }
            let (journal_id, maximum_bytes) = match parse_broker_lease_catalog_name(name)? {
                BrokerPaneLeaseCatalogMemberV1::Wal(journal_id) => {
                    let pair = pairs.entry(journal_id).or_default();
                    if pair.wal_name.replace(name.to_os_string()).is_some() {
                        return Err(BrokerPaneLeaseWalErrorV1::UnexpectedCatalogEntry);
                    }
                    (journal_id, BROKER_LEASE_WAL_MAX_PHYSICAL_BYTES)
                }
                BrokerPaneLeaseCatalogMemberV1::Head(journal_id) => {
                    let pair = pairs.entry(journal_id).or_default();
                    if pair.head_name.replace(name.to_os_string()).is_some() {
                        return Err(BrokerPaneLeaseWalErrorV1::UnexpectedCatalogEntry);
                    }
                    (journal_id, BROKER_LEASE_HEAD_MAX_PHYSICAL_BYTES)
                }
                BrokerPaneLeaseCatalogMemberV1::Creating(journal_id) => {
                    let pair = pairs.entry(journal_id).or_default();
                    if pair.creating_name.replace(name.to_os_string()).is_some() {
                        return Err(BrokerPaneLeaseWalErrorV1::InvalidCreationState);
                    }
                    (journal_id, BROKER_LEASE_CREATION_MARKER_BYTES)
                }
                BrokerPaneLeaseCatalogMemberV1::Completed(journal_id) => {
                    let pair = pairs.entry(journal_id).or_default();
                    if pair.completed_name.replace(name.to_os_string()).is_some() {
                        return Err(BrokerPaneLeaseWalErrorV1::InvalidCreationState);
                    }
                    (journal_id, BROKER_LEASE_CREATION_MARKER_BYTES)
                }
            };
            debug_assert!(pairs.contains_key(&journal_id));
            let identity = broker_spawn_catalog_stat_recoverable_creation_identity_at(
                &self.directory,
                name,
                0,
                maximum_bytes,
            )?;
            observed_bytes = observed_bytes
                .checked_add(identity.bytes)
                .ok_or(BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
        }
        if pairs.len() > GUARDIAN_MAX_PANES
            || observed_bytes > BROKER_LEASE_CATALOG_MAX_PHYSICAL_BYTES
        {
            return Err(BrokerPaneLeaseWalErrorV1::CapacityExhausted);
        }
        for pair in pairs.values() {
            if pair.creating_name.is_some() && pair.completed_name.is_some() {
                return Err(BrokerPaneLeaseWalErrorV1::InvalidCreationState);
            }
            if let Some(creating_name) = pair.creating_name.as_ref() {
                broker_spawn_catalog_stat_recoverable_creation_identity_at(
                    &self.directory,
                    creating_name,
                    0,
                    BROKER_LEASE_CREATION_MARKER_BYTES,
                )?;
                if let Some(wal_name) = pair.wal_name.as_ref() {
                    broker_spawn_catalog_stat_recoverable_creation_identity_at(
                        &self.directory,
                        wal_name,
                        0,
                        BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
                    )?;
                }
                if let Some(head_name) = pair.head_name.as_ref() {
                    broker_spawn_catalog_stat_recoverable_creation_identity_at(
                        &self.directory,
                        head_name,
                        0,
                        BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
                    )?;
                }
                continue;
            }
            let completed_name = pair
                .completed_name
                .as_ref()
                .ok_or(BrokerPaneLeaseWalErrorV1::IncompleteCatalogPair)?;
            let wal_name = pair
                .wal_name
                .as_ref()
                .ok_or(BrokerPaneLeaseWalErrorV1::IncompleteCatalogPair)?;
            let head_name = pair
                .head_name
                .as_ref()
                .ok_or(BrokerPaneLeaseWalErrorV1::IncompleteCatalogPair)?;
            broker_spawn_catalog_stat_identity_at(
                &self.directory,
                completed_name,
                BROKER_LEASE_CREATION_MARKER_BYTES,
                BROKER_LEASE_CREATION_MARKER_BYTES,
            )?;
            broker_spawn_catalog_stat_identity_at(
                &self.directory,
                wal_name,
                BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
                BROKER_LEASE_WAL_MAX_PHYSICAL_BYTES,
            )?;
            broker_spawn_catalog_stat_identity_at(
                &self.directory,
                head_name,
                BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
                BROKER_LEASE_HEAD_MAX_PHYSICAL_BYTES,
            )?;
        }
        Ok(pairs)
    }

    fn materialize_exact_header(
        &self,
        existing: Option<File>,
        name: &OsStr,
        expected: &[u8; BROKER_LEASE_WAL_FILE_HEADER_BYTES],
    ) -> Result<File, BrokerPaneLeaseWalErrorV1> {
        let mut file = if let Some(file) = existing {
            file
        } else {
            let file = open_broker_spawn_catalog_file_at(&self.directory, name, true)?;
            revalidate_open_broker_spawn_catalog_file(&self.directory, name, &file, 0, 0)?;
            file
        };
        let durable_prefix = validate_broker_lease_creation_prefix(&mut file, expected)?;
        file.seek(SeekFrom::Start(
            u64::try_from(durable_prefix)
                .map_err(|_| BrokerPaneLeaseWalErrorV1::CapacityExhausted)?,
        ))?;
        file.write_all(&expected[durable_prefix..])?;
        file.sync_all()?;
        let exact = open_and_seal_broker_spawn_creation_file_mode_at(
            &self.directory,
            name,
            BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
            BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
        )?;
        revalidate_open_broker_spawn_catalog_file(
            &self.directory,
            name,
            &exact,
            BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
            BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
        )?;
        Ok(exact)
    }

    fn open_completed_pair(
        &self,
        journal_id: Uuid,
        pair: &BrokerPaneLeaseWalCatalogPairV1,
        authenticator: GuardianBrokerLeaseWalAuthenticatorV1,
    ) -> Result<BrokerPaneLeaseJournalV1, BrokerPaneLeaseWalErrorV1> {
        let completed_name = pair
            .completed_name
            .as_ref()
            .ok_or(BrokerPaneLeaseWalErrorV1::IncompleteCatalogPair)?;
        let wal_name = pair
            .wal_name
            .as_ref()
            .ok_or(BrokerPaneLeaseWalErrorV1::IncompleteCatalogPair)?;
        let head_name = pair
            .head_name
            .as_ref()
            .ok_or(BrokerPaneLeaseWalErrorV1::IncompleteCatalogPair)?;
        let mut marker = open_revalidated_broker_spawn_catalog_file(
            &self.directory,
            completed_name,
            BROKER_LEASE_CREATION_MARKER_BYTES,
            BROKER_LEASE_CREATION_MARKER_BYTES,
        )?;
        let identity = read_broker_lease_creation_marker(&mut marker, &authenticator)?;
        if identity.spawn.journal_id() != journal_id
            || *completed_name != broker_lease_catalog_completed_name(journal_id)
        {
            return Err(BrokerPaneLeaseWalErrorV1::CreationMarkerMismatch);
        }
        let wal = open_revalidated_broker_spawn_catalog_file(
            &self.directory,
            wal_name,
            BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
            BROKER_LEASE_WAL_MAX_PHYSICAL_BYTES,
        )?;
        let head = open_revalidated_broker_spawn_catalog_file(
            &self.directory,
            head_name,
            BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
            BROKER_LEASE_HEAD_MAX_PHYSICAL_BYTES,
        )?;
        let journal = BrokerPaneLeaseJournalV1::open(wal, head, &identity, authenticator)?;
        journal.require_healthy_for_recovery()?;
        revalidate_open_broker_spawn_catalog_file(
            &self.directory,
            completed_name,
            &marker,
            BROKER_LEASE_CREATION_MARKER_BYTES,
            BROKER_LEASE_CREATION_MARKER_BYTES,
        )?;
        Ok(journal)
    }

    fn complete_creation(
        &self,
        identity: &BrokerPaneLeaseWalIdentityV1,
        pair: &BrokerPaneLeaseWalCatalogPairV1,
        authenticator: GuardianBrokerLeaseWalAuthenticatorV1,
    ) -> Result<BrokerPaneLeaseJournalV1, BrokerPaneLeaseWalErrorV1> {
        let journal_id = identity.spawn.journal_id();
        let creating_name = pair
            .creating_name
            .as_ref()
            .ok_or(BrokerPaneLeaseWalErrorV1::InvalidCreationState)?;
        if *creating_name != broker_lease_catalog_creating_name(journal_id)
            || pair.completed_name.is_some()
        {
            return Err(BrokerPaneLeaseWalErrorV1::InvalidCreationState);
        }
        let marker_header = encode_broker_lease_file_header(
            BROKER_LEASE_CREATION_MARKER_MAGIC,
            identity,
            &authenticator,
        )?;
        let wal_header =
            encode_broker_lease_file_header(BROKER_LEASE_WAL_FILE_MAGIC, identity, &authenticator)?;
        let head_header = encode_broker_lease_file_header(
            BROKER_LEASE_HEAD_FILE_MAGIC,
            identity,
            &authenticator,
        )?;
        let marker = open_and_seal_broker_spawn_creation_file_mode_at(
            &self.directory,
            creating_name,
            0,
            BROKER_LEASE_CREATION_MARKER_BYTES,
        )?;
        let wal = pair
            .wal_name
            .as_ref()
            .map(|name| {
                open_and_seal_broker_spawn_creation_file_mode_at(
                    &self.directory,
                    name,
                    0,
                    BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
                )
            })
            .transpose()?;
        let head = pair
            .head_name
            .as_ref()
            .map(|name| {
                open_and_seal_broker_spawn_creation_file_mode_at(
                    &self.directory,
                    name,
                    0,
                    BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
                )
            })
            .transpose()?;
        let marker = self.materialize_exact_header(Some(marker), creating_name, &marker_header)?;
        self.directory.sync_all()?;
        let wal_name = broker_lease_catalog_wal_name(journal_id);
        let head_name = broker_lease_catalog_head_name(journal_id);
        let wal = self.materialize_exact_header(wal, &wal_name, &wal_header)?;
        let head = self.materialize_exact_header(head, &head_name, &head_header)?;
        self.directory.sync_all()?;
        revalidate_open_broker_spawn_catalog_file(
            &self.directory,
            &wal_name,
            &wal,
            BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
            BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
        )?;
        revalidate_open_broker_spawn_catalog_file(
            &self.directory,
            &head_name,
            &head,
            BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
            BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
        )?;
        let completed_name = broker_lease_catalog_completed_name(journal_id);
        publish_broker_spawn_completed_marker_noreplace(
            &self.directory,
            creating_name,
            &completed_name,
        )?;
        revalidate_open_broker_spawn_catalog_file(
            &self.directory,
            &completed_name,
            &marker,
            BROKER_LEASE_CREATION_MARKER_BYTES,
            BROKER_LEASE_CREATION_MARKER_BYTES,
        )?;
        self.directory.sync_all()?;
        let states = self.scan_states()?;
        let completed = states
            .get(&journal_id)
            .ok_or(BrokerPaneLeaseWalErrorV1::InvalidCreationState)?;
        self.open_completed_pair(journal_id, completed, authenticator)
    }

    fn recover_creation_transactions(
        &self,
        authenticator: &GuardianBrokerLeaseWalAuthenticatorV1,
    ) -> Result<(), BrokerPaneLeaseWalErrorV1> {
        let states = self.scan_states()?;
        if states.values().all(|pair| pair.creating_name.is_none()) {
            return Ok(());
        }

        let mut identities = Vec::new();
        identities
            .try_reserve_exact(states.len())
            .map_err(|_| BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
        let mut creating = Vec::new();
        creating
            .try_reserve_exact(states.len())
            .map_err(|_| BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
        for (journal_id, pair) in &states {
            let identity = if let Some(creating_name) = pair.creating_name.as_ref() {
                let marker_identity = broker_spawn_catalog_stat_recoverable_creation_identity_at(
                    &self.directory,
                    creating_name,
                    0,
                    BROKER_LEASE_CREATION_MARKER_BYTES,
                )?;
                if marker_identity.bytes != BROKER_LEASE_CREATION_MARKER_BYTES {
                    return Err(BrokerPaneLeaseWalErrorV1::IncompleteTail);
                }
                let mut marker = open_and_seal_broker_spawn_creation_file_mode_at(
                    &self.directory,
                    creating_name,
                    BROKER_LEASE_CREATION_MARKER_BYTES,
                    BROKER_LEASE_CREATION_MARKER_BYTES,
                )?;
                let identity = read_broker_lease_creation_marker(&mut marker, authenticator)?;
                if identity.spawn.journal_id() != *journal_id
                    || *creating_name != broker_lease_catalog_creating_name(*journal_id)
                {
                    return Err(BrokerPaneLeaseWalErrorV1::CreationMarkerMismatch);
                }
                let wal_header = encode_broker_lease_file_header(
                    BROKER_LEASE_WAL_FILE_MAGIC,
                    &identity,
                    authenticator,
                )?;
                let head_header = encode_broker_lease_file_header(
                    BROKER_LEASE_HEAD_FILE_MAGIC,
                    &identity,
                    authenticator,
                )?;
                if let Some(wal_name) = pair.wal_name.as_ref() {
                    let mut wal = open_and_seal_broker_spawn_creation_file_mode_at(
                        &self.directory,
                        wal_name,
                        0,
                        BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
                    )?;
                    validate_broker_lease_creation_prefix(&mut wal, &wal_header)?;
                }
                if let Some(head_name) = pair.head_name.as_ref() {
                    let mut head = open_and_seal_broker_spawn_creation_file_mode_at(
                        &self.directory,
                        head_name,
                        0,
                        BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
                    )?;
                    validate_broker_lease_creation_prefix(&mut head, &head_header)?;
                }
                creating.push((*journal_id, identity));
                identity
            } else {
                self.open_completed_pair(*journal_id, pair, authenticator.clone())?
                    .identity
            };
            identities.push(identity);
        }
        validate_broker_lease_catalog_identities(&identities, authenticator)?;
        if self.scan_states()? != states {
            return Err(BrokerPaneLeaseWalErrorV1::FilesystemRevalidationMismatch);
        }

        for (journal_id, identity) in creating {
            let current = self.scan_states()?;
            let pair = current
                .get(&journal_id)
                .ok_or(BrokerPaneLeaseWalErrorV1::InvalidCreationState)?;
            drop(self.complete_creation(&identity, pair, authenticator.clone())?);
        }
        self.validate_pinned_directory()
    }

    fn scan_all_for_admission(
        &self,
        authenticator: &GuardianBrokerLeaseWalAuthenticatorV1,
    ) -> Result<Vec<BrokerPaneLeaseJournalV1>, BrokerPaneLeaseWalErrorV1> {
        self.recover_creation_transactions(authenticator)?;
        let states = self.scan_states()?;
        let mut identities = Vec::new();
        identities
            .try_reserve_exact(states.len())
            .map_err(|_| BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
        let mut recovered = Vec::new();
        recovered
            .try_reserve_exact(states.len())
            .map_err(|_| BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
        for (journal_id, pair) in &states {
            debug_assert!(pair.creating_name.is_none());
            let journal = self.open_completed_pair(*journal_id, pair, authenticator.clone())?;
            identities.push(journal.identity);
            recovered.push(journal);
        }
        validate_broker_lease_catalog_identities(&identities, authenticator)?;
        if self.scan_states()? != states {
            return Err(BrokerPaneLeaseWalErrorV1::FilesystemRevalidationMismatch);
        }
        self.validate_pinned_directory()?;
        Ok(recovered)
    }

    /// Reconcile authenticated WAL-ahead crash cuts without restoring the
    /// append authority that died with the previous broker process.
    ///
    /// Every completed marker, retained descriptor, identity, length, and
    /// deterministic head suffix is preflighted before the first content
    /// write. A later I/O failure can leave one exact authenticated head prefix
    /// for the next restart to resume, but it can never make a recovered lease
    /// writable or recreate its lost PTY effect authority.
    fn reconcile_recovered_read_only(
        &self,
        recovered: &mut [BrokerPaneLeaseJournalV1],
    ) -> Result<(), BrokerPaneLeaseWalErrorV1> {
        self.validate_pinned_directory()?;
        let states = self.scan_states()?;
        if states.len() != recovered.len()
            || recovered
                .iter()
                .any(|journal| !states.contains_key(&journal.identity.spawn.journal_id()))
        {
            return Err(BrokerPaneLeaseWalErrorV1::FilesystemRevalidationMismatch);
        }

        let mut activations = Vec::new();
        activations
            .try_reserve_exact(recovered.len())
            .map_err(|_| BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
        for journal in recovered.iter() {
            let journal_id = journal.identity.spawn.journal_id();
            let pair = states
                .get(&journal_id)
                .ok_or(BrokerPaneLeaseWalErrorV1::FilesystemRevalidationMismatch)?;
            let completed_name = pair
                .completed_name
                .as_ref()
                .ok_or(BrokerPaneLeaseWalErrorV1::IncompleteCatalogPair)?;
            let wal_name = pair
                .wal_name
                .as_ref()
                .ok_or(BrokerPaneLeaseWalErrorV1::IncompleteCatalogPair)?;
            let head_name = pair
                .head_name
                .as_ref()
                .ok_or(BrokerPaneLeaseWalErrorV1::IncompleteCatalogPair)?;
            if pair.creating_name.is_some()
                || *completed_name != broker_lease_catalog_completed_name(journal_id)
                || *wal_name != broker_lease_catalog_wal_name(journal_id)
                || *head_name != broker_lease_catalog_head_name(journal_id)
            {
                return Err(BrokerPaneLeaseWalErrorV1::FilesystemRevalidationMismatch);
            }

            let mut marker = open_revalidated_broker_spawn_catalog_file(
                &self.directory,
                completed_name,
                BROKER_LEASE_CREATION_MARKER_BYTES,
                BROKER_LEASE_CREATION_MARKER_BYTES,
            )?;
            let marker_identity =
                read_broker_lease_creation_marker(&mut marker, &journal.authenticator)?;
            if marker_identity != journal.identity {
                return Err(BrokerPaneLeaseWalErrorV1::IdentityMismatch);
            }
            revalidate_open_broker_spawn_catalog_file(
                &self.directory,
                completed_name,
                &marker,
                BROKER_LEASE_CREATION_MARKER_BYTES,
                BROKER_LEASE_CREATION_MARKER_BYTES,
            )?;
            let wal_identity = revalidate_open_broker_spawn_catalog_file(
                &self.directory,
                wal_name,
                &journal.wal,
                BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
                BROKER_LEASE_WAL_MAX_PHYSICAL_BYTES,
            )?;
            let head_identity = revalidate_open_broker_spawn_catalog_file(
                &self.directory,
                head_name,
                &journal.head,
                BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
                BROKER_LEASE_HEAD_MAX_PHYSICAL_BYTES,
            )?;
            let authority = BrokerPaneLeaseWalFilesystemRevalidationV1::from_revalidated_filesystem(
                &journal.identity,
                wal_identity.bytes,
                head_identity.bytes,
            )?;
            activations.push(journal.preflight_recovered_head_activation(
                authority,
                BrokerPaneLeaseWalRecoveredAuthorityV1::RetainWithheld,
            )?);
        }
        if self.scan_states()? != states {
            return Err(BrokerPaneLeaseWalErrorV1::FilesystemRevalidationMismatch);
        }
        self.validate_pinned_directory()?;

        for (journal, activation) in recovered.iter_mut().zip(activations) {
            journal.apply_recovered_head_activation(activation)?;
        }

        for journal in recovered.iter() {
            let status = journal.status();
            if status.head_reconciliation_required || !status.append_authority_withheld {
                return Err(BrokerPaneLeaseWalErrorV1::RecoveryAuthorityUnavailable);
            }
            let journal_id = journal.identity.spawn.journal_id();
            revalidate_open_broker_spawn_catalog_file(
                &self.directory,
                &broker_lease_catalog_wal_name(journal_id),
                &journal.wal,
                BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
                BROKER_LEASE_WAL_MAX_PHYSICAL_BYTES,
            )?;
            revalidate_open_broker_spawn_catalog_file(
                &self.directory,
                &broker_lease_catalog_head_name(journal_id),
                &journal.head,
                BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
                BROKER_LEASE_HEAD_MAX_PHYSICAL_BYTES,
            )?;
        }
        if self.scan_states()? != states {
            return Err(BrokerPaneLeaseWalErrorV1::FilesystemRevalidationMismatch);
        }
        self.validate_pinned_directory()
    }

    fn create_lease_journal(
        &self,
        identity: &BrokerPaneLeaseWalIdentityV1,
        authenticator: GuardianBrokerLeaseWalAuthenticatorV1,
    ) -> Result<BrokerPaneLeaseJournalV1, BrokerPaneLeaseWalErrorV1> {
        identity.validate()?;
        if identity.spawn.broker_lineage_id() != authenticator.lineage_id() {
            return Err(BrokerPaneLeaseWalErrorV1::LineageMismatch);
        }
        let states = self.scan_states()?;
        let journal_id = identity.spawn.journal_id();
        if let Some(pair) = states.get(&journal_id) {
            if pair.completed_name.is_some() {
                let journal = self.open_completed_pair(journal_id, pair, authenticator)?;
                if journal.identity != *identity {
                    return Err(BrokerPaneLeaseWalErrorV1::IdentityMismatch);
                }
                return self.activate_created_journal(journal);
            }
            let mut other_identities = Vec::new();
            for (other_id, other_pair) in &states {
                if other_id == &journal_id {
                    continue;
                }
                if other_pair.creating_name.is_some() {
                    return Err(BrokerPaneLeaseWalErrorV1::InvalidCreationState);
                }
                let other =
                    self.open_completed_pair(*other_id, other_pair, authenticator.clone())?;
                other_identities.push(other.identity);
            }
            other_identities.push(*identity);
            validate_broker_lease_catalog_identities(&other_identities, &authenticator)?;
            let journal = self.complete_creation(identity, pair, authenticator)?;
            return self.activate_created_journal(journal);
        }

        let recovered = self.scan_all_for_admission(&authenticator)?;
        if recovered.len() >= GUARDIAN_MAX_PANES {
            return Err(BrokerPaneLeaseWalErrorV1::CapacityExhausted);
        }
        let mut identities = Vec::new();
        identities
            .try_reserve_exact(recovered.len())
            .map_err(|_| BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
        identities.extend(recovered.iter().map(|journal| journal.identity));
        identities
            .try_reserve(1)
            .map_err(|_| BrokerPaneLeaseWalErrorV1::CapacityExhausted)?;
        identities.push(*identity);
        validate_broker_lease_catalog_identities(&identities, &authenticator)?;
        self.validate_pinned_directory()?;
        let creating_name = broker_lease_catalog_creating_name(journal_id);
        let marker = open_broker_spawn_catalog_file_at(&self.directory, &creating_name, true)?;
        revalidate_open_broker_spawn_catalog_file(&self.directory, &creating_name, &marker, 0, 0)?;
        marker.sync_all()?;
        self.directory.sync_all()?;
        drop(marker);
        let states = self.scan_states()?;
        let pair = states
            .get(&journal_id)
            .ok_or(BrokerPaneLeaseWalErrorV1::InvalidCreationState)?;
        let journal = self.complete_creation(identity, pair, authenticator)?;
        self.activate_created_journal(journal)
    }

    fn activate_created_journal(
        &self,
        mut journal: BrokerPaneLeaseJournalV1,
    ) -> Result<BrokerPaneLeaseJournalV1, BrokerPaneLeaseWalErrorV1> {
        let journal_id = journal.identity.spawn.journal_id();
        let wal_name = broker_lease_catalog_wal_name(journal_id);
        let head_name = broker_lease_catalog_head_name(journal_id);
        let wal = revalidate_open_broker_spawn_catalog_file(
            &self.directory,
            &wal_name,
            &journal.wal,
            BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
            BROKER_LEASE_WAL_MAX_PHYSICAL_BYTES,
        )?;
        let head = revalidate_open_broker_spawn_catalog_file(
            &self.directory,
            &head_name,
            &journal.head,
            BROKER_LEASE_WAL_FILE_HEADER_BYTES_U64,
            BROKER_LEASE_HEAD_MAX_PHYSICAL_BYTES,
        )?;
        let authority = BrokerPaneLeaseWalFilesystemRevalidationV1::from_revalidated_filesystem(
            &journal.identity,
            wal.bytes,
            head.bytes,
        )?;
        journal.reconcile_recovered_head_and_activate(authority)?;
        self.validate_pinned_directory()?;
        Ok(journal)
    }
}

fn broker_genesis_binding_digest(binding: BrokerGenesisBinding) -> [u8; 32] {
    let mut hasher = Sha256::new();
    hasher.update(b"frankenterm.guardian-broker.genesis-binding.v1\0");
    hasher.update(binding.mux_incarnation.as_bytes());
    hasher.update(binding.spawn_effect_id.as_bytes());
    hasher.update(binding.durable_pane_id.as_bytes());
    hasher.update(binding.origin_request_id.as_bytes());
    hasher.update(binding.spawn_payload_bytes.to_le_bytes());
    hasher.update(binding.spawn_payload_digest);
    hasher.update(binding.spawning_mux_build_identity_digest);
    hasher.update(binding.live_guardian_build_identity_digest);
    hasher.update(binding.rows.to_le_bytes());
    hasher.update(binding.cols.to_le_bytes());
    hasher.update(binding.pixel_width.to_le_bytes());
    hasher.update(binding.pixel_height.to_le_bytes());
    hasher.update(binding.checkpoint_identity_digest);
    hasher.update(binding.boundary_identity_digest);
    hasher.update(binding.upload_id.as_bytes());
    hasher.finalize().into()
}

fn broker_spawn_wal_authenticate(
    authenticator: &GuardianBrokerSpawnWalAuthenticatorV1,
    bytes: &[u8],
) -> Result<[u8; BROKER_SPAWN_WAL_MAC_BYTES], BrokerSpawnWalError> {
    authenticator
        .authenticate(bytes)
        .map_err(|_| BrokerSpawnWalError::AuthenticationFailed)
}

fn broker_spawn_wal_verify(
    authenticator: &GuardianBrokerSpawnWalAuthenticatorV1,
    bytes: &[u8],
    tag: &[u8],
) -> Result<(), BrokerSpawnWalError> {
    authenticator
        .verify(bytes, tag)
        .map_err(|_| BrokerSpawnWalError::AuthenticationFailed)
}

fn encode_broker_spawn_creation_identity(
    identity: BrokerSpawnWalIdentityV1,
) -> Result<[u8; BROKER_SPAWN_CREATION_IDENTITY_BYTES], BrokerSpawnWalError> {
    identity.validate()?;
    let mut encoded = [0_u8; BROKER_SPAWN_CREATION_IDENTITY_BYTES];
    encoded[0..16].copy_from_slice(identity.journal_id.as_bytes());
    encoded[16..32].copy_from_slice(identity.broker_lineage_id.as_bytes());
    encoded[32..48].copy_from_slice(identity.mux_incarnation.as_bytes());
    encoded[48..64].copy_from_slice(identity.durable_pane_id.as_bytes());
    encoded[64..80].copy_from_slice(identity.spawn_effect_id.as_bytes());
    encoded[80..96].copy_from_slice(identity.origin_request_id.as_bytes());
    encoded[96..104].copy_from_slice(&identity.spawn_payload_bytes.to_le_bytes());
    encoded[104..136].copy_from_slice(&identity.spawn_payload_digest);
    encoded[136..168].copy_from_slice(&identity.binding_digest);
    Ok(encoded)
}

fn decode_broker_spawn_creation_identity(
    encoded: &[u8; BROKER_SPAWN_CREATION_IDENTITY_BYTES],
) -> Result<BrokerSpawnWalIdentityV1, BrokerSpawnWalError> {
    let identity = BrokerSpawnWalIdentityV1 {
        journal_id: read_broker_uuid(&encoded[0..16]),
        broker_lineage_id: read_broker_uuid(&encoded[16..32]),
        mux_incarnation: read_broker_uuid(&encoded[32..48]),
        durable_pane_id: read_broker_uuid(&encoded[48..64]),
        spawn_effect_id: read_broker_uuid(&encoded[64..80]),
        origin_request_id: read_broker_uuid(&encoded[80..96]),
        spawn_payload_bytes: read_broker_u64(&encoded[96..104]),
        spawn_payload_digest: read_broker_array_32(&encoded[104..136]),
        binding_digest: read_broker_array_32(&encoded[136..168]),
    };
    identity.validate()?;
    Ok(identity)
}

fn broker_spawn_creation_authenticated_bytes(
    identity_bytes: &[u8; BROKER_SPAWN_CREATION_IDENTITY_BYTES],
) -> [u8; 8 + BROKER_SPAWN_CREATION_IDENTITY_BYTES] {
    let mut authenticated = [0_u8; 8 + BROKER_SPAWN_CREATION_IDENTITY_BYTES];
    authenticated[..8].copy_from_slice(&BROKER_SPAWN_CREATION_MARKER_MAGIC);
    authenticated[8..].copy_from_slice(identity_bytes);
    authenticated
}

fn encode_broker_spawn_creation_base85(
    bytes: &[u8; BROKER_SPAWN_CREATION_MARKER_BYTES],
) -> [u8; BROKER_SPAWN_CREATION_MARKER_ENCODED_BYTES] {
    let mut encoded = [0_u8; BROKER_SPAWN_CREATION_MARKER_ENCODED_BYTES];
    let (chunks, remainder) = bytes.as_chunks::<4>();
    debug_assert_eq!(remainder.len(), 0);
    for (chunk_index, chunk) in chunks.iter().enumerate() {
        let mut value = u32::from_be_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]);
        let encoded_offset = chunk_index * 5;
        for digit in (0..5).rev() {
            let alphabet_index =
                usize::try_from(value % 85).expect("base85 digit always fits usize");
            encoded[encoded_offset + digit] = BROKER_SPAWN_CREATION_BASE85[alphabet_index];
            value /= 85;
        }
    }
    encoded
}

fn decode_broker_spawn_creation_base85(
    encoded: &[u8],
) -> Result<[u8; BROKER_SPAWN_CREATION_MARKER_BYTES], BrokerSpawnWalError> {
    if encoded.len() != BROKER_SPAWN_CREATION_MARKER_ENCODED_BYTES {
        return Err(BrokerSpawnWalError::InvalidCreationMarker);
    }
    let mut decoded = [0_u8; BROKER_SPAWN_CREATION_MARKER_BYTES];
    let (chunks, remainder) = encoded.as_chunks::<5>();
    if !remainder.is_empty() {
        return Err(BrokerSpawnWalError::InvalidCreationMarker);
    }
    for (chunk_index, chunk) in chunks.iter().enumerate() {
        let mut value = 0_u64;
        for byte in chunk {
            let digit = BROKER_SPAWN_CREATION_BASE85
                .iter()
                .position(|candidate| candidate == byte)
                .ok_or(BrokerSpawnWalError::InvalidCreationMarker)?;
            value = value
                .checked_mul(85)
                .and_then(|value| {
                    value.checked_add(u64::try_from(digit).expect("base85 index fits u64"))
                })
                .ok_or(BrokerSpawnWalError::InvalidCreationMarker)?;
        }
        let value = u32::try_from(value).map_err(|_| BrokerSpawnWalError::InvalidCreationMarker)?;
        let decoded_offset = chunk_index * 4;
        decoded[decoded_offset..decoded_offset + 4].copy_from_slice(&value.to_be_bytes());
    }
    if encode_broker_spawn_creation_base85(&decoded).as_slice() != encoded {
        return Err(BrokerSpawnWalError::InvalidCreationMarker);
    }
    Ok(decoded)
}

fn broker_spawn_creation_marker_name(
    identity: BrokerSpawnWalIdentityV1,
    authenticator: &GuardianBrokerSpawnWalAuthenticatorV1,
    completed: bool,
) -> Result<OsString, BrokerSpawnWalError> {
    let identity_bytes = encode_broker_spawn_creation_identity(identity)?;
    let authentication_tag = broker_spawn_wal_authenticate(
        authenticator,
        &broker_spawn_creation_authenticated_bytes(&identity_bytes),
    )?;
    let mut marker = [0_u8; BROKER_SPAWN_CREATION_MARKER_BYTES];
    marker[..BROKER_SPAWN_CREATION_IDENTITY_BYTES].copy_from_slice(&identity_bytes);
    marker[BROKER_SPAWN_CREATION_IDENTITY_BYTES..].copy_from_slice(&authentication_tag);
    let encoded = encode_broker_spawn_creation_base85(&marker);
    let encoded =
        std::str::from_utf8(&encoded).map_err(|_| BrokerSpawnWalError::InvalidCreationMarker)?;
    let prefix = if completed {
        BROKER_SPAWN_COMPLETED_MARKER_PREFIX
    } else {
        BROKER_SPAWN_CREATION_MARKER_PREFIX
    };
    let name = format!("{prefix}{encoded}");
    if name.len() != BROKER_SPAWN_CREATION_MARKER_NAME_BYTES {
        return Err(BrokerSpawnWalError::InvalidCreationMarker);
    }
    Ok(name.into())
}

fn decode_broker_spawn_creation_marker_name(
    name: &OsStr,
) -> Result<(BrokerSpawnCreationMarkerV1, bool), BrokerSpawnWalError> {
    let text = name
        .to_str()
        .ok_or(BrokerSpawnWalError::InvalidCreationMarker)?;
    if text.len() != BROKER_SPAWN_CREATION_MARKER_NAME_BYTES {
        return Err(BrokerSpawnWalError::InvalidCreationMarker);
    }
    let (encoded, completed) =
        if let Some(encoded) = text.strip_prefix(BROKER_SPAWN_CREATION_MARKER_PREFIX) {
            (encoded, false)
        } else if let Some(encoded) = text.strip_prefix(BROKER_SPAWN_COMPLETED_MARKER_PREFIX) {
            (encoded, true)
        } else {
            return Err(BrokerSpawnWalError::InvalidCreationMarker);
        };
    let decoded = decode_broker_spawn_creation_base85(encoded.as_bytes())?;
    let mut identity_bytes = [0_u8; BROKER_SPAWN_CREATION_IDENTITY_BYTES];
    identity_bytes.copy_from_slice(&decoded[..BROKER_SPAWN_CREATION_IDENTITY_BYTES]);
    let identity = decode_broker_spawn_creation_identity(&identity_bytes)?;
    let mut authentication_tag = [0_u8; BROKER_SPAWN_WAL_MAC_BYTES];
    authentication_tag.copy_from_slice(&decoded[BROKER_SPAWN_CREATION_IDENTITY_BYTES..]);
    Ok((
        BrokerSpawnCreationMarkerV1 {
            name: name.to_os_string(),
            identity,
            authentication_tag,
        },
        completed,
    ))
}

fn validate_broker_spawn_creation_marker(
    marker: &BrokerSpawnCreationMarkerV1,
    authenticator: &GuardianBrokerSpawnWalAuthenticatorV1,
    completed: bool,
) -> Result<(), BrokerSpawnWalError> {
    let identity_bytes = encode_broker_spawn_creation_identity(marker.identity)?;
    broker_spawn_wal_verify(
        authenticator,
        &broker_spawn_creation_authenticated_bytes(&identity_bytes),
        &marker.authentication_tag,
    )
    .map_err(|_| BrokerSpawnWalError::CreationMarkerAuthenticationFailed)?;
    let expected = broker_spawn_creation_marker_name(marker.identity, authenticator, completed)?;
    if marker.name != expected {
        return Err(BrokerSpawnWalError::InvalidCreationMarker);
    }
    Ok(())
}

fn validate_broker_spawn_creation_header_prefix(
    file: &mut File,
    expected: &[u8; BROKER_SPAWN_WAL_FILE_HEADER_BYTES],
) -> Result<usize, BrokerSpawnWalError> {
    let observed_bytes = usize::try_from(file.metadata()?.len())
        .map_err(|_| BrokerSpawnWalError::CapacityExhausted)?;
    if observed_bytes > expected.len() {
        return Err(BrokerSpawnWalError::InvalidCreationState);
    }
    let mut observed = [0_u8; BROKER_SPAWN_WAL_FILE_HEADER_BYTES];
    file.seek(SeekFrom::Start(0))?;
    file.read_exact(&mut observed[..observed_bytes])?;
    validate_broker_spawn_creation_header_prefix_bytes(&observed[..observed_bytes], expected)?;
    file.seek(SeekFrom::Start(
        u64::try_from(observed_bytes).map_err(|_| BrokerSpawnWalError::CapacityExhausted)?,
    ))?;
    Ok(observed_bytes)
}

fn validate_broker_spawn_creation_header_prefix_bytes(
    observed: &[u8],
    expected: &[u8; BROKER_SPAWN_WAL_FILE_HEADER_BYTES],
) -> Result<(), BrokerSpawnWalError> {
    if observed.len() > expected.len() || observed != &expected[..observed.len()] {
        return Err(BrokerSpawnWalError::CreationHeaderMismatch);
    }
    Ok(())
}

fn read_broker_spawn_header_identity(
    file: &mut File,
    magic: [u8; 8],
    authenticator: &GuardianBrokerSpawnWalAuthenticatorV1,
) -> Result<BrokerSpawnWalIdentityV1, BrokerSpawnWalError> {
    let mut header = [0_u8; BROKER_SPAWN_WAL_FILE_HEADER_BYTES];
    file.seek(SeekFrom::Start(0))?;
    file.read_exact(&mut header)?;
    file.rewind()?;
    decode_broker_spawn_file_header(&header, magic, authenticator).map(|(identity, _)| identity)
}

fn validate_broker_spawn_catalog_identities(
    identities: &[BrokerSpawnWalIdentityV1],
    authenticator: &GuardianBrokerSpawnWalAuthenticatorV1,
) -> Result<(), BrokerSpawnWalError> {
    if identities.len() > GUARDIAN_MAX_PANES {
        return Err(BrokerSpawnWalError::CapacityExhausted);
    }
    let mut journal_ids = HashMap::new();
    let mut pane_ids = HashMap::new();
    let mut effect_ids = HashMap::new();
    let mut request_ids = HashMap::new();
    for index in [
        &mut journal_ids,
        &mut pane_ids,
        &mut effect_ids,
        &mut request_ids,
    ] {
        index
            .try_reserve(identities.len())
            .map_err(|_| BrokerSpawnWalError::CapacityExhausted)?;
    }
    for (index, identity) in identities.iter().copied().enumerate() {
        if identity.broker_lineage_id() != authenticator.lineage_id() {
            return Err(BrokerSpawnWalError::RecoveredCatalogLineageMismatch);
        }
        if journal_ids.insert(identity.journal_id(), index).is_some() {
            return Err(BrokerSpawnWalError::RecoveredCatalogDuplicateJournalId);
        }
        if pane_ids.insert(identity.durable_pane_id(), index).is_some() {
            return Err(BrokerSpawnWalError::RecoveredCatalogDuplicateDurablePaneId);
        }
        if effect_ids
            .insert(identity.spawn_effect_id(), index)
            .is_some()
        {
            return Err(BrokerSpawnWalError::RecoveredCatalogDuplicateSpawnEffectId);
        }
        if request_ids
            .insert(identity.origin_request_id(), index)
            .is_some()
        {
            return Err(BrokerSpawnWalError::RecoveredCatalogDuplicateOriginRequestId);
        }
    }
    Ok(())
}

fn encode_broker_spawn_file_header(
    magic: [u8; 8],
    identity: BrokerSpawnWalIdentityV1,
    authenticator: &GuardianBrokerSpawnWalAuthenticatorV1,
) -> Result<[u8; BROKER_SPAWN_WAL_FILE_HEADER_BYTES], BrokerSpawnWalError> {
    identity.validate()?;
    let mut header = [0_u8; BROKER_SPAWN_WAL_FILE_HEADER_BYTES];
    header[0..8].copy_from_slice(&magic);
    header[8..12].copy_from_slice(&BROKER_SPAWN_WAL_FORMAT_VERSION.to_le_bytes());
    header[12..16].copy_from_slice(&BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U32.to_le_bytes());
    header[16..32].copy_from_slice(identity.journal_id.as_bytes());
    header[32..48].copy_from_slice(identity.broker_lineage_id.as_bytes());
    header[48..64].copy_from_slice(identity.mux_incarnation.as_bytes());
    header[64..80].copy_from_slice(identity.durable_pane_id.as_bytes());
    header[80..96].copy_from_slice(identity.spawn_effect_id.as_bytes());
    header[96..112].copy_from_slice(identity.origin_request_id.as_bytes());
    header[112..120].copy_from_slice(&identity.spawn_payload_bytes.to_le_bytes());
    header[120..152].copy_from_slice(&identity.spawn_payload_digest);
    header[152..160].copy_from_slice(&authenticator.key_id());
    header[160..192].copy_from_slice(&identity.binding_digest);
    let tag = broker_spawn_wal_authenticate(
        authenticator,
        &header[..BROKER_SPAWN_WAL_AUTHENTICATED_HEADER_BYTES],
    )?;
    header[192..224].copy_from_slice(&tag);
    Ok(header)
}

fn validate_broker_spawn_file_header(
    header: &[u8; BROKER_SPAWN_WAL_FILE_HEADER_BYTES],
    magic: [u8; 8],
    expected: BrokerSpawnWalIdentityV1,
    authenticator: &GuardianBrokerSpawnWalAuthenticatorV1,
) -> Result<[u8; BROKER_SPAWN_WAL_MAC_BYTES], BrokerSpawnWalError> {
    let (observed, tag) = decode_broker_spawn_file_header(header, magic, authenticator)?;
    if observed != expected {
        return Err(BrokerSpawnWalError::IdentityMismatch);
    }
    Ok(tag)
}

fn decode_broker_spawn_file_header(
    header: &[u8; BROKER_SPAWN_WAL_FILE_HEADER_BYTES],
    magic: [u8; 8],
    authenticator: &GuardianBrokerSpawnWalAuthenticatorV1,
) -> Result<(BrokerSpawnWalIdentityV1, [u8; BROKER_SPAWN_WAL_MAC_BYTES]), BrokerSpawnWalError> {
    if header[0..8] != magic {
        return Err(BrokerSpawnWalError::InvalidFileMagic);
    }
    let version = read_broker_u32(&header[8..12]);
    if version != BROKER_SPAWN_WAL_FORMAT_VERSION {
        return Err(BrokerSpawnWalError::UnsupportedVersion { observed: version });
    }
    if read_broker_u32(&header[12..16]) != BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U32 {
        return Err(BrokerSpawnWalError::InvalidFileHeaderLength);
    }
    if header[152..160] != authenticator.key_id() {
        return Err(BrokerSpawnWalError::KeyIdentityMismatch);
    }
    let observed = BrokerSpawnWalIdentityV1 {
        journal_id: read_broker_uuid(&header[16..32]),
        broker_lineage_id: read_broker_uuid(&header[32..48]),
        mux_incarnation: read_broker_uuid(&header[48..64]),
        durable_pane_id: read_broker_uuid(&header[64..80]),
        spawn_effect_id: read_broker_uuid(&header[80..96]),
        origin_request_id: read_broker_uuid(&header[96..112]),
        spawn_payload_bytes: read_broker_u64(&header[112..120]),
        spawn_payload_digest: read_broker_array_32(&header[120..152]),
        binding_digest: read_broker_array_32(&header[160..192]),
    };
    observed.validate()?;
    broker_spawn_wal_verify(
        authenticator,
        &header[..BROKER_SPAWN_WAL_AUTHENTICATED_HEADER_BYTES],
        &header[192..224],
    )?;
    Ok((observed, read_broker_array_32(&header[192..224])))
}

fn encode_broker_spawn_wal_record(
    header_mac: [u8; BROKER_SPAWN_WAL_MAC_BYTES],
    authenticator: &GuardianBrokerSpawnWalAuthenticatorV1,
    sequence: u64,
    phase: BrokerSpawnWalPhaseV1,
    operation_id: Uuid,
    attempt_id: Uuid,
    child_identity: Option<BrokerKernelChildIdentityV1>,
    recovery_verifier: Option<BrokerPaneRecoveryVerifierV1>,
    previous_record_mac: [u8; BROKER_SPAWN_WAL_MAC_BYTES],
) -> Result<[u8; BROKER_SPAWN_WAL_RECORD_BYTES], BrokerSpawnWalError> {
    validate_broker_spawn_record_fields(
        phase,
        operation_id,
        attempt_id,
        child_identity,
        recovery_verifier,
    )?;
    let mut record = [0_u8; BROKER_SPAWN_WAL_RECORD_BYTES];
    record[0..8].copy_from_slice(&BROKER_SPAWN_WAL_RECORD_MAGIC);
    record[8..12].copy_from_slice(&BROKER_SPAWN_WAL_RECORD_BYTES_U32.to_le_bytes());
    record[12] = phase.to_wire();
    record[16..24].copy_from_slice(&sequence.to_le_bytes());
    record[24..40].copy_from_slice(operation_id.as_bytes());
    record[40..56].copy_from_slice(attempt_id.as_bytes());
    if let Some(child_identity) = child_identity {
        record[56..72].copy_from_slice(child_identity.broker_child_nonce.as_bytes());
        record[72..76].copy_from_slice(&child_identity.process_id.to_le_bytes());
        record[80..112].copy_from_slice(&child_identity.kernel_start_identity_digest);
    }
    if let Some(recovery_verifier) = recovery_verifier {
        record[112..144].copy_from_slice(&recovery_verifier.into_bytes());
    }
    record[144..176].copy_from_slice(&previous_record_mac);
    let mut authenticated =
        [0_u8; BROKER_SPAWN_WAL_MAC_BYTES + BROKER_SPAWN_WAL_AUTHENTICATED_RECORD_BYTES];
    authenticated[..BROKER_SPAWN_WAL_MAC_BYTES].copy_from_slice(&header_mac);
    authenticated[BROKER_SPAWN_WAL_MAC_BYTES..]
        .copy_from_slice(&record[..BROKER_SPAWN_WAL_AUTHENTICATED_RECORD_BYTES]);
    let tag = broker_spawn_wal_authenticate(authenticator, &authenticated)?;
    record[176..208].copy_from_slice(&tag);
    Ok(record)
}

#[allow(clippy::too_many_arguments)]
fn decode_broker_spawn_wal_record(
    record: &[u8; BROKER_SPAWN_WAL_RECORD_BYTES],
    header_mac: [u8; BROKER_SPAWN_WAL_MAC_BYTES],
    authenticator: &GuardianBrokerSpawnWalAuthenticatorV1,
    expected_sequence: u64,
    expected_previous_mac: [u8; BROKER_SPAWN_WAL_MAC_BYTES],
    previous: Option<BrokerSpawnWalRecordState>,
) -> Result<BrokerSpawnWalRecordState, BrokerSpawnWalError> {
    if record[0..8] != BROKER_SPAWN_WAL_RECORD_MAGIC
        || read_broker_u32(&record[8..12]) != BROKER_SPAWN_WAL_RECORD_BYTES_U32
    {
        return Err(BrokerSpawnWalError::InvalidRecordFraming);
    }
    if record[13..16].iter().any(|byte| *byte != 0) || record[76..80].iter().any(|byte| *byte != 0)
    {
        return Err(BrokerSpawnWalError::NonCanonicalRecord);
    }
    let sequence = read_broker_u64(&record[16..24]);
    if sequence != expected_sequence {
        return Err(BrokerSpawnWalError::SequenceMismatch);
    }
    if record[144..176] != expected_previous_mac {
        return Err(BrokerSpawnWalError::RecordChainMismatch);
    }
    let mut authenticated =
        [0_u8; BROKER_SPAWN_WAL_MAC_BYTES + BROKER_SPAWN_WAL_AUTHENTICATED_RECORD_BYTES];
    authenticated[..BROKER_SPAWN_WAL_MAC_BYTES].copy_from_slice(&header_mac);
    authenticated[BROKER_SPAWN_WAL_MAC_BYTES..]
        .copy_from_slice(&record[..BROKER_SPAWN_WAL_AUTHENTICATED_RECORD_BYTES]);
    broker_spawn_wal_verify(authenticator, &authenticated, &record[176..208])?;

    let phase = BrokerSpawnWalPhaseV1::from_wire(record[12])?;
    let operation_id = read_broker_uuid(&record[24..40]);
    let attempt_id = read_broker_uuid(&record[40..56]);
    let process_id = read_broker_u32(&record[72..76]);
    let broker_child_nonce = read_broker_uuid(&record[56..72]);
    let kernel_start_identity_digest = read_broker_array_32(&record[80..112]);
    let child_identity = if process_id == 0
        && broker_child_nonce.is_nil()
        && kernel_start_identity_digest == [0; 32]
    {
        None
    } else {
        Some(BrokerKernelChildIdentityV1 {
            process_id,
            broker_child_nonce,
            kernel_start_identity_digest,
        })
    };
    let recovery_verifier =
        BrokerPaneRecoveryVerifierV1::from_record(read_broker_array_32(&record[112..144]));
    validate_broker_spawn_record_fields(
        phase,
        operation_id,
        attempt_id,
        child_identity,
        recovery_verifier,
    )?;
    validate_broker_spawn_record_transition(
        previous,
        phase,
        attempt_id,
        child_identity,
        recovery_verifier,
    )?;
    let record_mac = read_broker_array_32(&record[176..208]);
    Ok(BrokerSpawnWalRecordState {
        phase,
        operation_id,
        attempt_id,
        child_identity,
        recovery_verifier,
        receipt: BrokerSpawnWalReceiptV1 {
            sequence,
            phase,
            committed_wal_bytes: BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64
                + (sequence + 1) * BROKER_SPAWN_WAL_RECORD_BYTES_U64,
            committed_head_bytes: BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
            record_mac,
            head_mac: [0; BROKER_SPAWN_WAL_MAC_BYTES],
        },
    })
}

fn encode_broker_spawn_head_record(
    head_header_mac: [u8; BROKER_SPAWN_WAL_MAC_BYTES],
    authenticator: &GuardianBrokerSpawnWalAuthenticatorV1,
    sequence: u64,
    wal_record_mac: [u8; BROKER_SPAWN_WAL_MAC_BYTES],
    previous_head_mac: [u8; BROKER_SPAWN_WAL_MAC_BYTES],
) -> Result<[u8; BROKER_SPAWN_HEAD_RECORD_BYTES], BrokerSpawnWalError> {
    let mut record = [0_u8; BROKER_SPAWN_HEAD_RECORD_BYTES];
    record[0..8].copy_from_slice(&BROKER_SPAWN_HEAD_RECORD_MAGIC);
    record[8..12].copy_from_slice(&BROKER_SPAWN_HEAD_RECORD_BYTES_U32.to_le_bytes());
    record[16..24].copy_from_slice(&sequence.to_le_bytes());
    record[24..56].copy_from_slice(&wal_record_mac);
    record[56..88].copy_from_slice(&previous_head_mac);
    let mut authenticated =
        [0_u8; BROKER_SPAWN_WAL_MAC_BYTES + BROKER_SPAWN_HEAD_AUTHENTICATED_RECORD_BYTES];
    authenticated[..BROKER_SPAWN_WAL_MAC_BYTES].copy_from_slice(&head_header_mac);
    authenticated[BROKER_SPAWN_WAL_MAC_BYTES..]
        .copy_from_slice(&record[..BROKER_SPAWN_HEAD_AUTHENTICATED_RECORD_BYTES]);
    let tag = broker_spawn_wal_authenticate(authenticator, &authenticated)?;
    record[88..120].copy_from_slice(&tag);
    Ok(record)
}

fn decode_broker_spawn_head_record(
    record: &[u8; BROKER_SPAWN_HEAD_RECORD_BYTES],
    head_header_mac: [u8; BROKER_SPAWN_WAL_MAC_BYTES],
    authenticator: &GuardianBrokerSpawnWalAuthenticatorV1,
    expected_sequence: u64,
    expected_wal_record_mac: [u8; BROKER_SPAWN_WAL_MAC_BYTES],
    expected_previous_head_mac: [u8; BROKER_SPAWN_WAL_MAC_BYTES],
) -> Result<[u8; BROKER_SPAWN_WAL_MAC_BYTES], BrokerSpawnWalError> {
    if record[0..8] != BROKER_SPAWN_HEAD_RECORD_MAGIC
        || read_broker_u32(&record[8..12]) != BROKER_SPAWN_HEAD_RECORD_BYTES_U32
    {
        return Err(BrokerSpawnWalError::InvalidRecordFraming);
    }
    if record[12..16].iter().any(|byte| *byte != 0)
        || read_broker_u64(&record[16..24]) != expected_sequence
        || record[24..56] != expected_wal_record_mac
        || record[56..88] != expected_previous_head_mac
    {
        return Err(BrokerSpawnWalError::HeadAnchorMismatch);
    }
    let mut authenticated =
        [0_u8; BROKER_SPAWN_WAL_MAC_BYTES + BROKER_SPAWN_HEAD_AUTHENTICATED_RECORD_BYTES];
    authenticated[..BROKER_SPAWN_WAL_MAC_BYTES].copy_from_slice(&head_header_mac);
    authenticated[BROKER_SPAWN_WAL_MAC_BYTES..]
        .copy_from_slice(&record[..BROKER_SPAWN_HEAD_AUTHENTICATED_RECORD_BYTES]);
    broker_spawn_wal_verify(authenticator, &authenticated, &record[88..120])?;
    Ok(read_broker_array_32(&record[88..120]))
}

fn validate_broker_spawn_record_fields(
    phase: BrokerSpawnWalPhaseV1,
    operation_id: Uuid,
    attempt_id: Uuid,
    child_identity: Option<BrokerKernelChildIdentityV1>,
    recovery_verifier: Option<BrokerPaneRecoveryVerifierV1>,
) -> Result<(), BrokerSpawnWalError> {
    if operation_id.is_nil() {
        return Err(BrokerSpawnWalError::NonCanonicalRecord);
    }
    match phase {
        BrokerSpawnWalPhaseV1::Intent
            if attempt_id.is_nil() && child_identity.is_none() && recovery_verifier.is_none() => {}
        BrokerSpawnWalPhaseV1::Attempted
            if !attempt_id.is_nil()
                && operation_id == attempt_id
                && child_identity.is_none()
                && recovery_verifier.is_none() => {}
        BrokerSpawnWalPhaseV1::SpawnObserved | BrokerSpawnWalPhaseV1::ReplyAcknowledged
            if !attempt_id.is_nil() && child_identity.is_some() && recovery_verifier.is_some() =>
        {
            child_identity.expect("checked child identity").validate()?;
        }
        _ => return Err(BrokerSpawnWalError::NonCanonicalRecord),
    }
    Ok(())
}

fn validate_broker_spawn_record_transition(
    previous: Option<BrokerSpawnWalRecordState>,
    phase: BrokerSpawnWalPhaseV1,
    attempt_id: Uuid,
    child_identity: Option<BrokerKernelChildIdentityV1>,
    recovery_verifier: Option<BrokerPaneRecoveryVerifierV1>,
) -> Result<(), BrokerSpawnWalError> {
    match (previous, phase) {
        (None, BrokerSpawnWalPhaseV1::Intent) => Ok(()),
        (Some(previous), BrokerSpawnWalPhaseV1::Attempted)
            if previous.phase == BrokerSpawnWalPhaseV1::Intent =>
        {
            Ok(())
        }
        (Some(previous), BrokerSpawnWalPhaseV1::SpawnObserved)
            if previous.phase == BrokerSpawnWalPhaseV1::Attempted
                && previous.attempt_id == attempt_id
                && recovery_verifier.is_some() =>
        {
            Ok(())
        }
        (Some(previous), BrokerSpawnWalPhaseV1::ReplyAcknowledged)
            if previous.phase == BrokerSpawnWalPhaseV1::SpawnObserved
                && previous.attempt_id == attempt_id
                && previous.child_identity == child_identity
                && previous.recovery_verifier == recovery_verifier =>
        {
            Ok(())
        }
        _ => Err(BrokerSpawnWalError::InvalidTransition),
    }
}

fn read_broker_u32(bytes: &[u8]) -> u32 {
    let mut value = [0_u8; 4];
    value.copy_from_slice(bytes);
    u32::from_le_bytes(value)
}

fn read_broker_u64(bytes: &[u8]) -> u64 {
    let mut value = [0_u8; 8];
    value.copy_from_slice(bytes);
    u64::from_le_bytes(value)
}

fn read_broker_uuid(bytes: &[u8]) -> Uuid {
    let mut value = [0_u8; 16];
    value.copy_from_slice(bytes);
    Uuid::from_bytes(value)
}

fn read_broker_array_32(bytes: &[u8]) -> [u8; 32] {
    let mut value = [0_u8; 32];
    value.copy_from_slice(bytes);
    value
}

fn scan_broker_spawn_wal(
    wal: &mut File,
    identity: BrokerSpawnWalIdentityV1,
    authenticator: &GuardianBrokerSpawnWalAuthenticatorV1,
) -> Result<([u8; BROKER_SPAWN_WAL_MAC_BYTES], BrokerSpawnWalScan), BrokerSpawnWalError> {
    let metadata = wal.metadata()?;
    if !metadata.file_type().is_file() {
        return Err(BrokerSpawnWalError::NotRegularFile);
    }
    let physical_bytes = metadata.len();
    if physical_bytes < BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64 {
        return Err(BrokerSpawnWalError::TornFileHeader);
    }
    let maximum_physical_bytes = BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64
        .checked_add(
            BROKER_SPAWN_WAL_MAX_RECORDS
                .checked_mul(BROKER_SPAWN_WAL_RECORD_BYTES_U64)
                .ok_or(BrokerSpawnWalError::CapacityExhausted)?,
        )
        .and_then(|bytes| bytes.checked_add(BROKER_SPAWN_WAL_RECORD_BYTES_U64 - 1))
        .ok_or(BrokerSpawnWalError::CapacityExhausted)?;
    if physical_bytes > maximum_physical_bytes {
        return Err(BrokerSpawnWalError::CapacityExhausted);
    }
    wal.seek(SeekFrom::Start(0))?;
    let mut header = [0_u8; BROKER_SPAWN_WAL_FILE_HEADER_BYTES];
    wal.read_exact(&mut header)?;
    let header_mac = validate_broker_spawn_file_header(
        &header,
        BROKER_SPAWN_WAL_FILE_MAGIC,
        identity,
        authenticator,
    )?;
    let record_region = physical_bytes - BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64;
    let complete_records = record_region / BROKER_SPAWN_WAL_RECORD_BYTES_U64;
    if complete_records > BROKER_SPAWN_WAL_MAX_RECORDS {
        return Err(BrokerSpawnWalError::CapacityExhausted);
    }
    let trailing_bytes = record_region % BROKER_SPAWN_WAL_RECORD_BYTES_U64;
    let capacity =
        usize::try_from(complete_records).map_err(|_| BrokerSpawnWalError::CapacityExhausted)?;
    let mut records = Vec::new();
    records
        .try_reserve_exact(capacity)
        .map_err(|_| BrokerSpawnWalError::CapacityExhausted)?;
    let mut previous_mac = header_mac;
    let mut previous = None;
    for sequence in 0..complete_records {
        let mut record = [0_u8; BROKER_SPAWN_WAL_RECORD_BYTES];
        wal.read_exact(&mut record)?;
        let decoded = decode_broker_spawn_wal_record(
            &record,
            header_mac,
            authenticator,
            sequence,
            previous_mac,
            previous,
        )?;
        previous_mac = decoded.receipt.record_mac;
        previous = Some(decoded);
        records.push(decoded);
    }
    Ok((
        header_mac,
        BrokerSpawnWalScan {
            committed_bytes: BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64
                + complete_records * BROKER_SPAWN_WAL_RECORD_BYTES_U64,
            trailing_bytes,
            records,
        },
    ))
}

fn scan_broker_spawn_head(
    head: &mut File,
    identity: BrokerSpawnWalIdentityV1,
    authenticator: &GuardianBrokerSpawnWalAuthenticatorV1,
    wal_records: &[BrokerSpawnWalRecordState],
) -> Result<([u8; BROKER_SPAWN_WAL_MAC_BYTES], BrokerSpawnHeadScan), BrokerSpawnWalError> {
    let metadata = head.metadata()?;
    if !metadata.file_type().is_file() {
        return Err(BrokerSpawnWalError::NotRegularFile);
    }
    let physical_bytes = metadata.len();
    if physical_bytes < BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64 {
        return Err(BrokerSpawnWalError::TornFileHeader);
    }
    let maximum_physical_bytes = BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64
        .checked_add(
            BROKER_SPAWN_WAL_MAX_RECORDS
                .checked_mul(BROKER_SPAWN_HEAD_RECORD_BYTES_U64)
                .ok_or(BrokerSpawnWalError::CapacityExhausted)?,
        )
        .and_then(|bytes| bytes.checked_add(BROKER_SPAWN_HEAD_RECORD_BYTES_U64 - 1))
        .ok_or(BrokerSpawnWalError::CapacityExhausted)?;
    if physical_bytes > maximum_physical_bytes {
        return Err(BrokerSpawnWalError::CapacityExhausted);
    }
    head.seek(SeekFrom::Start(0))?;
    let mut header = [0_u8; BROKER_SPAWN_WAL_FILE_HEADER_BYTES];
    head.read_exact(&mut header)?;
    let head_header_mac = validate_broker_spawn_file_header(
        &header,
        BROKER_SPAWN_HEAD_FILE_MAGIC,
        identity,
        authenticator,
    )?;
    let record_region = physical_bytes - BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64;
    let complete_records = record_region / BROKER_SPAWN_HEAD_RECORD_BYTES_U64;
    if complete_records > BROKER_SPAWN_WAL_MAX_RECORDS
        || complete_records
            > u64::try_from(wal_records.len())
                .map_err(|_| BrokerSpawnWalError::CapacityExhausted)?
    {
        return Err(BrokerSpawnWalError::HeadAnchorMismatch);
    }
    let trailing_bytes = record_region % BROKER_SPAWN_HEAD_RECORD_BYTES_U64;
    let capacity =
        usize::try_from(complete_records).map_err(|_| BrokerSpawnWalError::CapacityExhausted)?;
    let mut record_macs = Vec::new();
    record_macs
        .try_reserve_exact(capacity)
        .map_err(|_| BrokerSpawnWalError::CapacityExhausted)?;
    let mut previous_head_mac = head_header_mac;
    for sequence in 0..complete_records {
        let index =
            usize::try_from(sequence).map_err(|_| BrokerSpawnWalError::CapacityExhausted)?;
        let wal_record = wal_records
            .get(index)
            .ok_or(BrokerSpawnWalError::HeadAnchorMismatch)?;
        let mut record = [0_u8; BROKER_SPAWN_HEAD_RECORD_BYTES];
        head.read_exact(&mut record)?;
        let head_mac = decode_broker_spawn_head_record(
            &record,
            head_header_mac,
            authenticator,
            sequence,
            wal_record.receipt.record_mac,
            previous_head_mac,
        )?;
        previous_head_mac = head_mac;
        record_macs.push(head_mac);
    }
    if trailing_bytes != 0 {
        let next_index = usize::try_from(complete_records)
            .map_err(|_| BrokerSpawnWalError::CapacityExhausted)?;
        let wal_record = wal_records
            .get(next_index)
            .ok_or(BrokerSpawnWalError::IncompleteTail)?;
        let expected = encode_broker_spawn_head_record(
            head_header_mac,
            authenticator,
            complete_records,
            wal_record.receipt.record_mac,
            previous_head_mac,
        )?;
        let prefix_bytes =
            usize::try_from(trailing_bytes).map_err(|_| BrokerSpawnWalError::CapacityExhausted)?;
        let mut observed = [0_u8; BROKER_SPAWN_HEAD_RECORD_BYTES];
        head.read_exact(&mut observed[..prefix_bytes])?;
        if observed[..prefix_bytes] != expected[..prefix_bytes] {
            return Err(BrokerSpawnWalError::IncompleteTail);
        }
    }
    Ok((
        head_header_mac,
        BrokerSpawnHeadScan {
            committed_bytes: BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64
                + complete_records * BROKER_SPAWN_HEAD_RECORD_BYTES_U64,
            trailing_bytes,
            record_macs,
            terminal_head_mac: previous_head_mac,
        },
    ))
}

fn broker_spawn_catalog_wal_name(journal_id: Uuid) -> OsString {
    format!("{BROKER_SPAWN_CATALOG_PREFIX}{journal_id}{BROKER_SPAWN_CATALOG_WAL_SUFFIX}").into()
}

fn broker_spawn_catalog_head_name(journal_id: Uuid) -> OsString {
    format!("{BROKER_SPAWN_CATALOG_PREFIX}{journal_id}{BROKER_SPAWN_CATALOG_HEAD_SUFFIX}").into()
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum BrokerSpawnCatalogNameV1 {
    Wal(Uuid),
    Head(Uuid),
    Creating(BrokerSpawnCreationMarkerV1),
    Completed(BrokerSpawnCreationMarkerV1),
}

fn parse_broker_spawn_catalog_name(
    name: &OsStr,
) -> Result<BrokerSpawnCatalogNameV1, BrokerSpawnWalError> {
    let text = name
        .to_str()
        .ok_or(BrokerSpawnWalError::UnexpectedCatalogEntry)?;
    if text.starts_with(BROKER_SPAWN_CREATION_MARKER_PREFIX)
        || text.starts_with(BROKER_SPAWN_COMPLETED_MARKER_PREFIX)
    {
        let (marker, completed) = decode_broker_spawn_creation_marker_name(name)
            .map_err(|_| BrokerSpawnWalError::UnexpectedCatalogEntry)?;
        return Ok(if completed {
            BrokerSpawnCatalogNameV1::Completed(marker)
        } else {
            BrokerSpawnCatalogNameV1::Creating(marker)
        });
    }
    let (identifier, is_wal) = if let Some(identifier) = text
        .strip_prefix(BROKER_SPAWN_CATALOG_PREFIX)
        .and_then(|rest| rest.strip_suffix(BROKER_SPAWN_CATALOG_WAL_SUFFIX))
    {
        (identifier, true)
    } else if let Some(identifier) = text
        .strip_prefix(BROKER_SPAWN_CATALOG_PREFIX)
        .and_then(|rest| rest.strip_suffix(BROKER_SPAWN_CATALOG_HEAD_SUFFIX))
    {
        (identifier, false)
    } else {
        return Err(BrokerSpawnWalError::UnexpectedCatalogEntry);
    };
    let journal_id =
        Uuid::parse_str(identifier).map_err(|_| BrokerSpawnWalError::UnexpectedCatalogEntry)?;
    if journal_id.is_nil()
        || (is_wal && broker_spawn_catalog_wal_name(journal_id) != name)
        || (!is_wal && broker_spawn_catalog_head_name(journal_id) != name)
    {
        return Err(BrokerSpawnWalError::UnexpectedCatalogEntry);
    }
    Ok(if is_wal {
        BrokerSpawnCatalogNameV1::Wal(journal_id)
    } else {
        BrokerSpawnCatalogNameV1::Head(journal_id)
    })
}

fn validate_broker_spawn_catalog_path(path: &Path) -> Result<(), BrokerSpawnWalError> {
    if !path.is_absolute()
        || path.file_name().is_none()
        || path
            .components()
            .any(|component| !matches!(component, Component::RootDir | Component::Normal(_)))
    {
        return Err(BrokerSpawnWalError::InvalidCatalogPath);
    }
    let mut current = PathBuf::from("/");
    for component in path.components() {
        match component {
            Component::RootDir => continue,
            Component::Normal(part) => current.push(part),
            _ => return Err(BrokerSpawnWalError::InvalidCatalogPath),
        }
        let metadata = std::fs::symlink_metadata(&current)?;
        if metadata.file_type().is_symlink() || !metadata.is_dir() {
            return Err(BrokerSpawnWalError::InsecureCatalogIdentity);
        }
        if current != path && metadata.mode() & 0o022 != 0 && metadata.mode() & 0o1000 == 0 {
            return Err(BrokerSpawnWalError::InsecureCatalogIdentity);
        }
    }
    let metadata = std::fs::symlink_metadata(path)?;
    if metadata.uid() != geteuid().as_raw() || metadata.mode() & 0o777 != 0o700 {
        return Err(BrokerSpawnWalError::InsecureCatalogIdentity);
    }
    Ok(())
}

fn validate_broker_spawn_catalog_name_capacity(
    directory: &File,
) -> Result<(), BrokerSpawnWalError> {
    if BROKER_SPAWN_CREATION_MARKER_PREFIX.len() != BROKER_SPAWN_COMPLETED_MARKER_PREFIX.len() {
        return Err(BrokerSpawnWalError::InvalidCreationMarker);
    }
    let observed = fpathconf(directory, PathconfVar::NAME_MAX)
        .map_err(|error| BrokerSpawnWalError::Io(std::io::Error::from(error)))?
        .ok_or(BrokerSpawnWalError::CreationMarkerNameTooLong)?;
    let observed =
        usize::try_from(observed).map_err(|_| BrokerSpawnWalError::CreationMarkerNameTooLong)?;
    let maximum_required = BROKER_SPAWN_CREATION_MARKER_NAME_BYTES
        .max(
            broker_spawn_catalog_wal_name(Uuid::from_u128(u128::MAX))
                .as_bytes()
                .len(),
        )
        .max(
            broker_spawn_catalog_head_name(Uuid::from_u128(u128::MAX))
                .as_bytes()
                .len(),
        )
        .max(BROKER_SPAWN_CATALOG_LOCK_NAME.len());
    if maximum_required > observed {
        return Err(BrokerSpawnWalError::CreationMarkerNameTooLong);
    }
    Ok(())
}

fn broker_spawn_file_identity_from_metadata(metadata: &Metadata) -> BrokerSpawnWalFileIdentityV1 {
    BrokerSpawnWalFileIdentityV1 {
        device: metadata.dev(),
        inode: metadata.ino(),
        mode: metadata.mode(),
        owner: metadata.uid(),
        links: metadata.nlink(),
        bytes: metadata.len(),
    }
}

fn validate_broker_spawn_catalog_directory_metadata(
    metadata: &Metadata,
) -> Result<(), BrokerSpawnWalError> {
    if !metadata.is_dir()
        || metadata.uid() != geteuid().as_raw()
        || metadata.mode() & 0o777 != 0o700
    {
        return Err(BrokerSpawnWalError::InsecureCatalogIdentity);
    }
    Ok(())
}

fn require_same_broker_spawn_catalog_object(
    left: &Metadata,
    right: &Metadata,
) -> Result<(), BrokerSpawnWalError> {
    if left.dev() != right.dev()
        || left.ino() != right.ino()
        || left.mode() != right.mode()
        || left.uid() != right.uid()
        || left.nlink() != right.nlink()
    {
        return Err(BrokerSpawnWalError::InsecureCatalogIdentity);
    }
    Ok(())
}

fn validate_broker_spawn_catalog_file_metadata(
    metadata: &Metadata,
    minimum_bytes: u64,
    maximum_bytes: u64,
) -> Result<BrokerSpawnWalFileIdentityV1, BrokerSpawnWalError> {
    if !metadata.is_file()
        || metadata.uid() != geteuid().as_raw()
        || metadata.mode() & 0o777 != 0o600
        || metadata.nlink() != 1
        || metadata.len() < minimum_bytes
        || metadata.len() > maximum_bytes
    {
        return Err(BrokerSpawnWalError::InsecureCatalogIdentity);
    }
    Ok(broker_spawn_file_identity_from_metadata(metadata))
}

fn broker_spawn_catalog_stat_identity_at(
    directory: &File,
    name: &OsStr,
    minimum_bytes: u64,
    maximum_bytes: u64,
) -> Result<BrokerSpawnWalFileIdentityV1, BrokerSpawnWalError> {
    let metadata = rustix::fs::statat(directory, name, rustix::fs::AtFlags::SYMLINK_NOFOLLOW)
        .map_err(std::io::Error::from)?;
    #[allow(clippy::useless_conversion)]
    let identity = BrokerSpawnWalFileIdentityV1 {
        device: u64::try_from(metadata.st_dev)
            .map_err(|_| BrokerSpawnWalError::InsecureCatalogIdentity)?,
        inode: u64::try_from(metadata.st_ino)
            .map_err(|_| BrokerSpawnWalError::InsecureCatalogIdentity)?,
        mode: u32::from(metadata.st_mode),
        owner: u32::try_from(metadata.st_uid)
            .map_err(|_| BrokerSpawnWalError::InsecureCatalogIdentity)?,
        links: u64::from(metadata.st_nlink),
        bytes: u64::try_from(metadata.st_size)
            .map_err(|_| BrokerSpawnWalError::InsecureCatalogIdentity)?,
    };
    if rustix::fs::FileType::from_raw_mode(metadata.st_mode) != rustix::fs::FileType::RegularFile
        || identity.owner != geteuid().as_raw()
        || identity.mode & 0o777 != 0o600
        || identity.links != 1
        || identity.bytes < minimum_bytes
        || identity.bytes > maximum_bytes
    {
        return Err(BrokerSpawnWalError::InsecureCatalogIdentity);
    }
    Ok(identity)
}

fn broker_spawn_catalog_stat_recoverable_creation_identity_at(
    directory: &File,
    name: &OsStr,
    minimum_bytes: u64,
    maximum_bytes: u64,
) -> Result<BrokerSpawnWalFileIdentityV1, BrokerSpawnWalError> {
    let metadata = rustix::fs::statat(directory, name, rustix::fs::AtFlags::SYMLINK_NOFOLLOW)
        .map_err(std::io::Error::from)?;
    #[allow(clippy::useless_conversion)]
    let identity = BrokerSpawnWalFileIdentityV1 {
        device: u64::try_from(metadata.st_dev)
            .map_err(|_| BrokerSpawnWalError::InsecureCatalogIdentity)?,
        inode: u64::try_from(metadata.st_ino)
            .map_err(|_| BrokerSpawnWalError::InsecureCatalogIdentity)?,
        mode: u32::from(metadata.st_mode),
        owner: u32::try_from(metadata.st_uid)
            .map_err(|_| BrokerSpawnWalError::InsecureCatalogIdentity)?,
        links: u64::from(metadata.st_nlink),
        bytes: u64::try_from(metadata.st_size)
            .map_err(|_| BrokerSpawnWalError::InsecureCatalogIdentity)?,
    };
    let permissions = identity.mode & 0o7777;
    if rustix::fs::FileType::from_raw_mode(metadata.st_mode) != rustix::fs::FileType::RegularFile
        || identity.owner != geteuid().as_raw()
        || permissions & !0o600 != 0
        || identity.links != 1
        || identity.bytes < minimum_bytes
        || identity.bytes > maximum_bytes
    {
        return Err(BrokerSpawnWalError::InsecureCatalogIdentity);
    }
    Ok(identity)
}

#[cfg(any(
    target_os = "android",
    target_os = "ios",
    target_os = "linux",
    target_os = "macos",
    target_os = "tvos",
    target_os = "visionos",
    target_os = "watchos",
))]
fn open_and_seal_broker_spawn_creation_file_mode_at(
    directory: &File,
    name: &OsStr,
    minimum_bytes: u64,
    maximum_bytes: u64,
) -> Result<File, BrokerSpawnWalError> {
    let before = broker_spawn_catalog_stat_recoverable_creation_identity_at(
        directory,
        name,
        minimum_bytes,
        maximum_bytes,
    )?;
    let permissions = before.mode & 0o7777;
    if permissions != 0o600 {
        // O_CREAT applies the process umask before returning the new
        // descriptor. A crash before the creator's fchmod can therefore leave
        // 000/0200/0400 instead of 0600. Pin that exact regular inode first,
        // restore only owner read/write permission through its descriptor,
        // and synchronize the metadata before it can be published complete.
        if permissions & 0o600 != 0 {
            let access = if permissions & 0o400 != 0 {
                rustix::fs::OFlags::RDONLY
            } else {
                rustix::fs::OFlags::WRONLY
            };
            let mode_file = rustix::fs::openat(
                directory,
                name,
                access | rustix::fs::OFlags::CLOEXEC | rustix::fs::OFlags::NOFOLLOW,
                rustix::fs::Mode::empty(),
            )
            .map(File::from)
            .map_err(std::io::Error::from)?;
            let opened_metadata = mode_file.metadata()?;
            let opened = broker_spawn_file_identity_from_metadata(&opened_metadata);
            if !opened_metadata.is_file()
                || opened.owner != geteuid().as_raw()
                || opened.mode & 0o7777 != permissions
                || opened.links != 1
                || opened.bytes < minimum_bytes
                || opened.bytes > maximum_bytes
                || opened != before
                || broker_spawn_catalog_stat_recoverable_creation_identity_at(
                    directory,
                    name,
                    minimum_bytes,
                    maximum_bytes,
                )? != opened
            {
                return Err(BrokerSpawnWalError::InsecureCatalogIdentity);
            }
            rustix::fs::fchmod(&mode_file, rustix::fs::Mode::from_raw_mode(0o600))
                .map_err(std::io::Error::from)?;
        } else {
            // Mode 000 cannot be opened by its owner after restart. chmodat is
            // the portable recovery primitive. The parent is the already
            // pinned owner-only catalog; both pre/post lstat identity checks
            // make any rename/symlink race fail closed, and this transition
            // changes no content bytes.
            rustix::fs::chmodat(
                directory,
                name,
                rustix::fs::Mode::from_raw_mode(0o600),
                rustix::fs::AtFlags::empty(),
            )
            .map_err(std::io::Error::from)?;
        }
    }
    let after =
        broker_spawn_catalog_stat_identity_at(directory, name, minimum_bytes, maximum_bytes)?;
    if before.device != after.device
        || before.inode != after.inode
        || before.owner != after.owner
        || before.links != after.links
        || before.bytes != after.bytes
    {
        return Err(BrokerSpawnWalError::InsecureCatalogIdentity);
    }
    let file =
        open_revalidated_broker_spawn_catalog_file(directory, name, minimum_bytes, maximum_bytes)?;
    if permissions != 0o600 {
        file.sync_all()?;
        let durable = revalidate_open_broker_spawn_catalog_file(
            directory,
            name,
            &file,
            minimum_bytes,
            maximum_bytes,
        )?;
        if durable != after {
            return Err(BrokerSpawnWalError::InsecureCatalogIdentity);
        }
    }
    Ok(file)
}

#[cfg(not(any(
    target_os = "android",
    target_os = "ios",
    target_os = "linux",
    target_os = "macos",
    target_os = "tvos",
    target_os = "visionos",
    target_os = "watchos",
)))]
fn open_and_seal_broker_spawn_creation_file_mode_at(
    _directory: &File,
    _name: &OsStr,
    _minimum_bytes: u64,
    _maximum_bytes: u64,
) -> Result<File, BrokerSpawnWalError> {
    Err(BrokerSpawnWalError::CatalogLockUnsupported)
}

fn open_broker_spawn_catalog_file_at(
    directory: &File,
    name: &OsStr,
    create_new: bool,
) -> std::io::Result<File> {
    let mut flags =
        rustix::fs::OFlags::RDWR | rustix::fs::OFlags::CLOEXEC | rustix::fs::OFlags::NOFOLLOW;
    if create_new {
        flags |= rustix::fs::OFlags::CREATE | rustix::fs::OFlags::EXCL;
    }
    let file = rustix::fs::openat(
        directory,
        name,
        flags,
        rustix::fs::Mode::from_raw_mode(0o600),
    )
    .map(File::from)
    .map_err(std::io::Error::from)?;
    if create_new {
        rustix::fs::fchmod(&file, rustix::fs::Mode::from_raw_mode(0o600))
            .map_err(std::io::Error::from)?;
    }
    Ok(file)
}

fn open_revalidated_broker_spawn_catalog_file(
    directory: &File,
    name: &OsStr,
    minimum_bytes: u64,
    maximum_bytes: u64,
) -> Result<File, BrokerSpawnWalError> {
    let before =
        broker_spawn_catalog_stat_identity_at(directory, name, minimum_bytes, maximum_bytes)?;
    let file = open_broker_spawn_catalog_file_at(directory, name, false)?;
    let opened = validate_broker_spawn_catalog_file_metadata(
        &file.metadata()?,
        minimum_bytes,
        maximum_bytes,
    )?;
    let after =
        broker_spawn_catalog_stat_identity_at(directory, name, minimum_bytes, maximum_bytes)?;
    if before != opened || opened != after {
        return Err(BrokerSpawnWalError::InsecureCatalogIdentity);
    }
    Ok(file)
}

fn revalidate_open_broker_spawn_catalog_file(
    directory: &File,
    name: &OsStr,
    file: &File,
    minimum_bytes: u64,
    maximum_bytes: u64,
) -> Result<BrokerSpawnWalFileIdentityV1, BrokerSpawnWalError> {
    let named =
        broker_spawn_catalog_stat_identity_at(directory, name, minimum_bytes, maximum_bytes)?;
    let opened = validate_broker_spawn_catalog_file_metadata(
        &file.metadata()?,
        minimum_bytes,
        maximum_bytes,
    )?;
    if named != opened {
        return Err(BrokerSpawnWalError::InsecureCatalogIdentity);
    }
    Ok(opened)
}

#[cfg(any(
    target_os = "android",
    target_os = "ios",
    target_os = "linux",
    target_os = "macos",
    target_os = "tvos",
    target_os = "visionos",
    target_os = "watchos",
))]
fn lock_broker_spawn_catalog(file: &File) -> Result<(), BrokerSpawnWalError> {
    rustix::fs::flock(file, rustix::fs::FlockOperation::NonBlockingLockExclusive).map_err(|error| {
        let error = std::io::Error::from(error);
        if error.kind() == ErrorKind::WouldBlock {
            BrokerSpawnWalError::CatalogAlreadyOwned
        } else {
            BrokerSpawnWalError::Io(error)
        }
    })
}

