fn publish_broker_spawn_completed_marker_noreplace(
    directory: &File,
    creating_name: &OsStr,
    completed_name: &OsStr,
) -> std::io::Result<()> {
    rustix::fs::renameat_with(
        directory,
        creating_name,
        directory,
        completed_name,
        rustix::fs::RenameFlags::NOREPLACE,
    )
    .map_err(std::io::Error::from)
}

