fn publish_broker_spawn_completed_marker_noreplace(
    _directory: &File,
    _creating_name: &OsStr,
    _completed_name: &OsStr,
) -> std::io::Result<()> {
    Err(std::io::Error::new(
        ErrorKind::Unsupported,
        "atomic no-replace broker Spawn creation publication is unsupported",
    ))
}

impl BrokerSpawnWalCatalogV1 {
    /// Open and exclusively pin an existing owner-only catalog directory.
    pub(crate) fn open(directory_path: PathBuf) -> Result<Self, BrokerSpawnWalError> {
        validate_broker_spawn_catalog_path(&directory_path)?;
        let before = std::fs::symlink_metadata(&directory_path)?;
        validate_broker_spawn_catalog_directory_metadata(&before)?;
        let directory = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_CLOEXEC | libc::O_DIRECTORY | libc::O_NOFOLLOW)
            .open(&directory_path)?;
        let opened = directory.metadata()?;
        validate_broker_spawn_catalog_directory_metadata(&opened)?;
        require_same_broker_spawn_catalog_object(&before, &opened)?;
        let after = std::fs::symlink_metadata(&directory_path)?;
        require_same_broker_spawn_catalog_object(&opened, &after)?;
        // The authenticated creation certificate is deliberately close to
        // POSIX NAME_MAX. Query the exact pinned directory before creating
        // even the catalog lock, rather than assuming a platform-wide bound.
        validate_broker_spawn_catalog_name_capacity(&directory)?;

        let lock_name = OsStr::new(BROKER_SPAWN_CATALOG_LOCK_NAME);
        let (lock, created) = match open_broker_spawn_catalog_file_at(&directory, lock_name, true) {
            Ok(lock) => (lock, true),
            Err(error) if error.kind() == ErrorKind::AlreadyExists => {
                // The first catalog opener can die after O_CREAT applies a
                // restrictive umask but before fchmod restores 0600. The
                // fixed, empty lock inode is safe to resume under the same
                // recoverable owner-only mode-subset contract as an in-flight
                // creation marker.
                (
                    open_and_seal_broker_spawn_creation_file_mode_at(&directory, lock_name, 0, 0)?,
                    false,
                )
            }
            Err(error) => return Err(error.into()),
        };
        if created {
            revalidate_open_broker_spawn_catalog_file(&directory, lock_name, &lock, 0, 0)?;
            lock.sync_all()?;
            directory.sync_all()?;
        }
        lock_broker_spawn_catalog(&lock)?;
        let catalog = Self {
            directory_path,
            directory,
            lock,
            #[cfg(test)]
            creation_fault: None,
        };
        catalog.validate_pinned_directory()?;
        catalog.scan_catalog_states()?;
        Ok(catalog)
    }

    /// Admit one globally unique Spawn identity, then durably publish its new
    /// authenticated WAL/head pair.
    ///
    /// The mutable catalog borrow is the process-local serialization authority
    /// for this transition. Every existing pair is authenticated and admitted
    /// into all four lookup namespaces before either new path is created. A
    /// future live Spawn path must use this method; the raw file creator exists
    /// only beneath this admission boundary and in explicit invalid-state test
    /// fixtures.
    pub(crate) fn create_spawn_journal(
        &mut self,
        identity: BrokerSpawnWalIdentityV1,
        authenticator: GuardianBrokerSpawnWalAuthenticatorV1,
    ) -> Result<BrokerSpawnJournalV1, BrokerSpawnWalError> {
        identity.validate()?;
        if identity.broker_lineage_id() != authenticator.lineage_id() {
            return Err(BrokerSpawnWalError::NewJournalLineageMismatch);
        }
        let recovered = self.scan_all_for_admission(&authenticator)?;
        let admitted = BrokerRecoveredSpawnCatalogV1::admit(recovered, &authenticator)?;
        if admitted.journals.len() >= GUARDIAN_MAX_PANES {
            return Err(BrokerSpawnWalError::CapacityExhausted);
        }
        admitted.require_new_identity_available(identity)?;
        drop(admitted);
        self.validate_pinned_directory()?;
        self.create_spawn_journal_after_admission(identity, authenticator, true)
    }

    fn create_spawn_journal_after_admission(
        &mut self,
        identity: BrokerSpawnWalIdentityV1,
        authenticator: GuardianBrokerSpawnWalAuthenticatorV1,
        enforce_catalog_uniqueness: bool,
    ) -> Result<BrokerSpawnJournalV1, BrokerSpawnWalError> {
        identity.validate()?;
        self.validate_pinned_directory()?;
        let states = self.scan_catalog_states()?;
        if states.len() >= GUARDIAN_MAX_PANES || states.contains_key(&identity.journal_id) {
            return Err(BrokerSpawnWalError::CapacityExhausted);
        }
        let creating_name = broker_spawn_creation_marker_name(identity, &authenticator, false)?;
        let completed_name = broker_spawn_creation_marker_name(identity, &authenticator, true)?;
        if creating_name.as_bytes().len() > BROKER_SPAWN_CREATION_MARKER_NAME_BYTES
            || completed_name.as_bytes().len() > BROKER_SPAWN_CREATION_MARKER_NAME_BYTES
            || creating_name == completed_name
        {
            return Err(BrokerSpawnWalError::InvalidCreationMarker);
        }
        validate_broker_spawn_catalog_name_capacity(&self.directory)?;

        // The filename itself carries the complete authenticated identity. A
        // directory entry is atomic, and no canonical member is created until
        // this empty marker and its exact parent directory are synchronized.
        // Thus a crash before this barrier leaves either no marker or one
        // complete recoverable identity, never a canonical member first.
        let marker = open_broker_spawn_catalog_file_at(&self.directory, &creating_name, true)?;
        revalidate_open_broker_spawn_catalog_file(&self.directory, &creating_name, &marker, 0, 0)?;
        #[cfg(test)]
        if self.take_creation_fault(BrokerSpawnCreationInjectedFault::AfterMarkerCreateBeforeSync) {
            return Err(BrokerSpawnWalError::Io(std::io::Error::other(
                "injected broker Spawn creation fault after marker create",
            )));
        }
        marker.sync_all()?;
        #[cfg(test)]
        if self.take_creation_fault(
            BrokerSpawnCreationInjectedFault::AfterMarkerSyncBeforeDirectorySync,
        ) {
            return Err(BrokerSpawnWalError::Io(std::io::Error::other(
                "injected broker Spawn creation fault after marker sync",
            )));
        }
        self.directory.sync_all()?;
        #[cfg(test)]
        if self.take_creation_fault(BrokerSpawnCreationInjectedFault::AfterMarkerDirectorySync) {
            return Err(BrokerSpawnWalError::Io(std::io::Error::other(
                "injected broker Spawn creation fault after marker directory sync",
            )));
        }
        revalidate_open_broker_spawn_catalog_file(&self.directory, &creating_name, &marker, 0, 0)?;
        drop(marker);

        self.recover_creation_transactions(&authenticator, enforce_catalog_uniqueness)?;
        let pairs = self.scan_pairs()?;
        let pair = pairs
            .get(&identity.journal_id)
            .ok_or(BrokerSpawnWalError::InvalidCreationState)?;
        let completed = pair
            .completed
            .as_ref()
            .ok_or(BrokerSpawnWalError::InvalidCreationState)?;
        if completed.identity != identity || completed.name != completed_name {
            return Err(BrokerSpawnWalError::InvalidCreationState);
        }
        let wal_name = broker_spawn_catalog_wal_name(identity.journal_id);
        let head_name = broker_spawn_catalog_head_name(identity.journal_id);
        let wal = open_revalidated_broker_spawn_catalog_file(
            &self.directory,
            &wal_name,
            BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
            BROKER_SPAWN_WAL_MAX_PHYSICAL_BYTES,
        )?;
        let head = open_revalidated_broker_spawn_catalog_file(
            &self.directory,
            &head_name,
            BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
            BROKER_SPAWN_HEAD_MAX_PHYSICAL_BYTES,
        )?;
        let mut journal = BrokerSpawnJournalV1::open(wal, head, identity, authenticator)?;
        let authority = BrokerSpawnWalFilesystemRevalidationV1::from_revalidated_filesystem(
            identity,
            journal.wal.metadata()?.len(),
            journal.head.metadata()?.len(),
        )?;
        journal.reconcile_recovered_head_and_activate(authority)?;
        self.validate_pinned_directory()?;
        Ok(journal)
    }

    #[cfg(test)]
    fn create_spawn_journal_fixture_unadmitted(
        &mut self,
        identity: BrokerSpawnWalIdentityV1,
        authenticator: GuardianBrokerSpawnWalAuthenticatorV1,
    ) -> Result<BrokerSpawnJournalV1, BrokerSpawnWalError> {
        self.create_spawn_journal_after_admission(identity, authenticator, false)
    }

    /// Complete every authenticated header-only creation transaction before
    /// ordinary lifecycle admission. All markers, header prefixes, lineage,
    /// identities, and namespace uniqueness are preflighted before the first
    /// byte is written. The transition has no child effect and is idempotent.
    fn recover_creation_transactions(
        &mut self,
        authenticator: &GuardianBrokerSpawnWalAuthenticatorV1,
        enforce_catalog_uniqueness: bool,
    ) -> Result<(), BrokerSpawnWalError> {
        if self
            .scan_catalog_states()?
            .values()
            .all(|pair| pair.creating.is_none())
        {
            return Ok(());
        }
        let plans =
            self.preflight_creation_transactions(authenticator, enforce_catalog_uniqueness)?;
        for plan in plans {
            self.apply_creation_recovery_plan(plan)?;
        }
        self.validate_pinned_directory()?;
        Ok(())
    }

    fn preflight_creation_transactions(
        &self,
        authenticator: &GuardianBrokerSpawnWalAuthenticatorV1,
        enforce_catalog_uniqueness: bool,
    ) -> Result<Vec<BrokerSpawnCreationRecoveryPlanV1>, BrokerSpawnWalError> {
        self.validate_pinned_directory()?;
        validate_broker_spawn_catalog_name_capacity(&self.directory)?;
        let states = self.scan_catalog_states()?;
        let mut identities = Vec::new();
        identities
            .try_reserve_exact(states.len())
            .map_err(|_| BrokerSpawnWalError::CapacityExhausted)?;
        // Validate every filename certificate, every completed/legacy pair,
        // lineage, and global identity namespace before changing even a
        // recoverable mode bit. A creating pair whose mode was masked by
        // umask cannot always be reopened yet, but its full authenticated
        // identity is available in the filename.
        for (journal_id, pair) in &states {
            if let Some(completed) = pair.completed.as_ref() {
                validate_broker_spawn_creation_marker(completed, authenticator, true)?;
            }
            if let Some(creating) = pair.creating.as_ref() {
                validate_broker_spawn_creation_marker(creating, authenticator, false)?;
            }

            if let Some(creating) = pair.creating.as_ref() {
                if pair.completed.is_some() || creating.identity.journal_id() != *journal_id {
                    return Err(BrokerSpawnWalError::InvalidCreationState);
                }
                identities.push(creating.identity);
                continue;
            }

            let wal_name = pair
                .wal_name
                .as_ref()
                .ok_or(BrokerSpawnWalError::IncompleteCatalogPair)?;
            let head_name = pair
                .head_name
                .as_ref()
                .ok_or(BrokerSpawnWalError::IncompleteCatalogPair)?;
            let mut wal = open_revalidated_broker_spawn_catalog_file(
                &self.directory,
                wal_name,
                BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
                BROKER_SPAWN_WAL_MAX_PHYSICAL_BYTES,
            )?;
            let mut head = open_revalidated_broker_spawn_catalog_file(
                &self.directory,
                head_name,
                BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
                BROKER_SPAWN_HEAD_MAX_PHYSICAL_BYTES,
            )?;
            let wal_identity = read_broker_spawn_header_identity(
                &mut wal,
                BROKER_SPAWN_WAL_FILE_MAGIC,
                authenticator,
            )?;
            let head_identity = read_broker_spawn_header_identity(
                &mut head,
                BROKER_SPAWN_HEAD_FILE_MAGIC,
                authenticator,
            )?;
            if wal_identity != head_identity || wal_identity.journal_id() != *journal_id {
                return Err(BrokerSpawnWalError::CatalogIdentityMismatch);
            }
            if pair
                .completed
                .as_ref()
                .is_some_and(|completed| completed.identity != wal_identity)
            {
                return Err(BrokerSpawnWalError::InvalidCreationState);
            }
            let journal =
                BrokerSpawnJournalV1::open(wal, head, wal_identity, authenticator.clone())?;
            journal.require_healthy_for_recovery()?;
            identities.push(wal_identity);
        }

        if enforce_catalog_uniqueness {
            validate_broker_spawn_catalog_identities(&identities, authenticator)?;
        } else if identities
            .iter()
            .any(|identity| identity.broker_lineage_id() != authenticator.lineage_id())
        {
            return Err(BrokerSpawnWalError::RecoveredCatalogLineageMismatch);
        }

        let mut plans = Vec::new();
        plans
            .try_reserve_exact(states.len())
            .map_err(|_| BrokerSpawnWalError::CapacityExhausted)?;
        for (journal_id, pair) in &states {
            let Some(creating) = pair.creating.as_ref() else {
                continue;
            };
            let wal_header = encode_broker_spawn_file_header(
                BROKER_SPAWN_WAL_FILE_MAGIC,
                creating.identity,
                authenticator,
            )?;
            let head_header = encode_broker_spawn_file_header(
                BROKER_SPAWN_HEAD_FILE_MAGIC,
                creating.identity,
                authenticator,
            )?;
            let marker = open_and_seal_broker_spawn_creation_file_mode_at(
                &self.directory,
                &creating.name,
                0,
                0,
            )?;
            let wal = if let Some(wal_name) = pair.wal_name.as_ref() {
                let mut wal = open_and_seal_broker_spawn_creation_file_mode_at(
                    &self.directory,
                    wal_name,
                    0,
                    BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
                )?;
                validate_broker_spawn_creation_header_prefix(&mut wal, &wal_header)?;
                Some(wal)
            } else {
                None
            };
            let head = if let Some(head_name) = pair.head_name.as_ref() {
                let mut head = open_and_seal_broker_spawn_creation_file_mode_at(
                    &self.directory,
                    head_name,
                    0,
                    BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
                )?;
                validate_broker_spawn_creation_header_prefix(&mut head, &head_header)?;
                Some(head)
            } else {
                None
            };
            plans.push(BrokerSpawnCreationRecoveryPlanV1 {
                marker,
                creating: creating.clone(),
                completed_name: broker_spawn_creation_marker_name(
                    creating.identity,
                    authenticator,
                    true,
                )?,
                wal_name: broker_spawn_catalog_wal_name(*journal_id),
                head_name: broker_spawn_catalog_head_name(*journal_id),
                wal,
                head,
                wal_header,
                head_header,
            });
        }
        if self.scan_catalog_states()? != states {
            return Err(BrokerSpawnWalError::InsecureCatalogIdentity);
        }
        for plan in &mut plans {
            revalidate_open_broker_spawn_catalog_file(
                &self.directory,
                &plan.creating.name,
                &plan.marker,
                0,
                0,
            )?;
            if let Some(wal) = plan.wal.as_mut() {
                revalidate_open_broker_spawn_catalog_file(
                    &self.directory,
                    &plan.wal_name,
                    wal,
                    0,
                    BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
                )?;
                validate_broker_spawn_creation_header_prefix(wal, &plan.wal_header)?;
            }
            if let Some(head) = plan.head.as_mut() {
                revalidate_open_broker_spawn_catalog_file(
                    &self.directory,
                    &plan.head_name,
                    head,
                    0,
                    BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
                )?;
                validate_broker_spawn_creation_header_prefix(head, &plan.head_header)?;
            }
        }
        Ok(plans)
    }

    fn apply_creation_recovery_plan(
        &mut self,
        mut plan: BrokerSpawnCreationRecoveryPlanV1,
    ) -> Result<(), BrokerSpawnWalError> {
        revalidate_open_broker_spawn_catalog_file(
            &self.directory,
            &plan.creating.name,
            &plan.marker,
            0,
            0,
        )?;
        // A process may have died before either synchronization in the
        // original marker barrier. Re-establish both halves on every resume
        // before creating a missing canonical member.
        plan.marker.sync_all()?;
        self.directory.sync_all()?;
        revalidate_open_broker_spawn_catalog_file(
            &self.directory,
            &plan.creating.name,
            &plan.marker,
            0,
            0,
        )?;
        let wal = self.materialize_creation_header(
            plan.wal.take(),
            &plan.wal_name,
            &plan.wal_header,
            true,
        )?;
        #[cfg(test)]
        if self.take_creation_fault(BrokerSpawnCreationInjectedFault::AfterWalHeaderSync) {
            return Err(BrokerSpawnWalError::Io(std::io::Error::other(
                "injected broker Spawn creation fault after WAL header sync",
            )));
        }
        let head = self.materialize_creation_header(
            plan.head.take(),
            &plan.head_name,
            &plan.head_header,
            false,
        )?;
        #[cfg(test)]
        if self.take_creation_fault(BrokerSpawnCreationInjectedFault::AfterHeadHeaderSync) {
            return Err(BrokerSpawnWalError::Io(std::io::Error::other(
                "injected broker Spawn creation fault after head header sync",
            )));
        }

        revalidate_open_broker_spawn_catalog_file(
            &self.directory,
            &plan.wal_name,
            &wal,
            BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
            BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
        )?;
        revalidate_open_broker_spawn_catalog_file(
            &self.directory,
            &plan.head_name,
            &head,
            BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
            BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
        )?;
        self.directory.sync_all()?;
        #[cfg(test)]
        if self.take_creation_fault(
            BrokerSpawnCreationInjectedFault::AfterPairDirectorySyncBeforeMarkerRename,
        ) {
            return Err(BrokerSpawnWalError::Io(std::io::Error::other(
                "injected broker Spawn creation fault before marker publication",
            )));
        }

        revalidate_open_broker_spawn_catalog_file(
            &self.directory,
            &plan.creating.name,
            &plan.marker,
            0,
            0,
        )?;
        publish_broker_spawn_completed_marker_noreplace(
            &self.directory,
            &plan.creating.name,
            &plan.completed_name,
        )?;
        #[cfg(test)]
        if self.take_creation_fault(
            BrokerSpawnCreationInjectedFault::AfterMarkerRenameBeforeDirectorySync,
        ) {
            return Err(BrokerSpawnWalError::Io(std::io::Error::other(
                "injected broker Spawn creation fault after marker publication",
            )));
        }
        revalidate_open_broker_spawn_catalog_file(
            &self.directory,
            &plan.completed_name,
            &plan.marker,
            0,
            0,
        )?;
        self.directory.sync_all()?;

        let states = self.scan_catalog_states()?;
        let completed = states
            .get(&plan.creating.identity.journal_id())
            .and_then(|pair| pair.completed.as_ref())
            .ok_or(BrokerSpawnWalError::InvalidCreationState)?;
        if states
            .get(&plan.creating.identity.journal_id())
            .and_then(|pair| pair.creating.as_ref())
            .is_some()
            || completed.name != plan.completed_name
            || completed.identity != plan.creating.identity
        {
            return Err(BrokerSpawnWalError::InvalidCreationState);
        }
        Ok(())
    }

    #[cfg_attr(not(test), allow(clippy::needless_pass_by_ref_mut))]
    fn materialize_creation_header(
        &mut self,
        existing: Option<File>,
        name: &OsStr,
        expected: &[u8; BROKER_SPAWN_WAL_FILE_HEADER_BYTES],
        _is_wal: bool,
    ) -> Result<File, BrokerSpawnWalError> {
        let mut file = if let Some(file) = existing {
            file
        } else {
            let file = open_broker_spawn_catalog_file_at(&self.directory, name, true)?;
            revalidate_open_broker_spawn_catalog_file(&self.directory, name, &file, 0, 0)?;
            file
        };
        revalidate_open_broker_spawn_catalog_file(
            &self.directory,
            name,
            &file,
            0,
            BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
        )?;
        let durable_prefix_bytes =
            validate_broker_spawn_creation_header_prefix(&mut file, expected)?;
        file.seek(SeekFrom::Start(
            u64::try_from(durable_prefix_bytes)
                .map_err(|_| BrokerSpawnWalError::CapacityExhausted)?,
        ))?;

        #[cfg(test)]
        if let Some(injected_prefix_bytes) = self.take_partial_creation_header_fault(_is_wal) {
            if injected_prefix_bytes < durable_prefix_bytes
                || injected_prefix_bytes > expected.len()
            {
                return Err(BrokerSpawnWalError::InvalidCreationState);
            }
            file.write_all(&expected[durable_prefix_bytes..injected_prefix_bytes])?;
            file.sync_all()?;
            return Err(BrokerSpawnWalError::Io(std::io::Error::other(
                "injected partial broker Spawn creation-header write",
            )));
        }

        file.write_all(&expected[durable_prefix_bytes..])?;
        #[cfg(test)]
        {
            let fault = if _is_wal {
                BrokerSpawnCreationInjectedFault::AfterWalHeaderWriteBeforeSync
            } else {
                BrokerSpawnCreationInjectedFault::AfterHeadHeaderWriteBeforeSync
            };
            if self.take_creation_fault(fault) {
                return Err(BrokerSpawnWalError::Io(std::io::Error::other(
                    "injected broker Spawn creation fault before header sync",
                )));
            }
        }
        file.sync_all()?;
        revalidate_open_broker_spawn_catalog_file(
            &self.directory,
            name,
            &file,
            BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
            BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
        )?;
        validate_broker_spawn_creation_header_prefix(&mut file, expected)?;
        Ok(file)
    }

    #[cfg(test)]
    fn inject_creation_fault(&mut self, fault: BrokerSpawnCreationInjectedFault) {
        self.creation_fault = Some(fault);
    }

    #[cfg(test)]
    fn take_creation_fault(&mut self, expected: BrokerSpawnCreationInjectedFault) -> bool {
        if self.creation_fault == Some(expected) {
            self.creation_fault = None;
            true
        } else {
            false
        }
    }

    #[cfg(test)]
    fn take_partial_creation_header_fault(&mut self, is_wal: bool) -> Option<usize> {
        let observed = self.creation_fault?;
        let prefix = match (is_wal, observed) {
            (
                true,
                BrokerSpawnCreationInjectedFault::DuringWalHeaderWrite {
                    durable_prefix_bytes,
                },
            )
            | (
                false,
                BrokerSpawnCreationInjectedFault::DuringHeadHeaderWrite {
                    durable_prefix_bytes,
                },
            ) => durable_prefix_bytes,
            _ => return None,
        };
        self.creation_fault = None;
        Some(prefix)
    }

    /// Recover authenticated header-creation prefixes, then authenticate and
    /// revalidate every complete catalog pair without granting lifecycle
    /// append authority.
    ///
    /// A filename-carried creation identity may finish missing exact header
    /// suffixes before lifecycle admission; this never performs Spawn or adds
    /// a lifecycle record. Unknown names, unmarked half-pairs, replaced
    /// inodes, torn lifecycle records, key rotation, and catalog drift fail the
    /// entire scan. Cross-journal uniqueness and lifecycle policy are decided
    /// before
    /// [`Self::reconcile_admitted_and_activate`] is called.
    fn scan_all_for_admission(
        &mut self,
        authenticator: &GuardianBrokerSpawnWalAuthenticatorV1,
    ) -> Result<Vec<BrokerSpawnJournalV1>, BrokerSpawnWalError> {
        self.validate_pinned_directory()?;
        self.recover_creation_transactions(authenticator, true)?;
        let pairs = self.scan_pairs()?;
        let mut recovered = Vec::new();
        recovered
            .try_reserve_exact(pairs.len())
            .map_err(|_| BrokerSpawnWalError::CapacityExhausted)?;
        for (journal_id, pair) in &pairs {
            let wal_name = pair
                .wal_name
                .as_ref()
                .ok_or(BrokerSpawnWalError::IncompleteCatalogPair)?;
            let head_name = pair
                .head_name
                .as_ref()
                .ok_or(BrokerSpawnWalError::IncompleteCatalogPair)?;
            let mut wal = open_revalidated_broker_spawn_catalog_file(
                &self.directory,
                wal_name,
                BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
                BROKER_SPAWN_WAL_MAX_PHYSICAL_BYTES,
            )?;
            let head = open_revalidated_broker_spawn_catalog_file(
                &self.directory,
                head_name,
                BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
                BROKER_SPAWN_HEAD_MAX_PHYSICAL_BYTES,
            )?;
            let mut header = [0_u8; BROKER_SPAWN_WAL_FILE_HEADER_BYTES];
            wal.read_exact(&mut header)?;
            wal.rewind()?;
            let (identity, _) = decode_broker_spawn_file_header(
                &header,
                BROKER_SPAWN_WAL_FILE_MAGIC,
                authenticator,
            )?;
            if identity.journal_id != *journal_id {
                return Err(BrokerSpawnWalError::CatalogIdentityMismatch);
            }
            if let Some(completed) = pair.completed.as_ref() {
                validate_broker_spawn_creation_marker(completed, authenticator, true)?;
                if completed.identity != identity {
                    return Err(BrokerSpawnWalError::InvalidCreationState);
                }
            }
            let journal = BrokerSpawnJournalV1::open(wal, head, identity, authenticator.clone())?;
            // A torn physical tail is preserved by `open`, but it is never an
            // admissible catalog member. Reject it in this read-only pass so
            // later lifecycle policy cannot mask the precise corruption and
            // no earlier WAL-ahead member is reconciled first.
            journal.require_healthy_for_recovery()?;
            recovered.push((wal_name.clone(), head_name.clone(), journal));
        }
        if self.scan_pairs()? != pairs {
            return Err(BrokerSpawnWalError::InsecureCatalogIdentity);
        }

        let mut journals = Vec::new();
        journals
            .try_reserve_exact(recovered.len())
            .map_err(|_| BrokerSpawnWalError::CapacityExhausted)?;
        for (wal_name, head_name, journal) in recovered {
            revalidate_open_broker_spawn_catalog_file(
                &self.directory,
                &wal_name,
                &journal.wal,
                BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
                BROKER_SPAWN_WAL_MAX_PHYSICAL_BYTES,
            )?;
            revalidate_open_broker_spawn_catalog_file(
                &self.directory,
                &head_name,
                &journal.head,
                BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
                BROKER_SPAWN_HEAD_MAX_PHYSICAL_BYTES,
            )?;
            journals.push(journal);
        }
        if self.scan_pairs()? != pairs {
            return Err(BrokerSpawnWalError::InsecureCatalogIdentity);
        }
        self.validate_pinned_directory()?;
        Ok(journals)
    }

    /// Revalidate and reconcile a catalog only after complete cross-journal
    /// admission and caller-owned lifecycle policy have succeeded.
    ///
    /// A valid WAL-ahead crash cut may append one authenticated local-head
    /// record. No durable write occurs before this explicit transition.
    fn reconcile_admitted_and_activate(
        &self,
        admitted: &mut BrokerRecoveredSpawnCatalogV1,
    ) -> Result<(), BrokerSpawnWalError> {
        self.validate_pinned_directory()?;
        let pairs = self.scan_pairs()?;
        if pairs.len() != admitted.journals.len()
            || admitted
                .journals
                .iter()
                .any(|journal| !pairs.contains_key(&journal.identity().journal_id()))
        {
            return Err(BrokerSpawnWalError::InsecureCatalogIdentity);
        }

        let mut activations = Vec::new();
        activations
            .try_reserve_exact(admitted.journals.len())
            .map_err(|_| BrokerSpawnWalError::CapacityExhausted)?;
        for journal in &admitted.journals {
            let journal_id = journal.identity().journal_id();
            let wal_name = broker_spawn_catalog_wal_name(journal_id);
            let head_name = broker_spawn_catalog_head_name(journal_id);
            let wal_identity = revalidate_open_broker_spawn_catalog_file(
                &self.directory,
                &wal_name,
                &journal.wal,
                BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
                BROKER_SPAWN_WAL_MAX_PHYSICAL_BYTES,
            )?;
            let head_identity = revalidate_open_broker_spawn_catalog_file(
                &self.directory,
                &head_name,
                &journal.head,
                BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
                BROKER_SPAWN_HEAD_MAX_PHYSICAL_BYTES,
            )?;
            let authority = BrokerSpawnWalFilesystemRevalidationV1::from_revalidated_filesystem(
                journal.identity,
                wal_identity.bytes,
                head_identity.bytes,
            )?;
            activations.push(journal.preflight_recovered_head_activation(authority)?);
        }
        if self.scan_pairs()? != pairs {
            return Err(BrokerSpawnWalError::InsecureCatalogIdentity);
        }
        self.validate_pinned_directory()?;

        // Every deterministic/global validation, conversion, fixed-size
        // encoding, and allocation completed in the read-only pass above. No
        // multi-file atomic transaction exists: later descriptor drift or I/O
        // can still fail after an earlier head was reconciled, and a short or
        // ambiguously synchronized write can leave a partial current head.
        // Reconciliation is append-only, preserves that evidence, and fails
        // closed; all-or-nothing recovery across I/O faults remains pending.
        for (journal, activation) in admitted.journals.iter_mut().zip(activations) {
            journal.apply_recovered_head_activation(activation)?;
        }

        for journal in &admitted.journals {
            let journal_id = journal.identity().journal_id();
            let wal_name = broker_spawn_catalog_wal_name(journal_id);
            let head_name = broker_spawn_catalog_head_name(journal_id);
            revalidate_open_broker_spawn_catalog_file(
                &self.directory,
                &wal_name,
                &journal.wal,
                BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
                BROKER_SPAWN_WAL_MAX_PHYSICAL_BYTES,
            )?;
            revalidate_open_broker_spawn_catalog_file(
                &self.directory,
                &head_name,
                &journal.head,
                BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
                BROKER_SPAWN_HEAD_MAX_PHYSICAL_BYTES,
            )?;
        }
        if self.scan_pairs()? != pairs {
            return Err(BrokerSpawnWalError::InsecureCatalogIdentity);
        }
        self.validate_pinned_directory()
    }

    fn validate_pinned_directory(&self) -> Result<(), BrokerSpawnWalError> {
        validate_broker_spawn_catalog_path(&self.directory_path)?;
        let opened = self.directory.metadata()?;
        validate_broker_spawn_catalog_directory_metadata(&opened)?;
        let named = std::fs::symlink_metadata(&self.directory_path)?;
        validate_broker_spawn_catalog_directory_metadata(&named)?;
        require_same_broker_spawn_catalog_object(&opened, &named)?;
        revalidate_open_broker_spawn_catalog_file(
            &self.directory,
            OsStr::new(BROKER_SPAWN_CATALOG_LOCK_NAME),
            &self.lock,
            0,
            0,
        )?;
        Ok(())
    }

    fn scan_pairs(
        &self,
    ) -> Result<BTreeMap<Uuid, BrokerSpawnWalCatalogPairV1>, BrokerSpawnWalError> {
        let states = self.scan_catalog_states()?;
        Ok(states
            .into_iter()
            .filter(|(_, pair)| pair.creating.is_none())
            .collect())
    }

    fn scan_catalog_states(
        &self,
    ) -> Result<BTreeMap<Uuid, BrokerSpawnWalCatalogPairV1>, BrokerSpawnWalError> {
        let mut directory =
            rustix::fs::Dir::read_from(&self.directory).map_err(std::io::Error::from)?;
        let mut pairs: BTreeMap<Uuid, BrokerSpawnWalCatalogPairV1> = BTreeMap::new();
        let mut observed_entries = 0_usize;
        let mut observed_bytes = 0_u64;
        while let Some(entry) = directory.read() {
            let entry = entry.map_err(std::io::Error::from)?;
            let name = entry.file_name();
            if name.to_bytes() == b"." || name.to_bytes() == b".." {
                continue;
            }
            observed_entries = observed_entries
                .checked_add(1)
                .ok_or(BrokerSpawnWalError::CapacityExhausted)?;
            if observed_entries > BROKER_SPAWN_CATALOG_MAX_ENTRIES {
                return Err(BrokerSpawnWalError::CapacityExhausted);
            }
            let name = OsStr::from_bytes(name.to_bytes());
            if name == OsStr::new(BROKER_SPAWN_CATALOG_LOCK_NAME) {
                let lock = broker_spawn_catalog_stat_identity_at(&self.directory, name, 0, 0)?;
                observed_bytes = observed_bytes
                    .checked_add(lock.bytes)
                    .ok_or(BrokerSpawnWalError::CapacityExhausted)?;
                continue;
            }
            match parse_broker_spawn_catalog_name(name)? {
                BrokerSpawnCatalogNameV1::Wal(journal_id) => {
                    // Enumeration order is unspecified, so the corresponding
                    // creating marker may be encountered later. Accept only a
                    // secure owner-only mode subset here; the completed-state
                    // pass below still requires exact 0600.
                    let identity = broker_spawn_catalog_stat_recoverable_creation_identity_at(
                        &self.directory,
                        name,
                        0,
                        BROKER_SPAWN_WAL_MAX_PHYSICAL_BYTES,
                    )?;
                    observed_bytes = observed_bytes
                        .checked_add(identity.bytes)
                        .ok_or(BrokerSpawnWalError::CapacityExhausted)?;
                    let pair = pairs.entry(journal_id).or_default();
                    if pair.wal_name.replace(name.to_os_string()).is_some() {
                        return Err(BrokerSpawnWalError::UnexpectedCatalogEntry);
                    }
                }
                BrokerSpawnCatalogNameV1::Head(journal_id) => {
                    let identity = broker_spawn_catalog_stat_recoverable_creation_identity_at(
                        &self.directory,
                        name,
                        0,
                        BROKER_SPAWN_HEAD_MAX_PHYSICAL_BYTES,
                    )?;
                    observed_bytes = observed_bytes
                        .checked_add(identity.bytes)
                        .ok_or(BrokerSpawnWalError::CapacityExhausted)?;
                    let pair = pairs.entry(journal_id).or_default();
                    if pair.head_name.replace(name.to_os_string()).is_some() {
                        return Err(BrokerSpawnWalError::UnexpectedCatalogEntry);
                    }
                }
                BrokerSpawnCatalogNameV1::Creating(marker) => {
                    let identity = broker_spawn_catalog_stat_recoverable_creation_identity_at(
                        &self.directory,
                        name,
                        0,
                        0,
                    )?;
                    observed_bytes = observed_bytes
                        .checked_add(identity.bytes)
                        .ok_or(BrokerSpawnWalError::CapacityExhausted)?;
                    let pair = pairs.entry(marker.identity.journal_id()).or_default();
                    if pair.creating.replace(marker).is_some() {
                        return Err(BrokerSpawnWalError::InvalidCreationState);
                    }
                }
                BrokerSpawnCatalogNameV1::Completed(marker) => {
                    let identity =
                        broker_spawn_catalog_stat_identity_at(&self.directory, name, 0, 0)?;
                    observed_bytes = observed_bytes
                        .checked_add(identity.bytes)
                        .ok_or(BrokerSpawnWalError::CapacityExhausted)?;
                    let pair = pairs.entry(marker.identity.journal_id()).or_default();
                    if pair.completed.replace(marker).is_some() {
                        return Err(BrokerSpawnWalError::InvalidCreationState);
                    }
                }
            }
        }
        if pairs.len() > GUARDIAN_MAX_PANES
            || observed_bytes > BROKER_SPAWN_CATALOG_MAX_PHYSICAL_BYTES
        {
            return Err(BrokerSpawnWalError::CapacityExhausted);
        }
        for pair in pairs.values() {
            if pair.creating.is_some() && pair.completed.is_some() {
                return Err(BrokerSpawnWalError::InvalidCreationState);
            }
            if pair.creating.is_some() {
                if let Some(wal_name) = pair.wal_name.as_ref() {
                    broker_spawn_catalog_stat_recoverable_creation_identity_at(
                        &self.directory,
                        wal_name,
                        0,
                        BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
                    )?;
                }
                if let Some(head_name) = pair.head_name.as_ref() {
                    broker_spawn_catalog_stat_recoverable_creation_identity_at(
                        &self.directory,
                        head_name,
                        0,
                        BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
                    )?;
                }
            } else if pair.wal_name.is_none() || pair.head_name.is_none() {
                return Err(if pair.completed.is_some() {
                    BrokerSpawnWalError::InvalidCreationState
                } else {
                    BrokerSpawnWalError::IncompleteCatalogPair
                });
            } else {
                broker_spawn_catalog_stat_identity_at(
                    &self.directory,
                    pair.wal_name.as_deref().expect("validated WAL name"),
                    BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
                    BROKER_SPAWN_WAL_MAX_PHYSICAL_BYTES,
                )?;
                broker_spawn_catalog_stat_identity_at(
                    &self.directory,
                    pair.head_name.as_deref().expect("validated head name"),
                    BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
                    BROKER_SPAWN_HEAD_MAX_PHYSICAL_BYTES,
                )?;
            }
        }
        Ok(pairs)
    }
}

impl BrokerSpawnJournalV1 {
    /// Initialize two exclusively created, empty regular-file descriptors.
    ///
    /// Both authenticated headers are synchronized before this returns. No
    /// record append is allowed until the exact parent directory descriptor is
    /// synchronized, making publication of both names durable as one startup
    /// barrier.
    pub(crate) fn create(
        mut wal: File,
        mut head: File,
        identity: BrokerSpawnWalIdentityV1,
        authenticator: GuardianBrokerSpawnWalAuthenticatorV1,
    ) -> Result<Self, BrokerSpawnWalError> {
        identity.validate()?;
        if !wal.metadata()?.file_type().is_file() || !head.metadata()?.file_type().is_file() {
            return Err(BrokerSpawnWalError::NotRegularFile);
        }
        if wal.metadata()?.len() != 0 || head.metadata()?.len() != 0 {
            return Err(BrokerSpawnWalError::NewJournalNotEmpty);
        }
        let wal_header =
            encode_broker_spawn_file_header(BROKER_SPAWN_WAL_FILE_MAGIC, identity, &authenticator)?;
        let head_header = encode_broker_spawn_file_header(
            BROKER_SPAWN_HEAD_FILE_MAGIC,
            identity,
            &authenticator,
        )?;
        wal.seek(SeekFrom::Start(0))?;
        wal.write_all(&wal_header)?;
        wal.sync_all()?;
        head.seek(SeekFrom::Start(0))?;
        head.write_all(&head_header)?;
        head.sync_all()?;
        let mut records = Vec::new();
        records
            .try_reserve_exact(
                usize::try_from(BROKER_SPAWN_WAL_MAX_RECORDS)
                    .map_err(|_| BrokerSpawnWalError::CapacityExhausted)?,
            )
            .map_err(|_| BrokerSpawnWalError::CapacityExhausted)?;
        Ok(Self {
            wal,
            head,
            identity,
            authenticator,
            header_mac: read_broker_array_32(&wal_header[192..224]),
            head_header_mac: read_broker_array_32(&head_header[192..224]),
            committed_wal_bytes: BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
            committed_head_bytes: BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
            wal_trailing_bytes: 0,
            head_trailing_bytes: 0,
            records,
            terminal_head_mac: read_broker_array_32(&head_header[192..224]),
            publication_binding: None,
            directory_entry_sync_required: true,
            recovery_append_authority_withheld: false,
            head_reconciliation_required: false,
            poisoned: false,
            #[cfg(test)]
            injected_fault: None,
        })
    }

    /// Authenticate and recover an existing WAL/head pair without granting
    /// append authority.
    ///
    /// A complete WAL may be exactly one record ahead of its local head: that
    /// is the deliberate crash cut after WAL `sync_all` and before head
    /// `sync_all`. Head-ahead, divergent, multi-record-ahead, or incomplete
    /// pairs fail closed and preserve all bytes.
    pub(crate) fn open(
        mut wal: File,
        mut head: File,
        identity: BrokerSpawnWalIdentityV1,
        authenticator: GuardianBrokerSpawnWalAuthenticatorV1,
    ) -> Result<Self, BrokerSpawnWalError> {
        identity.validate()?;
        let (header_mac, mut wal_scan) = scan_broker_spawn_wal(&mut wal, identity, &authenticator)?;
        let (head_header_mac, head_scan) =
            scan_broker_spawn_head(&mut head, identity, &authenticator, &wal_scan.records)?;
        let wal_record_count = wal_scan.records.len();
        let head_record_count = head_scan.record_macs.len();
        let head_gap = wal_record_count
            .checked_sub(head_record_count)
            .ok_or(BrokerSpawnWalError::HeadAnchorMismatch)?;
        if head_gap > 1 {
            return Err(BrokerSpawnWalError::HeadReconciliationGap);
        }
        for (index, head_mac) in head_scan.record_macs.iter().copied().enumerate() {
            let record = wal_scan
                .records
                .get_mut(index)
                .ok_or(BrokerSpawnWalError::HeadAnchorMismatch)?;
            record.receipt.head_mac = head_mac;
            record.receipt.committed_head_bytes = BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64
                + u64::try_from(index + 1).map_err(|_| BrokerSpawnWalError::CapacityExhausted)?
                    * BROKER_SPAWN_HEAD_RECORD_BYTES_U64;
        }
        let mut records = Vec::new();
        records
            .try_reserve_exact(
                usize::try_from(BROKER_SPAWN_WAL_MAX_RECORDS)
                    .map_err(|_| BrokerSpawnWalError::CapacityExhausted)?,
            )
            .map_err(|_| BrokerSpawnWalError::CapacityExhausted)?;
        records.extend(wal_scan.records);
        Ok(Self {
            wal,
            head,
            identity,
            authenticator,
            header_mac,
            head_header_mac,
            committed_wal_bytes: wal_scan.committed_bytes,
            committed_head_bytes: head_scan.committed_bytes,
            wal_trailing_bytes: wal_scan.trailing_bytes,
            head_trailing_bytes: head_scan.trailing_bytes,
            records,
            terminal_head_mac: head_scan.terminal_head_mac,
            publication_binding: None,
            directory_entry_sync_required: false,
            recovery_append_authority_withheld: true,
            head_reconciliation_required: head_gap == 1,
            poisoned: false,
            #[cfg(test)]
            injected_fault: None,
        })
    }

    #[must_use]
    pub const fn identity(&self) -> BrokerSpawnWalIdentityV1 {
        self.identity
    }

    #[must_use]
    pub fn status(&self) -> BrokerSpawnWalStatusV1 {
        let terminal = self.records.last().copied();
        let child_identity = terminal.and_then(|record| record.child_identity);
        BrokerSpawnWalStatusV1 {
            identity: self.identity,
            phase: terminal.map(|record| record.phase),
            attempt_id: terminal
                .filter(|record| !record.attempt_id.is_nil())
                .map(|record| record.attempt_id),
            child_identity,
            reply_ack_id: terminal
                .filter(|record| record.phase == BrokerSpawnWalPhaseV1::ReplyAcknowledged)
                .map(|record| record.operation_id),
            recovery_verifier: terminal.and_then(|record| record.recovery_verifier),
            committed_records: u64::try_from(self.records.len()).unwrap_or(u64::MAX),
            committed_wal_bytes: self.committed_wal_bytes,
            committed_head_bytes: self.committed_head_bytes,
            tail: if self.wal_trailing_bytes == 0 && self.head_trailing_bytes == 0 {
                BrokerSpawnWalTailV1::Clean
            } else {
                BrokerSpawnWalTailV1::Incomplete {
                    wal_trailing_bytes: self.wal_trailing_bytes,
                    head_trailing_bytes: self.head_trailing_bytes,
                }
            },
            append_authority_withheld: self.directory_entry_sync_required
                || self.recovery_append_authority_withheld
                || self.head_reconciliation_required
                || self.poisoned
                || self.wal_trailing_bytes != 0
                || self.head_trailing_bytes != 0,
            head_reconciliation_required: self.head_reconciliation_required,
        }
    }

    #[must_use]
    pub const fn is_poisoned(&self) -> bool {
        self.poisoned
    }

    fn bind_parent_publication(
        &mut self,
        parent_directory: &File,
        wal_name: &OsStr,
        head_name: &OsStr,
    ) -> Result<(), BrokerSpawnWalError> {
        if !self.directory_entry_sync_required || self.publication_binding.is_some() {
            return Err(BrokerSpawnWalError::DirectoryEntryNotDurable);
        }
        let parent = parent_directory.metadata()?;
        validate_broker_spawn_catalog_directory_metadata(&parent)?;
        revalidate_open_broker_spawn_catalog_file(
            parent_directory,
            wal_name,
            &self.wal,
            BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
            BROKER_SPAWN_WAL_MAX_PHYSICAL_BYTES,
        )?;
        revalidate_open_broker_spawn_catalog_file(
            parent_directory,
            head_name,
            &self.head,
            BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
            BROKER_SPAWN_HEAD_MAX_PHYSICAL_BYTES,
        )?;
        self.publication_binding = Some(BrokerSpawnWalPublicationBindingV1 {
            parent_device: parent.dev(),
            parent_inode: parent.ino(),
            wal_name: wal_name.to_os_string(),
            head_name: head_name.to_os_string(),
        });
        Ok(())
    }

    /// Synchronize the exact parent that published both newly created files.
    pub fn sync_parent_directory_and_activate(
        &mut self,
        parent_directory: &File,
    ) -> Result<(), BrokerSpawnWalError> {
        if !self.directory_entry_sync_required {
            return Ok(());
        }
        let Some(binding) = self.publication_binding.as_ref() else {
            return Err(BrokerSpawnWalError::DirectoryEntryNotDurable);
        };
        let parent = parent_directory.metadata()?;
        validate_broker_spawn_catalog_directory_metadata(&parent)?;
        if parent.dev() != binding.parent_device || parent.ino() != binding.parent_inode {
            return Err(BrokerSpawnWalError::InsecureCatalogIdentity);
        }
        revalidate_open_broker_spawn_catalog_file(
            parent_directory,
            &binding.wal_name,
            &self.wal,
            BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
            BROKER_SPAWN_WAL_MAX_PHYSICAL_BYTES,
        )?;
        revalidate_open_broker_spawn_catalog_file(
            parent_directory,
            &binding.head_name,
            &self.head,
            BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
            BROKER_SPAWN_HEAD_MAX_PHYSICAL_BYTES,
        )?;
        parent_directory.sync_all()?;
        self.directory_entry_sync_required = false;
        self.publication_binding = None;
        Ok(())
    }

    /// Reconcile the only permitted recovery cut and restore append authority.
    ///
    /// The service must mint `authority` only after revalidating the no-follow,
    /// owner-only, single-link WAL/head names, their exact open inodes, the
    /// stable token identity, and the pinned parent directory. Incomplete tails
    /// are never truncated or repaired in place.
    pub(crate) fn reconcile_recovered_head_and_activate(
        &mut self,
        authority: BrokerSpawnWalFilesystemRevalidationV1,
    ) -> Result<(), BrokerSpawnWalError> {
        let activation = self.preflight_recovered_head_activation(authority)?;
        self.apply_recovered_head_activation(activation)
    }

    fn preflight_recovered_head_activation(
        &self,
        authority: BrokerSpawnWalFilesystemRevalidationV1,
    ) -> Result<BrokerSpawnWalRecoveryActivationV1, BrokerSpawnWalError> {
        self.require_healthy_for_recovery()?;
        if authority.identity != self.identity {
            return Err(BrokerSpawnWalError::FilesystemRevalidationMismatch);
        }
        let authoritative_lengths = (authority.observed_wal_bytes, authority.observed_head_bytes);
        let recovered_lengths = (
            self.committed_wal_bytes,
            self.committed_head_bytes
                .checked_add(self.head_trailing_bytes)
                .ok_or(BrokerSpawnWalError::CapacityExhausted)?,
        );
        if authoritative_lengths != recovered_lengths {
            return Err(BrokerSpawnWalError::FilesystemRevalidationMismatch);
        }
        let descriptor_lengths = (self.wal.metadata()?.len(), self.head.metadata()?.len());
        if descriptor_lengths != authoritative_lengths {
            return Err(BrokerSpawnWalError::FilesystemRevalidationMismatch);
        }
        let head = if self.head_reconciliation_required {
            let record = self
                .records
                .last()
                .copied()
                .ok_or(BrokerSpawnWalError::HeadAnchorMismatch)?;
            let terminal_index = self
                .records
                .len()
                .checked_sub(1)
                .ok_or(BrokerSpawnWalError::HeadAnchorMismatch)?;
            let expected_sequence = u64::try_from(terminal_index)
                .map_err(|_| BrokerSpawnWalError::CapacityExhausted)?;
            if record.receipt.sequence != expected_sequence {
                return Err(BrokerSpawnWalError::SequenceMismatch);
            }
            let encoded = encode_broker_spawn_head_record(
                self.head_header_mac,
                &self.authenticator,
                expected_sequence,
                record.receipt.record_mac,
                self.terminal_head_mac,
            )?;
            let projected_head_bytes = self
                .committed_head_bytes
                .checked_add(BROKER_SPAWN_HEAD_RECORD_BYTES_U64)
                .ok_or(BrokerSpawnWalError::CapacityExhausted)?;
            let durable_prefix_bytes = usize::try_from(self.head_trailing_bytes)
                .map_err(|_| BrokerSpawnWalError::CapacityExhausted)?;
            if durable_prefix_bytes >= BROKER_SPAWN_HEAD_RECORD_BYTES {
                return Err(BrokerSpawnWalError::IncompleteTail);
            }
            let head_mac = read_broker_array_32(&encoded[88..120]);
            Some(BrokerSpawnWalHeadReconciliationV1 {
                encoded,
                durable_prefix_bytes,
                projected_head_bytes,
                head_mac,
            })
        } else {
            None
        };
        Ok(BrokerSpawnWalRecoveryActivationV1 { authority, head })
    }

    fn apply_recovered_head_activation(
        &mut self,
        activation: BrokerSpawnWalRecoveryActivationV1,
    ) -> Result<(), BrokerSpawnWalError> {
        self.require_healthy_for_recovery()?;
        if activation.authority.identity != self.identity {
            return Err(BrokerSpawnWalError::FilesystemRevalidationMismatch);
        }
        let authoritative_lengths = (
            activation.authority.observed_wal_bytes,
            activation.authority.observed_head_bytes,
        );
        let recovered_lengths = (
            self.committed_wal_bytes,
            self.committed_head_bytes
                .checked_add(self.head_trailing_bytes)
                .ok_or(BrokerSpawnWalError::CapacityExhausted)?,
        );
        if authoritative_lengths != recovered_lengths {
            return Err(BrokerSpawnWalError::FilesystemRevalidationMismatch);
        }
        let descriptor_lengths = (self.wal.metadata()?.len(), self.head.metadata()?.len());
        if descriptor_lengths != authoritative_lengths {
            return Err(BrokerSpawnWalError::FilesystemRevalidationMismatch);
        }
        match (self.head_reconciliation_required, activation.head) {
            (true, Some(head)) => {
                let terminal = self
                    .records
                    .last_mut()
                    .ok_or(BrokerSpawnWalError::HeadAnchorMismatch)?;
                let result = (|| -> std::io::Result<()> {
                    let write_offset = self
                        .committed_head_bytes
                        .checked_add(self.head_trailing_bytes)
                        .ok_or_else(|| std::io::Error::other("head write offset overflow"))?;
                    self.head.seek(SeekFrom::Start(write_offset))?;
                    #[cfg(test)]
                    if self.injected_fault
                        == Some(BrokerSpawnWalInjectedFault::DuringRecoveredHeadWrite)
                    {
                        self.injected_fault = None;
                        let remaining = &head.encoded[head.durable_prefix_bytes..];
                        let injected_prefix_bytes = remaining.len().min(37);
                        self.head.write_all(&remaining[..injected_prefix_bytes])?;
                        self.head.sync_all()?;
                        return Err(std::io::Error::other(
                            "injected partial recovered-head write",
                        ));
                    }
                    self.head
                        .write_all(&head.encoded[head.durable_prefix_bytes..])?;
                    self.head.sync_all()
                })();
                if let Err(error) = result {
                    self.poisoned = true;
                    return Err(BrokerSpawnWalError::Io(error));
                }
                self.committed_head_bytes = head.projected_head_bytes;
                self.head_trailing_bytes = 0;
                self.terminal_head_mac = head.head_mac;
                terminal.receipt.head_mac = head.head_mac;
                terminal.receipt.committed_head_bytes = self.committed_head_bytes;
                self.head_reconciliation_required = false;
            }
            (false, None) => {}
            _ => return Err(BrokerSpawnWalError::FilesystemRevalidationMismatch),
        }
        self.recovery_append_authority_withheld = false;
        Ok(())
    }

    fn require_healthy_for_recovery(&self) -> Result<(), BrokerSpawnWalError> {
        if self.poisoned {
            return Err(BrokerSpawnWalError::Poisoned);
        }
        if self.directory_entry_sync_required {
            return Err(BrokerSpawnWalError::DirectoryEntryNotDurable);
        }
        if self.wal_trailing_bytes != 0
            || (self.head_trailing_bytes != 0 && !self.head_reconciliation_required)
        {
            return Err(BrokerSpawnWalError::IncompleteTail);
        }
        Ok(())
    }

    fn require_append_authority(&self) -> Result<(), BrokerSpawnWalError> {
        self.require_healthy_for_recovery()?;
        if self.recovery_append_authority_withheld || self.head_reconciliation_required {
            return Err(BrokerSpawnWalError::RecoveryAuthorityUnavailable);
        }
        if self.records.len()
            >= usize::try_from(BROKER_SPAWN_WAL_MAX_RECORDS)
                .map_err(|_| BrokerSpawnWalError::CapacityExhausted)?
        {
            return Err(BrokerSpawnWalError::CapacityExhausted);
        }
        Ok(())
    }

    #[cfg(test)]
    fn inject_fault(&mut self, fault: BrokerSpawnWalInjectedFault) {
        self.injected_fault = Some(fault);
    }

    #[cfg(test)]
    fn fail_if_injected(&mut self, fault: BrokerSpawnWalInjectedFault) -> std::io::Result<()> {
        if self.injected_fault == Some(fault) {
            self.injected_fault = None;
            Err(std::io::Error::other("injected broker Spawn WAL fault"))
        } else {
            Ok(())
        }
    }

    #[cfg(test)]
    fn fail_if_injected_for_phase(
        &mut self,
        generic: BrokerSpawnWalInjectedFault,
        phase_specific: BrokerSpawnWalInjectedFault,
    ) -> std::io::Result<()> {
        if self.injected_fault == Some(generic) || self.injected_fault == Some(phase_specific) {
            self.injected_fault = None;
            Err(std::io::Error::other("injected broker Spawn WAL fault"))
        } else {
            Ok(())
        }
    }
}

impl BrokerSpawnWalFilesystemRevalidationV1 {
    /// Mint recovery authority after the service has revalidated both pinned
    /// descriptors and their durable names. Raw wire fields must never call
    /// this constructor.
    pub(crate) fn from_revalidated_filesystem(
        identity: BrokerSpawnWalIdentityV1,
        observed_wal_bytes: u64,
        observed_head_bytes: u64,
    ) -> Result<Self, BrokerSpawnWalError> {
        identity.validate()?;
        if observed_wal_bytes < BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64
            || observed_head_bytes < BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64
        {
            return Err(BrokerSpawnWalError::FilesystemRevalidationMismatch);
        }
        Ok(Self {
            identity,
            observed_wal_bytes,
            observed_head_bytes,
        })
    }
}

impl BrokerSpawnJournalV1 {
    /// Synchronize the durable pre-effect intent. Exact retries return the
    /// original receipt and never advance the phase.
    pub fn append_intent_and_sync(
        &mut self,
    ) -> Result<BrokerSpawnWalReceiptV1, BrokerSpawnWalError> {
        if let Some(intent) = self.records.first() {
            if intent.phase == BrokerSpawnWalPhaseV1::Intent
                && intent.operation_id == self.identity.origin_request_id
            {
                return Ok(intent.receipt);
            }
            return Err(BrokerSpawnWalError::EffectIdentityConflict);
        }
        self.append_record_and_head(
            BrokerSpawnWalPhaseV1::Intent,
            self.identity.origin_request_id,
            Uuid::nil(),
            None,
            None,
        )
    }

    /// Synchronize the one-way Attempt fence before invoking Spawn.
    ///
    /// Only a newly synchronized Attempt yields the non-cloneable callback
    /// permit. An exact retry after reply loss returns Query state and cannot
    /// invoke Spawn again.
    pub fn begin_spawn_attempt_and_sync(
        &mut self,
        attempt_id: Uuid,
    ) -> Result<BrokerSpawnAttemptAdmissionV1, BrokerSpawnWalError> {
        if attempt_id.is_nil() {
            return Err(BrokerSpawnWalError::InvalidIdentity);
        }
        let terminal = self.records.last().copied();
        match terminal {
            Some(record) if record.phase == BrokerSpawnWalPhaseV1::Intent => {
                let receipt = self.append_record_and_head(
                    BrokerSpawnWalPhaseV1::Attempted,
                    attempt_id,
                    attempt_id,
                    None,
                    None,
                )?;
                Ok(BrokerSpawnAttemptAdmissionV1::Authorized(
                    BrokerSpawnAttemptPermitV1 {
                        identity: self.identity,
                        attempt_id,
                        attempt_record_mac: receipt.record_mac,
                    },
                ))
            }
            Some(record)
                if matches!(
                    record.phase,
                    BrokerSpawnWalPhaseV1::Attempted
                        | BrokerSpawnWalPhaseV1::SpawnObserved
                        | BrokerSpawnWalPhaseV1::ReplyAcknowledged
                ) && record.attempt_id == attempt_id =>
            {
                Ok(BrokerSpawnAttemptAdmissionV1::Reconciled(self.status()))
            }
            Some(_) => Err(BrokerSpawnWalError::EffectIdentityConflict),
            None => Err(BrokerSpawnWalError::InvalidTransition),
        }
    }

    /// Synchronize the exact non-recycled child identity after the authorized
    /// callback returned. Failure after the callback leaves Attempt durable and
    /// permanently ambiguous; the caller still owns the callback's returned
    /// value and must retain/quarantine it rather than retrying Spawn.
    #[cfg(test)]
    pub fn append_spawn_observed_and_sync(
        &mut self,
        observation: BrokerSpawnObservationPermitV1,
    ) -> Result<BrokerSpawnWalReceiptV1, BrokerSpawnWalError> {
        let recovery_secret = BrokerPaneRecoverySecretV1::generate()
            .map_err(|_| BrokerSpawnWalError::RecoveryVerifierUnavailable)?;
        let recovery_verifier = recovery_secret
            .verifier(observation.identity, 1)
            .map_err(|_| BrokerSpawnWalError::RecoveryVerifierUnavailable)?;
        self.append_spawn_observed_with_recovery_and_sync(observation, recovery_verifier)
    }

    fn append_spawn_observed_with_recovery_and_sync(
        &mut self,
        observation: BrokerSpawnObservationPermitV1,
        recovery_verifier: BrokerPaneRecoveryVerifierV1,
    ) -> Result<BrokerSpawnWalReceiptV1, BrokerSpawnWalError> {
        observation.child_identity.validate()?;
        if observation.identity != self.identity {
            return Err(BrokerSpawnWalError::EffectIdentityConflict);
        }
        let attempt = self
            .records
            .get(1)
            .copied()
            .ok_or(BrokerSpawnWalError::InvalidTransition)?;
        if attempt.phase != BrokerSpawnWalPhaseV1::Attempted
            || attempt.attempt_id != observation.attempt_id
            || attempt.receipt.record_mac != observation.attempt_record_mac
        {
            return Err(BrokerSpawnWalError::EffectIdentityConflict);
        }
        match self.records.last().copied() {
            Some(record) if record.phase == BrokerSpawnWalPhaseV1::Attempted => self
                .append_record_and_head(
                    BrokerSpawnWalPhaseV1::SpawnObserved,
                    observation.attempt_id,
                    observation.attempt_id,
                    Some(observation.child_identity),
                    Some(recovery_verifier),
                ),
            Some(record)
                if matches!(
                    record.phase,
                    BrokerSpawnWalPhaseV1::SpawnObserved | BrokerSpawnWalPhaseV1::ReplyAcknowledged
                ) && record.attempt_id == observation.attempt_id
                    && record.child_identity == Some(observation.child_identity) =>
            {
                if record.recovery_verifier == Some(recovery_verifier) {
                    Ok(record.receipt)
                } else {
                    Err(BrokerSpawnWalError::EffectIdentityConflict)
                }
            }
            Some(_) => Err(BrokerSpawnWalError::EffectIdentityConflict),
            None => Err(BrokerSpawnWalError::InvalidTransition),
        }
    }

    /// Durably acknowledge delivery of the exact Spawned Query result.
    ///
    /// A lost acknowledgement reply is idempotent for the same `ack_id`; no
    /// additional phase records or child effects are created.
    pub fn acknowledge_spawn_reply_and_sync(
        &mut self,
        ack_id: Uuid,
        child_identity: BrokerKernelChildIdentityV1,
    ) -> Result<BrokerSpawnWalReceiptV1, BrokerSpawnWalError> {
        if ack_id.is_nil() {
            return Err(BrokerSpawnWalError::InvalidIdentity);
        }
        child_identity.validate()?;
        match self.records.last().copied() {
            Some(record)
                if record.phase == BrokerSpawnWalPhaseV1::SpawnObserved
                    && record.child_identity == Some(child_identity) =>
            {
                self.append_record_and_head(
                    BrokerSpawnWalPhaseV1::ReplyAcknowledged,
                    ack_id,
                    record.attempt_id,
                    Some(child_identity),
                    record.recovery_verifier,
                )
            }
            Some(record)
                if record.phase == BrokerSpawnWalPhaseV1::ReplyAcknowledged
                    && record.operation_id == ack_id
                    && record.child_identity == Some(child_identity) =>
            {
                Ok(record.receipt)
            }
            Some(_) => Err(BrokerSpawnWalError::EffectIdentityConflict),
            None => Err(BrokerSpawnWalError::InvalidTransition),
        }
    }

    fn append_record_and_head(
        &mut self,
        phase: BrokerSpawnWalPhaseV1,
        operation_id: Uuid,
        attempt_id: Uuid,
        child_identity: Option<BrokerKernelChildIdentityV1>,
        recovery_verifier: Option<BrokerPaneRecoveryVerifierV1>,
    ) -> Result<BrokerSpawnWalReceiptV1, BrokerSpawnWalError> {
        self.require_append_authority()?;
        let previous = self.records.last().copied();
        validate_broker_spawn_record_transition(
            previous,
            phase,
            attempt_id,
            child_identity,
            recovery_verifier,
        )?;
        validate_broker_spawn_record_fields(
            phase,
            operation_id,
            attempt_id,
            child_identity,
            recovery_verifier,
        )?;
        let sequence = u64::try_from(self.records.len())
            .map_err(|_| BrokerSpawnWalError::CapacityExhausted)?;
        let previous_record_mac =
            previous.map_or(self.header_mac, |record| record.receipt.record_mac);
        let wal_record = encode_broker_spawn_wal_record(
            self.header_mac,
            &self.authenticator,
            sequence,
            phase,
            operation_id,
            attempt_id,
            child_identity,
            recovery_verifier,
            previous_record_mac,
        )?;
        let record_mac = read_broker_array_32(&wal_record[176..208]);
        let head_record = encode_broker_spawn_head_record(
            self.head_header_mac,
            &self.authenticator,
            sequence,
            record_mac,
            self.terminal_head_mac,
        )?;
        let projected_wal_bytes = self
            .committed_wal_bytes
            .checked_add(BROKER_SPAWN_WAL_RECORD_BYTES_U64)
            .ok_or(BrokerSpawnWalError::CapacityExhausted)?;
        let projected_head_bytes = self
            .committed_head_bytes
            .checked_add(BROKER_SPAWN_HEAD_RECORD_BYTES_U64)
            .ok_or(BrokerSpawnWalError::CapacityExhausted)?;
        if self.wal.metadata()?.len() != self.committed_wal_bytes
            || self.head.metadata()?.len() != self.committed_head_bytes
        {
            self.poisoned = true;
            return Err(BrokerSpawnWalError::ExternalLengthChange);
        }

        #[cfg(test)]
        if let Err(error) = self.fail_if_injected(BrokerSpawnWalInjectedFault::BeforeWalWrite) {
            return Err(BrokerSpawnWalError::Io(error));
        }

        let result = (|| -> Result<(), BrokerSpawnWalError> {
            self.wal.seek(SeekFrom::Start(self.committed_wal_bytes))?;
            self.wal.write_all(&wal_record)?;
            self.wal.sync_all()?;
            #[cfg(test)]
            self.fail_if_injected_for_phase(
                BrokerSpawnWalInjectedFault::AfterWalSyncBeforeHead,
                BrokerSpawnWalInjectedFault::AfterWalSyncBeforeHeadForPhase(phase),
            )?;
            self.head.seek(SeekFrom::Start(self.committed_head_bytes))?;
            self.head.write_all(&head_record)?;
            #[cfg(test)]
            self.fail_if_injected(BrokerSpawnWalInjectedFault::BeforeHeadSync)?;
            self.head.sync_all()?;
            Ok(())
        })();
        if let Err(error) = result {
            self.poisoned = true;
            return Err(error);
        }

        let head_mac = read_broker_array_32(&head_record[88..120]);
        let receipt = BrokerSpawnWalReceiptV1 {
            sequence,
            phase,
            committed_wal_bytes: projected_wal_bytes,
            committed_head_bytes: projected_head_bytes,
            record_mac,
            head_mac,
        };
        self.records.push(BrokerSpawnWalRecordState {
            phase,
            operation_id,
            attempt_id,
            child_identity,
            recovery_verifier,
            receipt,
        });
        self.committed_wal_bytes = projected_wal_bytes;
        self.committed_head_bytes = projected_head_bytes;
        self.terminal_head_mac = head_mac;
        Ok(receipt)
    }
}

impl BrokerSpawnAttemptPermitV1 {
    /// Invoke the one Spawn callback behind the synchronized Attempt fence.
    ///
    /// Callback error or recovered panic is conservatively indeterminate and
    /// never yields a replacement permit. If the callback succeeded but its
    /// child identity proof is invalid, the returned value is retained for
    /// quarantine rather than dropped accidentally.
    pub fn invoke_once<T, E>(
        self,
        effect: impl FnOnce() -> Result<(T, BrokerKernelChildIdentityV1), E>,
    ) -> BrokerSpawnAttemptExecutionV1<T> {
        match catch_recoverable(
            RecoverablePanicSite::MuxPaneCallback,
            AssertUnwindSafe(effect),
        ) {
            Ok(Ok((value, child_identity))) => {
                if child_identity.validate().is_err() {
                    BrokerSpawnAttemptExecutionV1::OutcomeIndeterminate {
                        retained_value: Some(value),
                    }
                } else {
                    BrokerSpawnAttemptExecutionV1::EffectSucceeded {
                        value,
                        observation: Box::new(BrokerSpawnObservationPermitV1 {
                            identity: self.identity,
                            attempt_id: self.attempt_id,
                            attempt_record_mac: self.attempt_record_mac,
                            child_identity,
                        }),
                    }
                }
            }
            Ok(Err(error)) => {
                let _ = catch_recoverable(
                    RecoverablePanicSite::MuxPaneCallback,
                    AssertUnwindSafe(|| drop(error)),
                );
                BrokerSpawnAttemptExecutionV1::OutcomeIndeterminate {
                    retained_value: None,
                }
            }
            Err(_) => BrokerSpawnAttemptExecutionV1::OutcomeIndeterminate {
                retained_value: None,
            },
        }
    }
}

/// Hard per-pane limits checked before the broker allocates a PTY.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct BrokerResourceLimitsV1 {
    max_spawn_payload_bytes: usize,
    max_successor_handoffs: u32,
    max_proxy_operation_bytes: usize,
    max_buffered_output_bytes: usize,
}

impl BrokerResourceLimitsV1 {
    pub fn new(
        max_spawn_payload_bytes: usize,
        max_successor_handoffs: u32,
    ) -> Result<Self, BrokerError> {
        Self::with_proxy_bounds(
            max_spawn_payload_bytes,
            max_successor_handoffs,
            BROKER_DEFAULT_MAX_PROXY_OPERATION_BYTES,
            BROKER_DEFAULT_MAX_BUFFERED_OUTPUT_BYTES,
        )
    }

    pub fn with_proxy_bounds(
        max_spawn_payload_bytes: usize,
        max_successor_handoffs: u32,
        max_proxy_operation_bytes: usize,
        max_buffered_output_bytes: usize,
    ) -> Result<Self, BrokerError> {
        if max_spawn_payload_bytes == 0
            || max_spawn_payload_bytes > GUARDIAN_MAX_PAYLOAD_BYTES
            || max_successor_handoffs == 0
            || max_successor_handoffs > BROKER_ABSOLUTE_MAX_SUCCESSOR_HANDOFFS
            || max_proxy_operation_bytes == 0
            || max_proxy_operation_bytes > BROKER_DEFAULT_MAX_PROXY_OPERATION_BYTES
            || max_buffered_output_bytes == 0
            || max_buffered_output_bytes > BROKER_ABSOLUTE_MAX_BUFFERED_OUTPUT_BYTES
        {
            return Err(BrokerError::CapacityExhausted);
        }
        Ok(Self {
            max_spawn_payload_bytes,
            max_successor_handoffs,
            max_proxy_operation_bytes,
            max_buffered_output_bytes,
        })
    }

    #[must_use]
    pub const fn max_spawn_payload_bytes(self) -> usize {
        self.max_spawn_payload_bytes
    }

    #[must_use]
    pub const fn max_successor_handoffs(self) -> u32 {
        self.max_successor_handoffs
    }

    #[must_use]
    pub const fn max_proxy_operation_bytes(self) -> usize {
        self.max_proxy_operation_bytes
    }

    #[must_use]
    pub const fn max_buffered_output_bytes(self) -> usize {
        self.max_buffered_output_bytes
    }
}

impl Default for BrokerResourceLimitsV1 {
    fn default() -> Self {
        Self {
            max_spawn_payload_bytes: GUARDIAN_MAX_PAYLOAD_BYTES,
            max_successor_handoffs: BROKER_ABSOLUTE_MAX_SUCCESSOR_HANDOFFS,
            max_proxy_operation_bytes: BROKER_DEFAULT_MAX_PROXY_OPERATION_BYTES,
            max_buffered_output_bytes: BROKER_DEFAULT_MAX_BUFFERED_OUTPUT_BYTES,
        }
    }
}

