    fn spawn_worker_completion(worker: &BrokerSpawnWorkerV1) -> BrokerSpawnWorkerCompletionV1 {
        let deadline = Instant::now() + Duration::from_secs(5);
        loop {
            match worker.try_completion() {
                BrokerSpawnWorkerCompletionStateV1::Ready(event) => match *event {
                    BrokerSpawnWorkerEventV1::Spawn(completion) => return completion,
                    BrokerSpawnWorkerEventV1::Acknowledge(_) => {
                        panic!("Spawn worker helper received an acknowledgement completion")
                    }
                },
                BrokerSpawnWorkerCompletionStateV1::Empty if Instant::now() < deadline => {
                    thread::sleep(Duration::from_millis(1));
                }
                BrokerSpawnWorkerCompletionStateV1::Empty => {
                    panic!("broker Spawn worker completion timed out")
                }
                BrokerSpawnWorkerCompletionStateV1::Disconnected => {
                    panic!("broker Spawn worker disconnected")
                }
                BrokerSpawnWorkerCompletionStateV1::AuthorityLost(_) => {
                    panic!("broker Spawn worker completion lost its authority")
                }
            }
        }
    }

    fn exec_bootstrap_identity(
        payload: &GuardianSpawnPayload,
        authority: &BrokerAuthenticatedGuardianConnectionV1,
    ) -> BrokerExecBootstrapIdentityV1 {
        let binding = binding_for(payload, authority);
        let wal = wal_identity(binding);
        BrokerExecBootstrapIdentityV1 {
            broker_incarnation: authority.broker_incarnation,
            broker_lineage_id: wal.broker_lineage_id,
            journal_id: wal.journal_id,
            attempt_id: id(902),
            durable_pane_id: wal.durable_pane_id,
            bootstrap_nonce: id(903),
            guardian_build_identity_digest: binding.live_guardian_build_identity_digest,
            binding_digest: wal.binding_digest,
            spawn_payload_digest: wal.spawn_payload_digest,
            spawn_payload_bytes: wal.spawn_payload_bytes,
        }
    }

