    #[test]
    fn creation_completion_publication_is_atomic_noreplace_and_retains_both_forks() {
        let directory = private_catalog_directory();
        let authenticator = wal_authenticator(0x96);
        let identity = recovered_catalog_identity(&authenticator, 0x37);
        let creating_name = broker_spawn_creation_marker_name(identity, &authenticator, false)
            .expect("encode no-replace creating marker");
        let completed_name = broker_spawn_creation_marker_name(identity, &authenticator, true)
            .expect("encode no-replace completed marker");
        create_empty_private_file(&directory.path().join(&creating_name));
        create_empty_private_file(&directory.path().join(&completed_name));
        let parent = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_CLOEXEC | libc::O_DIRECTORY | libc::O_NOFOLLOW)
            .open(directory.path())
            .expect("open no-replace parent directory");
        let creating_before = fs::metadata(directory.path().join(&creating_name))
            .expect("creating marker metadata before no-replace");
        let completed_before = fs::metadata(directory.path().join(&completed_name))
            .expect("completed marker metadata before no-replace");
        let error = publish_broker_spawn_completed_marker_noreplace(
            &parent,
            &creating_name,
            &completed_name,
        )
        .expect_err("no-replace publication must reject an existing certificate");
        assert_eq!(error.kind(), ErrorKind::AlreadyExists);
        let creating_after = fs::metadata(directory.path().join(&creating_name))
            .expect("retained creating marker after no-replace");
        let completed_after = fs::metadata(directory.path().join(&completed_name))
            .expect("retained completed marker after no-replace");
        assert_eq!(creating_before.ino(), creating_after.ino());
        assert_eq!(completed_before.ino(), completed_after.ino());
        assert_ne!(creating_after.ino(), completed_after.ino());
    }

    #[test]
    fn restart_recovers_multiple_independent_creation_transactions_before_admission() {
        let directory = private_catalog_directory();
        let authenticator = wal_authenticator(0x97);
        let first = recovered_catalog_identity(&authenticator, 0x38);
        let second = recovered_catalog_identity(&authenticator, 0x39);
        let third = recovered_catalog_identity(&authenticator, 0x3a);
        let mut catalog = BrokerSpawnWalCatalogV1::open(directory.path().to_path_buf())
            .expect("open multi-creation catalog");
        let first_journal = catalog
            .create_spawn_journal(first, authenticator.clone())
            .expect("create completed first journal");
        drop(first_journal);
        drop(catalog);

        let second_marker = broker_spawn_creation_marker_name(second, &authenticator, false)
            .expect("encode second creating marker");
        let third_marker = broker_spawn_creation_marker_name(third, &authenticator, false)
            .expect("encode third creating marker");
        create_empty_private_file(&directory.path().join(&second_marker));
        create_empty_private_file(&directory.path().join(&third_marker));
        let second_wal =
            encode_broker_spawn_file_header(BROKER_SPAWN_WAL_FILE_MAGIC, second, &authenticator)
                .expect("encode second partial WAL");
        create_private_broker_token_with_bytes(
            &directory
                .path()
                .join(broker_spawn_catalog_wal_name(second.journal_id())),
            &second_wal[..73],
        );
        let third_head =
            encode_broker_spawn_file_header(BROKER_SPAWN_HEAD_FILE_MAGIC, third, &authenticator)
                .expect("encode third partial head");
        create_private_broker_token_with_bytes(
            &directory
                .path()
                .join(broker_spawn_catalog_head_name(third.journal_id())),
            &third_head[..149],
        );

        let mut recovered = reopen_test_catalog_after_owner_drop(directory.path())
            .expect("reopen multiple independent creation transactions");
        let journals = recovered
            .scan_all_for_admission(&authenticator)
            .expect("recover all independent creation transactions");
        let admitted = BrokerRecoveredSpawnCatalogV1::admit(journals, &authenticator)
            .expect("admit all recovered unique identities");
        assert_eq!(admitted.journals.len(), 3);
        for identity in [first, second, third] {
            let pair = recovered
                .scan_catalog_states()
                .expect("scan multi-creation completion")
                .remove(&identity.journal_id())
                .expect("completed multi-creation pair");
            assert!(pair.creating.is_none());
            assert_eq!(
                pair.completed.as_ref().map(|marker| marker.identity),
                Some(identity)
            );
        }
    }

    #[test]
    fn later_invalid_lifecycle_member_blocks_all_creation_recovery_mutation() {
        let directory = private_catalog_directory();
        let authenticator = wal_authenticator(0x99);
        let existing = recovered_catalog_identity(&authenticator, 0x3c);
        let pending = recovered_catalog_identity(&authenticator, 0x3d);
        let mut catalog = BrokerSpawnWalCatalogV1::open(directory.path().to_path_buf())
            .expect("open catalog for creation preflight ordering");
        let existing_journal = catalog
            .create_spawn_journal(existing, authenticator.clone())
            .expect("create existing completed journal");
        drop(existing_journal);
        drop(catalog);

        let existing_wal_path = directory
            .path()
            .join(broker_spawn_catalog_wal_name(existing.journal_id()));
        let mut existing_wal = OpenOptions::new()
            .append(true)
            .open(&existing_wal_path)
            .expect("open existing WAL for retained torn lifecycle tail");
        existing_wal
            .write_all(&BROKER_SPAWN_WAL_RECORD_MAGIC[..3])
            .expect("write retained torn lifecycle tail");
        existing_wal
            .sync_all()
            .expect("synchronize retained torn lifecycle tail");
        drop(existing_wal);

        let pending_marker = broker_spawn_creation_marker_name(pending, &authenticator, false)
            .expect("encode pending preflight marker");
        create_empty_private_file(&directory.path().join(&pending_marker));
        let pending_wal_path = directory
            .path()
            .join(broker_spawn_catalog_wal_name(pending.journal_id()));
        let pending_head_path = directory
            .path()
            .join(broker_spawn_catalog_head_name(pending.journal_id()));

        let mut reopened = reopen_test_catalog_after_owner_drop(directory.path())
            .expect("structurally reopen invalid-lifecycle plus pending creation");
        assert!(matches!(
            reopened.scan_all_for_admission(&authenticator),
            Err(BrokerSpawnWalError::IncompleteTail)
        ));
        assert!(!pending_wal_path.exists());
        assert!(!pending_head_path.exists());
        assert!(directory.path().join(&pending_marker).exists());
        assert_eq!(
            fs::metadata(&existing_wal_path)
                .expect("retained invalid lifecycle WAL metadata")
                .len(),
            BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64 + 3
        );
    }

    #[test]
    fn creation_certificate_file_must_remain_empty_within_catalog_ceiling() {
        let directory = private_catalog_directory();
        let authenticator = wal_authenticator(0x98);
        let identity = recovered_catalog_identity(&authenticator, 0x3b);
        let marker = broker_spawn_creation_marker_name(identity, &authenticator, false)
            .expect("encode nonempty marker name");
        create_private_broker_token_with_bytes(&directory.path().join(&marker), &[0x5a]);
        assert!(matches!(
            BrokerSpawnWalCatalogV1::open(directory.path().to_path_buf()),
            Err(BrokerSpawnWalError::InsecureCatalogIdentity)
        ));
        assert_eq!(
            fs::read(directory.path().join(&marker)).expect("read retained nonempty marker"),
            vec![0x5a]
        );
    }

    fn recover_header_only_catalog_journals(
        directory: &std::path::Path,
        identities: &[BrokerSpawnWalIdentityV1],
        authenticator: &GuardianBrokerSpawnWalAuthenticatorV1,
    ) -> (BrokerSpawnWalCatalogV1, Vec<BrokerSpawnJournalV1>) {
        let mut catalog = BrokerSpawnWalCatalogV1::open(directory.to_path_buf())
            .expect("open empty catalog for header-only journal creation");
        for identity in identities {
            let journal = catalog
                .create_spawn_journal_fixture_unadmitted(*identity, authenticator.clone())
                .expect("create header-only catalog journal");
            drop(journal);
        }
        drop(catalog);

        let mut recovered_catalog = reopen_test_catalog_after_owner_drop(directory)
            .expect("reopen catalog for admission recovery");
        let journals = recovered_catalog
            .scan_all_for_admission(authenticator)
            .expect("recover authenticated header-only catalog journals");
        (recovered_catalog, journals)
    }

    #[test]
    fn control_codec_is_bounded_direction_separated_and_mutation_sensitive() {
        fn assert_zeroize_on_drop<T: ZeroizeOnDrop>() {}
        assert_zeroize_on_drop::<BrokerControlWireFrameV1>();

        let authority = control_authenticator(0x5a);
        let request = BrokerControlRequestV1::new(
            BrokerControlRequestHeaderV1 {
                operation: BrokerControlOperationV1::Hello,
                request_id: id(701),
                broker_incarnation: Uuid::nil(),
                guardian_incarnation: id(702),
                connection_id: id(703),
                mux_incarnation: id(704),
                guardian_build_identity_digest: [0x71; 32],
                mux_build_identity_digest: [0x72; 32],
                durable_pane_id: Uuid::nil(),
                lease_generation: 0,
                operation_id: Uuid::nil(),
            },
            &[],
        )
        .expect("canonical Hello request");
        let encoded = encode_broker_control_request(&authority, &request).expect("encode request");
        assert_eq!(encoded.as_slice().len(), BROKER_CONTROL_REQUEST_FIXED_BYTES);
        let decoded =
            decode_broker_control_request(&authority, encoded.as_slice()).expect("decode request");
        assert_eq!(decoded.header, request.header);
        assert_eq!(decoded.payload(), &[] as &[u8]);

        let mut mutated = encoded.as_slice().to_vec();
        mutated[20] ^= 1;
        assert!(matches!(
            decode_broker_control_request(&authority, &mutated),
            Err(BrokerControlProtocolError::AuthenticationFailed)
        ));
        let mut length_mutated = encoded.as_slice().to_vec();
        length_mutated[3] ^= 1;
        assert!(matches!(
            decode_broker_control_request(&authority, &length_mutated),
            Err(BrokerControlProtocolError::InvalidLength)
        ));

        let hello_payload = [0x74; BROKER_CONTROL_HELLO_PAYLOAD_BYTES];
        let response = BrokerControlResponseV1::new(
            BrokerControlResponseHeaderV1 {
                operation: BrokerControlOperationV1::Hello,
                status: BrokerControlResponseStatusV1::Applied,
                request_id: request.header.request_id,
                broker_incarnation: id(705),
                guardian_incarnation: request.header.guardian_incarnation,
                connection_id: request.header.connection_id,
                durable_pane_id: Uuid::nil(),
                lease_generation: 0,
                operation_id: Uuid::nil(),
                child_identity: None,
                output_sequence_start: 0,
                output_sequence_end: 0,
            },
            &hello_payload,
        )
        .expect("canonical Hello response");
        let encoded_response =
            encode_broker_control_response(&authority, &response).expect("encode response");
        assert_eq!(
            encoded_response.as_slice().len(),
            BROKER_CONTROL_RESPONSE_FIXED_BYTES + BROKER_CONTROL_HELLO_PAYLOAD_BYTES
        );
        let decoded_response =
            decode_broker_control_response(&authority, encoded_response.as_slice())
                .expect("decode response");
        assert_eq!(decoded_response.header, response.header);
        assert_eq!(decoded_response.payload(), hello_payload);
        assert!(
            decode_broker_control_request(&authority, encoded_response.as_slice()).is_err(),
            "a response-direction frame was accepted as a request"
        );
        assert!(
            decode_broker_control_response(&authority, encoded.as_slice()).is_err(),
            "a request-direction frame was accepted as a response"
        );

        let invalid_write = BrokerControlRequestV1::new(
            BrokerControlRequestHeaderV1 {
                operation: BrokerControlOperationV1::Write,
                request_id: id(706),
                broker_incarnation: id(705),
                guardian_incarnation: id(702),
                connection_id: id(703),
                mux_incarnation: id(704),
                guardian_build_identity_digest: [0x71; 32],
                mux_build_identity_digest: [0x72; 32],
                durable_pane_id: id(707),
                lease_generation: 1,
                operation_id: id(708),
            },
            &[],
        );
        assert!(matches!(
            invalid_write,
            Err(BrokerControlProtocolError::InvalidShape)
        ));

        let leased_operations: [(BrokerControlOperationV1, &[u8]); 6] = [
            (BrokerControlOperationV1::Write, b"must-be-fenced"),
            (BrokerControlOperationV1::Resize, &[0; 8]),
            (BrokerControlOperationV1::ReadOutput, &[0; 4]),
            (BrokerControlOperationV1::AcknowledgeOutput, &[0; 8]),
            (
                BrokerControlOperationV1::AttachSuccessor,
                &[0x75; BROKER_PANE_RECOVERY_SECRET_BYTES],
            ),
            (BrokerControlOperationV1::ClosePane, &[]),
        ];
        for (operation, payload) in leased_operations {
            let zero_generation_request = BrokerControlRequestV1::new(
                BrokerControlRequestHeaderV1 {
                    operation,
                    request_id: id(709),
                    broker_incarnation: id(705),
                    guardian_incarnation: id(702),
                    connection_id: id(703),
                    mux_incarnation: id(704),
                    guardian_build_identity_digest: [0x71; 32],
                    mux_build_identity_digest: [0x72; 32],
                    durable_pane_id: id(707),
                    lease_generation: 0,
                    operation_id: id(710),
                },
                payload,
            );
            assert!(
                matches!(
                    zero_generation_request,
                    Err(BrokerControlProtocolError::InvalidShape)
                ),
                "{operation:?} accepted reserved generation zero"
            );
        }

        let pre_lease_operations: [(BrokerControlOperationV1, &[u8]); 2] = [
            (BrokerControlOperationV1::QueryEffect, &[]),
            (
                BrokerControlOperationV1::AcknowledgeEffect,
                &[0x73; BROKER_PANE_RECOVERY_SECRET_BYTES],
            ),
        ];
        for (operation, payload) in pre_lease_operations {
            BrokerControlRequestV1::new(
                BrokerControlRequestHeaderV1 {
                    operation,
                    request_id: id(709),
                    broker_incarnation: id(705),
                    guardian_incarnation: id(702),
                    connection_id: id(703),
                    mux_incarnation: id(704),
                    guardian_build_identity_digest: [0x71; 32],
                    mux_build_identity_digest: [0x72; 32],
                    durable_pane_id: id(707),
                    lease_generation: 0,
                    operation_id: id(710),
                },
                payload,
            )
            .expect("generation zero is reserved for the pre-lease Spawn receipt");
        }
        assert!(matches!(
            BrokerControlRequestV1::new(
                BrokerControlRequestHeaderV1 {
                    operation: BrokerControlOperationV1::AcknowledgeEffect,
                    request_id: id(709),
                    broker_incarnation: id(705),
                    guardian_incarnation: id(702),
                    connection_id: id(703),
                    mux_incarnation: id(704),
                    guardian_build_identity_digest: [0x71; 32],
                    mux_build_identity_digest: [0x72; 32],
                    durable_pane_id: id(707),
                    lease_generation: 0,
                    operation_id: id(710),
                },
                &[],
            ),
            Err(BrokerControlProtocolError::InvalidShape)
        ));

        let child_identity = BrokerKernelChildIdentityV1 {
            process_id: 711,
            broker_child_nonce: id(712),
            kernel_start_identity_digest: [0x73; 32],
        };
        let spawn_request = BrokerControlRequestV1::new(
            BrokerControlRequestHeaderV1 {
                operation: BrokerControlOperationV1::Spawn,
                request_id: id(719),
                broker_incarnation: id(705),
                guardian_incarnation: id(702),
                connection_id: id(703),
                mux_incarnation: id(704),
                guardian_build_identity_digest: [0x71; 32],
                mux_build_identity_digest: [0x72; 32],
                durable_pane_id: id(707),
                lease_generation: 0,
                operation_id: id(720),
            },
            &[0x01],
        )
        .expect("canonical generation-zero Spawn request");
        let applied_spawn = BrokerControlResponseV1::new(
            BrokerControlResponseHeaderV1 {
                operation: BrokerControlOperationV1::Spawn,
                status: BrokerControlResponseStatusV1::Applied,
                request_id: spawn_request.header.request_id,
                broker_incarnation: id(705),
                guardian_incarnation: spawn_request.header.guardian_incarnation,
                connection_id: spawn_request.header.connection_id,
                durable_pane_id: spawn_request.header.durable_pane_id,
                lease_generation: 1,
                operation_id: spawn_request.header.operation_id,
                child_identity: Some(child_identity),
                output_sequence_start: 0,
                output_sequence_end: 0,
            },
            &[],
        )
        .expect("successful Spawn creates exactly generation one");
        assert!(broker_control_response_lease_generation_matches(
            spawn_request.header,
            applied_spawn.header,
        ));
        assert!(matches!(
            BrokerControlResponseV1::new(
                BrokerControlResponseHeaderV1 {
                    lease_generation: 2,
                    ..applied_spawn.header
                },
                &[],
            ),
            Err(BrokerControlProtocolError::InvalidShape)
        ));
        let rejected_spawn = BrokerControlResponseV1::new(
            BrokerControlResponseHeaderV1 {
                status: BrokerControlResponseStatusV1::Rejected,
                lease_generation: 0,
                child_identity: None,
                ..applied_spawn.header
            },
            &[],
        )
        .expect("rejected Spawn preserves request generation zero");
        assert!(broker_control_response_lease_generation_matches(
            spawn_request.header,
            rejected_spawn.header,
        ));

        let forged_rejected_write = BrokerControlResponseV1::new(
            BrokerControlResponseHeaderV1 {
                operation: BrokerControlOperationV1::Write,
                status: BrokerControlResponseStatusV1::Rejected,
                request_id: id(713),
                broker_incarnation: id(705),
                guardian_incarnation: id(702),
                connection_id: id(703),
                durable_pane_id: id(707),
                lease_generation: 1,
                operation_id: id(714),
                child_identity: Some(child_identity),
                output_sequence_start: 0,
                output_sequence_end: 0,
            },
            &[],
        );
        assert!(matches!(
            forged_rejected_write,
            Err(BrokerControlProtocolError::InvalidShape)
        ));

        let mismatched_read_range = BrokerControlResponseV1::new(
            BrokerControlResponseHeaderV1 {
                operation: BrokerControlOperationV1::ReadOutput,
                status: BrokerControlResponseStatusV1::Applied,
                request_id: id(715),
                broker_incarnation: id(705),
                guardian_incarnation: id(702),
                connection_id: id(703),
                durable_pane_id: id(707),
                lease_generation: 1,
                operation_id: id(716),
                child_identity: None,
                output_sequence_start: 40,
                output_sequence_end: 44,
            },
            b"five!",
        );
        assert!(matches!(
            mismatched_read_range,
            Err(BrokerControlProtocolError::InvalidShape)
        ));

        let spawn_query = BrokerControlResponseV1::new(
            BrokerControlResponseHeaderV1 {
                operation: BrokerControlOperationV1::QueryEffect,
                status: BrokerControlResponseStatusV1::Recovered,
                request_id: id(717),
                broker_incarnation: id(705),
                guardian_incarnation: id(702),
                connection_id: id(703),
                durable_pane_id: id(707),
                lease_generation: 0,
                operation_id: id(718),
                child_identity: Some(child_identity),
                output_sequence_start: 0,
                output_sequence_end: 0,
            },
            &[],
        )
        .expect("generation-zero QueryEffect may recover only Spawn identity");
        assert_eq!(spawn_query.header.child_identity, Some(child_identity));

        let forged_leased_query = BrokerControlResponseV1::new(
            BrokerControlResponseHeaderV1 {
                lease_generation: 1,
                ..spawn_query.header
            },
            &[],
        );
        assert!(matches!(
            forged_leased_query,
            Err(BrokerControlProtocolError::InvalidShape)
        ));
    }

    #[test]
    fn recovery_census_codec_is_canonical_bounded_and_request_correlated() {
        let first_request = BrokerCensusPageRequestV1::new(
            Uuid::nil(),
            0,
            1,
            u32::try_from(
                BROKER_CONTROL_CENSUS_PAGE_HEADER_BYTES + BROKER_CONTROL_CENSUS_ENTRY_BYTES,
            )
            .expect("single-row Census page bytes"),
        )
        .expect("canonical first Census request");
        assert_eq!(
            BrokerCensusPageRequestV1::decode(&first_request.encode())
                .expect("decode first Census request"),
            first_request
        );
        let continuation = BrokerCensusPageRequestV1::new(
            id(760),
            1,
            2,
            u32::try_from(
                BROKER_CONTROL_CENSUS_PAGE_HEADER_BYTES + BROKER_CONTROL_CENSUS_ENTRY_BYTES * 2,
            )
            .expect("two-row Census page bytes"),
        )
        .expect("canonical continuation Census request");
        assert_eq!(
            BrokerCensusPageRequestV1::decode(&continuation.encode())
                .expect("decode continuation Census request"),
            continuation
        );
        assert!(matches!(
            BrokerCensusPageRequestV1::new(
                Uuid::nil(),
                1,
                1,
                u32::try_from(
                    BROKER_CONTROL_CENSUS_PAGE_HEADER_BYTES + BROKER_CONTROL_CENSUS_ENTRY_BYTES,
                )
                .expect("single-row Census page bytes"),
            ),
            Err(BrokerControlClientError::Protocol)
        ));
        assert!(matches!(
            BrokerCensusPageRequestV1::new(
                id(761),
                0,
                1,
                u32::try_from(
                    BROKER_CONTROL_CENSUS_PAGE_HEADER_BYTES + BROKER_CONTROL_CENSUS_ENTRY_BYTES,
                )
                .expect("single-row Census page bytes"),
            ),
            Err(BrokerControlClientError::Protocol)
        ));
        let maximum_cursor = u64::try_from(GUARDIAN_MAX_PANES).expect("maximum Census cursor");
        let maximum_cursor_request =
            BrokerCensusPageRequestV1::new(id(761), maximum_cursor, 1, first_request.max_bytes())
                .expect("maximum bounded Census cursor");
        assert_eq!(maximum_cursor_request.cursor(), maximum_cursor);
        assert!(matches!(
            BrokerCensusPageRequestV1::new(
                id(761),
                maximum_cursor.checked_add(1).expect("cursor above maximum"),
                1,
                first_request.max_bytes(),
            ),
            Err(BrokerControlClientError::Protocol)
        ));
        assert!(matches!(
            BrokerCensusPageRequestV1::new(
                id(761),
                BROKER_CONTROL_CENSUS_NO_CURSOR,
                1,
                first_request.max_bytes(),
            ),
            Err(BrokerControlClientError::Protocol)
        ));

        let directory = private_catalog_directory();
        let authenticator = wal_authenticator(0xb1);
        let identity = recovered_catalog_identity(&authenticator, 0x51);
        let (_catalog, journals) =
            recover_header_only_catalog_journals(directory.path(), &[identity], &authenticator);
        let admitted = BrokerRecoveredSpawnCatalogV1::admit(journals, &authenticator)
            .expect("admit one header-only Census fixture");
        let entries = admitted
            .recovery_census_entries()
            .expect("classify one header-only Census row");
        let [entry] = entries.as_slice() else {
            panic!("expected one header-only Census row")
        };
        let entry = *entry;
        assert_eq!(
            entry.disposition,
            BrokerCensusDispositionV1::PreparedHeaderOnly
        );
        assert!(entry.effects_disabled);
        assert!(!entry.pty_available);
        assert!(!entry.lease_available);
        assert!(!entry.output_replay_available);
        let encoded_entry = entry.encode().expect("encode canonical Census row");
        assert_eq!(
            BrokerCensusEntryV1::decode(&encoded_entry).expect("decode canonical Census row"),
            entry
        );
        let mut enabled_effects = encoded_entry;
        enabled_effects[87] = 0;
        assert!(matches!(
            BrokerCensusEntryV1::decode(&enabled_effects),
            Err(BrokerControlProtocolError::InvalidShape)
        ));
        let mut forged_pty = encoded_entry;
        forged_pty[200] = 1;
        assert!(matches!(
            BrokerCensusEntryV1::decode(&forged_pty),
            Err(BrokerControlProtocolError::InvalidShape)
        ));
        let mut forged_recovered_generation = encoded_entry;
        forged_recovered_generation[223] = 1;
        assert!(matches!(
            BrokerCensusEntryV1::decode(&forged_recovered_generation),
            Err(BrokerControlProtocolError::InvalidShape)
        ));

        let live_entry = BrokerCensusEntryV1 {
            journal_id: id(765),
            mux_incarnation: identity.mux_incarnation(),
            durable_pane_id: id(766),
            spawn_effect_id: id(767),
            origin_request_id: id(768),
            phase: Some(BrokerSpawnWalPhaseV1::ReplyAcknowledged),
            disposition: BrokerCensusDispositionV1::ReplyAcknowledgedPtyAvailable,
            attempt_id: Some(id(769)),
            child_identity: Some(BrokerKernelChildIdentityV1 {
                process_id: 77,
                broker_child_nonce: id(770),
                kernel_start_identity_digest: [0x7a; 32],
            }),
            reply_ack_id: Some(id(771)),
            committed_records: BROKER_SPAWN_WAL_MAX_RECORDS,
            committed_wal_bytes: BROKER_SPAWN_WAL_MAX_PHYSICAL_BYTES,
            committed_head_bytes: BROKER_SPAWN_HEAD_MAX_PHYSICAL_BYTES,
            append_authority_withheld: false,
            head_reconciliation_required: false,
            effects_disabled: false,
            pty_available: true,
            lease_available: true,
            output_replay_available: true,
            owner_mux_incarnation: Some(identity.mux_incarnation()),
            lease_generation: 1,
        };
        let encoded_live_entry = live_entry
            .encode()
            .expect("encode canonical live Census row");
        assert_eq!(
            BrokerCensusEntryV1::decode(&encoded_live_entry)
                .expect("decode canonical live Census row"),
            live_entry
        );
        let successor_mux_incarnation = id(772);
        let mut successor_live_entry = live_entry;
        successor_live_entry.owner_mux_incarnation = Some(successor_mux_incarnation);
        let successor_page = BrokerCensusPageV1 {
            snapshot_id: id(773),
            entries: vec![successor_live_entry],
            next_cursor: None,
            total_entries: 1,
        };
        successor_page
            .validate_for_mux(successor_mux_incarnation)
            .expect("bind live Census row to exact successor mux owner");
        assert!(matches!(
            successor_page.validate_for_mux(identity.mux_incarnation()),
            Err(BrokerControlProtocolError::InvalidIdentity)
        ));
        for offset in [85, 87, 200, 201, 202, 203, 223] {
            let mut forged = encoded_live_entry;
            forged[offset] ^= 1;
            assert!(
                BrokerCensusEntryV1::decode(&forged).is_err(),
                "live Census authority mutation at byte {offset} was accepted"
            );
        }

        let snapshot_id = id(762);
        let page = BrokerCensusPageV1 {
            snapshot_id,
            entries,
            next_cursor: None,
            total_entries: 1,
        };
        let encoded_page = page.encode().expect("encode canonical Census page");
        let decoded_page =
            BrokerCensusPageV1::decode(&encoded_page).expect("decode canonical Census page");
        decoded_page
            .validate_for_request(first_request)
            .expect("correlate canonical first Census response");
        decoded_page
            .validate_for_mux(identity.mux_incarnation())
            .expect("bind canonical Census response to its mux");
        assert_eq!(decoded_page, page);

        let mut cross_mux_entry = entry;
        cross_mux_entry.mux_incarnation = id(764);
        let cross_mux_page = BrokerCensusPageV1 {
            snapshot_id,
            entries: vec![cross_mux_entry],
            next_cursor: None,
            total_entries: 1,
        };
        assert!(matches!(
            cross_mux_page.validate_for_mux(identity.mux_incarnation()),
            Err(BrokerControlProtocolError::InvalidIdentity)
        ));

        let distinct_entry = prepared_census_entry(900, identity.mux_incarnation());
        let canonical_pair = [entry, distinct_entry];
        validate_broker_census_entries(&canonical_pair)
            .expect("distinct Census identities are canonical");
        let mut duplicate_journal = distinct_entry;
        duplicate_journal.journal_id = entry.journal_id;
        let mut duplicate_spawn_effect = distinct_entry;
        duplicate_spawn_effect.spawn_effect_id = entry.spawn_effect_id;
        let mut duplicate_origin_request = distinct_entry;
        duplicate_origin_request.origin_request_id = entry.origin_request_id;
        for (namespace, duplicate) in [
            ("journal", duplicate_journal),
            ("Spawn effect", duplicate_spawn_effect),
            ("origin request", duplicate_origin_request),
        ] {
            let duplicate_page = BrokerCensusPageV1 {
                snapshot_id,
                entries: vec![entry, duplicate],
                next_cursor: None,
                total_entries: 2,
            };
            assert!(
                matches!(
                    duplicate_page.validate(),
                    Err(BrokerControlProtocolError::InvalidIdentity)
                ),
                "same-page duplicate {namespace} identity was accepted"
            );
        }
        let mut duplicate_pane = distinct_entry;
        duplicate_pane.durable_pane_id = entry.durable_pane_id;
        let duplicate_pane_page = BrokerCensusPageV1 {
            snapshot_id,
            entries: vec![entry, duplicate_pane],
            next_cursor: None,
            total_entries: 2,
        };
        assert!(matches!(
            duplicate_pane_page.validate(),
            Err(BrokerControlProtocolError::InvalidShape)
        ));

        let underfilled_continuation = BrokerCensusPageV1 {
            snapshot_id: continuation.snapshot_id(),
            entries: vec![distinct_entry],
            next_cursor: Some(2),
            total_entries: 3,
        };
        assert!(matches!(
            underfilled_continuation.validate_for_request(continuation),
            Err(BrokerControlProtocolError::InvalidShape)
        ));

        let mut forged_cursor = encoded_page.clone();
        forged_cursor[32..40].copy_from_slice(&0_u64.to_be_bytes());
        let forged_cursor =
            BrokerCensusPageV1::decode(&forged_cursor).expect("decode structurally valid cursor");
        assert!(matches!(
            forged_cursor.validate_for_request(first_request),
            Err(BrokerControlProtocolError::InvalidShape)
        ));
        let continuation_request =
            BrokerCensusPageRequestV1::new(snapshot_id, 1, 1, first_request.max_bytes())
                .expect("canonical continuation request");
        let forged_snapshot = BrokerCensusPageV1 {
            snapshot_id: id(763),
            entries: vec![entry],
            next_cursor: None,
            total_entries: 2,
        };
        assert!(matches!(
            forged_snapshot.validate_for_request(continuation_request),
            Err(BrokerControlProtocolError::InvalidIdentity)
        ));
    }

    #[test]
    fn recovery_census_classifies_every_spawn_phase_and_head_crash_cut() {
        fn advance_to_phase(
            journal: &mut BrokerSpawnJournalV1,
            target: Option<BrokerSpawnWalPhaseV1>,
            attempt_id: Uuid,
            child_identity: BrokerKernelChildIdentityV1,
            reply_ack_id: Uuid,
            crash_before_terminal_head: bool,
        ) {
            let Some(target) = target else {
                return;
            };
            if target == BrokerSpawnWalPhaseV1::Intent && crash_before_terminal_head {
                journal.inject_fault(BrokerSpawnWalInjectedFault::AfterWalSyncBeforeHeadForPhase(
                    target,
                ));
            }
            let intent = journal.append_intent_and_sync();
            if target == BrokerSpawnWalPhaseV1::Intent {
                if crash_before_terminal_head {
                    assert!(matches!(intent, Err(BrokerSpawnWalError::Io(_))));
                } else {
                    assert_eq!(
                        intent.expect("append exact-head Census Intent").phase(),
                        BrokerSpawnWalPhaseV1::Intent
                    );
                }
                return;
            }
            intent.expect("append preterminal Census Intent");

            if target == BrokerSpawnWalPhaseV1::Attempted && crash_before_terminal_head {
                journal.inject_fault(BrokerSpawnWalInjectedFault::AfterWalSyncBeforeHeadForPhase(
                    target,
                ));
            }
            let attempt = journal.begin_spawn_attempt_and_sync(attempt_id);
            let permit = match attempt {
                Ok(BrokerSpawnAttemptAdmissionV1::Authorized(permit)) => permit,
                Ok(BrokerSpawnAttemptAdmissionV1::Reconciled(_)) => {
                    panic!("first Census Attempt unexpectedly reconciled")
                }
                Err(BrokerSpawnWalError::Io(_))
                    if target == BrokerSpawnWalPhaseV1::Attempted && crash_before_terminal_head =>
                {
                    return;
                }
                Err(error) => panic!("append Census Attempt failed unexpectedly: {error:?}"),
            };
            if target == BrokerSpawnWalPhaseV1::Attempted {
                drop(permit);
                return;
            }
            let execution = permit.invoke_once(|| Ok::<_, ()>(((), child_identity)));
            let observation = match execution {
                BrokerSpawnAttemptExecutionV1::EffectSucceeded { observation, .. } => observation,
                BrokerSpawnAttemptExecutionV1::OutcomeIndeterminate { .. } => {
                    panic!("valid Census child identity became indeterminate")
                }
            };

            if target == BrokerSpawnWalPhaseV1::SpawnObserved && crash_before_terminal_head {
                journal.inject_fault(BrokerSpawnWalInjectedFault::AfterWalSyncBeforeHeadForPhase(
                    target,
                ));
            }
            let observed = journal.append_spawn_observed_and_sync(*observation);
            if target == BrokerSpawnWalPhaseV1::SpawnObserved {
                if crash_before_terminal_head {
                    assert!(matches!(observed, Err(BrokerSpawnWalError::Io(_))));
                } else {
                    assert_eq!(
                        observed
                            .expect("append exact-head Census SpawnObserved")
                            .phase(),
                        BrokerSpawnWalPhaseV1::SpawnObserved
                    );
                }
                return;
            }
            observed.expect("append preterminal Census SpawnObserved");

            if crash_before_terminal_head {
                journal.inject_fault(BrokerSpawnWalInjectedFault::AfterWalSyncBeforeHeadForPhase(
                    target,
                ));
            }
            let acknowledged =
                journal.acknowledge_spawn_reply_and_sync(reply_ack_id, child_identity);
            if crash_before_terminal_head {
                assert!(matches!(acknowledged, Err(BrokerSpawnWalError::Io(_))));
            } else {
                assert_eq!(
                    acknowledged
                        .expect("append exact-head Census ReplyAcknowledged")
                        .phase(),
                    BrokerSpawnWalPhaseV1::ReplyAcknowledged
                );
            }
        }

        let root = tempfile::tempdir_in(crate::canonical_test_temp_root())
            .expect("create all-phase recovery Census root");
        let authenticator = wal_authenticator(0xc1);
        let phases = [
            None,
            Some(BrokerSpawnWalPhaseV1::Intent),
            Some(BrokerSpawnWalPhaseV1::Attempted),
            Some(BrokerSpawnWalPhaseV1::SpawnObserved),
            Some(BrokerSpawnWalPhaseV1::ReplyAcknowledged),
        ];
        for (phase_index, phase) in phases.into_iter().enumerate() {
            for head_gap in [false, true] {
                if phase.is_none() && head_gap {
                    continue;
                }
                let directory = root
                    .path()
                    .join(format!("phase-{phase_index}-gap-{}", u8::from(head_gap)));
                fs::create_dir(&directory).expect("create all-phase Census case directory");
                let seed = 0x70_u8
                    .checked_add(u8::try_from(phase_index * 2 + usize::from(head_gap)).unwrap())
                    .expect("bounded all-phase Census seed");
                let identity = recovered_catalog_identity(&authenticator, seed);
                let attempt_id = id(7_000 + u128::from(seed));
                let child_identity = test_kernel_child(20_000 + u32::from(seed));
                let reply_ack_id = id(8_000 + u128::from(seed));
                let (mut journal, wal_path, head_path) =
                    create_test_spawn_journal(&directory, identity, authenticator.clone());
                advance_to_phase(
                    &mut journal,
                    phase,
                    attempt_id,
                    child_identity,
                    reply_ack_id,
                    head_gap,
                );
                drop(journal);
                let recovered = reopen_test_spawn_journal(
                    &wal_path,
                    &head_path,
                    identity,
                    authenticator.clone(),
                );
                let status = recovered.status();
                let entry = BrokerCensusEntryV1::from_recovered_status(&status)
                    .expect("classify all-phase recovered Census row");
                let expected_records = match phase {
                    None => 0,
                    Some(BrokerSpawnWalPhaseV1::Intent) => 1,
                    Some(BrokerSpawnWalPhaseV1::Attempted) => 2,
                    Some(BrokerSpawnWalPhaseV1::SpawnObserved) => 3,
                    Some(BrokerSpawnWalPhaseV1::ReplyAcknowledged) => 4,
                };
                let expected_disposition = match phase {
                    None => BrokerCensusDispositionV1::PreparedHeaderOnly,
                    Some(BrokerSpawnWalPhaseV1::Intent) => {
                        BrokerCensusDispositionV1::IntentEffectsDisabled
                    }
                    Some(BrokerSpawnWalPhaseV1::Attempted) => {
                        BrokerCensusDispositionV1::AttemptOutcomeIndeterminate
                    }
                    Some(BrokerSpawnWalPhaseV1::SpawnObserved) => {
                        BrokerCensusDispositionV1::SpawnObservedPtyUnavailable
                    }
                    Some(BrokerSpawnWalPhaseV1::ReplyAcknowledged) => {
                        BrokerCensusDispositionV1::ReplyAcknowledgedPtyUnavailable
                    }
                };
                assert_eq!(entry.phase, phase);
                assert_eq!(entry.disposition, expected_disposition);
                assert_eq!(entry.committed_records, expected_records);
                assert_eq!(
                    entry.committed_wal_bytes,
                    BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64
                        + expected_records * BROKER_SPAWN_WAL_RECORD_BYTES_U64
                );
                assert_eq!(entry.head_reconciliation_required, head_gap);
                assert_eq!(
                    entry.committed_head_bytes,
                    BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64
                        + (expected_records - u64::from(head_gap))
                            * BROKER_SPAWN_HEAD_RECORD_BYTES_U64
                );
                assert_eq!(
                    entry.attempt_id,
                    phase
                        .is_some_and(|phase| phase != BrokerSpawnWalPhaseV1::Intent)
                        .then_some(attempt_id)
                );
                assert_eq!(
                    entry.child_identity,
                    phase
                        .is_some_and(|phase| {
                            matches!(
                                phase,
                                BrokerSpawnWalPhaseV1::SpawnObserved
                                    | BrokerSpawnWalPhaseV1::ReplyAcknowledged
                            )
                        })
                        .then_some(child_identity)
                );
                assert_eq!(
                    entry.reply_ack_id,
                    (phase == Some(BrokerSpawnWalPhaseV1::ReplyAcknowledged))
                        .then_some(reply_ack_id)
                );
                assert_eq!(
                    BrokerCensusEntryV1::decode(
                        &entry.encode().expect("encode all-phase Census row")
                    )
                    .expect("decode all-phase Census row"),
                    entry
                );
            }
        }
    }

    #[test]
    fn exec_bootstrap_codec_binds_attempt_payload_and_message_direction() {
        fn assert_zeroize_on_drop<T: ZeroizeOnDrop>() {}
        assert_zeroize_on_drop::<BrokerExecBootstrapWireFrameV1>();

        let control_authority = control_authenticator(0xa5);
        let connection = authority(id(801), id(802), id(803), id(804), 0x81, 0x82);
        let payload = command_payload(
            "printf barrier-codec",
            Path::new("/tmp/frankenterm-bootstrap-codec-sentinel"),
        );
        let canonical_payload = payload.encode().expect("canonical Spawn payload");
        let identity = exec_bootstrap_identity(&payload, &connection);
        let encoded_identity = identity
            .encode_cli_identity()
            .expect("encode canonical bootstrap invocation identity");
        assert_eq!(
            encoded_identity.len(),
            BROKER_EXEC_BOOTSTRAP_IDENTITY_HEX_BYTES
        );
        assert_eq!(
            BrokerExecBootstrapIdentityV1::decode_cli_identity(&encoded_identity)
                .expect("decode canonical bootstrap invocation identity"),
            identity
        );
        let mut uppercase_identity = encoded_identity.clone();
        uppercase_identity.replace_range(0..1, "A");
        assert!(matches!(
            BrokerExecBootstrapIdentityV1::decode_cli_identity(&uppercase_identity),
            Err(BrokerExecBootstrapProtocolErrorV1::InvalidIdentity)
        ));
        assert!(matches!(
            BrokerExecBootstrapIdentityV1::decode_cli_identity(&encoded_identity[2..]),
            Err(BrokerExecBootstrapProtocolErrorV1::InvalidIdentity)
        ));

        for (kind, bytes) in [
            (BrokerExecBootstrapMessageKindV1::Ready, &[][..]),
            (
                BrokerExecBootstrapMessageKindV1::Prepare,
                canonical_payload.as_slice(),
            ),
            (BrokerExecBootstrapMessageKindV1::Prepared, &[][..]),
            (BrokerExecBootstrapMessageKindV1::Release, &[][..]),
        ] {
            let encoded =
                encode_broker_exec_bootstrap_frame(&control_authority, identity, kind, bytes)
                    .expect("encode authenticated bootstrap frame");
            assert_eq!(
                encoded.as_slice().len(),
                BROKER_EXEC_BOOTSTRAP_FIXED_BYTES + bytes.len()
            );
            let decoded = decode_broker_exec_bootstrap_frame(
                &control_authority,
                identity,
                encoded.as_slice(),
            )
            .expect("decode authenticated bootstrap frame");
            assert_eq!(decoded.kind, kind);
            assert_eq!(decoded.payload(), bytes);
        }

        let ready = encode_broker_exec_bootstrap_frame(
            &control_authority,
            identity,
            BrokerExecBootstrapMessageKindV1::Ready,
            &[],
        )
        .expect("encode Ready response");
        let ready_authenticated_bytes = ready.as_slice().len() - GUARDIAN_MAC_BYTES;
        assert!(
            control_authority
                .verify_request(
                    &ready.as_slice()[..ready_authenticated_bytes],
                    &ready.as_slice()[ready_authenticated_bytes..],
                )
                .is_err(),
            "bootstrap response authenticated as a broker request"
        );

        let prepare = encode_broker_exec_bootstrap_frame(
            &control_authority,
            identity,
            BrokerExecBootstrapMessageKindV1::Prepare,
            canonical_payload.as_slice(),
        )
        .expect("encode Prepare request");
        let prepare_authenticated_bytes = prepare.as_slice().len() - GUARDIAN_MAC_BYTES;
        assert!(
            control_authority
                .verify_response(
                    &prepare.as_slice()[..prepare_authenticated_bytes],
                    &prepare.as_slice()[prepare_authenticated_bytes..],
                )
                .is_err(),
            "broker request authenticated as a bootstrap response"
        );

        let mut tampered = ready.as_slice().to_vec();
        tampered[84] ^= 1;
        assert!(matches!(
            decode_broker_exec_bootstrap_frame(&control_authority, identity, &tampered),
            Err(BrokerExecBootstrapProtocolErrorV1::AuthenticationFailed)
        ));

        let mut other_attempt = identity;
        other_attempt.attempt_id = id(805);
        let authenticated_other_attempt = encode_broker_exec_bootstrap_frame(
            &control_authority,
            other_attempt,
            BrokerExecBootstrapMessageKindV1::Ready,
            &[],
        )
        .expect("encode distinct authenticated attempt");
        assert!(matches!(
            decode_broker_exec_bootstrap_frame(
                &control_authority,
                identity,
                authenticated_other_attempt.as_slice(),
            ),
            Err(BrokerExecBootstrapProtocolErrorV1::InvalidIdentity)
        ));

        let mut wrong_payload = canonical_payload.to_vec();
        wrong_payload[0] ^= 1;
        assert!(matches!(
            encode_broker_exec_bootstrap_frame(
                &control_authority,
                identity,
                BrokerExecBootstrapMessageKindV1::Prepare,
                &wrong_payload,
            ),
            Err(BrokerExecBootstrapProtocolErrorV1::InvalidShape)
        ));

        let mut noncanonical = ready.as_slice().to_vec();
        noncanonical.push(0);
        assert!(matches!(
            decode_broker_exec_bootstrap_frame(&control_authority, identity, &noncanonical),
            Err(BrokerExecBootstrapProtocolErrorV1::InvalidLength)
        ));
    }

    #[test]
    fn exec_bootstrap_withholds_exec_authority_until_authenticated_release() {
        let directory = tempfile::Builder::new()
            .prefix("frankenterm-exec-bootstrap-release-")
            .tempdir_in(crate::canonical_test_temp_root())
            .expect("create exec-bootstrap test directory")
            .keep();
        fs::set_permissions(&directory, fs::Permissions::from_mode(0o700))
            .expect("set exec-bootstrap test directory owner-only");
        let sentinel = directory.join("user-command-ran");
        let payload = command_payload("printf ran > \"$BROKER_SENTINEL\"", sentinel.as_path());
        let connection = authority(id(821), id(822), id(823), id(824), 0x83, 0x84);
        let identity = exec_bootstrap_identity(&payload, &connection);
        let control_authority = control_authenticator(0xb5);
        let canonical_payload = payload.encode().expect("canonical Spawn payload");
        let prepare = encode_broker_exec_bootstrap_frame(
            &control_authority,
            identity,
            BrokerExecBootstrapMessageKindV1::Prepare,
            canonical_payload.as_slice(),
        )
        .expect("encode Prepare request");
        let release = encode_broker_exec_bootstrap_frame(
            &control_authority,
            identity,
            BrokerExecBootstrapMessageKindV1::Release,
            &[],
        )
        .expect("encode Release request");

        let (mut parent_writer, child_writer) =
            BlockingUnixStream::pair().expect("create exec-bootstrap protocol socket pair");
        let mut parent_reader = parent_writer
            .try_clone()
            .expect("clone parent protocol reader");
        parent_reader
            .set_nonblocking(true)
            .expect("make parent protocol reader nonblocking");
        parent_writer
            .set_nonblocking(true)
            .expect("make parent protocol writer nonblocking");
        let mut child_input = child_writer
            .try_clone()
            .expect("clone child protocol reader");
        let mut child_output = child_writer;
        let child_authority = control_authority.clone();
        let (result_sender, result_receiver) = std::sync::mpsc::channel();
        let child = thread::spawn(move || {
            let mut validations = 0_u8;
            let result = prepare_broker_exec_command_after_release(
                &mut child_input,
                &mut child_output,
                &child_authority,
                identity,
                || {
                    validations = validations.saturating_add(1);
                    Ok(())
                },
            );
            let outcome = result.map(|prepared_command| {
                drop(prepared_command);
                validations
            });
            result_sender
                .send(outcome)
                .expect("send child protocol result");
        });

        let deadline = Instant::now() + Duration::from_secs(2);
        let mut io = BrokerExecBootstrapBrokerIoV1::new(&mut parent_reader, &mut parent_writer)
            .expect("create bounded broker protocol I/O");
        let ready_wire = io
            .read_frame_until(deadline, "test-ready-read")
            .expect("read Ready response");
        let ready =
            decode_broker_exec_bootstrap_frame(&control_authority, identity, ready_wire.as_slice())
                .expect("authenticate Ready response");
        assert_eq!(ready.kind, BrokerExecBootstrapMessageKindV1::Ready);
        io.write_frame_until(&prepare, deadline, "test-prepare-write")
            .expect("write Prepare request");
        let prepared_wire = io
            .read_frame_until(deadline, "test-prepared-read")
            .expect("read Prepared response");
        let prepared = decode_broker_exec_bootstrap_frame(
            &control_authority,
            identity,
            prepared_wire.as_slice(),
        )
        .expect("authenticate Prepared response");
        assert_eq!(prepared.kind, BrokerExecBootstrapMessageKindV1::Prepared);
        assert!(
            matches!(
                result_receiver.try_recv(),
                Err(std::sync::mpsc::TryRecvError::Empty)
            ),
            "child produced exec authority before Release"
        );
        assert!(!sentinel.exists(), "user command ran before Release");
        io.write_frame_until(&release, deadline, "test-release-write")
            .expect("write Release request");
        drop(io);
        assert_eq!(
            result_receiver
                .recv_timeout(Duration::from_secs(2))
                .expect("child returned after Release")
                .expect("child accepted the authenticated sequence"),
            3,
            "token authority was not checked at every child barrier"
        );
        child.join().expect("child protocol thread joined");
        assert!(
            !sentinel.exists(),
            "preparation alone executed the user command"
        );
    }

    #[test]
    fn exec_bootstrap_initial_pty_handoff_retries_bounded_zero_reads_for_live_child() {
        let payload = command_payload(
            "printf unused",
            Path::new("/tmp/frankenterm-exec-bootstrap-unused"),
        );
        let connection = authority(id(825), id(826), id(827), id(828), 0x91, 0x92);
        let identity = exec_bootstrap_identity(&payload, &connection);
        let control_authority = control_authenticator(0xb7);
        let ready = encode_broker_exec_bootstrap_frame(
            &control_authority,
            identity,
            BrokerExecBootstrapMessageKindV1::Ready,
            &[],
        )
        .expect("encode transient-handoff Ready response");
        let (broker_stream, mut bootstrap_stream) =
            BlockingUnixStream::pair().expect("create transient-handoff socket pair");
        broker_stream
            .set_nonblocking(true)
            .expect("make transient-handoff reader nonblocking");
        let mut broker_writer = broker_stream
            .try_clone()
            .expect("clone transient-handoff broker writer");
        bootstrap_stream
            .write_all(ready.as_slice())
            .expect("seed complete Ready response");
        let mut reader = InitialZeroPollableReader {
            stream: broker_stream,
            zero_reads_remaining: 2,
        };
        let mut child = std::process::Command::new("/bin/sh")
            .arg("-c")
            .arg("sleep 5")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("spawn live transient-handoff child");
        let deadline = Instant::now() + Duration::from_secs(2);
        let mut io = BrokerExecBootstrapBrokerIoV1::new(&mut reader, &mut broker_writer)
            .expect("create transient-handoff broker I/O");
        let observed_wire = io
            .read_initial_frame_until(&mut child, deadline, "test-initial-handoff-ready")
            .expect("retry bounded initial PTY handoff reads");
        let observed = decode_broker_exec_bootstrap_frame(
            &control_authority,
            identity,
            observed_wire.as_slice(),
        )
        .expect("authenticate Ready after transient PTY handoff");
        assert_eq!(observed.kind, BrokerExecBootstrapMessageKindV1::Ready);
        drop(io);
        assert_eq!(reader.zero_reads_remaining, 0);
        child.kill().expect("terminate transient-handoff child");
        child.wait().expect("reap transient-handoff child");
    }

    #[test]
    fn exec_bootstrap_eof_before_release_yields_no_exec_authority() {
        let directory = tempfile::Builder::new()
            .prefix("frankenterm-exec-bootstrap-eof-")
            .tempdir_in(crate::canonical_test_temp_root())
            .expect("create exec-bootstrap EOF test directory")
            .keep();
        fs::set_permissions(&directory, fs::Permissions::from_mode(0o700))
            .expect("set exec-bootstrap EOF directory owner-only");
        let sentinel = directory.join("user-command-ran");
        let payload = command_payload("printf ran > \"$BROKER_SENTINEL\"", sentinel.as_path());
        let connection = authority(id(831), id(832), id(833), id(834), 0x85, 0x86);
        let identity = exec_bootstrap_identity(&payload, &connection);
        let control_authority = control_authenticator(0xb6);
        let canonical_payload = payload.encode().expect("canonical Spawn payload");
        let prepare = encode_broker_exec_bootstrap_frame(
            &control_authority,
            identity,
            BrokerExecBootstrapMessageKindV1::Prepare,
            canonical_payload.as_slice(),
        )
        .expect("encode Prepare request");

        let (mut parent_writer, child_writer) =
            BlockingUnixStream::pair().expect("create exec-bootstrap EOF protocol socket pair");
        let mut parent_reader = parent_writer
            .try_clone()
            .expect("clone EOF parent protocol reader");
        parent_reader
            .set_nonblocking(true)
            .expect("make EOF parent protocol reader nonblocking");
        parent_writer
            .set_nonblocking(true)
            .expect("make EOF parent protocol writer nonblocking");
        let mut child_input = child_writer
            .try_clone()
            .expect("clone EOF child protocol reader");
        let mut child_output = child_writer;
        let child_authority = control_authority.clone();
        let (result_sender, result_receiver) = std::sync::mpsc::channel();
        let child = thread::spawn(move || {
            let result = prepare_broker_exec_command_after_release(
                &mut child_input,
                &mut child_output,
                &child_authority,
                identity,
                || Ok(()),
            );
            result_sender
                .send(result.map(drop))
                .expect("send EOF child protocol result");
        });

        let deadline = Instant::now() + Duration::from_secs(2);
        let mut io = BrokerExecBootstrapBrokerIoV1::new(&mut parent_reader, &mut parent_writer)
            .expect("create bounded EOF broker protocol I/O");
        let ready_wire = io
            .read_frame_until(deadline, "test-eof-ready-read")
            .expect("read EOF Ready response");
        let ready =
            decode_broker_exec_bootstrap_frame(&control_authority, identity, ready_wire.as_slice())
                .expect("authenticate EOF Ready response");
        assert_eq!(ready.kind, BrokerExecBootstrapMessageKindV1::Ready);
        io.write_frame_until(&prepare, deadline, "test-eof-prepare-write")
            .expect("write EOF Prepare request");
        let prepared_wire = io
            .read_frame_until(deadline, "test-eof-prepared-read")
            .expect("read EOF Prepared response");
        let prepared = decode_broker_exec_bootstrap_frame(
            &control_authority,
            identity,
            prepared_wire.as_slice(),
        )
        .expect("authenticate EOF Prepared response");
        assert_eq!(prepared.kind, BrokerExecBootstrapMessageKindV1::Prepared);
        drop(io);
        drop(parent_reader);
        drop(parent_writer);

        let result = result_receiver
            .recv_timeout(Duration::from_secs(2))
            .expect("child observed broker EOF");
        assert!(
            matches!(result, Err(BrokerExecBootstrapErrorV1::FrameIo { .. })),
            "broker EOF yielded exec authority instead of failing closed"
        );
        child.join().expect("EOF child protocol thread joined");
        assert!(!sentinel.exists(), "user command ran after broker EOF");
    }

    #[test]
    fn broker_control_config_rejects_non_normalized_or_catalog_overlapping_endpoints() {
        let root = crate::canonical_test_temp_root().join("broker-control-config-path-contract");
        let catalog = root.join("spawn-catalog");
        let lease_catalog = root.join("lease-catalog");
        let socket = root.join("broker.sock");
        let token = root.join("guardian.token");
        let config = |socket_path, token_path, spawn_catalog_path, lease_catalog_path| {
            BrokerControlServiceConfigV1::new(
                socket_path,
                token_path,
                spawn_catalog_path,
                lease_catalog_path,
                sealed(0xa0),
                4,
                Duration::from_millis(5),
            )
        };

        assert!(
            config(
                socket.clone(),
                token.clone(),
                catalog.clone(),
                lease_catalog.clone()
            )
            .is_ok()
        );
        assert!(
            config(
                root.join("spawn-catalog.sock"),
                token.clone(),
                catalog.clone(),
                lease_catalog.clone()
            )
            .is_ok(),
            "component-based containment confused a sibling path prefix"
        );
        for rejected in [
            config(
                catalog.join("broker.sock"),
                token.clone(),
                catalog.clone(),
                lease_catalog.clone(),
            ),
            config(
                socket.clone(),
                catalog.join("guardian.token"),
                catalog.clone(),
                lease_catalog.clone(),
            ),
            config(
                root.join("socket-parent"),
                token.clone(),
                root.join("socket-parent").join("spawn-catalog"),
                lease_catalog.clone(),
            ),
            config(
                socket.clone(),
                root.join("token-parent"),
                root.join("token-parent").join("spawn-catalog"),
                lease_catalog.clone(),
            ),
            config(
                PathBuf::from("relative-broker.sock"),
                token.clone(),
                catalog.clone(),
                lease_catalog.clone(),
            ),
            config(
                root.join("nested").join("..").join("broker.sock"),
                token.clone(),
                catalog.clone(),
                lease_catalog.clone(),
            ),
            config(
                socket.clone(),
                token.clone(),
                catalog.clone(),
                catalog.clone(),
            ),
            config(
                socket.clone(),
                token.clone(),
                catalog.clone(),
                catalog.join("leases"),
            ),
        ] {
            assert!(matches!(
                rejected,
                Err(BrokerControlServiceError::InvalidConfiguration(_))
            ));
        }
    }

    #[test]
    fn broker_control_accept_batch_is_bounded_under_planted_listener_flood() {
        let root = tempfile::tempdir_in(crate::canonical_test_temp_root())
            .expect("create broker accept-quantum test root");
        fs::set_permissions(root.path(), fs::Permissions::from_mode(0o700))
            .expect("set broker accept-quantum root owner-only");
        let spawn_catalog_path = root.path().join("spawn-catalog");
        fs::create_dir(&spawn_catalog_path).expect("create Spawn catalog");
        fs::set_permissions(&spawn_catalog_path, fs::Permissions::from_mode(0o700))
            .expect("set Spawn catalog owner-only");
        let lease_catalog_path = create_private_lease_catalog(root.path());
        let socket_path = root.path().join("broker.sock");
        let token_path = root.path().join("guardian.token");
        crate::transport::provision_guardian_token(&token_path).expect("provision broker token");
        let max_connections = BROKER_CONTROL_ACCEPT_QUANTUM + 2;
        let config = BrokerControlServiceConfigV1::new(
            socket_path.clone(),
            token_path,
            spawn_catalog_path,
            lease_catalog_path,
            sealed(0xa1),
            max_connections,
            Duration::from_millis(5),
        )
        .expect("valid broker accept-quantum config");
        let mut service = BrokerControlServiceV1::bind(config).expect("bind broker service");

        let mut planted_connections = Vec::new();
        planted_connections
            .try_reserve_exact(BROKER_CONTROL_ACCEPT_QUANTUM + 1)
            .expect("reserve planted connection handles");
        for _ in 0..=BROKER_CONTROL_ACCEPT_QUANTUM {
            planted_connections.push(
                BlockingUnixStream::connect(&socket_path)
                    .expect("plant connection in broker listener backlog"),
            );
        }

        service
            .accept_connections()
            .expect("accept one bounded listener batch");
        assert_eq!(service.connections.len(), BROKER_CONTROL_ACCEPT_QUANTUM);
        assert_eq!(
            service.free_connection_tokens.len(),
            max_connections - BROKER_CONTROL_ACCEPT_QUANTUM
        );

        service
            .accept_connections()
            .expect("leave excess listener readiness for the next batch");
        assert_eq!(service.connections.len(), BROKER_CONTROL_ACCEPT_QUANTUM + 1);
        drop(planted_connections);
    }

