    #[test]
    fn token_rotation_between_response_enqueue_and_flush_emits_zero_stale_bytes() {
        let root = tempfile::tempdir_in(crate::canonical_test_temp_root())
            .expect("create enqueue-flush rotation test root");
        fs::set_permissions(root.path(), fs::Permissions::from_mode(0o700))
            .expect("set enqueue-flush rotation root owner-only");
        let spawn_catalog_path = root.path().join("spawn-catalog");
        fs::create_dir(&spawn_catalog_path).expect("create enqueue-flush Spawn catalog");
        fs::set_permissions(&spawn_catalog_path, fs::Permissions::from_mode(0o700))
            .expect("set enqueue-flush Spawn catalog owner-only");
        let lease_catalog_path = create_private_lease_catalog(root.path());
        let socket_path = root.path().join("broker.sock");
        let token_path = root.path().join("guardian.token");
        crate::transport::provision_guardian_token(&token_path)
            .expect("provision enqueue-flush token");
        let original_token = fs::read(&token_path).expect("read enqueue-flush token");
        let secret =
            crate::transport::load_guardian_secret(&token_path).expect("load enqueue-flush token");
        let control_authenticator = secret
            .broker_control_authenticator()
            .expect("derive enqueue-flush authority");
        let config = BrokerControlServiceConfigV1::new(
            socket_path.clone(),
            token_path.clone(),
            spawn_catalog_path,
            lease_catalog_path,
            sealed(0xa5),
            1,
            Duration::from_millis(5),
        )
        .expect("valid enqueue-flush broker config");
        let mut service =
            BrokerControlServiceV1::bind(config).expect("bind enqueue-flush broker service");
        let mut client =
            BlockingUnixStream::connect(&socket_path).expect("connect enqueue-flush client");
        client
            .set_read_timeout(Some(Duration::from_millis(50)))
            .expect("bound enqueue-flush client read");
        service
            .accept_connections()
            .expect("accept enqueue-flush client");
        let (&token, connection) = service
            .connections
            .iter()
            .next()
            .expect("one accepted enqueue-flush connection");
        let generation = connection.generation;
        let request = BrokerControlRequestV1::new(
            BrokerControlRequestHeaderV1 {
                operation: BrokerControlOperationV1::Hello,
                request_id: id(6_184),
                broker_incarnation: Uuid::nil(),
                guardian_incarnation: id(6_185),
                connection_id: id(6_186),
                mux_incarnation: id(6_187),
                guardian_build_identity_digest: sealed(0xa6).into_bytes(),
                mux_build_identity_digest: sealed(0xa7).into_bytes(),
                durable_pane_id: Uuid::nil(),
                lease_generation: 0,
                operation_id: Uuid::nil(),
            },
            &[],
        )
        .expect("canonical enqueue-flush Hello");
        let frame = encode_broker_control_request(&control_authenticator, &request)
            .expect("authenticate enqueue-flush Hello");
        client
            .write_all(frame.as_slice())
            .expect("write enqueue-flush Hello");
        service
            .drive_connection_read(token, generation)
            .expect("queue pre-rotation Hello response");
        assert!(
            service
                .connections
                .get(&token)
                .is_some_and(|connection| connection.write_frame.is_some())
        );

        let retained_token = root.path().join("guardian-retained-enqueue-flush.token");
        fs::rename(&token_path, &retained_token)
            .expect("retain pre-rotation enqueue-flush token inode");
        let mut replacement_token = original_token.clone();
        replacement_token[0] ^= 0x40;
        create_private_broker_token_with_bytes(&token_path, &replacement_token);
        let flush_hook_called = AtomicBool::new(false);
        assert!(matches!(
            service.drive_connection_write_with_hook(token, generation, || {
                flush_hook_called.store(true, Ordering::Release);
            }),
            Err(BrokerControlServiceError::Endpoint(
                GuardianServiceError::FilesystemSecurity(_)
            ))
        ));
        assert!(
            !flush_hook_called.load(Ordering::Acquire),
            "stale-authority response reached its flush attempt"
        );
        let mut stale_byte = [0_u8; 1];
        let error = client
            .read_exact(&mut stale_byte)
            .expect_err("stale-authority response emitted bytes after token rotation");
        assert!(matches!(
            error.kind(),
            ErrorKind::WouldBlock | ErrorKind::TimedOut
        ));
        assert_eq!(
            fs::read(&retained_token).expect("read retained enqueue-flush token"),
            original_token
        );

        drop(service);
        assert_eq!(
            client
                .read(&mut stale_byte)
                .expect("observe enqueue-flush connection closure"),
            0,
            "service teardown emitted a stale queued response"
        );
    }

    #[test]
    fn broker_control_authentication_deadline_reclaims_saturated_partial_connections() {
        let root = tempfile::tempdir_in(crate::canonical_test_temp_root())
            .expect("create broker authentication-deadline test root");
        fs::set_permissions(root.path(), fs::Permissions::from_mode(0o700))
            .expect("set broker authentication-deadline root owner-only");
        let spawn_catalog_path = root.path().join("spawn-catalog");
        fs::create_dir(&spawn_catalog_path).expect("create Spawn catalog");
        fs::set_permissions(&spawn_catalog_path, fs::Permissions::from_mode(0o700))
            .expect("set Spawn catalog owner-only");
        let lease_catalog_path = create_private_lease_catalog(root.path());
        let socket_path = root.path().join("broker.sock");
        let token_path = root.path().join("guardian.token");
        crate::transport::provision_guardian_token(&token_path).expect("provision broker token");
        let config = BrokerControlServiceConfigV1::new(
            socket_path.clone(),
            token_path,
            spawn_catalog_path,
            lease_catalog_path,
            sealed(0xa4),
            2,
            Duration::from_millis(5),
        )
        .expect("valid broker authentication-deadline config");
        let mut service = BrokerControlServiceV1::bind(config).expect("bind broker service");

        let first = BlockingUnixStream::connect(&socket_path).expect("connect first partial peer");
        let second =
            BlockingUnixStream::connect(&socket_path).expect("connect second partial peer");
        service
            .accept_connections()
            .expect("accept saturated partial peers");
        assert_eq!(service.connections.len(), 2);
        assert_eq!(service.free_connection_tokens.len(), 0);

        let mut tokens = service.connections.keys().copied().collect::<Vec<_>>();
        tokens.sort_unstable_by_key(|token| token.0);
        let now = Instant::now();
        service
            .connections
            .get_mut(&tokens[0])
            .expect("first accepted connection")
            .accepted_at = now
            .checked_sub(BROKER_CONTROL_AUTHENTICATION_DEADLINE)
            .expect("deadline is representable");
        let pre_deadline_age = BROKER_CONTROL_AUTHENTICATION_DEADLINE
            .checked_sub(Duration::from_millis(100))
            .expect("authentication deadline exceeds the test margin");
        service
            .connections
            .get_mut(&tokens[1])
            .expect("second accepted connection")
            .accepted_at = now
            .checked_sub(pre_deadline_age)
            .expect("pre-deadline instant is representable");

        service.expire_unauthenticated_connections();
        assert!(!service.connections.contains_key(&tokens[0]));
        assert!(service.connections.contains_key(&tokens[1]));
        assert_eq!(service.expired_unauthenticated_connections(), 1);
        assert_eq!(service.free_connection_tokens.len(), 1);

        service
            .connections
            .get_mut(&tokens[1])
            .expect("pre-deadline connection remains admitted")
            .accepted_at = Instant::now()
            .checked_sub(BROKER_CONTROL_AUTHENTICATION_DEADLINE)
            .expect("deadline is representable");
        service.expire_unauthenticated_connections();
        assert!(service.connections.is_empty());
        assert_eq!(service.expired_unauthenticated_connections(), 2);
        assert_eq!(service.free_connection_tokens.len(), 2);

        drop((first, second));
        let replacement =
            BlockingUnixStream::connect(&socket_path).expect("connect replacement peer");
        service
            .accept_connections()
            .expect("reuse reclaimed connection capacity");
        assert_eq!(service.connections.len(), 1);
        drop(replacement);
    }

    #[test]
    fn hello_receipt_eviction_skips_active_front_for_inactive_later_entry() {
        let header = |request_id, connection_id| BrokerControlRequestHeaderV1 {
            operation: BrokerControlOperationV1::Hello,
            request_id,
            broker_incarnation: Uuid::nil(),
            guardian_incarnation: id(801),
            connection_id,
            mux_incarnation: id(802),
            guardian_build_identity_digest: [0xa2; 32],
            mux_build_identity_digest: [0xa3; 32],
            durable_pane_id: Uuid::nil(),
            lease_generation: 0,
            operation_id: Uuid::nil(),
        };
        let active_front = id(803);
        let inactive_later = id(804);
        let active_tail = id(805);
        let mut receipts = BTreeMap::from([
            (
                active_front,
                BrokerHelloReceiptV1 {
                    header: header(active_front, id(806)),
                    active_connection: Some((Token(1), 11)),
                },
            ),
            (
                inactive_later,
                BrokerHelloReceiptV1 {
                    header: header(inactive_later, id(807)),
                    active_connection: None,
                },
            ),
            (
                active_tail,
                BrokerHelloReceiptV1 {
                    header: header(active_tail, id(808)),
                    active_connection: Some((Token(2), 12)),
                },
            ),
        ]);
        let mut order = VecDeque::from([active_front, inactive_later, active_tail]);

        assert_eq!(
            evict_one_inactive_hello_receipt(&mut receipts, &mut order),
            Ok(true)
        );
        assert_eq!(order, VecDeque::from([active_front, active_tail]));
        assert!(receipts.contains_key(&active_front));
        assert!(!receipts.contains_key(&inactive_later));
        assert!(receipts.contains_key(&active_tail));
    }

    #[test]
    fn broker_process_control_loop_exposes_empty_recovery_census_and_rejects_invalid_spawn() {
        let root = tempfile::tempdir_in(crate::canonical_test_temp_root())
            .expect("create broker service test root");
        fs::set_permissions(root.path(), fs::Permissions::from_mode(0o700))
            .expect("set broker service root owner-only");
        let spawn_catalog_path = root.path().join("spawn-catalog");
        fs::create_dir(&spawn_catalog_path).expect("create Spawn catalog");
        fs::set_permissions(&spawn_catalog_path, fs::Permissions::from_mode(0o700))
            .expect("set Spawn catalog owner-only");
        let lease_catalog_path = create_private_lease_catalog(root.path());
        let socket_path = root.path().join("broker.sock");
        let token_path = root.path().join("guardian.token");
        crate::transport::provision_guardian_token(&token_path).expect("provision broker token");
        let broker_build = sealed(0x91);
        let config = BrokerControlServiceConfigV1::new(
            socket_path.clone(),
            token_path.clone(),
            spawn_catalog_path,
            lease_catalog_path,
            broker_build,
            4,
            Duration::from_millis(5),
        )
        .expect("valid broker service config");
        let service = BrokerControlServiceV1::bind(config).expect("bind broker service");
        let broker_incarnation = service.incarnation();
        let service = TestBrokerControlService::start(service);

        let connection_identity =
            BrokerGuardianConnectionIdentityV1::new(id(741), id(742), sealed(0x92), sealed(0x93))
                .expect("valid guardian connection identity");
        let mut client = BrokerControlClientV1::connect(
            &socket_path,
            &token_path,
            connection_identity,
            broker_build,
        )
        .expect("authenticated broker Hello");
        assert_eq!(client.broker_incarnation(), broker_incarnation);
        assert!(!client.recovered_hello());

        let page_request = BrokerCensusPageRequestV1::new(
            Uuid::nil(),
            0,
            16,
            u32::try_from(
                BROKER_CONTROL_CENSUS_PAGE_HEADER_BYTES + BROKER_CONTROL_CENSUS_ENTRY_BYTES * 16,
            )
            .expect("bounded Census page bytes"),
        )
        .expect("canonical first Census page request");
        let census = client
            .census_page_with_request_id(id(743), page_request)
            .expect("read empty immutable recovery Census");
        assert!(!census.snapshot_id().is_nil());
        assert_eq!(census.total_entries(), 0);
        assert_eq!(census.entries(), []);
        assert_eq!(census.next_cursor(), None);

        let rejected_spawn = BrokerControlRequestV1::new(
            BrokerControlRequestHeaderV1 {
                operation: BrokerControlOperationV1::Spawn,
                request_id: id(746),
                broker_incarnation,
                guardian_incarnation: connection_identity.guardian_incarnation,
                connection_id: client.connection_id,
                mux_incarnation: connection_identity.mux_incarnation,
                guardian_build_identity_digest: connection_identity
                    .guardian_build_identity
                    .into_bytes(),
                mux_build_identity_digest: connection_identity.mux_build_identity.into_bytes(),
                durable_pane_id: id(747),
                lease_generation: 0,
                operation_id: id(748),
            },
            &[0x01],
        )
        .expect("canonical malformed Spawn request");
        let spawn_response = client
            .exchange(&rejected_spawn)
            .expect("bounded Spawn rejection");
        assert_eq!(
            spawn_response.header.status,
            BrokerControlResponseStatusV1::Rejected
        );
        assert_eq!(spawn_response.payload(), &[] as &[u8]);
        assert_eq!(
            client
                .query_recovered_spawn(id(747), id(748))
                .expect("query absent recovered Spawn identity"),
            None
        );

        let lost_hello_request_id = id(744);
        let lost_connection_id = id(745);
        let secret =
            crate::transport::load_guardian_secret(&token_path).expect("reload broker test token");
        let control_authenticator = secret
            .broker_control_authenticator()
            .expect("derive broker test control authenticator");
        let lost_hello = BrokerControlRequestV1::new(
            BrokerControlRequestHeaderV1 {
                operation: BrokerControlOperationV1::Hello,
                request_id: lost_hello_request_id,
                broker_incarnation: Uuid::nil(),
                guardian_incarnation: connection_identity.guardian_incarnation,
                connection_id: lost_connection_id,
                mux_incarnation: connection_identity.mux_incarnation,
                guardian_build_identity_digest: connection_identity
                    .guardian_build_identity
                    .into_bytes(),
                mux_build_identity_digest: connection_identity.mux_build_identity.into_bytes(),
                durable_pane_id: Uuid::nil(),
                lease_generation: 0,
                operation_id: Uuid::nil(),
            },
            &[],
        )
        .expect("canonical lost-reply Hello");
        let lost_frame = encode_broker_control_request(&control_authenticator, &lost_hello)
            .expect("encode lost-reply Hello");
        let mut dropped_client =
            BlockingUnixStream::connect(&socket_path).expect("connect dropped broker client");
        dropped_client
            .write_all(lost_frame.as_slice())
            .expect("write lost-reply Hello");
        drop(dropped_client);
        thread::sleep(Duration::from_millis(50));

        let recovered = BrokerControlClientV1::connect_with_hello_ids(
            &socket_path,
            &token_path,
            connection_identity,
            broker_build,
            lost_hello_request_id,
            lost_connection_id,
        )
        .expect("recover dropped Hello response without minting new identity");
        assert_eq!(recovered.broker_incarnation(), broker_incarnation);
        assert!(recovered.recovered_hello());

        let wrong_expected_build = BrokerControlClientV1::connect(
            &socket_path,
            &token_path,
            connection_identity,
            sealed(0x94),
        );
        assert!(matches!(
            wrong_expected_build,
            Err(BrokerControlClientError::BrokerBuildIdentityMismatch)
        ));

        drop(recovered);
        drop(client);
        service.finish();
    }

    #[test]
    fn broker_recovery_census_is_mux_scoped_paginated_owner_fenced_and_restartable() {
        let root = tempfile::tempdir_in(crate::canonical_test_temp_root())
            .expect("create paginated recovery Census root");
        fs::set_permissions(root.path(), fs::Permissions::from_mode(0o700))
            .expect("set paginated recovery Census root owner-only");
        let spawn_catalog_path = root.path().join("spawn-catalog");
        fs::create_dir(&spawn_catalog_path).expect("create paginated recovery Spawn catalog");
        fs::set_permissions(&spawn_catalog_path, fs::Permissions::from_mode(0o700))
            .expect("set paginated recovery Spawn catalog owner-only");
        let lease_catalog_path = create_private_lease_catalog(root.path());
        let socket_path = root.path().join("broker.sock");
        let token_path = root.path().join("guardian.token");
        crate::transport::provision_guardian_token(&token_path)
            .expect("provision paginated recovery token");
        let secret = crate::transport::load_guardian_secret(&token_path)
            .expect("load paginated recovery token");
        let authenticator = secret
            .broker_spawn_wal_authenticator()
            .expect("derive paginated recovery WAL authority");
        let shared_mux_incarnation = id(6_200);
        let other_mux_incarnation = id(6_201);
        let mut first = recovered_catalog_identity(&authenticator, 0x61);
        let mut second = recovered_catalog_identity(&authenticator, 0x62);
        let mut third = recovered_catalog_identity(&authenticator, 0x63);
        let mut other = recovered_catalog_identity(&authenticator, 0x64);
        first.mux_incarnation = shared_mux_incarnation;
        second.mux_incarnation = shared_mux_incarnation;
        third.mux_incarnation = shared_mux_incarnation;
        other.mux_incarnation = other_mux_incarnation;
        let mut catalog = BrokerSpawnWalCatalogV1::open(spawn_catalog_path.clone())
            .expect("open paginated recovery Spawn catalog");
        for identity in [third, other, first, second] {
            drop(
                catalog
                    .create_spawn_journal(identity, authenticator.clone())
                    .expect("create paginated recovery header-only journal"),
            );
        }
        drop(catalog);

        let broker_build = sealed(0xb2);
        let config = BrokerControlServiceConfigV1::new(
            socket_path.clone(),
            token_path.clone(),
            spawn_catalog_path,
            lease_catalog_path,
            broker_build,
            4,
            Duration::from_millis(5),
        )
        .expect("valid paginated recovery service config");
        let service =
            bind_test_service_after_owner_drop(&config).expect("bind paginated recovery service");
        let service = TestBrokerControlService::start(service);
        let first_connection = BrokerGuardianConnectionIdentityV1::new(
            id(6_202),
            shared_mux_incarnation,
            sealed(0xb3),
            sealed(0xb4),
        )
        .expect("valid first paginated recovery connection");
        let second_connection = BrokerGuardianConnectionIdentityV1::new(
            id(6_203),
            shared_mux_incarnation,
            sealed(0xb5),
            sealed(0xb4),
        )
        .expect("valid second paginated recovery connection");
        let mut first_client = BrokerControlClientV1::connect(
            &socket_path,
            &token_path,
            first_connection,
            broker_build,
        )
        .expect("connect first paginated recovery client");
        let mut second_client = BrokerControlClientV1::connect(
            &socket_path,
            &token_path,
            second_connection,
            broker_build,
        )
        .expect("connect second paginated recovery client");
        let one_row_bytes = u32::try_from(
            BROKER_CONTROL_CENSUS_PAGE_HEADER_BYTES + BROKER_CONTROL_CENSUS_ENTRY_BYTES,
        )
        .expect("single-row Census byte bound");
        let first_page_request = BrokerCensusPageRequestV1::new(Uuid::nil(), 0, 1, one_row_bytes)
            .expect("valid first paginated Census request");
        let first_page = first_client
            .census_page(first_page_request)
            .expect("read first paginated recovery page");
        assert_eq!(first_page.total_entries(), 3);
        assert_eq!(first_page.entries().len(), 1);
        assert_eq!(
            first_page.entries()[0].durable_pane_id,
            first.durable_pane_id()
        );
        assert_eq!(
            first_page.entries()[0].mux_incarnation,
            shared_mux_incarnation
        );
        assert_eq!(first_page.next_cursor(), Some(1));
        let original_snapshot_id = first_page.snapshot_id();

        let stolen_continuation =
            BrokerCensusPageRequestV1::new(original_snapshot_id, 1, 1, one_row_bytes)
                .expect("valid cross-owner continuation shape");
        assert!(matches!(
            second_client.census_page(stolen_continuation),
            Err(BrokerControlClientError::CensusAuthorityConflict)
        ));
        second_client
            .census_page(first_page_request)
            .expect("authority conflict does not poison a fresh Census request");

        let second_page = first_client
            .census_page(stolen_continuation)
            .expect("read second paginated recovery page");
        assert_eq!(second_page.entries().len(), 1);
        assert_eq!(
            second_page.entries()[0].durable_pane_id,
            second.durable_pane_id()
        );
        assert_eq!(second_page.next_cursor(), Some(2));

        let final_page_request =
            BrokerCensusPageRequestV1::new(original_snapshot_id, 2, 1, one_row_bytes)
                .expect("valid final paginated Census request");
        let final_page = first_client
            .census_page(final_page_request)
            .expect("read final paginated recovery page");
        assert_eq!(final_page.entries().len(), 1);
        assert_eq!(
            final_page.entries()[0].durable_pane_id,
            third.durable_pane_id()
        );
        assert_eq!(final_page.next_cursor(), None);

        let complete_census = first_client
            .census()
            .expect("collect a complete bounded recovery Census");
        assert_ne!(complete_census.snapshot_id(), original_snapshot_id);
        assert_eq!(
            complete_census
                .entries()
                .iter()
                .map(|entry| entry.durable_pane_id)
                .collect::<Vec<_>>(),
            vec![
                first.durable_pane_id(),
                second.durable_pane_id(),
                third.durable_pane_id(),
            ]
        );

        let expired_continuation =
            BrokerCensusPageRequestV1::new(original_snapshot_id, 2, 1, one_row_bytes)
                .expect("valid expired continuation shape");
        assert!(matches!(
            first_client.census_page(expired_continuation),
            Err(BrokerControlClientError::CensusSnapshotUnavailable)
        ));
        assert!(
            first_client.census_page(first_page_request).is_ok(),
            "an expired snapshot response poisoned a valid cursor-zero restart"
        );
        assert_eq!(
            first_client
                .query_recovered_spawn(other.durable_pane_id(), other.spawn_effect_id())
                .expect("query cross-mux recovered identity"),
            None,
            "one mux connection observed another mux's recovered Spawn row"
        );

        let other_connection = BrokerGuardianConnectionIdentityV1::new(
            id(6_204),
            other_mux_incarnation,
            sealed(0xb6),
            sealed(0xb7),
        )
        .expect("valid other-mux recovery connection");
        let mut other_client = BrokerControlClientV1::connect(
            &socket_path,
            &token_path,
            other_connection,
            broker_build,
        )
        .expect("connect other-mux recovery client");
        let other_page = other_client
            .census_page(first_page_request)
            .expect("read other-mux recovery Census");
        assert_eq!(other_page.total_entries(), 1);
        assert_eq!(other_page.entries().len(), 1);
        assert_eq!(
            other_page.entries()[0].durable_pane_id,
            other.durable_pane_id()
        );

        drop(other_client);
        drop(second_client);
        drop(first_client);
        service.finish();
    }

    #[test]
    fn recovery_census_collector_rejects_cross_page_duplicate_global_identities() {
        let page_capacity = BROKER_CONTROL_MAX_PAYLOAD_BYTES
            .checked_sub(BROKER_CONTROL_CENSUS_PAGE_HEADER_BYTES)
            .expect("Census payload holds its fixed header")
            / BROKER_CONTROL_CENSUS_ENTRY_BYTES;
        assert!(page_capacity > 0);
        assert!(page_capacity < GUARDIAN_MAX_PANES);
        let mux_incarnation = id(6_210);
        let mut canonical_entries = Vec::with_capacity(page_capacity + 1);
        for index in 0..=page_capacity {
            canonical_entries.push(prepared_census_entry(
                u128::try_from(index).expect("Census fixture ordinal"),
                mux_incarnation,
            ));
        }
        validate_broker_census_entries(&canonical_entries)
            .expect("canonical cross-page Census fixture");

        for (case, namespace) in ["journal", "Spawn effect", "origin request"]
            .into_iter()
            .enumerate()
        {
            let mut entries = canonical_entries.clone();
            match namespace {
                "journal" => entries[page_capacity].journal_id = entries[0].journal_id,
                "Spawn effect" => {
                    entries[page_capacity].spawn_effect_id = entries[0].spawn_effect_id;
                }
                "origin request" => {
                    entries[page_capacity].origin_request_id = entries[0].origin_request_id;
                }
                _ => unreachable!("the duplicate-identity fixture namespace is exhaustive"),
            }
            assert!(matches!(
                validate_broker_census_entries(&entries),
                Err(BrokerControlProtocolError::InvalidIdentity)
            ));

            let authority_byte = 0xc0_u8
                .checked_add(u8::try_from(case).expect("duplicate fixture case"))
                .expect("duplicate fixture authority byte");
            let client_authority = control_authenticator(authority_byte);
            let server_authority = control_authenticator(authority_byte);
            let connection_identity = BrokerGuardianConnectionIdentityV1::new(
                id(6_211 + u128::try_from(case).expect("connection fixture case")),
                mux_incarnation,
                sealed(0xc4),
                sealed(0xc5),
            )
            .expect("valid duplicate Census connection identity");
            let connection_id = id(6_214 + u128::try_from(case).expect("connection fixture case"));
            let broker_incarnation = id(6_217 + u128::try_from(case).expect("broker fixture case"));
            let snapshot_id = id(6_230 + u128::try_from(case).expect("snapshot fixture case"));
            let (client_stream, mut server_stream) =
                BlockingUnixStream::pair().expect("create duplicate Census socket pair");
            let server = thread::spawn(move || {
                let total_entries =
                    u64::try_from(entries.len()).expect("duplicate Census total rows");
                let second_cursor =
                    u64::try_from(page_capacity).expect("duplicate Census second cursor");
                for page_index in 0..2 {
                    let frame = read_blocking_broker_control_frame(
                        &mut server_stream,
                        BROKER_CONTROL_REQUEST_FIXED_BYTES,
                    )
                    .expect("read duplicate Census request");
                    let request = decode_broker_control_request(&server_authority, &frame)
                        .expect("decode duplicate Census request");
                    assert_eq!(request.header.operation, BrokerControlOperationV1::Census);
                    let page_request = BrokerCensusPageRequestV1::decode(request.payload())
                        .expect("decode duplicate Census page request");
                    let expected_cursor = if page_index == 0 { 0 } else { second_cursor };
                    assert_eq!(page_request.cursor(), expected_cursor);
                    let page_entries = if page_index == 0 {
                        entries[..page_capacity].to_vec()
                    } else {
                        vec![entries[page_capacity]]
                    };
                    let page = BrokerCensusPageV1 {
                        snapshot_id,
                        entries: page_entries,
                        next_cursor: (page_index == 0).then_some(second_cursor),
                        total_entries,
                    };
                    page.validate_for_request(page_request)
                        .expect("serve one canonical duplicate Census page");
                    let payload = page.encode().expect("encode duplicate Census page");
                    let response = BrokerControlResponseV1::new(
                        BrokerControlResponseHeaderV1 {
                            operation: BrokerControlOperationV1::Census,
                            status: if page_index == 0 {
                                BrokerControlResponseStatusV1::Applied
                            } else {
                                BrokerControlResponseStatusV1::Recovered
                            },
                            request_id: request.header.request_id,
                            broker_incarnation,
                            guardian_incarnation: request.header.guardian_incarnation,
                            connection_id: request.header.connection_id,
                            durable_pane_id: Uuid::nil(),
                            lease_generation: 0,
                            operation_id: Uuid::nil(),
                            child_identity: None,
                            output_sequence_start: 0,
                            output_sequence_end: 0,
                        },
                        &payload,
                    )
                    .expect("construct duplicate Census response");
                    let response = encode_broker_control_response(&server_authority, &response)
                        .expect("authenticate duplicate Census response");
                    server_stream
                        .write_all(response.as_slice())
                        .expect("write duplicate Census response");
                }
            });
            let mut client = BrokerControlClientV1 {
                stream: client_stream,
                control_authenticator: client_authority,
                identity: connection_identity,
                connection_id,
                broker_incarnation,
                recovered_hello: false,
                poisoned: false,
            };
            assert!(
                matches!(
                    client.census(),
                    Err(BrokerControlClientError::UnexpectedResponse)
                ),
                "cross-page duplicate {namespace} identity was accepted"
            );
            assert!(
                client.poisoned,
                "duplicate Census did not poison the stream"
            );
            server.join().expect("join duplicate Census fixture");
        }
    }

    #[test]
    fn recovery_census_collects_the_exact_global_pane_bound_without_extra_page() {
        let page_capacity = BROKER_CONTROL_MAX_PAYLOAD_BYTES
            .checked_sub(BROKER_CONTROL_CENSUS_PAGE_HEADER_BYTES)
            .expect("Census payload holds its fixed header")
            / BROKER_CONTROL_CENSUS_ENTRY_BYTES;
        assert!(page_capacity > 0);
        let mux_incarnation = id(6_235);
        let mut entries = Vec::with_capacity(GUARDIAN_MAX_PANES);
        for index in 0..GUARDIAN_MAX_PANES {
            entries.push(prepared_census_entry(
                u128::try_from(index).expect("maximum Census fixture ordinal"),
                mux_incarnation,
            ));
        }
        validate_broker_census_entries(&entries).expect("canonical maximum-sized Census fixture");

        let client_authority = control_authenticator(0xc6);
        let server_authority = control_authenticator(0xc6);
        let connection_identity = BrokerGuardianConnectionIdentityV1::new(
            id(6_236),
            mux_incarnation,
            sealed(0xc7),
            sealed(0xc8),
        )
        .expect("valid maximum Census connection identity");
        let connection_id = id(6_237);
        let broker_incarnation = id(6_238);
        let snapshot_id = id(6_239);
        let (client_stream, mut server_stream) =
            BlockingUnixStream::pair().expect("create maximum Census socket pair");
        let server = thread::spawn(move || {
            let total_entries = u64::try_from(entries.len()).expect("maximum Census total rows");
            let mut cursor = 0_usize;
            while cursor < entries.len() {
                let frame = read_blocking_broker_control_frame(
                    &mut server_stream,
                    BROKER_CONTROL_REQUEST_FIXED_BYTES,
                )
                .expect("read maximum Census request");
                let request = decode_broker_control_request(&server_authority, &frame)
                    .expect("decode maximum Census request");
                let page_request = BrokerCensusPageRequestV1::decode(request.payload())
                    .expect("decode maximum Census page request");
                assert_eq!(
                    page_request.cursor(),
                    u64::try_from(cursor).expect("maximum Census cursor")
                );
                let end = cursor
                    .checked_add(page_capacity)
                    .expect("maximum Census page end")
                    .min(entries.len());
                let next_cursor = (end < entries.len())
                    .then(|| u64::try_from(end).expect("maximum Census next cursor"));
                let page = BrokerCensusPageV1 {
                    snapshot_id,
                    entries: entries[cursor..end].to_vec(),
                    next_cursor,
                    total_entries,
                };
                page.validate_for_request(page_request)
                    .expect("serve canonical maximum Census page");
                let payload = page.encode().expect("encode maximum Census page");
                let response = BrokerControlResponseV1::new(
                    BrokerControlResponseHeaderV1 {
                        operation: BrokerControlOperationV1::Census,
                        status: if cursor == 0 {
                            BrokerControlResponseStatusV1::Applied
                        } else {
                            BrokerControlResponseStatusV1::Recovered
                        },
                        request_id: request.header.request_id,
                        broker_incarnation,
                        guardian_incarnation: request.header.guardian_incarnation,
                        connection_id: request.header.connection_id,
                        durable_pane_id: Uuid::nil(),
                        lease_generation: 0,
                        operation_id: Uuid::nil(),
                        child_identity: None,
                        output_sequence_start: 0,
                        output_sequence_end: 0,
                    },
                    &payload,
                )
                .expect("construct maximum Census response");
                let response = encode_broker_control_response(&server_authority, &response)
                    .expect("authenticate maximum Census response");
                server_stream
                    .write_all(response.as_slice())
                    .expect("write maximum Census response");
                cursor = end;
            }
            server_stream
                .set_read_timeout(Some(Duration::from_millis(50)))
                .expect("bound extra maximum Census request observation");
            let mut unexpected_request = [0_u8; 1];
            let error = server_stream
                .read_exact(&mut unexpected_request)
                .expect_err("collector requested a page beyond the exact global bound");
            assert!(matches!(
                error.kind(),
                ErrorKind::WouldBlock | ErrorKind::TimedOut
            ));
        });
        let mut client = BrokerControlClientV1 {
            stream: client_stream,
            control_authenticator: client_authority,
            identity: connection_identity,
            connection_id,
            broker_incarnation,
            recovered_hello: false,
            poisoned: false,
        };
        let census = client
            .census()
            .expect("collect exact maximum-sized recovery Census");
        assert_eq!(census.snapshot_id(), snapshot_id);
        assert_eq!(census.entries().len(), GUARDIAN_MAX_PANES);
        assert_eq!(
            census.entries().first().map(|entry| entry.durable_pane_id),
            Some(prepared_census_entry(0, mux_incarnation).durable_pane_id)
        );
        assert_eq!(
            census.entries().last().map(|entry| entry.durable_pane_id),
            Some(
                prepared_census_entry(
                    u128::try_from(GUARDIAN_MAX_PANES - 1).expect("last maximum Census ordinal"),
                    mux_incarnation,
                )
                .durable_pane_id
            )
        );
        server.join().expect("join maximum Census fixture");
    }

    #[test]
    fn census_client_rejects_phase_inconsistent_success_and_failure_statuses() {
        let mux_incarnation = id(6_240);
        let first_entry = prepared_census_entry(1, mux_incarnation);
        let second_entry = prepared_census_entry(2, mux_incarnation);
        let one_row_bytes = u32::try_from(
            BROKER_CONTROL_CENSUS_PAGE_HEADER_BYTES + BROKER_CONTROL_CENSUS_ENTRY_BYTES,
        )
        .expect("single-row Census response bound");

        for case in 0..4 {
            let case = u128::try_from(case).expect("status fixture case");
            let snapshot_id = id(6_241 + case);
            let (page_request, page) = if case % 2 == 0 {
                (
                    BrokerCensusPageRequestV1::new(Uuid::nil(), 0, 1, one_row_bytes)
                        .expect("fresh status fixture request"),
                    BrokerCensusPageV1 {
                        snapshot_id,
                        entries: vec![first_entry],
                        next_cursor: None,
                        total_entries: 1,
                    },
                )
            } else {
                (
                    BrokerCensusPageRequestV1::new(snapshot_id, 1, 1, one_row_bytes)
                        .expect("continuation status fixture request"),
                    BrokerCensusPageV1 {
                        snapshot_id,
                        entries: vec![second_entry],
                        next_cursor: None,
                        total_entries: 2,
                    },
                )
            };
            let wrong_status = match case {
                0 => BrokerControlResponseStatusV1::Recovered,
                1 => BrokerControlResponseStatusV1::Applied,
                2 => BrokerControlResponseStatusV1::Rejected,
                3 => BrokerControlResponseStatusV1::Retryable,
                _ => unreachable!("the Census status fixture cases are exhaustive"),
            };
            page.validate_for_request(page_request)
                .expect("canonical status fixture page");

            let authority_byte = 0xc8_u8
                .checked_add(u8::try_from(case).expect("status fixture authority case"))
                .expect("status fixture authority byte");
            let client_authority = control_authenticator(authority_byte);
            let server_authority = control_authenticator(authority_byte);
            let connection_identity = BrokerGuardianConnectionIdentityV1::new(
                id(6_243 + case),
                mux_incarnation,
                sealed(0xca),
                sealed(0xcb),
            )
            .expect("valid status fixture connection identity");
            let connection_id = id(6_245 + case);
            let broker_incarnation = id(6_247 + case);
            let (client_stream, mut server_stream) =
                BlockingUnixStream::pair().expect("create status fixture socket pair");
            let server = thread::spawn(move || {
                let frame = read_blocking_broker_control_frame(
                    &mut server_stream,
                    BROKER_CONTROL_REQUEST_FIXED_BYTES,
                )
                .expect("read swapped-status Census request");
                let request = decode_broker_control_request(&server_authority, &frame)
                    .expect("decode swapped-status Census request");
                assert_eq!(request.header.operation, BrokerControlOperationV1::Census);
                assert_eq!(
                    BrokerCensusPageRequestV1::decode(request.payload())
                        .expect("decode swapped-status page request"),
                    page_request
                );
                let payload = if matches!(
                    wrong_status,
                    BrokerControlResponseStatusV1::Applied
                        | BrokerControlResponseStatusV1::Recovered
                ) {
                    page.encode().expect("encode swapped-status Census page")
                } else {
                    Vec::new()
                };
                let response = BrokerControlResponseV1::new(
                    BrokerControlResponseHeaderV1 {
                        operation: BrokerControlOperationV1::Census,
                        status: wrong_status,
                        request_id: request.header.request_id,
                        broker_incarnation,
                        guardian_incarnation: request.header.guardian_incarnation,
                        connection_id: request.header.connection_id,
                        durable_pane_id: Uuid::nil(),
                        lease_generation: 0,
                        operation_id: Uuid::nil(),
                        child_identity: None,
                        output_sequence_start: 0,
                        output_sequence_end: 0,
                    },
                    &payload,
                )
                .expect("construct swapped-status Census response");
                let response = encode_broker_control_response(&server_authority, &response)
                    .expect("authenticate swapped-status Census response");
                server_stream
                    .write_all(response.as_slice())
                    .expect("write swapped-status Census response");
            });
            let mut client = BrokerControlClientV1 {
                stream: client_stream,
                control_authenticator: client_authority,
                identity: connection_identity,
                connection_id,
                broker_incarnation,
                recovered_hello: false,
                poisoned: false,
            };
            assert!(matches!(
                client.census_page(page_request),
                Err(BrokerControlClientError::UnexpectedResponse)
            ));
            assert!(
                client.poisoned,
                "swapped Census status did not poison the stream"
            );
            server.join().expect("join swapped-status Census fixture");
        }
    }

    #[test]
    fn recovery_census_deadline_classification_restores_socket_timeouts() {
        let client_authority = control_authenticator(0xcc);
        let server_authority = control_authenticator(0xcc);
        let connection_identity = BrokerGuardianConnectionIdentityV1::new(
            id(6_250),
            id(6_251),
            sealed(0xcd),
            sealed(0xce),
        )
        .expect("valid stalled Census connection identity");
        let (client_stream, mut server_stream) =
            BlockingUnixStream::pair().expect("create stalled Census socket pair");
        let original_read_timeout = Duration::from_secs(2);
        let original_write_timeout = Duration::from_secs(3);
        client_stream
            .set_read_timeout(Some(original_read_timeout))
            .expect("set original stalled Census read timeout");
        client_stream
            .set_write_timeout(Some(original_write_timeout))
            .expect("set original stalled Census write timeout");
        let server = thread::spawn(move || {
            let frame = read_blocking_broker_control_frame(
                &mut server_stream,
                BROKER_CONTROL_REQUEST_FIXED_BYTES,
            )
            .expect("read stalled Census request");
            let request = decode_broker_control_request(&server_authority, &frame)
                .expect("decode stalled Census request");
            assert_eq!(request.header.operation, BrokerControlOperationV1::Census);
            thread::sleep(Duration::from_millis(100));
        });
        let mut client = BrokerControlClientV1 {
            stream: client_stream,
            control_authenticator: client_authority,
            identity: connection_identity,
            connection_id: id(6_252),
            broker_incarnation: id(6_253),
            recovered_hello: false,
            poisoned: false,
        };
        assert!(matches!(
            client.census_with_deadline(Duration::from_millis(25)),
            Err(BrokerControlClientError::CensusCollectionDeadlineExceeded)
        ));
        assert!(
            client.poisoned,
            "stalled Census exchange did not poison the stream"
        );
        assert_eq!(
            client
                .stream
                .read_timeout()
                .expect("read restored Census read timeout"),
            Some(original_read_timeout)
        );
        assert_eq!(
            client
                .stream
                .write_timeout()
                .expect("read restored Census write timeout"),
            Some(original_write_timeout)
        );
        server.join().expect("join stalled Census fixture");
    }

    #[test]
    fn recovery_census_absolute_deadline_rejects_a_drip_fed_partial_frame() {
        let client_authority = control_authenticator(0xcf);
        let server_authority = control_authenticator(0xcf);
        let mux_incarnation = id(6_260);
        let connection_identity = BrokerGuardianConnectionIdentityV1::new(
            id(6_261),
            mux_incarnation,
            sealed(0xd0),
            sealed(0xd1),
        )
        .expect("valid drip-fed Census connection identity");
        let connection_id = id(6_262);
        let broker_incarnation = id(6_263);
        let (client_stream, mut server_stream) =
            BlockingUnixStream::pair().expect("create drip-fed Census socket pair");
        let original_read_timeout = Duration::from_secs(2);
        let original_write_timeout = Duration::from_secs(3);
        client_stream
            .set_read_timeout(Some(original_read_timeout))
            .expect("set original drip-fed Census read timeout");
        client_stream
            .set_write_timeout(Some(original_write_timeout))
            .expect("set original drip-fed Census write timeout");
        let client = BrokerControlClientV1 {
            stream: client_stream,
            control_authenticator: client_authority,
            identity: connection_identity,
            connection_id,
            broker_incarnation,
            recovered_hello: false,
            poisoned: false,
        };
        let client_done = Arc::new(AtomicBool::new(false));
        let client_thread_done = Arc::clone(&client_done);
        let client_thread = thread::spawn(move || {
            let mut client = client;
            let started = Instant::now();
            let result = client.census_with_deadline(Duration::from_millis(200));
            let elapsed = started.elapsed();
            client_thread_done.store(true, Ordering::Release);
            (client, result, elapsed)
        });

        let request_frame = read_blocking_broker_control_frame(
            &mut server_stream,
            BROKER_CONTROL_REQUEST_FIXED_BYTES,
        )
        .expect("read drip-fed Census request");
        let request = decode_broker_control_request(&server_authority, &request_frame)
            .expect("decode drip-fed Census request");
        let page_request = BrokerCensusPageRequestV1::decode(request.payload())
            .expect("decode drip-fed Census page request");
        let page = BrokerCensusPageV1 {
            snapshot_id: id(6_264),
            entries: vec![prepared_census_entry(1, mux_incarnation)],
            next_cursor: None,
            total_entries: 1,
        };
        page.validate_for_request(page_request)
            .expect("canonical drip-fed Census page");
        let payload = page.encode().expect("encode drip-fed Census page");
        let response = BrokerControlResponseV1::new(
            BrokerControlResponseHeaderV1 {
                operation: BrokerControlOperationV1::Census,
                status: BrokerControlResponseStatusV1::Applied,
                request_id: request.header.request_id,
                broker_incarnation,
                guardian_incarnation: request.header.guardian_incarnation,
                connection_id: request.header.connection_id,
                durable_pane_id: Uuid::nil(),
                lease_generation: 0,
                operation_id: Uuid::nil(),
                child_identity: None,
                output_sequence_start: 0,
                output_sequence_end: 0,
            },
            &payload,
        )
        .expect("construct drip-fed Census response");
        let response = encode_broker_control_response(&server_authority, &response)
            .expect("authenticate drip-fed Census response");
        let response_bytes = response.as_slice();
        server_stream
            .write_all(&response_bytes[..5])
            .expect("write drip-fed frame prefix and first body byte");
        let mut written = 5;
        for byte in &response_bytes[5..] {
            if client_done.load(Ordering::Acquire) {
                break;
            }
            thread::sleep(Duration::from_millis(15));
            if client_done.load(Ordering::Acquire) {
                break;
            }
            if server_stream.write_all(&[*byte]).is_err() {
                break;
            }
            written += 1;
        }
        assert!(
            written < response_bytes.len(),
            "drip fixture completed the frame"
        );

        let (client, result, elapsed) = client_thread.join().expect("join drip-fed Census client");
        assert!(matches!(
            result,
            Err(BrokerControlClientError::CensusCollectionDeadlineExceeded)
        ));
        assert!(
            elapsed < Duration::from_secs(1),
            "absolute Census deadline was reset"
        );
        assert!(client.poisoned, "drip-fed Census did not poison the stream");
        assert_eq!(
            client
                .stream
                .read_timeout()
                .expect("read restored drip-fed Census read timeout"),
            Some(original_read_timeout)
        );
        assert_eq!(
            client
                .stream
                .write_timeout()
                .expect("read restored drip-fed Census write timeout"),
            Some(original_write_timeout)
        );
    }

    #[test]
    fn ambiguous_control_exchange_permanently_poisoned_the_connection_before_retry() {
        let client_authority = control_authenticator(0xbc);
        let server_authority = control_authenticator(0xbc);
        let connection_identity = BrokerGuardianConnectionIdentityV1::new(
            id(6_220),
            id(6_221),
            sealed(0xbd),
            sealed(0xbe),
        )
        .expect("valid poisoned-exchange connection identity");
        let connection_id = id(6_222);
        let broker_incarnation = id(6_223);
        let durable_pane_id = id(6_224);
        let operation_id = id(6_225);
        let request = BrokerControlRequestV1::new(
            BrokerControlRequestHeaderV1 {
                operation: BrokerControlOperationV1::QueryEffect,
                request_id: id(6_226),
                broker_incarnation,
                guardian_incarnation: connection_identity.guardian_incarnation,
                connection_id,
                mux_incarnation: connection_identity.mux_incarnation,
                guardian_build_identity_digest: connection_identity
                    .guardian_build_identity
                    .into_bytes(),
                mux_build_identity_digest: connection_identity.mux_build_identity.into_bytes(),
                durable_pane_id,
                lease_generation: 0,
                operation_id,
            },
            &[],
        )
        .expect("canonical lost-reply QueryEffect request");
        let (client_stream, mut server_stream) =
            BlockingUnixStream::pair().expect("create poisoned-exchange socket pair");
        client_stream
            .set_read_timeout(Some(Duration::from_millis(10)))
            .expect("set short poisoned-exchange client timeout");
        client_stream
            .set_write_timeout(Some(Duration::from_millis(10)))
            .expect("set poisoned-exchange client write timeout");
        let server = thread::spawn(move || {
            let frame = read_blocking_broker_control_frame(
                &mut server_stream,
                BROKER_CONTROL_REQUEST_FIXED_BYTES,
            )
            .expect("read one lost-reply request");
            let decoded = decode_broker_control_request(&server_authority, &frame)
                .expect("decode one lost-reply request");
            thread::sleep(Duration::from_millis(50));
            let response = BrokerControlResponseV1::new(
                BrokerControlResponseHeaderV1 {
                    operation: decoded.header.operation,
                    status: BrokerControlResponseStatusV1::Rejected,
                    request_id: decoded.header.request_id,
                    broker_incarnation,
                    guardian_incarnation: decoded.header.guardian_incarnation,
                    connection_id: decoded.header.connection_id,
                    durable_pane_id: decoded.header.durable_pane_id,
                    lease_generation: decoded.header.lease_generation,
                    operation_id: decoded.header.operation_id,
                    child_identity: None,
                    output_sequence_start: 0,
                    output_sequence_end: 0,
                },
                &[],
            )
            .expect("construct delayed lost-reply response");
            let response = encode_broker_control_response(&server_authority, &response)
                .expect("encode delayed lost-reply response");
            server_stream
                .write_all(response.as_slice())
                .expect("write delayed lost-reply response");
            server_stream
                .set_read_timeout(Some(Duration::from_millis(20)))
                .expect("set duplicate-request observation timeout");
            let mut duplicate = [0_u8; 1];
            let error = server_stream
                .read_exact(&mut duplicate)
                .expect_err("poisoned client sent a duplicate request on the ambiguous stream");
            assert!(matches!(
                error.kind(),
                ErrorKind::WouldBlock | ErrorKind::TimedOut
            ));
        });
        let mut client = BrokerControlClientV1 {
            stream: client_stream,
            control_authenticator: client_authority,
            identity: connection_identity,
            connection_id,
            broker_incarnation,
            recovered_hello: false,
            poisoned: false,
        };
        let first_error = client
            .exchange(&request)
            .expect_err("delayed response must cross the client timeout");
        assert!(matches!(
            first_error,
            BrokerControlClientError::Io(ref error)
                if matches!(error.kind(), ErrorKind::WouldBlock | ErrorKind::TimedOut)
        ));
        assert!(matches!(
            client.exchange(&request),
            Err(BrokerControlClientError::ConnectionPoisoned)
        ));
        server.join().expect("join delayed-response broker fixture");
    }

    #[test]
    fn spawn_control_payload_round_trips_exact_admission_binding() {
        let authenticated = authority(id(721), id(722), id(723), id(724), 0x81, 0x82);
        let sentinel = crate::canonical_test_temp_root().join("broker-control-spawn-never-created");
        let payload = command_payload("printf never-spawned", &sentinel);
        let binding = binding_for(&payload, &authenticated);
        let request = BrokerSpawnControlRequestV1::from_parts(
            id(725),
            id(726),
            [0x83; BROKER_CATALOG_CHECKSUM_BYTES],
            binding,
            payload,
        )
        .expect("canonical Spawn control request");
        let encoded = request.encode().expect("encode Spawn control request");
        let decoded =
            BrokerSpawnControlRequestV1::decode(&encoded).expect("decode Spawn control request");
        assert_eq!(decoded.journal_id, id(725));
        assert_eq!(decoded.attempt_id, id(726));
        assert_eq!(decoded.binding, binding);
        assert_eq!(decoded.payload, request.payload);

        let header = BrokerControlRequestHeaderV1 {
            operation: BrokerControlOperationV1::Spawn,
            request_id: id(727),
            broker_incarnation: authenticated.broker_incarnation,
            guardian_incarnation: authenticated.owner.guardian_incarnation,
            connection_id: authenticated.owner.connection_id,
            mux_incarnation: authenticated.owner.mux_incarnation,
            guardian_build_identity_digest: authenticated.owner.guardian_build_identity_digest,
            mux_build_identity_digest: authenticated.owner.mux_build_identity_digest,
            durable_pane_id: binding.durable_pane_id,
            lease_generation: 0,
            operation_id: binding.spawn_effect_id,
        };
        decoded
            .validate_control_header(header)
            .expect("control header binds exact admission");
        let mut wrong_header = header;
        wrong_header.operation_id = id(728);
        assert!(matches!(
            decoded.validate_control_header(wrong_header),
            Err(BrokerControlProtocolError::InvalidIdentity)
        ));

        let mut mutated = encoded.to_vec();
        mutated[72 + 72] ^= 1;
        assert!(BrokerSpawnControlRequestV1::decode(&mutated).is_err());
        assert!(!sentinel.exists(), "control decode launched a user child");
    }

    #[test]
    fn capacity_one_spawn_worker_recovers_exact_inflight_retry_and_spawns_once() {
        let root = private_catalog_directory().keep();
        let catalog_path = root.join("spawn-catalog");
        fs::create_dir(&catalog_path).expect("create Spawn catalog directory");
        fs::set_permissions(&catalog_path, fs::Permissions::from_mode(0o700))
            .expect("make Spawn catalog private");
        let lease_catalog_path = create_private_lease_catalog(&root);
        let token_path = root.join("broker.token");
        let (exec_launch, spawn_authenticator) = unit_test_exec_bootstrap_launch(&token_path, 0xd1);
        let (secret, mut token_authority) = load_guardian_secret_with_authority(&token_path)
            .expect("load Spawn worker token authority");
        let lease_authenticator = secret
            .broker_lease_wal_authenticator()
            .expect("derive Spawn worker lease-WAL authority");
        let poll = Poll::new().expect("create Spawn worker completion poll");
        let completion_waker = Arc::new(
            Waker::new(poll.registry(), Token(1)).expect("create Spawn worker completion waker"),
        );
        let output_pipeline =
            GuardianOutputPipeline::open(&token_path, 1, Arc::clone(&completion_waker))
                .expect("open Spawn worker output pipeline");
        let spawn_catalog =
            BrokerSpawnWalCatalogV1::open(catalog_path).expect("open Spawn worker catalog");
        let lease_catalog = BrokerPaneLeaseWalCatalogV1::open(lease_catalog_path)
            .expect("open Spawn worker lease catalog");
        let broker_incarnation = id(7_201);
        let authority = authority(
            broker_incarnation,
            id(7_202),
            id(7_203),
            id(7_204),
            0xd2,
            0xd3,
        );
        let sentinel = root.join("spawn-worker-count");
        let payload = command_payload(
            "printf W >>\"$BROKER_SENTINEL\"; IFS= read -r ignored",
            &sentinel,
        );
        let binding = binding_for(&payload, &authority);
        let control_spawn = BrokerSpawnControlRequestV1::from_parts(
            id(7_205),
            id(7_206),
            [0xd4; BROKER_CATALOG_CHECKSUM_BYTES],
            binding,
            payload,
        )
        .expect("construct worker Spawn request");
        let encoded_spawn = control_spawn.encode().expect("encode worker Spawn request");
        let header = BrokerControlRequestHeaderV1 {
            operation: BrokerControlOperationV1::Spawn,
            request_id: id(7_207),
            broker_incarnation,
            guardian_incarnation: authority.owner.guardian_incarnation,
            connection_id: authority.owner.connection_id,
            mux_incarnation: authority.owner.mux_incarnation,
            guardian_build_identity_digest: authority.owner.guardian_build_identity_digest,
            mux_build_identity_digest: authority.owner.mux_build_identity_digest,
            durable_pane_id: binding.durable_pane_id,
            lease_generation: 0,
            operation_id: binding.spawn_effect_id,
        };
        let mut make_job = |header| {
            let request = BrokerSpawnControlRequestV1::decode(&encoded_spawn)
                .expect("decode independent worker Spawn authority");
            let token_effect_lease = token_authority
                .acquire_effect_lease()
                .expect("acquire Spawn worker effect lease");
            BrokerSpawnWorkerJobV1::new(
                broker_incarnation,
                header,
                authority.owner,
                request,
                token_effect_lease,
            )
            .expect("construct authenticated worker job")
        };
        let (effect_entered_tx, effect_entered_rx) = sync_channel(1);
        let (effect_release_tx, effect_release_rx) = sync_channel(1);
        let worker = BrokerSpawnWorkerV1::start(
            BrokerSpawnWorkerStateV1 {
                spawn_catalog,
                spawn_authenticator,
                lease_catalog,
                lease_authenticator,
                output_pipeline,
                exec_launch,
                broker_incarnation,
                limits: BrokerResourceLimitsV1::default(),
                effect_lease_probe: Some(BrokerSpawnWorkerEffectLeaseProbeV1 {
                    entered: effect_entered_tx,
                    release: effect_release_rx,
                }),
            },
            completion_waker,
        )
        .expect("start capacity-one Spawn worker");

        let prevalidation_job = make_job(header);
        fs::set_permissions(&token_path, fs::Permissions::from_mode(0o640))
            .expect("make worker token insecure before validation");
        assert_eq!(
            worker.try_submit(prevalidation_job),
            Ok(BrokerSpawnWorkerSubmissionV1::Submitted)
        );
        let prevalidation_failure = spawn_worker_completion(&worker);
        assert!(prevalidation_failure.token_authority_failed);
        assert!(matches!(
            prevalidation_failure.outcome,
            BrokerSpawnWorkerOutcomeV1::FailedBeforeDurableAttempt {
                journal: None,
                error: BrokerSpawnWorkerFailureV1::TokenAuthority,
            }
        ));
        assert!(
            !sentinel.exists(),
            "invalid pre-effect token authority created a user child"
        );
        fs::set_permissions(&token_path, fs::Permissions::from_mode(0o600))
            .expect("restore private worker token permissions");

        assert_eq!(
            worker.try_submit(make_job(header)),
            Ok(BrokerSpawnWorkerSubmissionV1::Submitted)
        );
        assert_eq!(
            worker.try_submit(make_job(header)),
            Ok(BrokerSpawnWorkerSubmissionV1::RecoveredInFlight),
            "exact retry enqueued a second PTY effect"
        );
        let mut conflicting_header = header;
        conflicting_header.request_id = id(7_208);
        assert_eq!(
            worker.try_submit(make_job(conflicting_header)),
            Err(BrokerSpawnWorkerSubmitErrorV1::ConflictingInFlight),
            "mutated retry shared the in-flight authority"
        );
        assert_eq!(
            effect_entered_rx
                .recv_timeout(Duration::from_secs(5))
                .expect("Spawn worker reached effect-lease boundary"),
            BrokerSpawnWorkerActiveV1::Spawn(make_job(header).fingerprint)
        );
        assert!(
            !crate::transport::guardian_token_publication_lock_is_available(&token_path)
                .expect("probe token publication while Spawn worker is blocked"),
            "cooperative token publication crossed the worker-owned Spawn effect lease"
        );
        effect_release_tx
            .send(())
            .expect("release Spawn worker effect-lease boundary");

        let completion = spawn_worker_completion(&worker);
        assert_eq!(completion.fingerprint.header, header);
        assert!(!completion.token_authority_failed);
        assert!(
            crate::transport::guardian_token_publication_lock_is_available(&token_path)
                .expect("probe token publication after Spawn completion"),
            "Spawn completion retained the worker effect lease"
        );
        let child_identity = match &completion.outcome {
            BrokerSpawnWorkerOutcomeV1::Applied {
                journal,
                adoption,
                spawn_observed,
                ..
            } => {
                assert_eq!(spawn_observed.phase(), BrokerSpawnWalPhaseV1::SpawnObserved);
                assert_eq!(
                    journal.status().phase,
                    Some(BrokerSpawnWalPhaseV1::SpawnObserved)
                );
                assert_eq!(adoption.attachment.identity().lease_generation(), 1);
                adoption.pane.kernel_child_identity()
            }
            _ => panic!("capacity-one worker did not durably apply Spawn"),
        };
        let deadline = Instant::now() + Duration::from_secs(3);
        while !sentinel.exists() && Instant::now() < deadline {
            thread::sleep(Duration::from_millis(1));
        }
        assert_eq!(
            fs::read(&sentinel).expect("read worker Spawn count"),
            b"W",
            "one admitted Spawn created a duplicate child"
        );

        drop(make_job);
        let ack_id = id(7_209);
        let ack_token_effect_lease = token_authority
            .acquire_effect_lease()
            .expect("acquire Spawn acknowledgement effect lease");
        let ack_job =
            BrokerSpawnAckWorkerJobV1::new(ack_id, Box::new(completion), ack_token_effect_lease)
                .unwrap_or_else(|_| panic!("construct worker acknowledgement job"));
        {
            let mut active = worker.active.lock().expect("lock worker authority fixture");
            assert!(active.is_none());
            *active = Some(BrokerSpawnWorkerActiveV1::Spawn(ack_job.fingerprint.spawn));
        }
        let rejected = match worker.try_submit_acknowledgement(ack_job) {
            Err(rejected) => rejected,
            Ok(_) => panic!("conflicting worker authority accepted an acknowledgement"),
        };
        assert_eq!(
            rejected.kind,
            BrokerSpawnWorkerSubmitErrorV1::ConflictingInFlight
        );
        assert!(matches!(
            &rejected.job.retained.outcome,
            BrokerSpawnWorkerOutcomeV1::Applied { adoption, .. }
                if adoption.pane.kernel_child_identity() == child_identity
        ));
        {
            let mut active = worker
                .active
                .lock()
                .expect("unlock worker authority fixture");
            assert!(active.take().is_some());
        }
        let acknowledgement_fingerprint = rejected.job.fingerprint;
        assert_eq!(
            worker.try_submit_acknowledgement(rejected.job).ok(),
            Some(BrokerSpawnWorkerSubmissionV1::Submitted)
        );
        assert_eq!(
            effect_entered_rx
                .recv_timeout(Duration::from_secs(5))
                .expect("acknowledgement worker reached effect-lease boundary"),
            BrokerSpawnWorkerActiveV1::Acknowledge(acknowledgement_fingerprint)
        );
        assert!(
            !crate::transport::guardian_token_publication_lock_is_available(&token_path)
                .expect("probe token publication while acknowledgement worker is blocked"),
            "cooperative token publication crossed the worker-owned Ack effect lease"
        );
        fs::set_permissions(&token_path, fs::Permissions::from_mode(0o640))
            .expect("drift worker token after Ack prevalidation");
        {
            let mut active = worker
                .active
                .lock()
                .expect("corrupt worker authority fixture");
            assert_eq!(
                *active,
                Some(BrokerSpawnWorkerActiveV1::Acknowledge(
                    acknowledgement_fingerprint
                ))
            );
            *active = Some(BrokerSpawnWorkerActiveV1::Spawn(
                acknowledgement_fingerprint.spawn,
            ));
        }
        effect_release_tx
            .send(())
            .expect("release acknowledgement worker effect-lease boundary");
        let deadline = Instant::now() + Duration::from_secs(5);
        let acknowledged = loop {
            match worker.try_completion() {
                BrokerSpawnWorkerCompletionStateV1::AuthorityLost(event) => match *event {
                    BrokerSpawnWorkerEventV1::Acknowledge(completion) => break completion,
                    BrokerSpawnWorkerEventV1::Spawn(_) => {
                        panic!("authority-loss proof received a Spawn completion")
                    }
                },
                BrokerSpawnWorkerCompletionStateV1::Empty if Instant::now() < deadline => {
                    thread::sleep(Duration::from_millis(1));
                }
                BrokerSpawnWorkerCompletionStateV1::Empty => {
                    panic!("authority-loss completion timed out")
                }
                BrokerSpawnWorkerCompletionStateV1::Ready(_) => {
                    panic!("corrupt worker authority accepted a completion")
                }
                BrokerSpawnWorkerCompletionStateV1::Disconnected => {
                    panic!("authority-loss worker disconnected")
                }
            }
        };
        assert_eq!(acknowledged.fingerprint.ack_id, ack_id);
        assert!(
            acknowledged.token_authority_failed,
            "post-Ack token drift was reported as normal live authority"
        );
        fs::set_permissions(&token_path, fs::Permissions::from_mode(0o600))
            .expect("restore worker token after Ack drift proof");
        assert!(
            crate::transport::guardian_token_publication_lock_is_available(&token_path)
                .expect("probe token publication after acknowledgement completion"),
            "acknowledgement completion retained the worker effect lease"
        );
        assert!(matches!(
            acknowledged.result.as_ref(),
            Some(Ok(result))
                if result.acknowledgement.phase()
                    == BrokerSpawnWalPhaseV1::ReplyAcknowledged
                    && !result.lease_journal.status().append_authority_withheld
                    && result.lease_journal.status().committed_records == 0
        ));
        let retained = *acknowledged.retained;
        let BrokerSpawnWorkerOutcomeV1::Applied {
            journal, adoption, ..
        } = retained.outcome
        else {
            panic!("acknowledgement worker lost the live Spawn authority")
        };
        assert_eq!(
            journal.status().phase,
            Some(BrokerSpawnWalPhaseV1::ReplyAcknowledged)
        );
        assert_eq!(journal.status().reply_ack_id, Some(ack_id));
        let BrokerAdoptionV1 {
            mut pane,
            attachment,
        } = *adoption;
        assert_eq!(attachment.identity().lease_generation(), 1);
        assert_eq!(pane.kernel_child_identity(), child_identity);
        pane.terminate_and_wait_for_test();
    }

    #[test]
    fn broker_control_spawn_is_async_query_recoverable_and_exactly_once() {
        for _repetition in 0..20 {
            broker_control_spawn_is_async_query_recoverable_and_exactly_once_once();
        }
    }

    fn broker_control_spawn_is_async_query_recoverable_and_exactly_once_once() {
        let root = private_catalog_directory().keep();
        let spawn_catalog_path = root.join("spawn-catalog");
        fs::create_dir(&spawn_catalog_path).expect("create control Spawn catalog");
        fs::set_permissions(&spawn_catalog_path, fs::Permissions::from_mode(0o700))
            .expect("make control Spawn catalog private");
        let lease_catalog_path = create_private_lease_catalog(&root);
        let socket_path = root.join("broker.sock");
        let token_path = root.join("guardian.token");
        crate::transport::provision_guardian_token(&token_path)
            .expect("provision control Spawn token");
        let broker_build = sealed(0xd5);
        let service = BrokerControlServiceV1::bind(
            BrokerControlServiceConfigV1::new(
                socket_path.clone(),
                token_path.clone(),
                spawn_catalog_path.clone(),
                lease_catalog_path.clone(),
                broker_build,
                2,
                Duration::from_millis(2),
            )
            .expect("construct control Spawn service config"),
        )
        .expect("bind control Spawn service");
        let broker_incarnation = service.incarnation();
        let service = TestBrokerControlService::start(service);
        let connection_identity = BrokerGuardianConnectionIdentityV1::new(
            id(7_301),
            id(7_302),
            sealed(0xd6),
            sealed(0xd7),
        )
        .expect("construct control Spawn connection identity");
        let mut client = BrokerControlClientV1::connect(
            &socket_path,
            &token_path,
            connection_identity,
            broker_build,
        )
        .expect("connect control Spawn client");
        let authenticated = BrokerAuthenticatedGuardianConnectionV1 {
            broker_incarnation,
            owner: BrokerGuardianOwnerIdentity {
                guardian_incarnation: connection_identity.guardian_incarnation,
                connection_id: client.connection_id,
                mux_incarnation: connection_identity.mux_incarnation,
                mux_build_identity_digest: connection_identity.mux_build_identity.into_bytes(),
                guardian_build_identity_digest: connection_identity
                    .guardian_build_identity
                    .into_bytes(),
            },
        };
        let sentinel = root.join("control-spawn-count");
        let payload = command_payload(
            "printf C >>\"$BROKER_SENTINEL\"; IFS= read -r ignored",
            &sentinel,
        );
        let binding = binding_for(&payload, &authenticated);
        let control_spawn = BrokerSpawnControlRequestV1::from_parts(
            id(7_303),
            id(7_304),
            [0xd8; BROKER_CATALOG_CHECKSUM_BYTES],
            binding,
            payload,
        )
        .expect("construct control Spawn payload");
        let encoded_spawn = control_spawn
            .encode()
            .expect("encode control Spawn payload");
        let header = BrokerControlRequestHeaderV1 {
            operation: BrokerControlOperationV1::Spawn,
            request_id: binding.origin_request_id,
            broker_incarnation,
            guardian_incarnation: authenticated.owner.guardian_incarnation,
            connection_id: authenticated.owner.connection_id,
            mux_incarnation: authenticated.owner.mux_incarnation,
            guardian_build_identity_digest: authenticated.owner.guardian_build_identity_digest,
            mux_build_identity_digest: authenticated.owner.mux_build_identity_digest,
            durable_pane_id: binding.durable_pane_id,
            lease_generation: 0,
            operation_id: binding.spawn_effect_id,
        };
        let spawn_request = |header| {
            BrokerControlRequestV1::new(header, &encoded_spawn)
                .expect("construct authenticated control Spawn request")
        };

        let submitted = client
            .exchange(&spawn_request(header))
            .expect("submit asynchronous control Spawn");
        assert_eq!(
            submitted.header.status,
            BrokerControlResponseStatusV1::Retryable
        );
        assert!(submitted.header.child_identity.is_none());
        assert_eq!(
            client
                .query_spawn_effect(binding.durable_pane_id, id(7_306))
                .expect("query live Spawn with a conflicting effect identity"),
            BrokerSpawnEffectQueryV1::Quarantined
        );
        assert_eq!(
            client
                .query_spawn_effect(id(7_307), binding.spawn_effect_id)
                .expect("query live Spawn with a conflicting pane identity"),
            BrokerSpawnEffectQueryV1::Quarantined
        );

        let deadline = Instant::now() + Duration::from_secs(5);
        let child_identity = loop {
            match client
                .query_spawn_effect(binding.durable_pane_id, binding.spawn_effect_id)
                .expect("query asynchronous control Spawn")
            {
                BrokerSpawnEffectQueryV1::Pending if Instant::now() < deadline => {
                    thread::sleep(Duration::from_millis(1));
                }
                BrokerSpawnEffectQueryV1::Applied(child_identity) => break child_identity,
                outcome => panic!("control Spawn did not become live: {outcome:?}"),
            }
        };
        assert!(matches!(
            client.query_recovered_spawn(binding.durable_pane_id, binding.spawn_effect_id),
            Err(BrokerControlClientError::SpawnPtyAvailable)
        ));
        assert_eq!(
            client
                .query_spawn_effect(binding.durable_pane_id, binding.spawn_effect_id)
                .expect("query live Spawn after recovered-only compatibility result"),
            BrokerSpawnEffectQueryV1::Applied(child_identity),
            "recovered-only compatibility result poisoned the live Spawn connection"
        );
        let initial_claim = match client
            .query_spawn_claim(binding.durable_pane_id, binding.spawn_effect_id)
            .expect("recover the initial pane claim and recovery capability")
        {
            BrokerSpawnClaimQueryV1::Claim(claim) => claim,
            outcome => panic!("control Spawn did not expose its initial claim: {outcome:?}"),
        };
        assert_eq!(initial_claim.child_identity(), child_identity);
        let other_mux_identity = BrokerGuardianConnectionIdentityV1::new(
            id(7_311),
            id(7_312),
            sealed(0xd9),
            sealed(0xda),
        )
        .expect("construct cross-mux control Spawn connection identity");
        let mut other_mux_client = BrokerControlClientV1::connect(
            &socket_path,
            &token_path,
            other_mux_identity,
            broker_build,
        )
        .expect("connect cross-mux control Spawn client");
        assert_eq!(
            other_mux_client
                .query_spawn_effect(binding.durable_pane_id, binding.spawn_effect_id)
                .expect("query another mux's live Spawn identity"),
            BrokerSpawnEffectQueryV1::Absent
        );
        assert_eq!(
            other_mux_client
                .acknowledge_spawn_effect(
                    binding.durable_pane_id,
                    binding.spawn_effect_id,
                    id(7_313),
                    initial_claim.recovery_secret(),
                )
                .expect("acknowledge another mux's live Spawn identity"),
            BrokerSpawnEffectAcknowledgementV1::Absent
        );
        drop(other_mux_client);
        let ack_id = id(7_308);
        let forged_recovery_secret =
            BrokerPaneRecoverySecretV1::from_wire(&[0xa5; BROKER_PANE_RECOVERY_SECRET_BYTES])
                .expect("construct nonzero forged recovery capability");
        assert_eq!(
            client
                .acknowledge_spawn_effect(
                    binding.durable_pane_id,
                    binding.spawn_effect_id,
                    ack_id,
                    &forged_recovery_secret,
                )
                .expect("reject forged pane recovery capability"),
            BrokerSpawnEffectAcknowledgementV1::Quarantined
        );
        assert_eq!(
            client
                .acknowledge_spawn_effect(
                    binding.durable_pane_id,
                    binding.spawn_effect_id,
                    ack_id,
                    initial_claim.recovery_secret(),
                )
                .expect("submit asynchronous Spawn acknowledgement"),
            BrokerSpawnEffectAcknowledgementV1::Pending
        );
        assert_eq!(
            client
                .acknowledge_spawn_effect(
                    binding.durable_pane_id,
                    binding.spawn_effect_id,
                    id(7_309),
                    initial_claim.recovery_secret(),
                )
                .expect("reject mutated Spawn acknowledgement identity"),
            BrokerSpawnEffectAcknowledgementV1::Quarantined
        );
        assert_eq!(
            client
                .acknowledge_spawn_effect(
                    binding.durable_pane_id,
                    id(7_314),
                    ack_id,
                    initial_claim.recovery_secret(),
                )
                .expect("reject acknowledgement with a conflicting effect namespace"),
            BrokerSpawnEffectAcknowledgementV1::Quarantined
        );
        assert_eq!(
            client
                .acknowledge_spawn_effect(
                    id(7_315),
                    binding.spawn_effect_id,
                    ack_id,
                    initial_claim.recovery_secret(),
                )
                .expect("reject acknowledgement with a conflicting pane namespace"),
            BrokerSpawnEffectAcknowledgementV1::Quarantined
        );
        let ack_deadline = Instant::now() + Duration::from_secs(5);
        loop {
            match client
                .acknowledge_spawn_effect(
                    binding.durable_pane_id,
                    binding.spawn_effect_id,
                    ack_id,
                    initial_claim.recovery_secret(),
                )
                .expect("recover asynchronous Spawn acknowledgement")
            {
                BrokerSpawnEffectAcknowledgementV1::Pending if Instant::now() < ack_deadline => {
                    thread::sleep(Duration::from_millis(1));
                }
                BrokerSpawnEffectAcknowledgementV1::Acknowledged => break,
                outcome => panic!("Spawn acknowledgement did not become durable: {outcome:?}"),
            }
        }
        assert_eq!(
            client
                .acknowledge_spawn_effect(
                    binding.durable_pane_id,
                    binding.spawn_effect_id,
                    ack_id,
                    initial_claim.recovery_secret(),
                )
                .expect("recover a second exact acknowledgement reply"),
            BrokerSpawnEffectAcknowledgementV1::Acknowledged
        );
        assert_eq!(
            fs::read_dir(&lease_catalog_path)
                .expect("enumerate live pane-lease catalog after exact Ack retry")
                .count(),
            4,
            "exact Spawn-Ack retry published a duplicate pane-lease member"
        );
        assert_eq!(
            client
                .query_spawn_effect(binding.durable_pane_id, binding.spawn_effect_id)
                .expect("query acknowledged live Spawn"),
            BrokerSpawnEffectQueryV1::Acknowledged {
                lease_generation: 1
            }
        );
        assert!(matches!(
            client
                .query_spawn_claim(binding.durable_pane_id, binding.spawn_effect_id)
                .expect("query acknowledged claim without plaintext reissue"),
            BrokerSpawnClaimQueryV1::Acknowledged {
                lease_generation: 1
            }
        ));
        let live_census = client
            .census()
            .expect("collect acknowledged live Spawn Census");
        let [live_entry] = live_census.entries() else {
            panic!("acknowledged live Spawn Census did not contain exactly one row")
        };
        assert_eq!(live_entry.durable_pane_id, binding.durable_pane_id);
        assert_eq!(live_entry.spawn_effect_id, binding.spawn_effect_id);
        assert_eq!(
            live_entry.disposition,
            BrokerCensusDispositionV1::ReplyAcknowledgedPtyAvailable
        );
        assert_eq!(
            live_entry.owner_mux_incarnation,
            Some(authenticated.owner.mux_incarnation)
        );
        assert_eq!(live_entry.lease_generation, 1);
        assert!(!live_entry.append_authority_withheld);
        assert!(!live_entry.effects_disabled);
        assert!(live_entry.pty_available);
        assert!(live_entry.lease_available);
        assert!(live_entry.output_replay_available);
        let recovered = client
            .exchange(&spawn_request(header))
            .expect("recover exact completed control Spawn");
        assert_eq!(
            recovered.header.status,
            BrokerControlResponseStatusV1::Recovered
        );
        assert_eq!(recovered.header.child_identity, Some(child_identity));
        assert!(
            recovered.payload().is_empty(),
            "acknowledged Spawn retry reissued the plaintext recovery capability"
        );

        let mut mutated_header = header;
        mutated_header.request_id = id(7_305);
        let conflict = client
            .exchange(&spawn_request(mutated_header))
            .expect("receive mutated Spawn quarantine");
        assert_eq!(
            conflict.header.status,
            BrokerControlResponseStatusV1::Quarantined
        );
        let count_deadline = Instant::now() + Duration::from_secs(3);
        while !sentinel.exists() && Instant::now() < count_deadline {
            thread::sleep(Duration::from_millis(1));
        }
        assert_eq!(
            fs::read(&sentinel).expect("read control Spawn count"),
            b"C",
            "control retry created more than one child"
        );
        drop(client);
        let mut reconnect = BrokerControlClientV1::connect(
            &socket_path,
            &token_path,
            connection_identity,
            broker_build,
        )
        .expect("reconnect exact mux after acknowledged owner EOF");
        let eof_deadline = Instant::now() + Duration::from_secs(5);
        loop {
            match reconnect
                .query_spawn_effect(binding.durable_pane_id, binding.spawn_effect_id)
                .expect("query live Spawn while predecessor connection is fenced")
            {
                BrokerSpawnEffectQueryV1::Pending => break,
                BrokerSpawnEffectQueryV1::Quarantined if Instant::now() < eof_deadline => {
                    thread::sleep(Duration::from_millis(1));
                }
                outcome => panic!("owner EOF did not fence the live lease: {outcome:?}"),
            }
        }
        let awaiting_census = reconnect
            .census()
            .expect("collect awaiting-successor live Spawn Census");
        let [awaiting_entry] = awaiting_census.entries() else {
            panic!("awaiting-successor Census did not contain exactly one live pane")
        };
        assert_eq!(
            awaiting_entry.disposition,
            BrokerCensusDispositionV1::ReplyAcknowledgedAwaitingSuccessor
        );
        assert_eq!(awaiting_entry.lease_generation, 2);
        assert!(awaiting_entry.effects_disabled);
        assert!(awaiting_entry.pty_available);
        assert!(!awaiting_entry.lease_available);
        assert!(!awaiting_entry.output_replay_available);

        let successor_identity = BrokerGuardianConnectionIdentityV1::new(
            id(7_316),
            id(7_317),
            sealed(0xdb),
            sealed(0xdc),
        )
        .expect("construct successor mux connection identity");
        let mut successor_client = BrokerControlClientV1::connect(
            &socket_path,
            &token_path,
            successor_identity,
            broker_build,
        )
        .expect("connect successor mux client");
        let handoff_id = id(7_318);
        let forged_predecessor_secret =
            BrokerPaneRecoverySecretV1::from_wire(&[0xb5; BROKER_PANE_RECOVERY_SECRET_BYTES])
                .expect("construct forged predecessor recovery capability");
        assert!(matches!(
            successor_client
                .claim_successor(
                    binding.durable_pane_id,
                    handoff_id,
                    2,
                    &forged_predecessor_secret,
                )
                .expect("reject forged predecessor capability"),
            BrokerSuccessorClaimQueryV1::Quarantined
        ));
        let successor_claim = match successor_client
            .claim_successor(
                binding.durable_pane_id,
                handoff_id,
                2,
                initial_claim.recovery_secret(),
            )
            .expect("claim the exact successor generation")
        {
            BrokerSuccessorClaimQueryV1::Claim(claim) => claim,
            outcome => panic!("successor Claim did not return a capability: {outcome:?}"),
        };
        assert_eq!(successor_claim.durable_pane_id(), binding.durable_pane_id);
        assert_eq!(successor_claim.handoff_id(), handoff_id);
        assert_eq!(successor_claim.lease_generation(), 2);
        assert!(matches!(
            reconnect
                .query_successor_claim(binding.durable_pane_id, handoff_id, 2)
                .expect("fence predecessor from successor Claim replay"),
            BrokerSuccessorClaimQueryV1::Quarantined
        ));
        assert!(matches!(
            successor_client
                .query_successor_claim(binding.durable_pane_id, handoff_id, 2)
                .expect("replay the exact successor Claim"),
            BrokerSuccessorClaimQueryV1::Claim(_)
        ));
        assert_eq!(
            successor_client
                .acknowledge_successor_claim(
                    binding.durable_pane_id,
                    handoff_id,
                    id(7_319),
                    2,
                    initial_claim.recovery_secret(),
                )
                .expect("reject predecessor capability as successor acknowledgement"),
            BrokerSuccessorAcknowledgementV1::Quarantined
        );
        let successor_ack_id = id(7_320);
        assert_eq!(
            successor_client
                .acknowledge_successor_claim(
                    binding.durable_pane_id,
                    handoff_id,
                    successor_ack_id,
                    2,
                    successor_claim.recovery_secret(),
                )
                .expect("acknowledge the exact successor Claim"),
            BrokerSuccessorAcknowledgementV1::Acknowledged
        );
        assert_eq!(
            successor_client
                .acknowledge_successor_claim(
                    binding.durable_pane_id,
                    handoff_id,
                    successor_ack_id,
                    2,
                    successor_claim.recovery_secret(),
                )
                .expect("recover the exact successor acknowledgement reply"),
            BrokerSuccessorAcknowledgementV1::Acknowledged
        );
        assert!(matches!(
            successor_client
                .query_successor_claim(binding.durable_pane_id, handoff_id, 2)
                .expect("query the acknowledged successor Claim"),
            BrokerSuccessorClaimQueryV1::Acknowledged
        ));
        let successor_census = successor_client
            .census()
            .expect("collect activated successor Census");
        let [successor_entry] = successor_census.entries() else {
            panic!("activated successor Census did not contain exactly one live pane")
        };
        assert_eq!(
            successor_entry.disposition,
            BrokerCensusDispositionV1::ReplyAcknowledgedPtyAvailable
        );
        assert_eq!(
            successor_entry.owner_mux_incarnation,
            Some(successor_identity.mux_incarnation)
        );
        assert_eq!(successor_entry.lease_generation, 2);
        assert!(!successor_entry.effects_disabled);
        assert!(successor_entry.lease_available);
        assert!(successor_entry.output_replay_available);
        drop(reconnect);
        drop(successor_client);
        service.finish();

        let secret = crate::transport::load_guardian_secret(&token_path)
            .expect("reload control Spawn token after service shutdown");
        let authenticator = secret
            .broker_spawn_wal_authenticator()
            .expect("derive control Spawn WAL authority after service shutdown");
        let lease_authenticator = secret
            .broker_lease_wal_authenticator()
            .expect("derive control Spawn lease-WAL authority after service shutdown");
        let mut catalog = reopen_test_catalog_after_owner_drop(&spawn_catalog_path)
            .expect("reopen acknowledged control Spawn catalog");
        let journals = catalog
            .scan_all_for_admission(&authenticator)
            .expect("scan acknowledged control Spawn catalog");
        let [journal] = journals.as_slice() else {
            panic!("expected exactly one acknowledged control Spawn journal")
        };
        let durable_status = journal.status();
        assert_eq!(
            durable_status.phase,
            Some(BrokerSpawnWalPhaseV1::ReplyAcknowledged)
        );
        assert_eq!(durable_status.reply_ack_id, Some(ack_id));
        assert_eq!(durable_status.child_identity, Some(child_identity));
        assert!(
            durable_status
                .recovery_verifier
                .expect("acknowledged Spawn retained its durable recovery verifier")
                .verifies(initial_claim.recovery_secret(), durable_status.identity, 1,),
            "durable recovery verifier did not authenticate the issued capability"
        );
        drop(journals);
        drop(catalog);
        let lease_catalog = reopen_test_lease_catalog_after_owner_drop(&lease_catalog_path)
            .expect("reopen acknowledged control Spawn lease catalog");
        let lease_journals = lease_catalog
            .scan_all_for_admission(&lease_authenticator)
            .expect("authenticate acknowledged control Spawn lease catalog");
        let [lease_journal] = lease_journals.as_slice() else {
            panic!("expected exactly one acknowledged control Spawn lease journal")
        };
        let lease_status = lease_journal.status();
        assert_eq!(lease_status.identity.spawn, durable_status.identity);
        assert_eq!(lease_status.identity.child_identity, child_identity);
        assert_eq!(
            lease_status.identity.initial_recovery_verifier,
            durable_status
                .recovery_verifier
                .expect("acknowledged Spawn retained its recovery verifier")
        );
        assert!(lease_status.append_authority_withheld);
        assert_eq!(lease_status.committed_records, 0);
        drop(lease_journals);
        drop(lease_catalog);
        drop(lease_authenticator);
        drop(authenticator);
        drop(secret);

        let restart_socket_path = root.join("broker-restart.sock");
        let restarted = BrokerControlServiceV1::bind(
            BrokerControlServiceConfigV1::new(
                restart_socket_path.clone(),
                token_path.clone(),
                spawn_catalog_path,
                lease_catalog_path,
                broker_build,
                2,
                Duration::from_millis(2),
            )
            .expect("construct restarted acknowledged Spawn service config"),
        )
        .expect("bind restarted acknowledged Spawn service");
        assert_eq!(restarted.recovered_lease_count(), 1);
        let restarted = TestBrokerControlService::start(restarted);
        let mut restarted_client = BrokerControlClientV1::connect(
            &restart_socket_path,
            &token_path,
            connection_identity,
            broker_build,
        )
        .expect("connect to restarted acknowledged Spawn service");
        assert_eq!(
            restarted_client
                .acknowledge_spawn_effect(
                    binding.durable_pane_id,
                    binding.spawn_effect_id,
                    ack_id,
                    initial_claim.recovery_secret(),
                )
                .expect("recover durable acknowledgement after broker restart"),
            BrokerSpawnEffectAcknowledgementV1::Acknowledged
        );
        assert_eq!(
            restarted_client
                .acknowledge_spawn_effect(
                    binding.durable_pane_id,
                    binding.spawn_effect_id,
                    id(7_310),
                    initial_claim.recovery_secret(),
                )
                .expect("reject mutated durable acknowledgement after broker restart"),
            BrokerSpawnEffectAcknowledgementV1::Quarantined
        );
        match restarted_client
            .query_spawn_effect(binding.durable_pane_id, binding.spawn_effect_id)
            .expect("query acknowledged Spawn after broker restart")
        {
            BrokerSpawnEffectQueryV1::RecoveredWithoutPty(entry) => {
                assert_eq!(entry.phase, Some(BrokerSpawnWalPhaseV1::ReplyAcknowledged));
                assert_eq!(entry.reply_ack_id, Some(ack_id));
                assert_eq!(entry.child_identity, Some(child_identity));
            }
            outcome => panic!("expected acknowledged PTY-unavailable recovery row: {outcome:?}"),
        }
        drop(restarted_client);
        restarted.finish();
    }

    fn private_catalog_directory() -> tempfile::TempDir {
        let directory = tempfile::tempdir_in(crate::canonical_test_temp_root())
            .expect("create private broker catalog test directory");
        fs::set_permissions(directory.path(), fs::Permissions::from_mode(0o700))
            .expect("set broker catalog test directory owner-only");
        directory
    }

    fn reopen_test_catalog_after_owner_drop(
        directory: &Path,
    ) -> Result<BrokerSpawnWalCatalogV1, BrokerSpawnWalError> {
        // Parallel spawn tests can fork while this process owns the catalog
        // lock. The child inherits that open-file description until the
        // portable-pty pre-exec close sweep runs, so an immediate same-process
        // restart can transiently observe CatalogAlreadyOwned even after the
        // parent descriptor was explicitly dropped. Production admission must
        // still fail immediately on a real competing owner; only this bounded
        // test restart helper waits for the CLOEXEC/pre-exec handoff to settle.
        for attempt in 0..100 {
            match BrokerSpawnWalCatalogV1::open(directory.to_path_buf()) {
                Err(BrokerSpawnWalError::CatalogAlreadyOwned) if attempt < 99 => {
                    thread::sleep(Duration::from_millis(1));
                }
                result => return result,
            }
        }
        unreachable!("the bounded catalog reopen loop always returns")
    }

    fn reopen_test_lease_catalog_after_owner_drop(
        directory: &Path,
    ) -> Result<BrokerPaneLeaseWalCatalogV1, BrokerPaneLeaseWalErrorV1> {
        for attempt in 0..100 {
            match BrokerPaneLeaseWalCatalogV1::open(directory.to_path_buf()) {
                Err(BrokerPaneLeaseWalErrorV1::CatalogAuthority(
                    BrokerSpawnWalError::CatalogAlreadyOwned,
                )) if attempt < 99 => thread::sleep(Duration::from_millis(1)),
                result => return result,
            }
        }
        unreachable!("the bounded pane-lease catalog reopen loop always returns")
    }

    fn bind_test_service_after_owner_drop(
        config: &BrokerControlServiceConfigV1,
    ) -> Result<BrokerControlServiceV1, BrokerControlServiceError> {
        // Like direct catalog reopen, service bind can race a parallel test's
        // fork between descriptor inheritance and the pre-exec close sweep.
        // Retry only that transient inherited-lock classification. Any real
        // competing owner survives the fixed 100 ms ceiling, and every other
        // startup error remains immediate and unchanged.
        for attempt in 0..100 {
            match BrokerControlServiceV1::bind(config.clone()) {
                Err(BrokerControlServiceError::SpawnCatalog(
                    BrokerSpawnWalError::CatalogAlreadyOwned,
                )) if attempt < 99 => thread::sleep(Duration::from_millis(1)),
                Err(BrokerControlServiceError::LeaseCatalog(
                    BrokerPaneLeaseWalErrorV1::CatalogAuthority(
                        BrokerSpawnWalError::CatalogAlreadyOwned,
                    ),
                )) if attempt < 99 => thread::sleep(Duration::from_millis(1)),
                result => return result,
            }
        }
        unreachable!("the bounded service-bind retry loop always returns")
    }

    fn create_private_broker_token_with_bytes(path: &Path, bytes: &[u8]) {
        let mut file = OpenOptions::new()
            .create_new(true)
            .write(true)
            .mode(0o600)
            .open(path)
            .expect("create private broker token replacement");
        file.write_all(bytes)
            .expect("write private broker token replacement");
        file.sync_all()
            .expect("synchronize private broker token replacement");
    }

    fn open_new_test_file(path: &std::path::Path) -> File {
        OpenOptions::new()
            .read(true)
            .write(true)
            .create_new(true)
            .mode(0o600)
            .open(path)
            .expect("create exclusive test file")
    }

