    fn proxy_write(
        pane: &mut BrokerAdoptedPaneV1,
        attachment: &BrokerPtyAttachmentV1,
        bytes: &[u8],
    ) {
        let permit = pane
            .admit_proxy_write(attachment, bytes)
            .expect("admit proxy write");
        pane.execute_proxy_write(permit, bytes)
            .expect("execute proxy write");
    }

    fn read_until(
        pane: &mut BrokerAdoptedPaneV1,
        attachment: &BrokerPtyAttachmentV1,
        needle: &[u8],
    ) -> Vec<u8> {
        let deadline = Instant::now() + Duration::from_secs(5);
        let mut output = Vec::new();
        let mut chunk = [0_u8; 512];
        while Instant::now() < deadline {
            let max_bytes = pane.limits.max_proxy_operation_bytes.min(chunk.len());
            let permit = pane
                .admit_proxy_read(attachment, max_bytes)
                .expect("admit proxy read");
            match pane.execute_proxy_read(permit, &mut chunk) {
                Ok(receipt) if receipt.bytes_read == 0 => break,
                Ok(receipt) => {
                    let count = receipt.bytes_read;
                    output.extend_from_slice(&chunk[..count]);
                    let ack = pane
                        .admit_proxy_output_ack(attachment, receipt.output_sequence_end)
                        .expect("admit output acknowledgement");
                    pane.execute_proxy_output_ack(ack)
                        .expect("commit output acknowledgement");
                    if output.windows(needle.len()).any(|window| window == needle) {
                        return output;
                    }
                }
                Err(BrokerError::ProxyWouldBlock) => match pane.pump_ready_output() {
                    Ok(BrokerOutputPumpOutcomeV1::Drained(receipt))
                        if receipt.bytes_drained > 0 => {}
                    Ok(BrokerOutputPumpOutcomeV1::Drained(_))
                    | Err(BrokerError::ProxyWouldBlock) => {
                        thread::sleep(Duration::from_millis(5));
                    }
                    Ok(BrokerOutputPumpOutcomeV1::TerminalDrained(receipt)) => panic!(
                        "PTY output became terminal before {:?}: {:?}",
                        String::from_utf8_lossy(needle),
                        receipt.reason
                    ),
                    Err(error) => panic!("PTY output pump failed: {error}"),
                },
                Err(error) => panic!("PTY proxy read failed: {error}"),
            }
        }
        panic!(
            "timed out waiting for {:?}; output was {:?}",
            String::from_utf8_lossy(needle),
            String::from_utf8_lossy(&output)
        );
    }

    fn pump_until_sequence_advances(pane: &mut BrokerAdoptedPaneV1, baseline: u64) {
        let deadline = Instant::now() + Duration::from_secs(5);
        while Instant::now() < deadline {
            match pane.pump_ready_output() {
                Ok(BrokerOutputPumpOutcomeV1::Drained(_))
                    if pane.status().output_sequence > baseline =>
                {
                    return;
                }
                Ok(BrokerOutputPumpOutcomeV1::Drained(_)) | Err(BrokerError::ProxyWouldBlock) => {
                    thread::sleep(Duration::from_millis(5));
                }
                Ok(BrokerOutputPumpOutcomeV1::TerminalDrained(receipt)) => {
                    panic!("PTY output became terminal before sequence advanced: {receipt:?}")
                }
                Err(error) => panic!("PTY output pump failed: {error}"),
            }
        }
        panic!("timed out draining output while guardian lease was absent");
    }

    fn pump_until_drained(pane: &mut BrokerAdoptedPaneV1) -> BrokerOutputPumpReceiptV1 {
        let deadline = Instant::now() + Duration::from_secs(5);
        while Instant::now() < deadline {
            match pane.pump_ready_output() {
                Ok(BrokerOutputPumpOutcomeV1::Drained(receipt)) => return receipt,
                Ok(BrokerOutputPumpOutcomeV1::TerminalDrained(receipt)) => {
                    panic!("PTY became terminal before yielding expected bytes: {receipt:?}")
                }
                Err(BrokerError::ProxyWouldBlock) => thread::sleep(Duration::from_millis(5)),
                Err(error) => panic!("PTY output pump failed: {error}"),
            }
        }
        panic!("timed out waiting for PTY output");
    }

    #[derive(Clone, Copy)]
    enum TerminalReadMode {
        Zero,
        Eio,
    }

    struct TerminalTestReader {
        fd: fs::File,
        reads: Arc<AtomicUsize>,
        mode: TerminalReadMode,
    }

    impl Read for TerminalTestReader {
        fn read(&mut self, _output: &mut [u8]) -> std::io::Result<usize> {
            self.reads.fetch_add(1, Ordering::AcqRel);
            match self.mode {
                TerminalReadMode::Zero => Ok(0),
                TerminalReadMode::Eio => Err(std::io::Error::from_raw_os_error(libc::EIO)),
            }
        }
    }

    #[test]
    fn spawn_creation_recovers_every_secure_umask_cut_without_changing_prefix_bytes() {
        let directory = private_catalog_directory();
        let authenticator = wal_authenticator(0xa1);
        let identity = recovered_catalog_identity(&authenticator, 0x41);
        let creating_name = broker_spawn_creation_marker_name(identity, &authenticator, false)
            .expect("encode mode-cut creating marker");
        let completed_name = broker_spawn_creation_marker_name(identity, &authenticator, true)
            .expect("encode mode-cut completed marker");
        let wal_name = broker_spawn_catalog_wal_name(identity.journal_id());
        let head_name = broker_spawn_catalog_head_name(identity.journal_id());
        let lock_path = directory.path().join(BROKER_SPAWN_CATALOG_LOCK_NAME);
        let creating_path = directory.path().join(&creating_name);
        let completed_path = directory.path().join(&completed_name);
        let wal_path = directory.path().join(&wal_name);
        let head_path = directory.path().join(&head_name);
        let wal_header =
            encode_broker_spawn_file_header(BROKER_SPAWN_WAL_FILE_MAGIC, identity, &authenticator)
                .expect("encode mode-cut WAL header");
        let head_header =
            encode_broker_spawn_file_header(BROKER_SPAWN_HEAD_FILE_MAGIC, identity, &authenticator)
                .expect("encode mode-cut head header");

        let catalog = BrokerSpawnWalCatalogV1::open(directory.path().to_path_buf())
            .expect("create mode-cut catalog lock");
        drop(catalog);
        create_empty_private_file(&creating_path);
        create_private_broker_token_with_bytes(&wal_path, &wal_header[..73]);
        create_private_broker_token_with_bytes(&head_path, &head_header[..149]);
        let mut head_probe = OpenOptions::new()
            .read(true)
            .open(&head_path)
            .expect("pin head prefix before simulated mode cut");

        // O_CREAT(0600) is filtered through umask. These are the only secure
        // permission subsets a creator can leave if power fails before its
        // following fchmod(0600), including the otherwise-unopenable 000 cut.
        fs::set_permissions(&lock_path, fs::Permissions::from_mode(0o000))
            .expect("set simulated lock create/fchmod cut");
        fs::set_permissions(&creating_path, fs::Permissions::from_mode(0o000))
            .expect("set simulated marker create/fchmod cut");
        fs::set_permissions(&wal_path, fs::Permissions::from_mode(0o400))
            .expect("set simulated WAL create/fchmod cut");
        fs::set_permissions(&head_path, fs::Permissions::from_mode(0o200))
            .expect("set simulated head create/fchmod cut");
        assert_eq!(
            fs::metadata(&lock_path).expect("mode-cut lock").mode() & 0o7777,
            0
        );
        assert_eq!(
            fs::metadata(&creating_path)
                .expect("mode-cut marker")
                .mode()
                & 0o7777,
            0
        );
        assert_eq!(
            fs::metadata(&wal_path).expect("mode-cut WAL").mode() & 0o7777,
            0o400
        );
        assert_eq!(
            fs::metadata(&head_path).expect("mode-cut head").mode() & 0o7777,
            0o200
        );

        let mut recovered = reopen_test_catalog_after_owner_drop(directory.path())
            .expect("structurally reopen every secure umask cut");
        assert_eq!(
            fs::read(&wal_path).expect("read WAL prefix after structural reopen"),
            wal_header[..73]
        );
        let mut observed_head_prefix = Vec::new();
        head_probe
            .read_to_end(&mut observed_head_prefix)
            .expect("read retained head descriptor after structural reopen");
        assert_eq!(observed_head_prefix, head_header[..149]);
        let journals = recovered
            .scan_all_for_admission(&authenticator)
            .expect("seal modes and resume exact authenticated prefixes");
        assert_eq!(journals.len(), 1);
        assert_eq!(journals[0].identity(), identity);
        assert_eq!(
            fs::read(&wal_path).expect("read recovered mode-cut WAL"),
            wal_header
        );
        assert_eq!(
            fs::read(&head_path).expect("read recovered mode-cut head"),
            head_header
        );
        assert!(!creating_path.exists());
        assert!(completed_path.exists());
        for path in [&lock_path, &completed_path, &wal_path, &head_path] {
            assert_eq!(
                fs::metadata(path).expect("sealed creation object").mode() & 0o7777,
                0o600
            );
        }
    }

    impl AsFd for TerminalTestReader {
        fn as_fd(&self) -> BorrowedFd<'_> {
            self.fd.as_fd()
        }
    }

    #[test]
    fn recovered_catalog_admission_accepts_valid_distinct_journals() {
        let directory = private_catalog_directory();
        let authenticator = wal_authenticator(0xa1);
        let first = recovered_catalog_identity(&authenticator, 1);
        let second = recovered_catalog_identity(&authenticator, 2);
        let (_catalog, journals) = recover_header_only_catalog_journals(
            directory.path(),
            &[first, second],
            &authenticator,
        );

        let admitted = BrokerRecoveredSpawnCatalogV1::admit(journals, &authenticator)
            .expect("admit distinct recovered identities");
        assert_eq!(admitted.journals.len(), 2);
        assert_eq!(admitted.by_journal_id.len(), 2);
        assert_eq!(admitted.by_durable_pane_id.len(), 2);
        assert_eq!(admitted.by_spawn_effect_id.len(), 2);
        assert_eq!(admitted.by_origin_request_id.len(), 2);
        assert!(!admitted.contains_spawn_lifecycle());
        for identity in [first, second] {
            let journal_index = *admitted
                .by_journal_id
                .get(&identity.journal_id())
                .expect("journal identity index");
            assert_eq!(
                admitted.by_durable_pane_id.get(&identity.durable_pane_id()),
                Some(&journal_index)
            );
            assert_eq!(
                admitted.by_spawn_effect_id.get(&identity.spawn_effect_id()),
                Some(&journal_index)
            );
            assert_eq!(
                admitted
                    .by_origin_request_id
                    .get(&identity.origin_request_id()),
                Some(&journal_index)
            );
            assert_eq!(admitted.journals[journal_index].identity(), identity);
        }
    }

