    #[test]
    fn later_invalid_catalog_pair_does_not_reconcile_an_earlier_wal_ahead_head() {
        let directory = private_catalog_directory();
        let authenticator = wal_authenticator(0xa9);
        let first = recovered_catalog_identity(&authenticator, 15);
        let second = recovered_catalog_identity(&authenticator, 16);
        let first_head_path = directory
            .path()
            .join(broker_spawn_catalog_head_name(first.journal_id()));
        let second_head_path = directory
            .path()
            .join(broker_spawn_catalog_head_name(second.journal_id()));

        let mut catalog = BrokerSpawnWalCatalogV1::open(directory.path().to_path_buf())
            .expect("open catalog for two-pass reconciliation test");
        let mut first_journal = catalog
            .create_spawn_journal(first, authenticator.clone())
            .expect("create first catalog journal");
        first_journal.inject_fault(BrokerSpawnWalInjectedFault::AfterWalSyncBeforeHead);
        assert!(matches!(
            first_journal.append_intent_and_sync(),
            Err(BrokerSpawnWalError::Io(_))
        ));
        let second_journal = catalog
            .create_spawn_journal(second, authenticator.clone())
            .expect("create later catalog journal");
        drop(first_journal);
        drop(second_journal);
        drop(catalog);

        let first_head_before_activation =
            fs::read(&first_head_path).expect("read first head before activation");
        assert_eq!(
            u64::try_from(first_head_before_activation.len()).expect("first head length"),
            BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
        );

        let mut recovered_catalog = reopen_test_catalog_after_owner_drop(directory.path())
            .expect("reopen catalog for two-pass reconciliation test");
        let journals = recovered_catalog
            .scan_all_for_admission(&authenticator)
            .expect("purely scan both valid catalog pairs");
        let mut admitted = BrokerRecoveredSpawnCatalogV1::admit(journals, &authenticator)
            .expect("admit both unique catalog pairs");
        assert_eq!(admitted.journals[0].identity(), first);
        assert!(admitted.journals[0].status().head_reconciliation_required);

        let mut later_head = OpenOptions::new()
            .append(true)
            .open(&second_head_path)
            .expect("open later head for planted length drift");
        later_head
            .write_all(&[0x5a])
            .expect("plant later head length drift");
        later_head.sync_all().expect("synchronize planted drift");
        drop(later_head);

        assert!(matches!(
            recovered_catalog.reconcile_admitted_and_activate(&mut admitted),
            Err(BrokerSpawnWalError::FilesystemRevalidationMismatch)
        ));
        assert_eq!(
            fs::read(&first_head_path).expect("read first head after rejected activation"),
            first_head_before_activation,
            "a later invalid pair changed bytes in the earlier WAL-ahead head"
        );
        assert!(admitted.journals[0].status().head_reconciliation_required);
        assert!(admitted.journals[0].status().append_authority_withheld);
    }

    #[test]
    fn later_torn_lifecycle_tail_is_rejected_before_reconciliation_or_socket_bind() {
        let root = tempfile::tempdir_in(crate::canonical_test_temp_root())
            .expect("create broker torn-catalog root");
        fs::set_permissions(root.path(), fs::Permissions::from_mode(0o700))
            .expect("set torn-catalog root owner-only");
        let spawn_catalog_path = root.path().join("spawn-catalog");
        fs::create_dir(&spawn_catalog_path).expect("create torn Spawn catalog");
        fs::set_permissions(&spawn_catalog_path, fs::Permissions::from_mode(0o700))
            .expect("set torn Spawn catalog owner-only");
        let lease_catalog_path = create_private_lease_catalog(root.path());
        let socket_path = root.path().join("broker.sock");
        let token_path = root.path().join("guardian.token");
        crate::transport::provision_guardian_token(&token_path)
            .expect("provision torn-catalog token");
        let secret =
            crate::transport::load_guardian_secret(&token_path).expect("load torn-catalog token");
        let authenticator = secret
            .broker_spawn_wal_authenticator()
            .expect("derive torn-catalog WAL authority");
        let first = recovered_catalog_identity(&authenticator, 17);
        let second = recovered_catalog_identity(&authenticator, 18);
        let first_head_path =
            spawn_catalog_path.join(broker_spawn_catalog_head_name(first.journal_id()));
        let second_wal_path =
            spawn_catalog_path.join(broker_spawn_catalog_wal_name(second.journal_id()));

        let mut catalog = BrokerSpawnWalCatalogV1::open(spawn_catalog_path.clone())
            .expect("open catalog for torn-tail admission test");
        let mut first_journal = catalog
            .create_spawn_journal(first, authenticator.clone())
            .expect("create first WAL-ahead journal");
        first_journal.inject_fault(BrokerSpawnWalInjectedFault::AfterWalSyncBeforeHead);
        assert!(matches!(
            first_journal.append_intent_and_sync(),
            Err(BrokerSpawnWalError::Io(_))
        ));
        let mut second_journal = catalog
            .create_spawn_journal(second, authenticator)
            .expect("create later torn journal");
        second_journal
            .append_intent_and_sync()
            .expect("commit later lifecycle prefix");
        drop(first_journal);
        drop(second_journal);
        drop(catalog);

        let first_head_before =
            fs::read(&first_head_path).expect("read first head before rejected bind");
        let second_wal_before_tail = fs::metadata(&second_wal_path)
            .expect("read second WAL metadata before torn tail")
            .len();
        let mut external = OpenOptions::new()
            .append(true)
            .open(&second_wal_path)
            .expect("open later WAL for torn tail");
        external
            .write_all(&BROKER_SPAWN_WAL_RECORD_MAGIC[..3])
            .expect("append later incomplete WAL tail");
        external.sync_all().expect("synchronize later torn tail");
        drop(external);

        let config = BrokerControlServiceConfigV1::new(
            socket_path.clone(),
            token_path,
            spawn_catalog_path,
            lease_catalog_path,
            sealed(0xaa),
            4,
            Duration::from_millis(5),
        )
        .expect("valid torn-catalog service config");
        assert!(matches!(
            bind_test_service_after_owner_drop(&config),
            Err(BrokerControlServiceError::SpawnCatalog(
                BrokerSpawnWalError::IncompleteTail
            ))
        ));
        assert_eq!(
            fs::read(&first_head_path).expect("read first head after rejected bind"),
            first_head_before,
            "a later torn member reconciled the earlier WAL-ahead head"
        );
        assert_eq!(
            fs::metadata(&second_wal_path)
                .expect("read retained torn WAL metadata")
                .len(),
            second_wal_before_tail + 3,
            "pure admission scan changed the retained torn-tail evidence"
        );
        assert!(
            !socket_path.exists(),
            "torn catalog bound a broker socket before rejection"
        );
    }

    #[test]
    fn broker_service_exposes_recovered_lifecycle_read_only_without_head_reconciliation() {
        let root = tempfile::tempdir_in(crate::canonical_test_temp_root())
            .expect("create broker lifecycle-refusal root");
        fs::set_permissions(root.path(), fs::Permissions::from_mode(0o700))
            .expect("set lifecycle-refusal root owner-only");
        let spawn_catalog_path = root.path().join("spawn-catalog");
        fs::create_dir(&spawn_catalog_path).expect("create lifecycle-refusal Spawn catalog");
        fs::set_permissions(&spawn_catalog_path, fs::Permissions::from_mode(0o700))
            .expect("set lifecycle-refusal Spawn catalog owner-only");
        let lease_catalog_path = create_private_lease_catalog(root.path());
        let socket_path = root.path().join("broker.sock");
        let token_path = root.path().join("guardian.token");
        crate::transport::provision_guardian_token(&token_path)
            .expect("provision lifecycle-refusal token");
        let secret = crate::transport::load_guardian_secret(&token_path)
            .expect("load lifecycle-refusal token");
        let authenticator = secret
            .broker_spawn_wal_authenticator()
            .expect("derive lifecycle-refusal WAL authority");
        let identity = recovered_catalog_identity(&authenticator, 14);
        let wal_path =
            spawn_catalog_path.join(broker_spawn_catalog_wal_name(identity.journal_id()));
        let head_path =
            spawn_catalog_path.join(broker_spawn_catalog_head_name(identity.journal_id()));
        let mut catalog = BrokerSpawnWalCatalogV1::open(spawn_catalog_path.clone())
            .expect("open lifecycle-refusal catalog");
        let mut journal = catalog
            .create_spawn_journal(identity, authenticator)
            .expect("create lifecycle-refusal journal");
        journal.inject_fault(BrokerSpawnWalInjectedFault::AfterWalSyncBeforeHead);
        assert!(matches!(
            journal.append_intent_and_sync(),
            Err(BrokerSpawnWalError::Io(_))
        ));
        drop(journal);
        drop(catalog);
        let wal_before_bind =
            fs::read(&wal_path).expect("read recovered lifecycle WAL before bind");
        let head_before_bind =
            fs::read(&head_path).expect("read recovered lifecycle head before bind");
        assert_eq!(
            u64::try_from(head_before_bind.len()).expect("recovered lifecycle head length"),
            BROKER_SPAWN_WAL_FILE_HEADER_BYTES_U64,
        );

        let broker_build = sealed(0xa8);
        let config = BrokerControlServiceConfigV1::new(
            socket_path.clone(),
            token_path.clone(),
            spawn_catalog_path.clone(),
            lease_catalog_path,
            broker_build,
            4,
            Duration::from_millis(5),
        )
        .expect("valid recovered-lifecycle service config");
        let service = bind_test_service_after_owner_drop(&config)
            .expect("bind read-only service over recovered lifecycle");
        let broker_incarnation = service.incarnation();
        assert_eq!(
            fs::read(&wal_path).expect("read recovered lifecycle WAL after bind"),
            wal_before_bind,
            "read-only bind changed durable WAL bytes"
        );
        assert_eq!(
            fs::read(&head_path).expect("read recovered lifecycle head after bind"),
            head_before_bind,
            "read-only bind reconciled durable head bytes"
        );
        assert!(
            socket_path.exists(),
            "read-only broker did not bind its socket"
        );
        let service = TestBrokerControlService::start(service);

        let connection_identity = BrokerGuardianConnectionIdentityV1::new(
            id(6_100),
            identity.mux_incarnation(),
            sealed(0xa9),
            sealed(0xaa),
        )
        .expect("valid recovered-lifecycle connection identity");
        let mut client = BrokerControlClientV1::connect(
            &socket_path,
            &token_path,
            connection_identity,
            broker_build,
        )
        .expect("connect to read-only recovered-lifecycle broker");
        assert_eq!(client.broker_incarnation(), broker_incarnation);

        let page_request = BrokerCensusPageRequestV1::new(
            Uuid::nil(),
            0,
            1,
            u32::try_from(
                BROKER_CONTROL_CENSUS_PAGE_HEADER_BYTES + BROKER_CONTROL_CENSUS_ENTRY_BYTES,
            )
            .expect("single-row Census byte bound"),
        )
        .expect("valid first recovered-lifecycle Census request");
        let page = client
            .census_page(page_request)
            .expect("read recovered lifecycle Census row");
        assert_eq!(page.total_entries(), 1);
        assert_eq!(page.next_cursor(), None);
        let [entry] = page.entries() else {
            panic!("expected one recovered lifecycle Census row")
        };
        assert_eq!(entry.journal_id, identity.journal_id());
        assert_eq!(entry.mux_incarnation, identity.mux_incarnation());
        assert_eq!(entry.durable_pane_id, identity.durable_pane_id());
        assert_eq!(entry.spawn_effect_id, identity.spawn_effect_id());
        assert_eq!(entry.origin_request_id, identity.origin_request_id());
        assert_eq!(entry.phase, Some(BrokerSpawnWalPhaseV1::Intent));
        assert_eq!(
            entry.disposition,
            BrokerCensusDispositionV1::IntentEffectsDisabled
        );
        assert!(entry.append_authority_withheld);
        assert!(entry.head_reconciliation_required);
        assert!(entry.effects_disabled);
        assert!(!entry.pty_available);
        assert!(!entry.lease_available);
        assert!(!entry.output_replay_available);

        assert_eq!(
            client
                .query_recovered_spawn(identity.durable_pane_id(), identity.spawn_effect_id())
                .expect("query exact recovered Spawn identity"),
            Some(*entry)
        );
        assert!(matches!(
            client.query_recovered_spawn(identity.durable_pane_id(), id(6_101)),
            Err(BrokerControlClientError::SpawnQuarantined)
        ));
        assert!(matches!(
            client.query_recovered_spawn(id(6_102), identity.spawn_effect_id()),
            Err(BrokerControlClientError::SpawnQuarantined)
        ));
        assert_eq!(
            client
                .query_recovered_spawn(id(6_104), id(6_105))
                .expect("query an unrelated absent recovered Spawn identity"),
            None
        );

        let sentinel = root.path().join("recovered-census-must-not-exec");
        let spawn_payload = command_payload("printf must-not-run", &sentinel);
        let authenticated = BrokerAuthenticatedGuardianConnectionV1 {
            broker_incarnation,
            owner: BrokerGuardianOwnerIdentity {
                guardian_incarnation: connection_identity.guardian_incarnation,
                connection_id: client.connection_id,
                mux_incarnation: connection_identity.mux_incarnation,
                mux_build_identity_digest: connection_identity.mux_build_identity.into_bytes(),
                guardian_build_identity_digest: connection_identity
                    .guardian_build_identity
                    .into_bytes(),
            },
        };
        let binding = binding_for(&spawn_payload, &authenticated);
        let control_spawn = BrokerSpawnControlRequestV1::from_parts(
            identity.journal_id(),
            id(6_103),
            [0xab; BROKER_CATALOG_CHECKSUM_BYTES],
            binding,
            spawn_payload,
        )
        .expect("valid recovered-collision Spawn control payload");
        let encoded_spawn = control_spawn
            .encode()
            .expect("encode recovered-collision Spawn control payload");
        let spawn_request = BrokerControlRequestV1::new(
            BrokerControlRequestHeaderV1 {
                operation: BrokerControlOperationV1::Spawn,
                request_id: binding.origin_request_id,
                broker_incarnation,
                guardian_incarnation: connection_identity.guardian_incarnation,
                connection_id: client.connection_id,
                mux_incarnation: connection_identity.mux_incarnation,
                guardian_build_identity_digest: connection_identity
                    .guardian_build_identity
                    .into_bytes(),
                mux_build_identity_digest: connection_identity.mux_build_identity.into_bytes(),
                durable_pane_id: binding.durable_pane_id,
                lease_generation: 0,
                operation_id: binding.spawn_effect_id,
            },
            &encoded_spawn,
        )
        .expect("canonical recovered-collision Spawn request");
        let spawn_response = client
            .exchange(&spawn_request)
            .expect("receive recovered-collision Spawn quarantine");
        assert_eq!(
            spawn_response.header.status,
            BrokerControlResponseStatusV1::Quarantined
        );
        assert!(!sentinel.exists(), "recovery visibility executed a child");

        drop(client);
        service.finish();
        assert_eq!(
            fs::read(&wal_path).expect("read recovered lifecycle WAL after queries"),
            wal_before_bind,
            "recovery visibility appended a lifecycle record"
        );
        assert_eq!(
            fs::read(&head_path).expect("read recovered lifecycle head after queries"),
            head_before_bind,
            "recovery visibility reconciled the durable head"
        );
    }

    #[test]
    fn token_replacement_before_creation_recovery_preserves_catalog_and_never_binds() {
        fn snapshot_catalog(path: &Path) -> Vec<(Vec<u8>, Vec<u8>, u32)> {
            let mut snapshot = fs::read_dir(path)
                .expect("enumerate creation-recovery catalog")
                .map(|entry| {
                    let entry = entry.expect("read creation-recovery catalog entry");
                    let metadata = entry
                        .metadata()
                        .expect("read creation-recovery catalog metadata");
                    (
                        entry.file_name().as_os_str().as_bytes().to_vec(),
                        fs::read(entry.path()).expect("read creation-recovery catalog bytes"),
                        metadata.mode() & 0o7777,
                    )
                })
                .collect::<Vec<_>>();
            snapshot.sort_unstable_by(|left, right| left.0.cmp(&right.0));
            snapshot
        }

        let root = tempfile::tempdir_in(crate::canonical_test_temp_root())
            .expect("create creation-recovery token-fence root");
        fs::set_permissions(root.path(), fs::Permissions::from_mode(0o700))
            .expect("set creation-recovery token-fence root owner-only");
        let spawn_catalog_path = root.path().join("spawn-catalog");
        fs::create_dir(&spawn_catalog_path).expect("create creation-recovery Spawn catalog");
        fs::set_permissions(&spawn_catalog_path, fs::Permissions::from_mode(0o700))
            .expect("set creation-recovery Spawn catalog owner-only");
        let socket_path = root.path().join("broker.sock");
        let token_path = root.path().join("guardian.token");
        crate::transport::provision_guardian_token(&token_path)
            .expect("provision creation-recovery token");
        let original_token = fs::read(&token_path).expect("read creation-recovery token");
        let (secret, mut token_authority) =
            crate::transport::load_guardian_secret_with_authority(&token_path)
                .expect("load creation-recovery token authority");
        let authenticator = secret
            .broker_spawn_wal_authenticator()
            .expect("derive creation-recovery WAL authority");
        let identity = recovered_catalog_identity(&authenticator, 0x66);
        let mut catalog = BrokerSpawnWalCatalogV1::open(spawn_catalog_path.clone())
            .expect("open interrupted creation-recovery catalog");
        catalog.inject_creation_fault(BrokerSpawnCreationInjectedFault::DuringWalHeaderWrite {
            durable_prefix_bytes: 73,
        });
        assert!(matches!(
            catalog.create_spawn_journal_fixture_unadmitted(identity, authenticator.clone()),
            Err(BrokerSpawnWalError::Io(_))
        ));
        drop(catalog);
        let catalog_before = snapshot_catalog(&spawn_catalog_path);

        let retained_token = root
            .path()
            .join("guardian-retained-creation-recovery.token");
        fs::rename(&token_path, &retained_token)
            .expect("retain original creation-recovery token inode");
        create_private_broker_token_with_bytes(&token_path, &original_token);
        assert!(matches!(
            open_and_scan_broker_spawn_catalog_under_token_authority(
                &mut token_authority,
                spawn_catalog_path.clone(),
                &authenticator,
            ),
            Err(BrokerControlServiceError::Endpoint(
                GuardianServiceError::FilesystemSecurity(_)
            ))
        ));
        assert_eq!(
            snapshot_catalog(&spawn_catalog_path),
            catalog_before,
            "stale token authority changed interrupted creation bytes, names, or modes"
        );
        assert!(
            !socket_path.exists(),
            "stale token authority reached broker socket binding"
        );
        assert_eq!(
            fs::read(&retained_token).expect("read retained creation-recovery token"),
            original_token
        );
    }

