    #[test]
    fn catalog_reconciliation_holds_token_effect_lease_across_head_append() {
        let root = tempfile::tempdir_in(crate::canonical_test_temp_root())
            .expect("create reconciliation-effect-lease root");
        fs::set_permissions(root.path(), fs::Permissions::from_mode(0o700))
            .expect("set reconciliation-effect-lease root owner-only");
        let spawn_catalog_path = root.path().join("spawn-catalog");
        fs::create_dir(&spawn_catalog_path)
            .expect("create reconciliation-effect-lease Spawn catalog");
        fs::set_permissions(&spawn_catalog_path, fs::Permissions::from_mode(0o700))
            .expect("set reconciliation-effect-lease catalog owner-only");
        let token_path = root.path().join("guardian.token");
        crate::transport::provision_guardian_token(&token_path)
            .expect("provision reconciliation-effect-lease token");
        let (secret, mut token_authority) =
            crate::transport::load_guardian_secret_with_authority(&token_path)
                .expect("load reconciliation-effect-lease token authority");
        let authenticator = secret
            .broker_spawn_wal_authenticator()
            .expect("derive reconciliation-effect-lease WAL authority");
        let identity = recovered_catalog_identity(&authenticator, 0x67);
        let head_path =
            spawn_catalog_path.join(broker_spawn_catalog_head_name(identity.journal_id()));
        let mut catalog = BrokerSpawnWalCatalogV1::open(spawn_catalog_path.clone())
            .expect("open reconciliation-effect-lease catalog");
        let mut journal = catalog
            .create_spawn_journal(identity, authenticator.clone())
            .expect("create reconciliation-effect-lease journal");
        journal.inject_fault(BrokerSpawnWalInjectedFault::AfterWalSyncBeforeHead);
        assert!(matches!(
            journal.append_intent_and_sync(),
            Err(BrokerSpawnWalError::Io(_))
        ));
        drop(journal);
        drop(catalog);
        let head_before = fs::read(&head_path).expect("read unreconciled effect-lease head");
        let mut catalog = reopen_test_catalog_after_owner_drop(&spawn_catalog_path)
            .expect("reopen reconciliation-effect-lease catalog");
        let journals = catalog
            .scan_all_for_admission(&authenticator)
            .expect("scan reconciliation-effect-lease catalog");
        let mut admitted = BrokerRecoveredSpawnCatalogV1::admit(journals, &authenticator)
            .expect("admit reconciliation-effect-lease catalog");
        assert!(admitted.journals[0].status().head_reconciliation_required);

        reconcile_broker_catalog_under_token_authority_with_hook(
            &mut token_authority,
            &catalog,
            &mut admitted,
            || {
                assert!(
                    !crate::transport::guardian_token_publication_lock_is_available(&token_path)
                        .expect("probe token publication during head reconciliation"),
                    "cooperative token publication crossed recovered-head append"
                );
            },
        )
        .expect("reconcile catalog under exact token effect lease");
        assert!(
            crate::transport::guardian_token_publication_lock_is_available(&token_path)
                .expect("probe token publication after head reconciliation"),
            "head reconciliation retained its token effect lease"
        );
        assert_ne!(
            fs::read(&head_path).expect("read reconciled effect-lease head"),
            head_before,
            "head reconciliation did not append its authenticated anchor"
        );
        assert!(!admitted.journals[0].status().head_reconciliation_required);
    }

    #[test]
    fn running_broker_refuses_token_rotation_before_poll_or_accept() {
        let root = tempfile::tempdir_in(crate::canonical_test_temp_root())
            .expect("create running broker token-authority root");
        fs::set_permissions(root.path(), fs::Permissions::from_mode(0o700))
            .expect("set running broker token-authority root owner-only");
        let spawn_catalog_path = root.path().join("spawn-catalog");
        fs::create_dir(&spawn_catalog_path).expect("create running broker Spawn catalog");
        fs::set_permissions(&spawn_catalog_path, fs::Permissions::from_mode(0o700))
            .expect("set running broker Spawn catalog owner-only");
        let lease_catalog_path = create_private_lease_catalog(root.path());
        let socket_path = root.path().join("broker.sock");
        let token_path = root.path().join("guardian.token");
        crate::transport::provision_guardian_token(&token_path)
            .expect("provision running broker token");
        let original_token = fs::read(&token_path).expect("read running broker token");
        let config = BrokerControlServiceConfigV1::new(
            socket_path.clone(),
            token_path.clone(),
            spawn_catalog_path,
            lease_catalog_path,
            sealed(0xab),
            4,
            Duration::from_millis(5),
        )
        .expect("valid running broker token-authority config");
        let mut service = BrokerControlServiceV1::bind(config)
            .expect("bind running broker under retained token authority");
        assert!(socket_path.exists());

        let retained_token = root.path().join(format!(
            "guardian-running-retained-{}.token",
            Uuid::new_v4()
        ));
        fs::rename(&token_path, &retained_token).expect("retain running broker token inode");
        let mut replacement = original_token.clone();
        replacement[0] ^= 0x20;
        create_private_broker_token_with_bytes(&token_path, &replacement);

        assert!(matches!(
            service.poll_once(),
            Err(BrokerControlServiceError::Endpoint(
                GuardianServiceError::FilesystemSecurity(_)
            ))
        ));
        assert!(service.connections.is_empty());
        assert_eq!(service.rejected_connections(), 0);
        assert!(
            socket_path.exists(),
            "running refusal removed socket evidence"
        );
        assert_eq!(fs::read(&retained_token).unwrap(), original_token);
    }

    #[test]
    fn pinned_catalog_reconciles_wal_ahead_of_head_without_second_spawn_authority() {
        let directory = private_catalog_directory();
        let sentinel = directory.path().join("unused-spawn-sentinel");
        let authority = authority(id(880), id(881), id(882), id(883), 0x81, 0x82);
        let payload = command_payload("printf unexpected", &sentinel);
        let authenticator = wal_authenticator(0x91);
        let identity = BrokerSpawnWalIdentityV1::from_binding(
            id(900),
            authenticator.lineage_id(),
            binding_for(&payload, &authority),
        )
        .expect("valid token-lineage broker WAL identity");
        let mut catalog = BrokerSpawnWalCatalogV1::open(directory.path().to_path_buf())
            .expect("open empty pinned broker catalog");
        let mut journal = catalog
            .create_spawn_journal(identity, authenticator.clone())
            .expect("create catalog-managed Spawn WAL");
        journal
            .append_intent_and_sync()
            .expect("synchronize catalog-managed intent");
        let attempt_id = id(884);
        journal.inject_fault(BrokerSpawnWalInjectedFault::AfterWalSyncBeforeHead);
        assert!(matches!(
            journal.begin_spawn_attempt_and_sync(attempt_id),
            Err(BrokerSpawnWalError::Io(_))
        ));
        assert!(journal.is_poisoned());
        drop(journal);
        drop(catalog);

        let mut recovered_catalog = reopen_test_catalog_after_owner_drop(directory.path())
            .expect("reopen exact pinned broker catalog");
        let journals = recovered_catalog
            .scan_all_for_admission(&authenticator)
            .expect("authenticate complete catalog before admission");
        let mut admitted = BrokerRecoveredSpawnCatalogV1::admit(journals, &authenticator)
            .expect("admit the complete unique catalog before reconciliation");
        recovered_catalog
            .reconcile_admitted_and_activate(&mut admitted)
            .expect("reconcile the admitted complete catalog");
        assert_eq!(admitted.journals.len(), 1);
        let mut recovered = admitted.journals.pop().expect("one recovered journal");
        let status = recovered.status();
        assert_eq!(status.identity, identity);
        assert_eq!(status.phase, Some(BrokerSpawnWalPhaseV1::Attempted));
        assert_eq!(status.attempt_id, Some(attempt_id));
        assert!(!status.append_authority_withheld);
        assert!(!status.head_reconciliation_required);
        assert!(status.durable_protocol_fence().unwrap().is_some());
        assert!(matches!(
            recovered
                .begin_spawn_attempt_and_sync(attempt_id)
                .expect("recover exact lost attempt reply"),
            BrokerSpawnAttemptAdmissionV1::Reconciled(replayed)
                if replayed.phase == Some(BrokerSpawnWalPhaseV1::Attempted)
        ));
    }

    #[test]
    fn pinned_catalog_rejects_second_owner_unknown_orphan_and_insecure_inode() {
        let owned_directory = private_catalog_directory();
        let owner = BrokerSpawnWalCatalogV1::open(owned_directory.path().to_path_buf())
            .expect("first catalog owner");
        assert!(matches!(
            BrokerSpawnWalCatalogV1::open(owned_directory.path().to_path_buf()),
            Err(BrokerSpawnWalError::CatalogAlreadyOwned)
        ));
        drop(owner);

        let unknown_directory = private_catalog_directory();
        let unknown = unknown_directory.path().join("unexpected-state");
        let unknown_file = OpenOptions::new()
            .read(true)
            .write(true)
            .create_new(true)
            .mode(0o600)
            .open(&unknown)
            .expect("create unknown catalog entry");
        drop(unknown_file);
        assert!(matches!(
            BrokerSpawnWalCatalogV1::open(unknown_directory.path().to_path_buf()),
            Err(BrokerSpawnWalError::UnexpectedCatalogEntry)
        ));

        let orphan_directory = private_catalog_directory();
        let orphan_name = broker_spawn_catalog_wal_name(id(885));
        let orphan = OpenOptions::new()
            .read(true)
            .write(true)
            .create_new(true)
            .mode(0o600)
            .open(orphan_directory.path().join(orphan_name))
            .expect("create orphan WAL name");
        drop(orphan);
        assert!(matches!(
            BrokerSpawnWalCatalogV1::open(orphan_directory.path().to_path_buf()),
            Err(BrokerSpawnWalError::IncompleteCatalogPair)
        ));

        let linked_directory = private_catalog_directory();
        let sentinel = linked_directory.path().join("unused-spawn-sentinel");
        let authority = authority(id(886), id(887), id(888), id(889), 0x83, 0x84);
        let payload = command_payload("printf unexpected", &sentinel);
        let authenticator = wal_authenticator(0x92);
        let identity = BrokerSpawnWalIdentityV1::from_binding(
            id(900),
            authenticator.lineage_id(),
            binding_for(&payload, &authority),
        )
        .expect("valid catalog-lineage broker WAL identity");
        let mut catalog = BrokerSpawnWalCatalogV1::open(linked_directory.path().to_path_buf())
            .expect("open catalog before link mutation");
        let journal = catalog
            .create_spawn_journal(identity, authenticator.clone())
            .expect("create pair before link mutation");
        let wal_name = broker_spawn_catalog_wal_name(identity.journal_id());
        fs::hard_link(
            linked_directory.path().join(&wal_name),
            linked_directory.path().join("retained-hard-link-evidence"),
        )
        .expect("create hard-link mutation");
        drop(journal);
        assert!(matches!(
            catalog.scan_all_for_admission(&authenticator),
            Err(BrokerSpawnWalError::UnexpectedCatalogEntry
                | BrokerSpawnWalError::InsecureCatalogIdentity)
        ));

        let target_directory = private_catalog_directory();
        let link_parent = private_catalog_directory();
        let link_path = link_parent.path().join("catalog-link");
        symlink(target_directory.path(), &link_path).expect("create catalog symlink mutation");
        assert!(matches!(
            BrokerSpawnWalCatalogV1::open(link_path),
            Err(BrokerSpawnWalError::InsecureCatalogIdentity)
        ));
    }

